    'zanzibar_meta_description' => 'Zanzíbar después de su safari: playas de Nungwi, Kendwa, Paje y Jambiani, Stone Town, Bosque de Jozani, Safari Blue y snorkel en Mnemba. Vuelos desde el Serengeti organizados para usted.',
