    'zanzibar_why_badge' => 'Por qué añadir Zanzíbar',
    'zanzibar_why_title' => 'La forma perfecta de terminar un safari',
    'zanzibar_why_1_title' => 'Contraste perfecto',
    'zanzibar_why_1_desc' => 'Cambie los game drives al amanecer por mañanas tranquilas y agua cálida, y el polvo de la sabana por el aire marino.',
    'zanzibar_why_2_title' => 'Un viaje, dos mundos',
    'zanzibar_why_2_desc' => 'Misma visa, misma moneda, un simple vuelo interno: sin necesidad de planificar unas vacaciones aparte.',
    'zanzibar_why_3_title' => 'Nos encargamos de la logística',
    'zanzibar_why_3_desc' => 'Vuelos, traslados y hotel reservados como parte de su itinerario. Usted solo tiene que llegar y deshacer las maletas.',

    'zanzibar_gallery_badge' => 'La isla',
    'zanzibar_gallery_title' => 'Zanzíbar en imágenes',

    'zanzibar_beaches_badge' => 'Elija su costa',
    'zanzibar_beaches_title' => 'Qué playa le conviene',
    'zanzibar_beaches_intro' => 'La isla es pequeña, pero las costas son muy diferentes. Las mareas importan más de lo que la mayoría de los visitantes esperan.',
    'zanzibar_beach_north_region' => 'Norte',
    'zanzibar_beach_north_name' => 'Nungwi y Kendwa',
    'zanzibar_beach_north_desc' => 'Las únicas playas donde se puede nadar en cualquier estado de la marea. La parte más animada de la isla, con más hoteles y restaurantes, y los mejores atardeceres.',
    'zanzibar_beach_north_best' => 'Ideal para: primera visita, natación, vida nocturna',
    'zanzibar_beach_se_region' => 'Sureste',
    'zanzibar_beach_se_name' => 'Paje y Jambiani',
    'zanzibar_beach_se_desc' => 'Laguna amplia, mareas fuertes y viento constante: la costa del kitesurf. Más tranquila, más joven y más relajada que el norte.',
    'zanzibar_beach_se_best' => 'Ideal para: kitesurf, largas caminatas, buena relación calidad-precio',
    'zanzibar_beach_east_region' => 'Este y Sur',
    'zanzibar_beach_east_name' => 'Matemwe y Kizimkazi',
    'zanzibar_beach_east_desc' => 'Matemwe está frente al atolón de Mnemba, el mejor lugar de snorkel de la isla. Kizimkazi es de donde salen los barcos para ver delfines.',
    'zanzibar_beach_east_best' => 'Ideal para: snorkel, buceo, tranquilidad',
    'zanzibar_tide_note' => '<strong>Sobre las mareas:</strong> en las costas este y sureste, el mar se retira varios cientos de metros durante la marea baja y nadar no es posible durante parte del día. No es un problema, es simplemente cómo funciona la isla, pero si nadar cuando quiera le importa, elija el norte.',

    'zanzibar_excursions_badge' => 'Más allá de la playa',
    'zanzibar_excursions_title' => 'Excursiones que vale la pena hacer',
    'zanzibar_exc_stonetown_title' => 'Stone Town',
    'zanzibar_exc_stonetown_desc' => 'Un sitio Patrimonio de la Humanidad de la UNESCO: puertas talladas, el antiguo mercado de esclavos, el mercado nocturno de Forodhani. Medio día con un guía local.',
    'zanzibar_exc_spice_title' => 'Tour de especias',
    'zanzibar_exc_spice_desc' => 'Las plantaciones que dieron nombre a la isla: clavo, vainilla, nuez moscada y canela, degustados directamente del árbol.',
    'zanzibar_exc_safariblue_title' => 'Safari Blue',
    'zanzibar_exc_safariblue_desc' => 'Un día completo en dhow: bancos de arena, snorkel, un almuerzo de mariscos en la isla de Kwale y canales de manglares.',
    'zanzibar_exc_jozani_title' => 'Bosque de Jozani',
    'zanzibar_exc_jozani_desc' => 'El último hábitat del colobo rojo, que no se encuentra en ningún otro lugar de la tierra. Dos horas, fácilmente combinable con la costa sur.',
    'zanzibar_exc_mnemba_title' => 'Atolón de Mnemba',
    'zanzibar_exc_mnemba_desc' => 'El mejor snorkel y buceo de la isla, al que se llega en barco desde Matemwe.',
    'zanzibar_exc_prison_title' => 'Isla de la Prisión',
    'zanzibar_exc_prison_desc' => 'Tortugas gigantes de Aldabra, algunas con más de un siglo de vida, a un corto trayecto en barco desde Stone Town.',

    'zanzibar_when_badge' => 'Planificación',
    'zanzibar_when_title' => 'Cuándo ir',
    'zanzibar_when_dry_period' => 'Junio – Octubre',
    'zanzibar_when_dry_temp' => '26–30°C',
    'zanzibar_when_dry_desc' => 'Seco, soleado y menos húmedo. La temporada alta, y la continuación natural de un safari en temporada seca.',
    'zanzibar_when_dry_tag' => 'Lo mejor',
    'zanzibar_when_summer_period' => 'Diciembre – Febrero',
    'zanzibar_when_summer_temp' => '28–32°C',
    'zanzibar_when_summer_desc' => 'Cálido, mar en calma, excelente visibilidad para el buceo. Posibles chubascos cortos.',
    'zanzibar_when_summer_tag' => 'Muy bueno',
    'zanzibar_when_long_rains_period' => 'Marzo – Mayo',
    'zanzibar_when_long_rains_temp' => '27–31°C',
    'zanzibar_when_long_rains_desc' => 'Las lluvias largas. Precios más bajos y playas vacías, pero algunos hoteles cierran en abril y mayo.',
    'zanzibar_when_long_rains_tag' => 'Temporada baja',
    'zanzibar_when_nov_period' => 'Noviembre',
    'zanzibar_when_nov_temp' => '27–31°C',
    'zanzibar_when_nov_desc' => 'Lluvias cortas: breves aguaceros por la tarde, por lo demás soleado. Buena relación calidad-precio antes de la afluencia de diciembre.',
    'zanzibar_when_nov_tag' => 'Buena relación calidad-precio',

    'zanzibar_featured_badge' => 'Combinación más solicitada',
    'zanzibar_featured_title' => 'Safari de 7 días + Zanzíbar',
    'zanzibar_featured_desc' => '5 noches de safari por el circuito norte, 2 noches de relax en Zanzíbar, vuelo interno incluido.',
    'zanzibar_featured_price' => 'desde 2.200 € por persona',
    'zanzibar_featured_cta' => 'Ver este paquete',

    'zanzibar_practical_badge' => 'Bueno saber',
    'zanzibar_practical_title' => 'Notas prácticas',
    'zanzibar_practical_entry_title' => 'Requisitos de entrada',
    'zanzibar_practical_entry_desc' => 'Zanzíbar forma parte de Tanzania, por lo que se aplica la misma visa. Desde 2024 también se requiere a la llegada una póliza de seguro emitida por un proveedor aprobado por Zanzíbar; cuesta alrededor de 44 USD y podemos organizarla junto con su reserva.',
    'zanzibar_practical_dress_title' => 'Vestimenta y costumbres',
    'zanzibar_practical_dress_desc' => 'Zanzíbar es predominantemente musulmán. El traje de baño está bien en la playa y en su hotel, pero cubra hombros y rodillas en Stone Town y las aldeas. Durante el Ramadán, muchos restaurantes fuera de los complejos turísticos cierran durante el día.',
    'zanzibar_practical_flight_title' => 'Cómo llegar desde el safari',
    'zanzibar_practical_flight_desc' => 'Un vuelo directo desde las pistas del Serengeti dura aproximadamente 1 hora y 30 minutos; desde Arusha o el Aeropuerto del Kilimanjaro, alrededor de una hora. Reservamos estos vuelos internos como parte de su itinerario.',
    'zanzibar_practical_malaria_title' => 'Malaria',
    'zanzibar_practical_malaria_desc' => 'Zanzíbar es una zona de malaria. Se recomienda profilaxis (consulte a su médico o clínica de viajes) y usar repelente al atardecer. Beba agua embotellada o filtrada.',

    'zanzibar_faq_title' => 'Preguntas comunes',
    'zanzibar_faq_q1' => '¿Cuántos días debo añadir para Zanzíbar?',
    'zanzibar_faq_a1' => 'Tres noches es el mínimo para que se sienta como unas vacaciones en lugar de una escala. Cuatro a cinco días le dan tiempo para un día de playa, una excursión y Stone Town sin prisas.',
    'zanzibar_faq_q2' => '¿Está Zanzíbar incluido en el precio del safari?',
    'zanzibar_faq_a2' => 'No, es una extensión opcional. La cotizamos por separado junto a su safari para que pueda ver exactamente qué añade, incluido el vuelo interno.',
    'zanzibar_faq_q3' => '¿Qué playa deberían elegir los visitantes primerizos?',
    'zanzibar_faq_a3' => 'Nungwi o Kendwa en el norte: se puede nadar con cualquier marea, la mayor cantidad de hoteles y restaurantes, y la introducción más fácil a la isla.',
    'zanzibar_faq_q4' => '¿Necesito vacunas adicionales para Zanzíbar?',
    'zanzibar_faq_a4' => 'No se requieren vacunas más allá de las necesarias para la Tanzania continental. Se recomienda profilaxis antipalúdica, y la póliza de seguro local es obligatoria a la llegada.',

    'zanzibar_cta_title' => 'Planifique su viaje con nosotros',
    'zanzibar_cta_intro' => 'Envíenos sus fechas, tamaño del grupo y presupuesto. Respondemos con un itinerario escrito y un desglose completo de precios, sin compromiso.',
    'zanzibar_cta_whatsapp' => 'Escríbanos por WhatsApp',
