    'trekking_meta_title' => 'Trekking al Kilimanjaro y monte Meru | Serengeti Budget Safari',
    'trekking_meta_description' => 'Escale el Kilimanjaro con un operador local de Arusha: rutas Machame, Lemosho, Marangu, Rongai y Northern Circuit, además del monte Meru, Ol Doinyo Lengai y las montañas Usambara.',
    'trekking_hero_badge' => 'Trekking',
    'trekking_hero_title_1' => 'Trekking al',
    'trekking_hero_title_2' => 'Kilimanjaro',
    'trekking_hero_sub' => "El punto más alto de África a 5.895 m, además del monte Meru, Ol Doinyo Lengai y las colinas Usambara, escalados con nuestro propio equipo de montaña.",
    'trekking_hero_cta_quote' => 'Solicitar presupuesto',

    'trekking_routes_badge' => 'Elija su camino',
    'trekking_routes_title' => 'Elija su ruta',
    'trekking_routes_intro' => 'La montaña no es técnica: el desafío es la altitud. Cuanto más larga sea la ruta, mejor se aclimatará su cuerpo y mayores serán sus posibilidades de pisar el Uhuru Peak.',

    'trekking_route_lemosho_tagline' => 'Mejor paisaje y aclimatación',
    'trekking_route_lemosho_name' => 'Lemosho',
    'trekking_route_lemosho_days' => '7–8 días',
    'trekking_route_lemosho_desc' => 'Un comienzo tranquilo a través del bosque, uniéndose a Machame más arriba. El mejor perfil de aclimatación de todas las rutas.',
    'trekking_route_lemosho_success' => 'El más alto',

    'trekking_route_machame_tagline' => 'La "Ruta del Whisky" · la más popular',
    'trekking_route_machame_name' => 'Machame',
    'trekking_route_machame_days' => '6–7 días',
    'trekking_route_machame_desc' => 'Escénica, empinada en tramos, un perfil de aclimatación sólido. La ruta que eligen la mayoría de los escaladores.',
    'trekking_route_machame_success' => 'Alto',

    'trekking_route_northern_tagline' => 'Senderos más tranquilos, ruta más larga',
    'trekking_route_northern_name' => 'Northern Circuit',
    'trekking_route_northern_days' => '9 días',
    'trekking_route_northern_desc' => 'Casi un círculo completo alrededor de la montaña. La ruta más larga, con muy pocos otros grupos en el sendero.',
    'trekking_route_northern_success' => 'El más alto',

    'trekking_route_rongai_tagline' => 'La más seca en los meses lluviosos',
    'trekking_route_rongai_name' => 'Rongai',
    'trekking_route_rongai_days' => '6–7 días',
    'trekking_route_rongai_desc' => 'Se aproxima desde el lado norte, más seco. La mejor opción si escala fuera de la principal temporada seca.',
    'trekking_route_rongai_success' => 'Bueno',

    'trekking_route_marangu_tagline' => 'Refugios en lugar de tiendas',
    'trekking_route_marangu_name' => 'Marangu',
    'trekking_route_marangu_days' => '5–6 días',
    'trekking_route_marangu_desc' => 'La única ruta con alojamiento en refugios. Mismo camino de ida y vuelta, y la opción más corta.',
    'trekking_route_marangu_success' => 'Más bajo',

    'trekking_routes_note' => 'Si tiene los días disponibles, tome la ruta más larga. La noche adicional es el seguro más barato que puede comprar contra el mal de altura.',

    'trekking_included_title' => 'Qué incluye cada ascenso',
    'trekking_included_subtitle' => 'La misma tarificación transparente que nuestros safaris, sin extras ocultos una vez en la montaña.',
    'trekking_included_heading' => 'Incluido',
    'trekking_included_1' => 'Tasas de parque, tasas de campamento o refugio y tasas de rescate',
    'trekking_included_2' => 'Guía de montaña certificado, guías asistentes, cocinero y porteadores',
    'trekking_included_3' => 'Todas las comidas en la montaña y agua potable',
    'trekking_included_4' => 'Tiendas, colchonetas, tienda comedor y equipo de cocina',
    'trekking_included_5' => 'Controles con oxímetro de pulso y un botiquín llevado por el guía',
    'trekking_included_6' => 'Traslados entre Arusha y el punto de partida',
    'trekking_included_7' => 'Dos noches en Arusha, antes y después del ascenso',
    'trekking_excluded_heading' => 'No incluido',
    'trekking_excluded_1' => 'Vuelos internacionales y visa',
    'trekking_excluded_2' => 'Seguro de viaje que cubra trekking hasta 6.000 m (obligatorio)',
    'trekking_excluded_3' => 'Equipo personal y saco de dormir (alquiler disponible)',
    'trekking_excluded_4' => 'Propinas para el equipo de montaña',
    'trekking_excluded_5' => 'Oxígeno portátil o porteador personal, si se solicita',

    'trekking_other_badge' => 'Más allá del Kilimanjaro',
    'trekking_other_title' => 'Otras montañas',
    'trekking_meru_name' => 'Monte Meru, 4.566 m',
    'trekking_meru_desc' => 'Tres o cuatro días dentro del Parque Nacional de Arusha, caminando con un ranger armado junto a búfalos y jirafas. La mejor aclimatación posible antes del Kilimanjaro.',
    'trekking_lengai_name' => 'Ol Doinyo Lengai, 2.962 m',
    'trekking_lengai_desc' => 'La "Montaña de Dios" de los masái, un volcán activo escalado durante la noche para alcanzar el borde del cráter al amanecer. Empinado, caliente y verdaderamente exigente.',
    'trekking_usambara_name' => 'Usambara y Udzungwa',
    'trekking_usambara_desc' => 'Montañas verdes, cascadas y aldeas, recorridas durante dos a cuatro días a baja altitud. Una buena opción en la temporada de lluvias o con niños.',

    'trekking_guide_badge' => 'Profundizar',
    'trekking_guide_title' => 'Lea la guía completa del parque',
    'trekking_guide_intro' => 'Todo sobre el Parque Nacional del Kilimanjaro en un solo lugar: las siete rutas comparadas con tasas de éxito, las tasas de parque de 2026 detalladas, el mal de altura explicado, y cómo se debe tratar a los porteadores.',
    'trekking_guide_kili_badge' => 'Guía del parque',
    'trekking_guide_kili_title' => 'Parque Nacional del Kilimanjaro',
    'trekking_guide_kili_desc' => 'Cinco zonas climáticas, siete rutas, 5.895 m. Solo las tasas de parque son de alrededor de 956 $ para un ascenso de siete días. Le mostramos exactamente cómo se calcula eso.',
    'trekking_guide_kili_cta' => 'Guía completa del Kilimanjaro',
    'trekking_guide_meru_badge' => 'Guía del parque',
    'trekking_guide_meru_title' => 'Parque Nacional de Arusha y monte Meru',
    'trekking_guide_meru_desc' => 'El Meru, a 4.566 m, ofrece la mejor aclimatación disponible antes del Kilimanjaro, y es por sí solo una montaña magnífica y casi vacía.',
    'trekking_guide_meru_cta' => 'Guía completa del Parque Nacional de Arusha',

    'trekking_faq_title' => 'Antes de reservar',
    'trekking_faq_q1' => '¿Necesito experiencia en escalada?',
    'trekking_faq_a1' => 'No. El Kilimanjaro es una larga caminata, no una escalada: no hay técnica de cuerdas ni terreno técnico. Lo que exige es resistencia para seis a nueve días de caminata y la capacidad de soportar el aire enrarecido. Entrene caminando cuesta arriba durante varias horas seguidas.',
    'trekking_faq_q2' => '¿Cuál es la mejor época para escalar?',
    'trekking_faq_a2' => 'De enero a principios de marzo y de junio a octubre. Abril, mayo y noviembre son los meses húmedos: la montaña sigue siendo escalable, pero los senderos están resbaladizos y las vistas suelen estar cerradas. Rongai es la ruta más seca en condiciones marginales.',
    'trekking_faq_q3' => '¿Qué pasa con el mal de altura?',
    'trekking_faq_a3' => 'Los dolores de cabeza leves y la falta de aire son normales por encima de 4.000 m. Nuestros guías verifican la saturación de oxígeno dos veces al día y llevan un botiquín de primeros auxilios. La regla en nuestros ascensos es simple: si un guía juzga que debe descender, desciende. A nadie se le obliga a continuar.',

    'trekking_cta_title' => 'Planifique su viaje con nosotros',
    'trekking_cta_intro' => 'Envíenos sus fechas, tamaño del grupo y presupuesto. Respondemos con un itinerario escrito y un desglose completo de precios, sin compromiso.',
    'trekking_cta_whatsapp' => 'Escríbanos por WhatsApp',
    'trekking_cta_contact_form' => 'Formulario de contacto',

    'groups_meta_title' => 'Safaris en grupo compartido Tanzania | Serengeti Budget Safari',
    'groups_meta_description' => 'Únase a un safari en grupo programado en Tanzania y divida el costo de un 4x4 privado sin dividir la experiencia. Salidas fijas, grupos pequeños, adecuado para viajeros solos.',
    'groups_hero_badge' => 'Safaris en grupo compartido',
    'groups_hero_title_1' => 'Únase a un safari,',
    'groups_hero_title_2' => 'no a una multitud',
    'groups_hero_sub' => 'Pequeñas salidas compartidas para viajeros solos y parejas: el precio de un grupo, la sensación de un viaje privado.',
    'groups_hero_cta_quote' => 'Pregunte sobre la próxima salida',

    'groups_how_badge' => 'Cómo funciona',
    'groups_how_title' => 'De la consulta al vehículo',
    'groups_how_1_title' => 'Indíquenos sus fechas',
    'groups_how_1_desc' => 'Envíenos un mensaje con el mes en que desea viajar y cuántos días tiene.',
    'groups_how_2_title' => 'Le asignamos una salida',
    'groups_how_2_desc' => 'Verificamos qué grupo programado está más cerca de sus fechas y confirmamos los lugares disponibles.',
    'groups_how_3_title' => 'Se une a un grupo pequeño',
    'groups_how_3_desc' => 'Máximo 6 personas por vehículo, repartidas entre otros viajeros en las mismas fechas.',
    'groups_how_4_title' => 'Un 4x4 compartido, un guía',
    'groups_how_4_desc' => 'Mismo guía, mismo vehículo y mismo itinerario que un safari privado, a un precio compartido.',

    'groups_why_badge' => 'Por qué unirse a un grupo',
    'groups_why_title' => 'Diseñado para viajeros solos y parejas',
    'groups_why_1_title' => 'Menor costo por persona',
    'groups_why_1_desc' => 'Las tasas de parque y el vehículo son costos fijos, así que compartirlos con 3-5 otros viajeros reduce significativamente su precio.',
    'groups_why_2_title' => 'Conozca gente, no extraños',
    'groups_why_2_desc' => 'Los grupos se mantienen pequeños (máx. 6) y se emparejan por fechas de viaje, no se ensamblan al azar. La mayoría de los huéspedes se conocen para el segundo día.',
    'groups_why_3_title' => 'Misma calidad, sin compromisos',
    'groups_why_3_desc' => 'El mismo estándar de guía, 4x4 e itinerario que nuestros safaris privados. Usted comparte el vehículo, no la experiencia.',

    'groups_departures_badge' => 'Calendario de ejemplo',
    'groups_departures_title' => 'Cómo se ve un calendario de salidas',
    'groups_departures_intro' => 'Este es un ejemplo de cómo se programan nuestras salidas en grupo. Las fechas reales y la disponibilidad de plazas se confirman al contactarnos, ya que cambian a medida que llegan las reservas.',
    'groups_departures_col_departure' => 'Salida',
    'groups_departures_col_itinerary' => 'Itinerario',
