    'groups_faq_title' => 'Preguntas comunes',
    'groups_faq_q1' => '¿Qué pasa si una salida no se llena?',
    'groups_faq_a1' => 'Nuestras salidas programadas funcionan con un mínimo de 2 viajeros. Si se han reservado menos personas, se lo comunicaremos con antelación en lugar de cancelar a última hora. Puede esperar a la próxima fecha o preguntar por un safari privado a un precio ajustado.',
    'groups_faq_q2' => '¿Puedo reservar un safari en grupo estando solo?',
    'groups_faq_a2' => 'Sí, la mayoría de nuestros viajeros en grupo viajan solos. Compartirá el vehículo y el guía con un pequeño número de otros viajeros en las mismas fechas, no será el único huésped.',
    'groups_faq_q3' => '¿Con cuánta antelación debo reservar?',
    'groups_faq_a3' => 'Para junio a octubre (temporada alta), apunte a 2-3 meses de antelación. Fuera de esa ventana, 3-4 semanas suelen ser suficientes, pero escríbanos con antelación si sus fechas son fijas.',
    'groups_faq_q4' => '¿Pueden las parejas o amigos viajar juntos dentro de un safari en grupo?',
    'groups_faq_a4' => 'Sí, compartirá el vehículo con otros viajeros pero se sentará junto como pareja o grupo pequeño. Simplemente llenamos las plazas restantes con otros huéspedes en las mismas fechas.',

    'pkg3d_meta_title' => 'Safari Serengeti de 3 días | Serengeti Budget Safari',
    'pkg3d_meta_description' => 'Un safari de 3 días por el Serengeti Central y el Cráter del Ngorongoro: Big Five, depredadores, 4x4 privado, desde 1.000 € por persona. El precio baja automáticamente para grupos más grandes.',
    'pkg3d_hero_badge' => 'Más vendido',
    'pkg3d_hero_title' => 'Safari Serengeti de 3 días',
    'pkg3d_hero_sub' => 'Serengeti Central y Cráter del Ngorongoro: la forma más rápida de ver los Big Five sin apresurar el viaje.',

