    'pkg3d_calc_wa_template' => "Hola, estoy interesado/a en el Safari Serengeti de 3 días para {people} personas. Precio estimado: {pp} p.p. ({total} total). ¿Puede confirmar disponibilidad?",

    'pkg3d_itinerary_badge' => 'Día a día',
    'pkg3d_itinerary_title' => 'Su itinerario',
    'pkg3d_itinerary_intro' => 'Cada parada, cada trayecto, cada comida: aquí está exactamente cómo serán sus tres días.',

    'pkg3d_day1_title' => 'Arusha al Serengeti',
    'pkg3d_day1_mood' => 'Karibu Sana, bienvenido a Tanzania.',
    'pkg3d_day1_tl1_time' => '07:00',
    'pkg3d_day1_tl1_title' => 'Recogida en Arusha',
    'pkg3d_day1_tl1_desc' => 'Su chófer-guía le espera en su hotel, con el Land Cruiser cargado y listo. Este es el momento en que el viaje realmente comienza, todo antes de esto era solo planificación.',
    'pkg3d_day1_tl2_time' => '09:30',
    'pkg3d_day1_tl2_title' => 'Tierras altas del Ngorongoro',
    'pkg3d_day1_tl2_desc' => 'El camino asciende hacia un fresco y neblinoso bosque de tierras altas. Una breve parada en el mirador del cráter le da su primera vista hacia la caldera, y la mayoría de los huéspedes guardan silencio por un momento aquí.',
    'pkg3d_day1_tl3_time' => '12:00',
    'pkg3d_day1_tl3_title' => 'Descenso hacia el Serengeti',
    'pkg3d_day1_tl3_desc' => 'Las tierras altas quedan atrás y las llanuras se abren: este es el "Serengeti" que los masái nombraron por su infinitud. El almuerzo es un picnic con una vista que la mayoría de los restaurantes no pueden igualar.',
    'pkg3d_day1_tl4_time' => '15:30',
    'pkg3d_day1_tl4_title' => 'Primer game drive',
    'pkg3d_day1_tl4_desc' => 'Llegará al campamento a través del monte, no por la carretera, en un game drive de la tarde que ha producido más avistamientos de leones el primer día de los que podemos contar. Lentamente, el campamento aparece a la vista.',
    'pkg3d_day1_tl5_time' => '18:30',
    'pkg3d_day1_tl5_title' => 'Campamento, cena, primera noche bajo lona',
    'pkg3d_day1_tl5_desc' => 'Instálese en su tienda antes del anochecer. La cena se sirve bajo las estrellas, y en algún lugar por ahí, el Serengeti ya está despierto. Probablemente se quede dormido con ese sonido.',
    'pkg3d_day1_drive' => '4–5 horas en coche',
    'pkg3d_day1_meals' => 'Almuerzo y cena',
    'pkg3d_day1_stay' => 'Campamento con tienda en el Serengeti',

    'pkg3d_day2_title' => 'Día completo, Serengeti Central',
    'pkg3d_day2_mood' => 'Hay tanto que ver que vale cada hora.',
    'pkg3d_day2_tl1_time' => '06:00',
    'pkg3d_day2_tl1_title' => 'Game drive al amanecer',
    'pkg3d_day2_tl1_desc' => 'La mejor hora de cualquier día de safari. Los depredadores que cazaron durante la noche siguen fuera, la luz es suave y dorada, y las llanuras de Seronera, con la mayor densidad de depredadores de África, empiezan a moverse.',
    'pkg3d_day2_tl2_time' => '08:30',
    'pkg3d_day2_tl2_title' => 'Desayuno en el monte',
    'pkg3d_day2_tl2_desc' => 'Se pone una mesa donde le encuentre la mañana, a veces con vista a cebras pastando. Es, sin excepción, el mejor escenario de desayuno que nuestros huéspedes hayan tenido jamás.',
    'pkg3d_day2_tl3_time' => '10:00',
    'pkg3d_day2_tl3_title' => 'Exploración de todo el día',
    'pkg3d_day2_tl3_desc' => 'El resto del día transcurre sin prisas: su guía interpreta la radio y las huellas en la tierra para decidir hacia dónde ir después. Este es el momento en que el Serengeti deja de ser un lugar que se visita y comienza a ser un lugar que se vive.',
    'pkg3d_day2_tl4_time' => '13:00',
    'pkg3d_day2_tl4_title' => 'Almuerzo para llevar, dondequiera que esté',
    'pkg3d_day2_tl4_desc' => 'Sin prisa por volver al campamento. El almuerzo viene a usted, bajo una acacia, con las llanuras extendiéndose en todas direcciones.',
    'pkg3d_day2_tl5_time' => '19:00',
    'pkg3d_day2_tl5_title' => 'Cena bajo las estrellas',
    'pkg3d_day2_tl5_desc' => 'De vuelta en el campamento, se enciende la fogata y las historias del día se cuentan y se vuelven a contar. Pregunte a su guía sobre el nombre del Serengeti, "llanuras sin fin" en masái, y por qué se ha ganado cada sílaba de él.',
    'pkg3d_day2_drive' => 'Día completo, fuera de pista',
    'pkg3d_day2_meals' => 'Desayuno, almuerzo y cena',
    'pkg3d_day2_stay' => 'Campamento con tienda en el Serengeti',

    'pkg3d_day3_title' => 'Cráter del Ngorongoro a Arusha',
    'pkg3d_day3_mood' => 'Hoy, la octava maravilla del mundo.',
    'pkg3d_day3_tl1_time' => '05:30',
    'pkg3d_day3_tl1_title' => 'Salida temprana',
    'pkg3d_day3_tl1_desc' => 'Un comienzo antes del amanecer vale la pena hoy. El desayuno viene empacado, y estará en la carretera mientras el Serengeti todavía se despierta a su alrededor.',
    'pkg3d_day3_tl2_time' => '08:00',
    'pkg3d_day3_tl2_title' => 'Borde del cráter, primera luz',
    'pkg3d_day3_tl2_desc' => 'La vista desde el borde le pone la piel de gallina a casi todo el mundo, y no solo por el frío a 2.300 metros. Debajo de usted, 264 km² de caldera albergan una de las concentraciones más densas de fauna en la Tierra.',
    'pkg3d_day3_tl3_time' => '09:00',
    'pkg3d_day3_tl3_title' => 'Descenso al fondo del cráter',
    'pkg3d_day3_tl3_desc' => 'La pista desciende serpenteando hasta 1.700 metros. Esta es su mejor oportunidad en Tanzania de ver rinoceronte negro, junto con leones, elefantes y las manadas de cebras y ñus que nunca abandonan el fondo del cráter.',
    'pkg3d_day3_tl4_time' => '12:30',
    'pkg3d_day3_tl4_title' => 'Almuerzo picnic, fondo del cráter',
    'pkg3d_day3_tl4_desc' => 'El almuerzo se toma con las paredes del cráter elevándose a su alrededor, uno de los comedores más surrealistas en los que se sentará jamás.',
    'pkg3d_day3_tl5_time' => '14:30',
    'pkg3d_day3_tl5_title' => 'Salida, camino a Arusha',
    'pkg3d_day3_tl5_desc' => 'La salida del cráter es tan espectacular como la entrada, así que eche un último vistazo atrás. Desde aquí, son unas horas de viaje de vuelta a Arusha, llegando a última hora de la tarde con tres días de historias que contar.',
    'pkg3d_day3_drive' => '4–5 horas en coche',
    'pkg3d_day3_meals' => 'Desayuno y almuerzo',
    'pkg3d_day3_stay' => 'Fin del viaje, Arusha',

    'pkg3d_included_heading' => 'Incluido',
    'pkg3d_included_1' => 'Land Cruiser 4x4 con techo elevable y asiento ventana garantizado',
    'pkg3d_included_2' => 'Chófer-guía de habla inglesa (italiano bajo petición)',
    'pkg3d_included_3' => 'Todas las tasas de entrada y conservación de los parques',
    'pkg3d_included_4' => '2 noches de alojamiento en campamento con tienda, pensión completa',
    'pkg3d_included_5' => 'Agua potable durante los game drives',
    'pkg3d_included_6' => 'Recogida y traslado en Arusha',
    'pkg3d_excluded_heading' => 'No incluido',
    'pkg3d_excluded_1' => 'Vuelos internacionales y visa tanzana',
    'pkg3d_excluded_2' => 'Seguro de viaje (obligatorio)',
    'pkg3d_excluded_3' => 'Bebidas que no sean agua, y gastos personales',
    'pkg3d_excluded_4' => 'Propinas para el guía y el personal del campamento',
    'pkg3d_excluded_5' => 'Vuelo opcional en globo sobre el Serengeti',

    'pkg3d_gallery_badge' => 'Lo que verá',
    'pkg3d_gallery_title' => 'Serengeti y Ngorongoro en imágenes',

    'pkg3d_faq_title' => 'Preguntas sobre este safari',
    'pkg3d_faq_q1' => '¿Son suficientes 3 días para ver el Serengeti?',
    'pkg3d_faq_a1' => 'Es el mínimo práctico. Obtiene un día completo dentro del parque más el Cráter del Ngorongoro, que entre ambos cubren las mayores concentraciones de fauna de Tanzania. Los viajes más largos añaden más parques, no más del Serengeti en sí.',
    'pkg3d_faq_q2' => '¿Veré los Big Five?',
    'pkg3d_faq_a2' => 'León, elefante, búfalo y leopardo se ven regularmente en esta ruta. El rinoceronte negro solo es realista en el Cráter del Ngorongoro, por eso este itinerario lo incluye. Ningún operador puede garantizar el avistamiento de un animal salvaje, pero esta combinación le ofrece las mejores probabilidades del país.',
    'pkg3d_faq_q3' => '¿Puedo extender esto a más días?',
    'pkg3d_faq_a3' => 'Sí, este itinerario es la base de nuestros paquetes de 4, 5 y 8 días, que añaden Tarangire, más días en el Serengeti, o la ruta de la migración. Indíquenos sus fechas y lo ajustaremos.',

    'pkg3d_cta_title' => '¿Listo para reservar este safari?',
    'pkg3d_cta_intro' => 'Envíenos sus fechas y el tamaño del grupo. Respondemos con un itinerario escrito y el precio final, sin compromiso.',
    'pkg3d_cta_whatsapp' => 'Escríbanos por WhatsApp',
    'pkg3d_cta_contact_form' => 'Reservar ahora',

    'pkg5d_meta_title' => 'Safari Serengeti y Ngorongoro de 5 días | Serengeti Budget Safari',
    'pkg5d_meta_description' => 'Safari de 5 días en Tanzania por Tarangire, Serengeti y Ngorongoro: Big Five, 4x4 privado, todas las tasas de parque incluidas, desde 650 € por persona.',

    'pkg5d_type' => 'Safari Privado',
    'pkg5d_budget' => 'Económico',
