    'pkg5d_gallery_view_all' => 'Ver todas las fotos',

    'pkg5d_overview_badge' => 'Descripción general',
    'pkg5d_overview_title' => 'Viva el corazón salvaje de Tanzania',
    'pkg5d_overview_p1' => 'Viva un inolvidable safari de 5 días en Tanzania por Tarangire, Serengeti y Ngorongoro. Busque los Big Five, explore paisajes impresionantes y disfrute de un alojamiento cómodo mientras viaja en un vehículo de safari 4x4 privado.',
    'pkg5d_overview_p2' => 'Cada game drive está dirigido por nuestros propios guías, en nuestros propios vehículos: el mismo equipo desde la primera recogida en Arusha hasta el último traslado. Sin vehículos subcontratados, sin itinerarios compartidos con extraños a menos que elija una salida en grupo.',
    'pkg5d_love_title' => "Por qué le encantará este safari",
    'pkg5d_love_1' => 'Oportunidades de ver los Big Five',
    'pkg5d_love_2' => 'Guía de safari profesional',
    'pkg5d_love_3' => 'Vehículo 4x4 privado',
    'pkg5d_love_4' => 'Todas las tasas de parque incluidas',
    'pkg5d_love_5' => 'Itinerario flexible',
    'pkg5d_love_6' => 'Campamentos con tienda confortables',

    'pkg5d_route_badge' => 'El viaje',
    'pkg5d_route_title' => 'Ruta del safari',
    'pkg5d_route_arusha' => 'Arusha',
    'pkg5d_route_tarangire' => 'Tarangire',
    'pkg5d_route_serengeti' => 'Serengeti',
    'pkg5d_route_ngorongoro' => 'Ngorongoro',

    'pkg5d_itinerary_badge' => 'Día a día',
    'pkg5d_itinerary_title' => 'Su itinerario',
    'pkg5d_itinerary_intro' => 'Toque un día para expandirlo.',

    'pkg5d_day1_title' => 'Arusha → Parque Nacional de Tarangire',
    'pkg5d_day1_mood' => 'Karibu Sana, bienvenido a Tanzania.',
    'pkg5d_day1_drive' => '2–3 horas en coche',
    'pkg5d_day1_meals' => 'Almuerzo y cena',
    'pkg5d_day1_stay' => 'Marera Valley Lodge',
    'pkg5d_day1_desc' => 'Recogida en su hotel de Arusha a media mañana y viaje al Parque Nacional de Tarangire, famoso por sus baobabs y enormes manadas de elefantes. Game drive de la tarde a lo largo del río Tarangire antes de registrarse en su lodge.',
    'pkg5d_day1_act1' => 'Game drive',
    'pkg5d_day1_act2' => 'Observación de fauna',
    'pkg5d_day1_tl1_time' => '09:30',
    'pkg5d_day1_tl1_title' => 'Recogida en Arusha',
    'pkg5d_day1_tl1_desc' => 'Un comienzo a media mañana significa no tener alarma antes del amanecer en su primer día. Su chófer-guía carga el Land Cruiser y el viaje finalmente, realmente, está sucediendo.',
    'pkg5d_day1_tl2_time' => '12:00',
    'pkg5d_day1_tl2_title' => 'Entrada a Tarangire',
    'pkg5d_day1_tl2_desc' => 'La puerta del parque marca el inicio del país de los baobabs, y algunos de estos árboles llevan en pie más de mil años. Los elefantes se reúnen aquí en números que casi no se encuentran en ningún otro lugar de Tanzania.',
    'pkg5d_day1_tl3_time' => '14:30',
    'pkg5d_day1_tl3_title' => 'Game drive de la tarde',
    'pkg5d_day1_tl3_desc' => 'Siguiendo el río Tarangire, donde la fauna se concentra incluso en los meses secos. Observe familias de elefantes cruzando en fila india, y los baobabs erguidos como centinelas sobre todo ello.',
    'pkg5d_day1_tl4_time' => '17:30',
    'pkg5d_day1_tl4_title' => 'Registro, Marera Valley Lodge',
    'pkg5d_day1_tl4_desc' => 'Su primera noche marca el tono del viaje: cena con vista al valle, y el sonido de Tarangire adentrándose en la oscuridad.',

    'pkg5d_day2_title' => 'Tarangire → Serengeti Central',
    'pkg5d_day2_mood' => 'De los baobabs a las llanuras sin fin.',
    'pkg5d_day2_drive' => '4–5 horas en coche',
    'pkg5d_day2_meals' => 'Desayuno, almuerzo y cena',
    'pkg5d_day2_stay' => 'Campamento con tienda en el Serengeti',
    'pkg5d_day2_desc' => 'Viaje matutino hacia el oeste a través del Gran Valle del Rift hasta el Serengeti central, con una parada en un mirador masái. Game drive de la tarde a la llegada, buscando leones y guepardos en las llanuras abiertas.',
    'pkg5d_day2_act1' => 'Trayecto panorámico',
    'pkg5d_day2_act2' => 'Game drive de la tarde',
    'pkg5d_day2_tl1_time' => '07:30',
    'pkg5d_day2_tl1_title' => 'Hacia el oeste a través del Valle del Rift',
    'pkg5d_day2_tl1_desc' => 'El camino desciende de las tierras altas hacia el Gran Valle del Rift, uno de los pocos lugares en la Tierra donde puede ver la historia tectónica del planeta simplemente mirando por la ventana.',
    'pkg5d_day2_tl2_time' => '10:00',
    'pkg5d_day2_tl2_title' => 'Mirador masái',
    'pkg5d_day2_tl2_desc' => 'Una breve parada donde la tierra se abre ante usted: su primer vistazo real de lo que realmente significan las "llanuras sin fin".',
    'pkg5d_day2_tl3_time' => '13:00',
    'pkg5d_day2_tl3_title' => 'Llegada, Serengeti central',
    'pkg5d_day2_tl3_desc' => 'Ahora está en el territorio de los grandes felinos. Un game drive de la tarde el día de la llegada tiene la costumbre de producir avistamientos de leones y guepardos antes de que haya deshecho las maletas.',
    'pkg5d_day2_tl4_time' => '18:30',
    'pkg5d_day2_tl4_title' => 'Campamento, primera noche en el Serengeti',
    'pkg5d_day2_tl4_desc' => 'Cena bajo lona, con las llanuras extendiéndose oscuras y silenciosas en todas direcciones fuera de la luz del fuego.',

    'pkg5d_day3_title' => 'Día completo en el Serengeti',
    'pkg5d_day3_mood' => 'Hay tanto que ver que vale cada hora.',
    'pkg5d_day3_drive' => 'Game drives dentro del parque',
    'pkg5d_day3_meals' => 'Desayuno, almuerzo y cena',
    'pkg5d_day3_stay' => 'Campamento con tienda en el Serengeti',
    'pkg5d_day3_desc' => 'Un día completo explorando la región de Seronera, la mayor densidad de depredadores del parque. Almuerzo para llevar en el monte, con la opción de extender el trayecto de la tarde hacia el río Mara en temporada de migración.',
    'pkg5d_day3_act1' => 'Game drive de todo el día',
    'pkg5d_day3_act2' => 'Almuerzo en el monte',
    'pkg5d_day3_tl1_time' => '06:00',
    'pkg5d_day3_tl1_title' => 'Game drive al amanecer',
    'pkg5d_day3_tl1_desc' => 'La mejor hora de cualquier día de safari. Los depredadores que cazaron durante la noche suelen seguir visibles, y la región de Seronera se despierta a su alrededor con luz dorada.',
    'pkg5d_day3_tl2_time' => '09:00',
    'pkg5d_day3_tl2_title' => 'Desayuno en el monte',
    'pkg5d_day3_tl2_desc' => 'Una mesa puesta donde le encuentre la mañana. Es un fuerte candidato a la mejor vista de desayuno que tendrá jamás.',
    'pkg5d_day3_tl3_time' => '11:00',
    'pkg5d_day3_tl3_title' => 'Exploración de todo el día',
    'pkg5d_day3_tl3_desc' => 'Su guía interpreta la radio y las huellas en la tierra para decidir hacia dónde lleva el día. En temporada de migración, este es el momento en que el trayecto puede extenderse hacia el norte, hacia los cruces del río Mara.',
    'pkg5d_day3_tl4_time' => '19:00',
    'pkg5d_day3_tl4_title' => 'Cena, historias junto al fuego',
    'pkg5d_day3_tl4_desc' => 'De vuelta en el campamento, los avistamientos del día se cuentan y se vuelven a contar junto al fuego. Pregunte a su guía qué significa "Serengeti" en masái, y por qué el nombre se ha ganado cada sílaba.',

    'pkg5d_day4_title' => 'Serengeti → Ngorongoro',
    'pkg5d_day4_mood' => 'Un último vistazo a las llanuras, y luego hacia las nubes.',
    'pkg5d_day4_drive' => '3–4 horas en coche',
    'pkg5d_day4_meals' => 'Desayuno, almuerzo y cena',
    'pkg5d_day4_stay' => 'Ngorongoro Rim Lodge',
    'pkg5d_day4_desc' => 'Último game drive matutino en el Serengeti antes de subir a las tierras altas del Ngorongoro. Tarde libre en su lodge en el borde del cráter, con vistas panorámicas sobre la caldera.',
    'pkg5d_day4_act1' => 'Game drive matutino',
    'pkg5d_day4_act2' => 'Vistas del borde del cráter',
    'pkg5d_day4_tl1_time' => '06:30',
    'pkg5d_day4_tl1_title' => 'Último game drive en el Serengeti',
    'pkg5d_day4_tl1_desc' => 'Un amanecer más en las llanuras antes de partir, una forma adecuada de despedirse de un lugar difícil de dejar.',
    'pkg5d_day4_tl2_time' => '10:00',
    'pkg5d_day4_tl2_title' => 'Ascenso a las tierras altas',
    'pkg5d_day4_tl2_desc' => 'El camino se eleva desde las llanuras hacia un fresco y neblinoso bosque de tierras altas, una Tanzania completamente diferente de la que dejó esa mañana.',
    'pkg5d_day4_tl3_time' => '14:00',
    'pkg5d_day4_tl3_title' => 'Registro, borde del cráter',
    'pkg5d_day4_tl3_desc' => 'Su lodge está en el borde del Cráter del Ngorongoro, una de las vistas más extraordinarias de todo el safari, y una tarde tranquila para disfrutarla.',
    'pkg5d_day4_tl4_time' => '19:00',
    'pkg5d_day4_tl4_title' => 'Cena con vistas',
    'pkg5d_day4_tl4_desc' => 'Mientras la luz se desvanece sobre la caldera abajo, la mayoría de los huéspedes coinciden en que este es el escenario de cena que más recuerdan.',

    'pkg5d_day5_title' => 'Ngorongoro → Arusha',
    'pkg5d_day5_mood' => 'Hoy, la octava maravilla del mundo.',
    'pkg5d_day5_drive' => '3 horas en coche',
    'pkg5d_day5_meals' => 'Desayuno y almuerzo',
    'pkg5d_day5_stay' => 'Salida',
    'pkg5d_day5_desc' => 'Descienda al Cráter del Ngorongoro al amanecer para tener la mejor oportunidad de ver rinoceronte negro, junto con densas concentraciones de leones, elefantes y búfalos. Suba de nuevo a media mañana y regrese a Arusha, llegando por la tarde.',
    'pkg5d_day5_act1' => 'Game drive por el fondo del cráter',
    'pkg5d_day5_act2' => 'Traslado en Arusha',
    'pkg5d_day5_tl1_time' => '06:00',
    'pkg5d_day5_tl1_title' => 'Descenso al fondo del cráter',
    'pkg5d_day5_tl1_desc' => 'La pista desciende serpenteando hasta 1.700 metros, hacia una caldera de 264 km² que alberga una de las concentraciones más densas de fauna en la Tierra, y su mejor oportunidad en Tanzania de ver rinoceronte negro.',
    'pkg5d_day5_tl2_time' => '09:30',
    'pkg5d_day5_tl2_title' => 'El fondo del cráter',
    'pkg5d_day5_tl2_desc' => 'Leones, elefantes, búfalos y las manadas de cebras y ñus que nunca abandonan el fondo del cráter, todo dentro de un espacio lo bastante pequeño como para sentirse como una reserva de fauna privada.',
    'pkg5d_day5_tl3_time' => '11:30',
    'pkg5d_day5_tl3_title' => 'Ascenso de salida',
    'pkg5d_day5_tl3_desc' => 'La salida es tan espectacular como el descenso, así que eche un último vistazo atrás antes de que el camino gire hacia Arusha.',
    'pkg5d_day5_tl4_time' => '15:00',
    'pkg5d_day5_tl4_title' => 'Traslado en Arusha',
    'pkg5d_day5_tl4_desc' => 'Su viaje termina donde comenzó, con cinco días de historias y, si es como nuestros huéspedes anteriores, ya planeando su regreso.',

