    'contact_meta_title' => 'Contáctenos | Serengeti Budget Safari',
    'contact_meta_description' => 'Póngase en contacto con Serengeti Budget Safari: envíenos sus fechas de viaje y tamaño de grupo para un itinerario y precio escritos, o escríbanos directamente por WhatsApp.',
