    'contact_faq_title' => 'Antes de escribirnos',
    'contact_faq_q1' => '¿Con qué rapidez recibiré una respuesta?',
    'contact_faq_a1' => 'Los mensajes de WhatsApp generalmente se responden en menos de una hora durante nuestro horario de trabajo. Las consultas por formulario de contacto y correo electrónico se responden en 24 horas.',
    'contact_faq_q2' => '¿Necesito pagar algo para obtener un presupuesto?',
    'contact_faq_a2' => 'No. Todo presupuesto e itinerario escrito es gratuito y sin obligación de reservar.',
    'contact_faq_q3' => "¿Qué pasa si aún no sé mis fechas exactas?",
    'contact_faq_a3' => 'No hay problema. Indíquenos su mes aproximado o un rango de fechas y le asesoraremos sobre disponibilidad y precios para ese período.',

    'arusha_meta_title' => 'Guía del Parque Nacional de Arusha (2026) | Serengeti Budget Safari',
    'arusha_meta_description' => 'Guía del Parque Nacional de Arusha: monte Meru, los lagos Momella, safaris a pie, leones trepadores de árboles, tasas de parque 2026, cuándo ir y dónde alojarse. A 40 minutos de la ciudad de Arusha.',
    'arusha_hero_badge' => 'Parque Nacional de Arusha',
    'arusha_hero_title' => 'Parque Nacional de Arusha',
    'arusha_hero_sub' => "El parque más infravalorado de Tanzania: el monte Meru, los lagos Momella y safaris a pie, a solo 40 minutos de Arusha.",
    'arusha_hero_cta_quote' => 'Solicitar presupuesto',

    'arusha_intro_badge' => 'Descripción general',
    'arusha_intro_title' => 'Un pequeño parque con una diversidad de paisajes desproporcionada',
    'arusha_intro_p1' => "El Parque Nacional de Arusha es el parque más conveniente de Tanzania, a 40 minutos de la ciudad de Arusha y a menudo visitado como excursión de medio día o como día de aclimatación antes de una ascensión al Kilimanjaro o al Meru. A pesar de su tamaño, cubre cuatro paisajes distintos en una sola visita: el Cráter de Ngurdoto, los lagos Momella, el bosque montano, y las laderas inferiores del propio monte Meru.",
    'arusha_intro_p2' => "También es uno de los tres únicos parques de Tanzania donde se permiten safaris a pie, y el único lugar cerca de Arusha donde se puede hacer canoa entre hipopótamos y flamencos en los lagos Momella.",
    'arusha_intro_p3' => "La mayoría de los visitantes lo combinan con un itinerario de medio día, aunque también sirve como trek de aclimatación antes de escalar el monte Meru, cuya cumbre se encuentra dentro de los límites del parque.",
    'arusha_fact_area' => 'Superficie',
    'arusha_fact_established' => 'Fundado en',
    'arusha_fact_meru' => 'Cumbre del monte Meru',
    'arusha_fact_birds' => 'Especies de aves',
    'arusha_fact_lions' => 'Depredadores',
    'arusha_fact_lions_value' => 'Leopardo, presente pero raramente visto',
    'arusha_fact_stay' => 'Visita típica',
    'arusha_fact_stay_value' => 'Medio día, o 3–4 días para el Meru',
    'arusha_fact_from_arusha' => 'Desde la ciudad de Arusha',
    'arusha_fact_from_airport' => 'Desde el Aeropuerto del Kilimanjaro',

    'arusha_regions_badge' => 'Tres paisajes en un parque',
    'arusha_regions_title' => 'Qué ver',
    'arusha_regions_intro' => 'Arusha reúne una diversidad de terreno inusual en una pequeña área. Planifique su ruta alrededor de estas tres zonas.',
    'arusha_region_ngurdoto_name' => 'Cráter de Ngurdoto',
    'arusha_region_ngurdoto_desc' => 'Un fondo de cráter exuberante y pantanoso rodeado de bosque, a menudo llamado el "pequeño Ngorongoro". Los vehículos no pueden descender a él, por lo que la observación se hace desde el borde, mirando hacia abajo a búfalos, facóqueros y kobos de agua pastando.',
    'arusha_region_momella_name' => 'Lagos Momella',
    'arusha_region_momella_desc' => 'Una cadena de lagos alcalinos poco profundos, cada uno de un tono diferente de verde o azul según su contenido de algas y minerales. Flamencos, jirafas y búfalos se reúnen en las orillas, y aquí es donde parten los safaris en canoa.',
    'arusha_region_meru_name' => 'Monte Meru',
    'arusha_region_meru_desc' => "El quinto pico más alto de África a 4.566 m, y el telón de fondo dramático de la mayor parte del parque. Escalable en 3–4 días, con muchos menos excursionistas que el Kilimanjaro y magníficas vistas del propio Kilimanjaro en un día despejado.",

    'arusha_walking_badge' => 'Un permiso poco común',
    'arusha_walking_title' => 'Safaris a pie',
    'arusha_walking_intro' => 'Arusha es uno de los tres únicos parques de Tanzania donde se permiten los safaris a pie. La mayoría de los parques del circuito norte exigen permanecer en el vehículo.',
    'arusha_walking_p1' => 'Las caminatas guiadas con un ranger armado le permiten acercarse a jirafas, cebras y búfalos a pie, leyendo huellas y excrementos, y escuchando el monte a nivel del suelo en lugar de a través de un parabrisas.',
    'arusha_walking_p2' => 'Como los grandes depredadores están mayormente ausentes, caminar aquí es más seguro que en los parques más grandes. Los encuentros peligrosos son casi siempre con búfalos, que el ranger está entrenado para manejar a una distancia segura.',

    'arusha_wildlife_badge' => 'Lo que vive aquí',
    'arusha_wildlife_title' => 'Fauna',
    'arusha_wildlife_intro' => 'Arusha no tiene leones y muy poco del clásico "gran gibio" del Serengeti. Su atractivo faunístico es diferente: primates, aves y especies forestales que no verá en un safari de sabana.',
    'arusha_animal_giraffe' => 'Jirafa',
    'arusha_animal_colobus' => 'Colobo blanco y negro',
    'arusha_animal_zebra' => 'Cebra',
    'arusha_animal_buffalo' => 'Búfalo',
    'arusha_animal_waterbuck' => 'Kobo de agua',
    'arusha_animal_flamingo' => 'Flamenco',
    'arusha_animal_elephant' => 'Elefante (ocasional)',
    'arusha_animal_warthog' => 'Facóquero',
    'arusha_wildlife_p1' => "La verdadera especialidad del parque son sus tropas de colobos blancos y negros, fácilmente vistos en el bosque montano, junto con más de 400 especies de aves registradas solo alrededor de los lagos Momella.",
    'arusha_wildlife_p2' => 'Los avistamientos de elefantes ocurren pero son ocasionales más que fiables. Este no es el parque a elegir si los Big Five son su prioridad, pero recompensa a los visitantes interesados en paisajes, aves y un ritmo más tranquilo.',

    'arusha_when_badge' => 'Planificación',
    'arusha_when_title' => 'Cuándo ir',
    'arusha_when_intro' => 'Arusha es un parque abierto todo el año: su baja altitud y proximidad a la ciudad hacen que rara vez cierre, a diferencia de los treks de mayor altitud.',
    'arusha_when_p1' => 'De junio a octubre (temporada seca) ofrece las vistas más despejadas del monte Meru y el Kilimanjaro, y las condiciones de caminata más fáciles.',
    'arusha_when_p2' => 'Los meses más húmedos (marzo–mayo) tiñen el cráter y los bordes del lago de un verde intenso y atraen más aves, aunque las pistas pueden estar embarradas y las vistas de la montaña menos fiables.',

    'arusha_stay_badge' => 'Dónde alojarse',
    'arusha_stay_title' => 'Alojamiento',
    'arusha_stay_intro' => "La mayoría de los visitantes se alojan en la ciudad de Arusha y visitan el parque en excursión de un día, pero algunos establecimientos están cerca de la entrada del parque para quienes escalan el Meru o lo combinan con otro parque.",
    'arusha_stay_town_title' => 'Ciudad de Arusha',
    'arusha_stay_town_price' => 'Económico – Lujo',
    'arusha_stay_town_desc' => 'La opción más común: a 30–40 minutos de la entrada del parque, con la mayor variedad de hoteles y traslados fáciles hacia el Aeropuerto del Kilimanjaro o el circuito norte.',
    'arusha_stay_lodge_title' => 'Lodges cerca de la entrada',
    'arusha_stay_lodge_price' => 'Gama media – Lujo',
    'arusha_stay_lodge_desc' => 'Un puñado de lodges se encuentran a corta distancia en coche de la entrada del parque, útiles para un comienzo temprano en una ascensión al Meru o un safari a pie al amanecer.',
    'arusha_stay_camp_title' => 'Refugios de montaña del Meru',
    'arusha_stay_camp_price' => 'Incluido en el paquete de trek',
    'arusha_stay_camp_desc' => 'Los escaladores pernoctan en una serie de refugios de montaña durante el ascenso, Miriakamba y Saddle Hut, incluidos como parte de cualquier paquete de trekking del monte Meru.',
    'arusha_stay_note' => 'Podemos organizar alojamiento en cualquier nivel como parte de una excursión de un día o un paquete de trekking al Meru. Pregúntenos por la disponibilidad actual.',

    'arusha_fees_badge' => 'Tasas 2026',
    'arusha_fees_title' => 'Tasas de entrada al parque',
    'arusha_fees_intro' => 'Las tasas son por persona por período de 24 horas e incluyen el 18% de IVA. Se pagan con tarjeta o tarjeta de parque precargada. No se acepta efectivo en la entrada.',
    'arusha_table_category' => 'Categoría',
    'arusha_table_adult' => 'Adulto',
    'arusha_table_child' => 'Niño (5–15)',
    'arusha_fee_entry' => 'Entrada al parque',
    'arusha_fee_concession' => 'Concesión de trekking del Meru',
    'arusha_fee_campsite' => 'Tasa de campamento',
    'arusha_fees_note' => 'Cuando viaja con nosotros, todas las tasas de parque se calculan y se incluyen en el precio cotizado, sin necesidad de pago separado en la entrada.',

    'arusha_gallery_badge' => 'Arusha en imágenes',
    'arusha_gallery_title' => 'Lo que verá',
    'arusha_gallery_caption_1' => 'Colobos en el bosque',
    'arusha_gallery_caption_2' => 'Sabana al amanecer',
    'arusha_gallery_caption_3' => 'Piragüismo en los lagos Momella',
    'arusha_gallery_caption_4' => 'Cebras en las llanuras',
    'arusha_gallery_caption_5' => 'Elefante bajo una acacia',
    'arusha_gallery_caption_6' => 'Un borde de cráter, similar en forma al de Ngurdoto',

    'arusha_back_to_parks' => 'Comparar los nueve parques',

    'arusha_faq_badge' => 'Preguntas frecuentes',
    'arusha_faq_title' => 'Preguntas comunes',
    'arusha_faq_q1' => '¿Puedo visitar el Parque Nacional de Arusha en medio día?',
    'arusha_faq_a1' => "Sí, es la forma más común de visitarlo, generalmente combinada con una salida matutina desde la ciudad de Arusha y regreso a primera hora de la tarde.",
    'arusha_faq_q2' => '¿Veré los Big Five aquí?',
    'arusha_faq_a2' => 'No. Arusha no tiene leones ni rinocerontes, y los avistamientos de elefantes son ocasionales. Se elige por el paisaje, los safaris a pie, los colobos y las aves más que por los Big Five.',
    'arusha_faq_q3' => '¿Es seguro caminar aquí?',
    'arusha_faq_a3' => 'Sí, relativamente. La ausencia de leones hace de Arusha uno de los parques más seguros para caminar, aunque los búfalos todavía requieren precaución y un ranger armado siempre acompaña a los grupos que caminan.',
    'arusha_faq_q4' => '¿Puedo escalar el monte Meru sin escalar el Kilimanjaro?',
    'arusha_faq_a4' => 'Sí, el Meru es un trek independiente y una opción popular por derecho propio. Muchos escaladores lo prefieren por sus senderos más tranquilos y su dramática caminata por el borde del cráter.',
    'arusha_faq_q5' => '¿Cómo se compara el Meru con el Kilimanjaro como ascenso?',
    'arusha_faq_a5' => 'El Meru es más corto (3–4 días frente a 5–9), más empinado en tramos, y mucho menos concurrido. También se usa comúnmente como práctica de aclimatación antes de un intento del Kilimanjaro.',
    'arusha_faq_q6' => '¿Puedo combinar Arusha con otros parques?',
    'arusha_faq_a6' => 'Sí, su proximidad a la ciudad lo convierte en un fácil añadido a un itinerario de Tarangire o Ngorongoro, o un relajado primer/último día de un safari más largo.',
    'arusha_faq_q7' => '¿Hay safaris en canoa?',
    'arusha_faq_a7' => 'Sí, en los lagos Momella: una forma suave de ver hipopótamos, flamencos y aves acuáticas desde el agua, generalmente combinada con una parte a pie o en vehículo de la visita.',
    'arusha_faq_q8' => '¿Se requiere un guía?',
    'arusha_faq_a8' => 'Sí para los safaris a pie y el trek del Meru (un ranger armado es obligatorio), y muy recomendado para los game drives dada la señalización limitada dentro del parque.',

    'arusha_cta_title' => '¿Listo para visitar el Parque Nacional de Arusha?',
    'arusha_cta_intro' => 'Envíenos sus fechas y el tamaño del grupo. Respondemos con un itinerario escrito y el precio completo, sin compromiso.',
    'arusha_cta_whatsapp' => 'Escríbanos por WhatsApp',
    'arusha_cta_safaris' => 'Ver paquetes de safari',

    'kilimanjaro_meta_title' => 'Guía del Parque Nacional del Kilimanjaro (2026) | Serengeti Budget Safari',
    'kilimanjaro_meta_description' => 'Guía del Parque Nacional del Kilimanjaro: las siete rutas comparadas, tasas de parque 2026, tasas de éxito, mal de altura, cuándo escalar y dónde dormir en la montaña.',
    'kilimanjaro_hero_badge' => 'Parque Nacional del Kilimanjaro',
    'kilimanjaro_hero_title' => 'Parque Nacional del Kilimanjaro',
    'kilimanjaro_hero_sub' => "El punto más alto de África a 5.895 m: cinco zonas climáticas, siete rutas, y una cumbre al alcance de cualquier caminante razonablemente en forma.",
    'kilimanjaro_hero_cta_quote' => 'Solicitar presupuesto',

    'kilimanjaro_intro_badge' => 'Descripción general',
    'kilimanjaro_intro_title' => 'El techo de África',
    'kilimanjaro_intro_p1' => "El Kilimanjaro es la montaña más alta de África y el pico independiente más alto del mundo, elevándose desde la sabana a unos 900 m hasta una cumbre glaciada a 5.895 m sin una cordillera conectada. El ascenso es una larga caminata, no una escalada técnica: sin cuerdas, sin equipo de escalada, solo varios días de caminata constante cuesta arriba a través de cinco zonas climáticas distintas.",
    'kilimanjaro_intro_p2' => "Esas zonas (tierras de cultivo, selva tropical, páramo, desierto alpino y la zona cumbre ártica) hacen que un trek al Kilimanjaro se sienta como caminar del ecuador a los polos en menos de una semana.",
    'kilimanjaro_intro_p3' => "El verdadero desafío es la altitud, no la forma física o la habilidad técnica. El factor más importante para alcanzar la cumbre es elegir una ruta con suficientes días para que su cuerpo se aclimate.",
    'kilimanjaro_fact_area' => 'Superficie del parque',
    'kilimanjaro_fact_summit' => 'Cumbre',
    'kilimanjaro_fact_status' => 'Estado',
    'kilimanjaro_fact_routes' => 'Rutas',
    'kilimanjaro_fact_duration' => 'Duración típica',
    'kilimanjaro_fact_success' => 'Rango de tasa de éxito',
    'kilimanjaro_fact_climbers' => 'Escaladores al año',
    'kilimanjaro_fact_days' => 'Mínimo recomendado',
    'kilimanjaro_fact_year' => '5+ días',
    'kilimanjaro_fact_from_arusha' => 'Desde Arusha',

    'kilimanjaro_routes_badge' => 'Elija su camino',
    'kilimanjaro_routes_title' => 'Las rutas',
    'kilimanjaro_routes_intro' => 'Siete rutas oficiales llegan a la cumbre. Estas cuatro son las que ofrecemos, elegidas por su perfil de aclimatación y fiabilidad.',
    'kilimanjaro_route_marangu_name' => 'Marangu',
    'kilimanjaro_route_marangu_desc' => 'La única ruta con alojamiento en refugios en lugar de tiendas, y el mismo camino usado tanto para el ascenso como para el descenso. La opción más corta, lo que también le da la tasa de éxito más baja: menos tiempo para aclimatarse.',
    'kilimanjaro_route_machame_name' => 'Machame',
    'kilimanjaro_route_machame_desc' => 'Conocida como la "Ruta del Whisky" por su reputación de ascenso más duro. Escénica y variada, acampando en tiendas, y la ruta más popular de la montaña gracias a su sólido perfil de aclimatación.',
    'kilimanjaro_route_lemosho_name' => 'Lemosho',
    'kilimanjaro_route_lemosho_desc' => 'Un comienzo más tranquilo a través de selva tropical intacta, uniéndose a la ruta Machame más arriba. Ampliamente considerada la mejor combinación de paisaje y aclimatación.',
    'kilimanjaro_route_rongai_name' => 'Rongai',
    'kilimanjaro_route_rongai_desc' => 'Se aproxima desde el lado norte más seco de la montaña, cerca de la frontera con Kenia. La mejor opción durante los meses de transición lluviosos, cuando las rutas del sur están más húmedas.',

    'kilimanjaro_compare_badge' => 'Comparación',
    'kilimanjaro_compare_title' => 'Comparar todas las rutas',
    'kilimanjaro_compare_intro' => 'Las tasas de éxito son indicativas. Aumentan considerablemente con más días en la montaña, independientemente de la ruta.',
    'kilimanjaro_table_route' => 'Ruta',
    'kilimanjaro_table_days' => 'Días',
    'kilimanjaro_table_sleeping' => 'Alojamiento',
    'kilimanjaro_table_scenery' => 'Paisaje',
    'kilimanjaro_table_success' => 'Tasa de éxito',
    'kilimanjaro_sleep_tents' => 'Tiendas',
    'kilimanjaro_sleep_huts' => 'Refugios',
    'kilimanjaro_scenery_varied' => 'Variado, empinado en tramos',
    'kilimanjaro_scenery_best' => 'El mejor en general',
    'kilimanjaro_scenery_full' => 'Circuito completo de la montaña',
    'kilimanjaro_scenery_direct' => 'Directo, menos variado',
    'kilimanjaro_scenery_dry' => 'Más seco, senderos más tranquilos',
    'kilimanjaro_northern_circuit' => 'Northern Circuit',
    'kilimanjaro_compare_note' => 'La noche adicional en una ruta más larga es el seguro más barato que puede comprar contra el mal de altura. Si su horario lo permite, elija la opción más larga.',

    'kilimanjaro_wildlife_badge' => 'De camino hacia arriba',
    'kilimanjaro_wildlife_title' => 'Fauna en la montaña',
    'kilimanjaro_wildlife_intro' => "El Kilimanjaro no es un destino de observación de fauna, pero las zonas forestales inferiores tienen un interés faunístico genuino. La mayoría de los escaladores se sorprenden de la cantidad de vida que existe en las laderas de la montaña.",
    'kilimanjaro_animal_colobus' => 'Colobo blanco y negro',
    'kilimanjaro_animal_blue_monkey' => 'Mono azul',
    'kilimanjaro_animal_bushbuck' => 'Antílope bushbuck',
    'kilimanjaro_animal_buffalo' => 'Búfalo (zona forestal)',
    'kilimanjaro_animal_elephant' => 'Elefante (zona forestal, raro)',
    'kilimanjaro_animal_sunbird' => 'Suimanga malaquita',
    'kilimanjaro_animal_raven' => 'Cuervo de nuca blanca',
    'kilimanjaro_animal_groundsel' => 'Senecio gigante (planta)',
    'kilimanjaro_wildlife_p1' => 'La zona de selva tropical, cruzada en el primer día o dos en la mayoría de las rutas, es hogar de colobos y monos azules, antílopes forestales y ocasionalmente búfalos o elefantes, todos encontrados en el sendero más que buscados.',
    'kilimanjaro_wildlife_p2' => 'Por encima del bosque, el páramo y las zonas alpinas son más extrañas que salvajes: senecios gigantes y lobelias que no se encuentran en ningún otro lugar, y aves como el cuervo de nuca blanca que siguen a los escaladores por restos de comida en los campamentos altos.',

    'kilimanjaro_when_badge' => 'Planificación',
    'kilimanjaro_when_title' => 'Cuándo escalar',
    'kilimanjaro_when_intro' => "El Kilimanjaro técnicamente se puede escalar todo el año, pero las condiciones varían considerablemente según la temporada.",
    'kilimanjaro_when_p1' => 'De enero a principios de marzo y de junio a octubre son las dos ventanas secas: las condiciones más fiables, las vistas más despejadas de la cumbre y los senderos más concurridos, especialmente de julio a septiembre.',
    'kilimanjaro_when_p2' => 'Abril, mayo y noviembre son los meses húmedos. La montaña permanece abierta y escalable, pero los senderos están resbaladizos y la nubosidad a menudo oculta la cumbre. Rongai, en el lado norte más seco, es la mejor opción si debe escalar en esta ventana.',

    'kilimanjaro_stay_badge' => 'Dónde duerme',
    'kilimanjaro_stay_title' => 'Alojamiento en la montaña',
    'kilimanjaro_stay_intro' => 'Dónde duerme depende enteramente de la ruta elegida. Esto es fijo, no una cuestión de nivel de presupuesto.',
    'kilimanjaro_stay_huts_title' => 'Refugios de montaña (solo Marangu)',
    'kilimanjaro_stay_huts_price' => 'Incluido en la ruta Marangu',
    'kilimanjaro_stay_huts_desc' => 'Refugios estilo dormitorio con literas, comedores compartidos e instalaciones básicas. La única ruta que ofrece esta opción, y parte de por qué es la más corta y asequible.',
    'kilimanjaro_stay_camping_title' => 'Camping de montaña (todas las demás rutas)',
    'kilimanjaro_stay_camping_price' => 'Incluido en el precio de la ruta',
    'kilimanjaro_stay_camping_desc' => 'Tiendas para dos personas transportadas y montadas por el equipo en cada campamento, con una tienda comedor separada para las comidas. El estándar para Machame, Lemosho, Rongai y el Northern Circuit.',
    'kilimanjaro_stay_private_title' => 'Arusha, antes y después',
    'kilimanjaro_stay_private_price' => 'Incluido en cada paquete',
    'kilimanjaro_stay_private_desc' => 'Una noche de hotel en Arusha antes del ascenso y después de su descenso está incluida en cada paquete del Kilimanjaro que ofrecemos, para una ducha caliente y una cama de verdad a cada lado de la montaña.',
    'kilimanjaro_stay_note' => 'Todo el alojamiento de montaña, refugios o tiendas, está incluido en el precio de su paquete de trekking, junto con todas las tasas de camping y refugios.',

    'kilimanjaro_fees_badge' => 'Tasas 2026',
    'kilimanjaro_fees_title' => 'Tasas de parque',
    'kilimanjaro_fees_intro' => 'Las tasas se detallan por persona y se incluyen en su paquete de trekking, mostradas aquí para que sepa exactamente qué está pagando.',
    'kilimanjaro_table_category' => 'Tasa',
    'kilimanjaro_table_basis' => 'Base',
    'kilimanjaro_table_adult' => 'Adulto (USD)',
    'kilimanjaro_table_child' => 'Niño (5–15)',
    'kilimanjaro_fee_conservation' => 'Tasa de conservación',
    'kilimanjaro_fee_camping' => 'Tasa de camping',
    'kilimanjaro_fee_huts' => 'Tasa de refugio (Marangu)',
    'kilimanjaro_fee_rescue' => 'Tasa de rescate',
    'kilimanjaro_fee_basis_day' => 'Por día',
    'kilimanjaro_fee_basis_night' => 'Por noche',
    'kilimanjaro_fee_basis_once' => 'Una vez por trek',
    'kilimanjaro_fees_example' => 'Para una ascensión Lemosho de 7 días, las tasas de parque solas suman aproximadamente 956 $ por persona. Esto es completamente aparte de los costos de guía, porteador, comida y equipo.',
    'kilimanjaro_fees_note' => 'Cuando escala con nosotros, todas las tasas de parque se calculan y se incluyen en el precio de trekking cotizado, sin necesidad de pago separado en la entrada.',

    'kilimanjaro_gallery_badge' => 'El Kilimanjaro en imágenes',
    'kilimanjaro_gallery_title' => 'La montaña',
    'kilimanjaro_gallery_caption_1' => 'Sabana en la base de la montaña',
    'kilimanjaro_gallery_caption_2' => 'Fauna en las llanuras circundantes',
    'kilimanjaro_gallery_caption_3' => 'Un guía con escaladores antes del ascenso',

    'kilimanjaro_back_to_parks' => 'Comparar los nueve parques',

    'kilimanjaro_faq_badge' => 'Preguntas frecuentes',
    'kilimanjaro_faq_title' => 'Preguntas comunes',
    'kilimanjaro_faq_q1' => '¿Necesito experiencia en escalada?',
    'kilimanjaro_faq_a1' => 'No. El Kilimanjaro es una larga caminata, no una escalada técnica: no hay técnica de cuerdas ni escalada libre. Lo que exige es resistencia para cinco a nueve días de caminata y la capacidad de soportar el aire enrarecido.',
    'kilimanjaro_faq_q2' => '¿Qué ruta tiene la mayor tasa de éxito?',
    'kilimanjaro_faq_a2' => 'El Northern Circuit y Lemosho, ambos alrededor del 90–95%, gracias a su perfil de aclimatación más largo. Marangu, la ruta más corta, tiene la tasa de éxito más baja, alrededor del 50–60%.',
    'kilimanjaro_faq_q3' => '¿Qué pasa con el mal de altura?',
    'kilimanjaro_faq_a3' => 'Los dolores de cabeza leves y la falta de aire son normales por encima de 4.000 m. Nuestros guías verifican la saturación de oxígeno dos veces al día y llevan un botiquín de primeros auxilios. Si un guía juzga que debe descender, desciende, sin excepciones.',
    'kilimanjaro_faq_q4' => '¿Qué tan en forma necesito estar?',
    'kilimanjaro_faq_a4' => 'No se requiere condición física de escalada técnica, pero varias horas de entrenamiento de senderismo previo marcan una diferencia real. El desafío es la resistencia y la altitud, no la fuerza.',
    'kilimanjaro_faq_q5' => '¿Cuál es el número mínimo de días?',
    'kilimanjaro_faq_a5' => 'Cinco días (Marangu) es el mínimo legal, pero recomendamos al menos seis a siete para una probabilidad significativamente mejor de alcanzar la cumbre.',
    'kilimanjaro_faq_q6' => '¿Pueden los principiantes escalar el Kilimanjaro?',
    'kilimanjaro_faq_a6' => 'Sí, no se requiere experiencia previa en trekking, aunque cierta condición física de senderismo ayuda. Muchos de nuestros escaladores nunca han hecho un trek de varios días antes.',
    'kilimanjaro_faq_q7' => '¿Qué se incluye en un paquete de trekking?',
    'kilimanjaro_faq_a7' => 'Todas las tasas de parque, un guía certificado, cocinero y porteadores, comidas y agua potable en la montaña, tasas de camping o refugio, y traslados en Arusha. Vea la lista completa de incluido/no incluido en nuestra página de trekking.',
    'kilimanjaro_faq_q8' => '¿Se usa oxígeno portátil?',
    'kilimanjaro_faq_a8' => 'No de forma rutinaria. Está disponible bajo petición como medida de seguridad adicional, pero la aclimatación adecuada mediante la elección de la ruta es la estrategia principal en la que confiamos.',

    'kilimanjaro_cta_title' => '¿Listo para escalar el Kilimanjaro?',
    'kilimanjaro_cta_intro' => 'Envíenos sus fechas y ruta preferida. Respondemos con un itinerario escrito y el precio completo, sin compromiso.',
    'kilimanjaro_cta_whatsapp' => 'Escríbanos por WhatsApp',
    'kilimanjaro_cta_safaris' => 'Ver paquetes de trekking',

    'ruaha_meta_title' => 'Guía del Parque Nacional de Ruaha (2026) | Serengeti Budget Safari',
    'ruaha_meta_description' => "Guía del Parque Nacional de Ruaha: el parque más grande de Tanzania, alrededor del 10% de los leones del mundo, enormes manadas de elefantes, licaón, tasas de parque 2026 y dónde alojarse.",
    'ruaha_hero_badge' => 'Parque Nacional de Ruaha',
    'ruaha_hero_title' => 'Parque Nacional de Ruaha',
    'ruaha_hero_sub' => "El parque nacional más grande de Tanzania: escarpado, remoto, y hogar de aproximadamente una décima parte de los leones que quedan en el mundo.",
    'ruaha_hero_cta_quote' => 'Solicitar presupuesto',

    'ruaha_intro_badge' => 'Descripción general',
    'ruaha_intro_title' => 'Grande, salvaje y casi vacío',
    'ruaha_intro_p1' => "Ruaha es el parque nacional más grande de Tanzania con más de 20.000 km², más grande que el Serengeti, sin embargo recibe una fracción de los visitantes, gracias al vuelo adicional requerido desde Dar es Salaam en lugar de un traslado por carretera desde Arusha.",
    'ruaha_intro_p2' => "Esa lejanía es exactamente su atractivo: vastas llanuras salpicadas de baobabs, el gran río Ruaha, y algunas de las mayores densidades de depredadores de África, vistas desde un vehículo que a menudo tendrá completamente para usted.",
    'ruaha_intro_p3' => "Recompensa a los viajeros que ya han hecho el circuito norte y quieren algo genuinamente diferente: cielos más grandes, pistas más ásperas, y fauna que reacciona a los vehículos como debería, como una novedad en lugar de una ocurrencia diaria.",
    'ruaha_fact_area' => 'Superficie',
    'ruaha_fact_rank' => 'Clasificación por tamaño',
    'ruaha_fact_rank_value' => "El parque más grande de Tanzania",
    'ruaha_fact_lions' => 'Población de leones',
    'ruaha_fact_lions_of_world' => '~10% de los leones salvajes del mundo',
    'ruaha_fact_elephants' => 'Población de elefantes',
    'ruaha_fact_kudu' => 'Especies notables',
    'ruaha_fact_kudu_value' => 'Kudú mayor y menor',
    'ruaha_fact_visitors' => 'Densidad de visitantes',
    'ruaha_fact_visitors_value' => 'Muy baja',
    'ruaha_fact_stay' => 'Estancia recomendada',
    'ruaha_fact_days' => '3–4 días',
    'ruaha_fact_from_dar' => 'Desde Dar es Salaam',
    'ruaha_fact_by_air' => 'En avión ligero',

    'ruaha_regions_badge' => 'El paisaje',
    'ruaha_regions_title' => 'Qué ver',
    'ruaha_regions_intro' => 'Ruaha alterna entre tres paisajes distintos a lo largo de su vasta extensión.',
    'ruaha_region_river_name' => 'El gran río Ruaha',
    'ruaha_region_river_desc' => 'El sustento del parque. Durante la temporada seca, la fauna se concentra a lo largo de sus orillas y bancos de arena en números que rivalizan con cualquier cruce de río del circuito norte, sin las multitudes.',
    'ruaha_region_baobab_name' => 'Llanuras de baobabs',
    'ruaha_region_baobab_desc' => 'Colinas onduladas salpicadas de antiguos baobabs, algunos estimados en más de mil años, dando a Ruaha una silueta distintiva a diferencia de cualquier parque del norte.',
    'ruaha_region_miombo_name' => 'Bosque de miombo',
    'ruaha_region_miombo_desc' => 'Vastas extensiones de bosque de miombo cubren gran parte del interior del parque, hogar de especies como el kudú mayor y el antílope sable que prefieren este hábitat a la pradera abierta.',

    'ruaha_wildlife_badge' => 'Lo que vive aquí',
    'ruaha_wildlife_title' => 'Fauna',
    'ruaha_wildlife_intro' => 'Ruaha se encuentra en la superposición de especies de África Oriental y Austral, lo que le da una de las listas de fauna más diversas de cualquier parque tanzano.',
    'ruaha_animal_lion' => 'León',
    'ruaha_animal_elephant' => 'Elefante',
    'ruaha_animal_leopard' => 'Leopardo',
    'ruaha_animal_cheetah' => 'Guepardo',
    'ruaha_animal_wilddog' => 'Licaón africano',
    'ruaha_animal_buffalo' => 'Búfalo',
    'ruaha_animal_giraffe' => 'Jirafa',
    'ruaha_animal_zebra' => 'Cebra',
    'ruaha_animal_kudu' => 'Kudú mayor',
    'ruaha_animal_hippo' => 'Hipopótamo',
    'ruaha_wildlife_p1' => "Ruaha alberga aproximadamente el 10% de los leones salvajes que quedan en el mundo y una población de elefantes entre las más grandes de África Oriental, junto con buenas cantidades de leopardos y una de las mejores oportunidades de Tanzania de encontrar licaones africanos.",
    'ruaha_wildlife_p2' => 'La mezcla de especies de África Oriental (león, jirafa, cebra) y especies de África Austral (kudú mayor, antílope sable, hipótrago ruano) que no se encuentra en ningún otro lugar del circuito norte es parte de lo que hace a Ruaha genuinamente distinto.',

    'ruaha_when_badge' => 'Planificación',
    'ruaha_when_title' => 'Cuándo ir',
    'ruaha_when_intro' => 'Ruaha se visita mejor en la temporada seca, cuando la fauna se concentra de forma predecible a lo largo del río.',
    'ruaha_when_p1' => 'De junio a octubre es el pico de la temporada seca: el río se reduce a charcas y bancos de arena, atrayendo grandes concentraciones de fauna y los mejores avistamientos de depredadores del año.',
    'ruaha_when_p2' => 'De noviembre a mayo llegan las lluvias: el parque se vuelve verde, muchos campamentos cierran por la temporada, y las carreteras pueden volverse intransitables. Esta no es una ventana realista para la mayoría de los visitantes.',

    'ruaha_stay_badge' => 'Dónde alojarse',
    'ruaha_stay_title' => 'Alojamiento',
    'ruaha_stay_intro' => "La lejanía de Ruaha significa menos establecimientos que el circuito norte, pero una buena distribución en todos los niveles de presupuesto cerca del río.",
    'ruaha_stay_budget_title' => 'Campamentos económicos',
    'ruaha_stay_budget_price' => 'Camping / tienda básica',
    'ruaha_stay_budget_desc' => 'Campamentos con tienda sencillos con instalaciones compartidas, gestionados por pequeños operadores locales. La forma más asequible de experimentar el parque.',
    'ruaha_stay_mid_title' => 'Campamentos de gama media',
    'ruaha_stay_mid_price' => 'Campamento con tienda, baño privado',
    'ruaha_stay_mid_desc' => 'Cómodos campamentos permanentes con tienda con baños privados, a menudo ubicados a lo largo de la ribera del río para vistas de fauna desde el propio campamento.',
    'ruaha_stay_luxury_title' => 'Campamentos de lujo',
    'ruaha_stay_luxury_price' => 'Campamento con tienda premium',
    'ruaha_stay_luxury_desc' => 'Un pequeño número de campamentos de alta gama ofrecen guía privado, plataformas de observación elevadas y una sensación verdaderamente exclusiva dado cuántos pocos visitantes recibe el parque.',
    'ruaha_stay_note' => 'Podemos organizar alojamiento en cualquier nivel como parte de su itinerario a Ruaha, incluido el traslado en avión ligero desde Dar es Salaam.',

    'ruaha_fees_badge' => 'Tasas 2026',
    'ruaha_fees_title' => 'Tasas de entrada al parque',
    'ruaha_fees_intro' => 'Las tasas son por persona por período de 24 horas e incluyen el 18% de IVA. Se pagan con tarjeta o tarjeta de parque precargada. No se acepta efectivo en la entrada.',
