    'ruaha_back_to_parks' => 'Comparar los nueve parques',

    'ruaha_faq_badge' => 'Preguntas frecuentes',
    'ruaha_faq_title' => 'Preguntas comunes',
    'ruaha_faq_q1' => '¿Cómo llego a Ruaha?',
    'ruaha_faq_a1' => 'En avión ligero desde Dar es Salaam. No hay una ruta terrestre práctica desde Arusha. Los vuelos suelen tomar alrededor de dos horas.',
    'ruaha_faq_q2' => '¿Vale la pena Ruaha el costo adicional del vuelo?',
    'ruaha_faq_a2' => 'Para viajeros que ya han visto el circuito norte, sí. La densidad de fauna rivaliza con el Serengeti con una fracción de los vehículos, lo cual es una experiencia genuinamente diferente.',
    'ruaha_faq_q3' => '¿Cuántos días necesito?',
    'ruaha_faq_a3' => 'Tres a cuatro días le permiten explorar adecuadamente las zonas riberreñas y boscosas sin sentirse apresurado, dadas las distancias de conducción implicadas.',
    'ruaha_faq_q4' => '¿Puedo combinar Ruaha con otros parques del sur?',
    'ruaha_faq_a4' => 'Sí, Ruaha se combina naturalmente con Nyerere (Selous) para un safari del circuito sur, ambos accesibles desde Dar es Salaam.',
    'ruaha_faq_q5' => '¿Veré licaones?',
    'ruaha_faq_a5' => 'Ruaha es uno de los mejores lugares de Tanzania para el licaón africano, aunque los avistamientos nunca están garantizados para ningún animal salvaje. Una estancia de varios días mejora considerablemente sus probabilidades.',
    'ruaha_faq_q6' => '¿Es Ruaha bueno para la fotografía?',
    'ruaha_faq_a6' => 'Mucho. La baja densidad de vehículos significa avistamientos ininterrumpidos y el paisaje de baobabs ofrece fondos dramáticos raramente disponibles en los parques del norte más concurridos.',
    'ruaha_faq_q7' => '¿Cuál es la mejor época para ver leones?',
    'ruaha_faq_a7' => 'Todo el año, pero la temporada seca (junio–octubre) los concentra de forma más predecible a lo largo del río, donde también se reúnen los animales presa.',
    'ruaha_faq_q8' => '¿Es Ruaha adecuado para un primer safari?',
    'ruaha_faq_a8' => "Puede serlo, pero la mayoría de los primeros visitantes están mejor atendidos comenzando con el circuito norte por sus traslados más cortos e infraestructura más desarrollada. Ruaha recompensa a los viajeros que ya saben lo que quieren de un safari.",

    'ruaha_cta_title' => '¿Listo para visitar Ruaha?',
    'ruaha_cta_intro' => 'Envíenos sus fechas y el tamaño del grupo. Respondemos con un itinerario escrito y el precio completo, sin compromiso.',
    'ruaha_cta_whatsapp' => 'Escríbanos por WhatsApp',
    'ruaha_cta_safaris' => 'Ver paquetes de safari',

    'mikumi_meta_title' => 'Guía del Parque Nacional de Mikumi (2026) | Serengeti Budget Safari',
    'mikumi_meta_description' => "Guía del Parque Nacional de Mikumi: el safari real más asequible de Tanzania, a cuatro horas de Dar es Salaam por carretera, sin vuelo necesario. Tasas 2026, fauna y cuándo ir.",
    'mikumi_hero_badge' => 'Parque Nacional de Mikumi',
    'mikumi_hero_title' => 'Parque Nacional de Mikumi',
    'mikumi_hero_sub' => "El safari real más económico de Tanzania: a cuatro horas de Dar es Salaam por carretera, sin necesidad de vuelo interno.",
    'mikumi_hero_cta_quote' => 'Solicitar presupuesto',

    'mikumi_intro_badge' => 'Descripción general',
    'mikumi_intro_title' => 'Un safari real sin el vuelo',
    'mikumi_intro_p1' => "Mikumi es el más accesible de los parques del sur de Tanzania: un simple viaje de cuatro horas desde Dar es Salaam por carretera pavimentada, sin necesidad de vuelo interno. Esa accesibilidad, combinada con tasas de parque más bajas que el circuito norte, lo convierte en el safari real más asequible del país.",
    'mikumi_intro_p2' => "Su punto central es la llanura de inundación de Mkata, una pradera abierta a menudo comparada con un Serengeti en miniatura: amplios horizontes, observación fácil de fauna, y ninguna de las complicaciones logísticas de vuelo de Ruaha o Nyerere.",
    'mikumi_intro_p3' => "Funciona bien como safari de fin de semana desde Dar es Salaam, una parada en el camino hacia Ruaha o Nyerere, o una introducción económica a la fauna tanzana.",
    'mikumi_fact_area' => 'Superficie',
    'mikumi_fact_established' => 'Fundado en',
    'mikumi_fact_status' => 'Acceso',
    'mikumi_fact_status_value' => 'Por carretera, sin vuelo necesario',
    'mikumi_fact_lions' => 'Depredadores',
    'mikumi_fact_lions_value' => 'León, leopardo presente',
    'mikumi_fact_birds' => 'Especies de aves',
    'mikumi_fact_entry' => 'Nivel de tasa de entrada',
    'mikumi_fact_stay' => 'Estancia recomendada',
    'mikumi_fact_days' => '1–2 días',
    'mikumi_fact_from_dar' => 'Desde Dar es Salaam',

    'mikumi_regions_badge' => 'El paisaje',
    'mikumi_regions_title' => 'Qué ver',
    'mikumi_regions_intro' => 'Mikumi se centra en dos hábitats contrastantes.',
    'mikumi_region_mkata_name' => 'Llanura de inundación de Mkata',
    'mikumi_region_mkata_desc' => "El corazón del parque: pradera abierta flanqueada por las montañas Uluguru y Lumango, con las mayores concentraciones de fauna y la observación más fácil del parque.",
    'mikumi_region_miombo_name' => 'Bosque de miombo',
    'mikumi_region_miombo_desc' => 'El bosque de miombo de las laderas rodea la llanura de inundación, hogar de especies menos comúnmente vistas como el eland y el antílope sable para visitantes que exploran más allá de la llanura.',

    'mikumi_wildlife_badge' => 'Lo que vive aquí',
    'mikumi_wildlife_title' => 'Fauna',
    'mikumi_wildlife_intro' => 'Mikumi tiene una muestra genuina de la fauna de África Oriental, concentrada en la llanura de inundación abierta de Mkata.',
    'mikumi_animal_lion' => 'León',
    'mikumi_animal_elephant' => 'Elefante',
    'mikumi_animal_leopard' => 'Leopardo',
    'mikumi_animal_wilddog' => 'Licaón africano',
    'mikumi_animal_buffalo' => 'Búfalo',
    'mikumi_animal_giraffe' => 'Jirafa',
    'mikumi_animal_zebra' => 'Cebra',
    'mikumi_animal_wildebeest' => 'Ñu',
    'mikumi_animal_hippo' => 'Hipopótamo',
    'mikumi_wildlife_p1' => 'La llanura de inundación alberga grandes manadas de búfalos, cebras y ñus todo el año, con elefantes comúnmente vistos a lo largo de los cursos de agua estacionales que cruzan la pradera.',
    'mikumi_wildlife_p2' => 'León y leopardo están ambos presentes y se avistan regularmente, y Mikumi es uno de los pocos parques donde el licaón africano pasa ocasionalmente. Nunca garantizado, pero una posibilidad real.',

    'mikumi_when_badge' => 'Planificación',
    'mikumi_when_title' => 'Cuándo ir',
    'mikumi_when_intro' => 'Mikumi es un destino de todo el año dada su baja altitud y fácil acceso por carretera.',
    'mikumi_when_p1' => 'De junio a octubre (temporada seca) ofrece la mejor observación de fauna, ya que esta se concentra alrededor de las fuentes de agua restantes en la llanura de inundación.',
    'mikumi_when_p2' => 'De noviembre a mayo es más verde y tranquilo, con tarifas más bajas en la mayoría de los campamentos: una buena opción para una visita más corta y económica si la observación de fauna en temporada alta no es la prioridad.',

    'mikumi_stay_badge' => 'Dónde alojarse',
    'mikumi_stay_title' => 'Alojamiento',
    'mikumi_stay_intro' => "El fácil acceso de Mikumi desde Dar es Salaam ha atraído una buena variedad de alojamiento en todos los niveles de presupuesto.",
    'mikumi_stay_budget_title' => 'Campamentos económicos',
    'mikumi_stay_budget_price' => 'Camping / tienda básica',
    'mikumi_stay_budget_desc' => 'Campings sencillos y opciones básicas de tienda cerca de la entrada del parque, la forma más asequible de establecerse para una visita tipo excursión de un día.',
    'mikumi_stay_mid_title' => 'Lodges de gama media',
    'mikumi_stay_mid_price' => 'Lodge, baño privado',
    'mikumi_stay_mid_desc' => 'Lodges confortables con vista a la llanura de inundación, ofreciendo un buen equilibrio de confort y valor para una estancia de una o dos noches.',
    'mikumi_stay_luxury_title' => 'Lodges de lujo',
    'mikumi_stay_luxury_price' => 'Lodge premium',
    'mikumi_stay_luxury_desc' => 'Un menor número de establecimientos de alta gama ofrecen terrazas privadas y vistas elevadas sobre la llanura, para viajeros que quieren comodidad adicional cerca de Dar.',
    'mikumi_stay_note' => 'Podemos organizar alojamiento en cualquier nivel como parte de su itinerario a Mikumi, incluido el transporte desde Dar es Salaam.',

    'mikumi_access_badge' => 'Cómo llegar',
    'mikumi_access_title' => 'Acceso desde Dar es Salaam',
    'mikumi_access_intro' => "La mayor ventaja de Mikumi sobre Ruaha y Nyerere es que no necesita vuelo interno.",
    'mikumi_access_p1' => 'Una carretera pavimentada conecta Dar es Salaam con Mikumi en unas cuatro horas, haciéndolo realista como viaje de fin de semana o parada en un itinerario del circuito sur más largo hacia Ruaha.',
    'mikumi_access_p2' => 'Este acceso por carretera es la razón principal por la que Mikumi es el safari real más económico de Tanzania. Sin costos de vuelo charter que incluir en su viaje.',

    'mikumi_fees_badge' => 'Tasas 2026',
    'mikumi_fees_title' => 'Tasas de entrada al parque',
    'mikumi_fees_intro' => 'Las tasas son por persona por período de 24 horas e incluyen el 18% de IVA, entre las más bajas de cualquier parque nacional tanzano. Se pagan con tarjeta o tarjeta de parque precargada. No se acepta efectivo en la entrada.',
