    'mikumi_faq_badge' => 'Preguntas frecuentes',
    'mikumi_faq_title' => 'Preguntas comunes',
    'mikumi_faq_q1' => '¿Necesito volar a Mikumi?',
    'mikumi_faq_a1' => 'No. Se llega a Mikumi con un viaje de cuatro horas por carretera pavimentada desde Dar es Salaam, que es exactamente lo que lo convierte en la opción de safari más asequible de Tanzania.',
    'mikumi_faq_q2' => '¿Es Mikumi bueno para un viaje de fin de semana?',
    'mikumi_faq_a2' => 'Sí, su corto trayecto desde Dar es Salaam lo hace realista como safari de fin de semana de dos días, algo que ninguno de los otros parques del sur o del norte puede ofrecer fácilmente.',
    'mikumi_faq_q3' => '¿Veré los Big Five?',
    'mikumi_faq_a3' => 'León, elefante y búfalo se ven regularmente. El leopardo está presente pero es esquivo, y el rinoceronte no se encuentra en Mikumi. Para una oportunidad realista de los Big Five, el Ngorongoro sigue siendo la mejor opción.',
    'mikumi_faq_q4' => '¿Cómo se compara Mikumi con Ruaha o Nyerere?',
    'mikumi_faq_a4' => 'Mikumi es más pequeño y más fácil de acceder, con tasas más bajas, pero Ruaha y Nyerere ofrecen mayor densidad de fauna y una sensación más remota. Mikumi es la opción económica y conveniente de los tres.',
    'mikumi_faq_q5' => '¿Puedo combinar Mikumi con Ruaha?',
    'mikumi_faq_a5' => 'Sí, Mikumi se encuentra en la ruta hacia Ruaha, lo que lo convierte en una parada natural en un itinerario del circuito sur más largo.',
    'mikumi_faq_q6' => '¿Cuál es la mejor época para visitar?',
    'mikumi_faq_a6' => 'De junio a octubre para la mejor observación de fauna, aunque el parque es accesible y merece la pena todo el año dada su baja altitud y fácil acceso por carretera.',
    'mikumi_faq_q7' => '¿Es Mikumi adecuado para un primer safari?',
    'mikumi_faq_a7' => 'Sí, su accesibilidad y menor costo lo convierten en una introducción sensata a la fauna tanzana, especialmente para viajeros basados en o que llegan vía Dar es Salaam.',
    'mikumi_faq_q8' => '¿Es necesario un vehículo 4x4?',
    'mikumi_faq_a8' => "Sí, como en cualquier parque nacional tanzano, proporcionamos un 4x4 privado con chófer-guía como estándar en cada itinerario a Mikumi.",

    'mikumi_cta_title' => '¿Listo para visitar Mikumi?',
    'mikumi_cta_intro' => 'Envíenos sus fechas y el tamaño del grupo. Respondemos con un itinerario escrito y el precio completo, sin compromiso.',
