    'pkg5d_faq_title' => 'Preguntas frecuentes',
    'pkg5d_faq_q1' => '¿Es este safari privado?',
    'pkg5d_faq_a1' => 'Sí, el vehículo y el guía son privados para su grupo a menos que reserve específicamente una salida de Grupo Compartido. Usted establece el ritmo y las paradas.',
    'pkg5d_faq_q2' => '¿Puedo personalizar el safari?',
    'pkg5d_faq_a2' => 'Sí, se pueden añadir días extra, parques diferentes o una extensión a Zanzíbar. Indíquenos lo que tiene en mente y ajustaremos el itinerario y el precio.',
    'pkg5d_faq_q3' => '¿Puedo empezar en cualquier fecha?',
    'pkg5d_faq_a3' => 'Sí, los safaris privados salen en la fecha que elija, sujeto a la disponibilidad de lodges en temporada alta (junio–octubre).',
    'pkg5d_faq_q4' => '¿Está incluida la recogida en el aeropuerto?',
    'pkg5d_faq_a4' => 'Sí, la recogida desde el Aeropuerto Internacional del Kilimanjaro o su hotel en Arusha está incluida en el precio.',
    'pkg5d_faq_q5' => '¿Qué debo traer?',
    'pkg5d_faq_a5' => 'Ropa de colores neutros, una capa cálida para las mañanas frías, protector solar, un sombrero, prismáticos y una cámara. Enviamos una lista completa de equipaje una vez confirmado su viaje.',
    'pkg5d_faq_q6' => '¿Es este safari adecuado para niños?',
    'pkg5d_faq_a6' => 'Sí, la mayoría de los lodges en esta ruta reciben niños de todas las edades, aunque algunos tienen una edad mínima para los game drives. Indíquenos las edades de los viajeros y confirmaremos.',

