    'safari_park_serengeti_desc' => 'La Gran Migración, la mayor densidad de depredadores de África, y 14.763 km² de llanuras.',
    'safari_park_ngorongoro_desc' => '25.000 animales en una caldera de 260 km², y el único rinoceronte negro realista de Tanzania.',
