    'safari_included_title' => 'Qué incluye un safari con nosotros',
    'safari_included_subtitle' => 'A menos que su presupuesto diga lo contrario, cada precio en esta página cubre lo siguiente.',
    'safari_included_heading' => 'Incluido',
    'safari_included_1' => 'Land Cruiser 4x4 con techo elevable y asiento ventana garantizado para todos',
    'safari_included_2' => 'Chófer-guía de habla inglesa (italiano bajo petición)',
    'safari_included_3' => 'Todas las tasas de entrada y conservación de parques en el itinerario',
    'safari_included_4' => 'Alojamiento y comidas como se describe en su programa',
    'safari_included_5' => 'Agua potable durante los game drives',
    'safari_included_6' => 'Recogida y traslado en Arusha o en el Aeropuerto del Kilimanjaro',
    'safari_excluded_heading' => 'No incluido',
    'safari_excluded_1' => 'Vuelos internacionales y visa tanzana',
    'safari_excluded_2' => 'Seguro de viaje (obligatorio)',
    'safari_excluded_3' => 'Bebidas que no sean agua, y gastos personales',
    'safari_excluded_4' => 'Propinas para el guía y el personal del lodge',
    'safari_excluded_5' => 'Extras opcionales: vuelo en globo, visitas culturales, vuelos internos',

    'safari_parks_title' => 'Lea primero sobre los parques',
    'safari_parks_subtitle' => 'Antes de elegir un itinerario, ayuda saber qué ofrece realmente cada parque. Estas guías están escritas por nuestros propios guías y cubren fauna, tasas 2026, cuándo ir y dónde alojarse.',
    'safari_parks_beyond_title' => 'Más allá del circuito norte',
    'safari_parks_beyond_desc' => 'Otros tres parques se alcanzan desde Dar es Salaam en lugar de Arusha. Más grandes, más vacíos y más económicos de entrar, con safaris en bote y a pie que los parques del norte no pueden ofrecer.',
    'safari_parks_full_guide' => 'Guía completa',
    'safari_parks_compare_all' => 'Comparar los nueve parques lado a lado',

    'safari_faq_title' => 'Preguntas comunes',
    'safari_faq_q1' => '¿Cuánto cuesta realmente un safari en Tanzania?',
    'safari_faq_a1' => 'Económico desde alrededor de 200 € por persona y día, gama media 250–350 €, y lujo desde 600 €. Las variables más grandes son el nivel del alojamiento y el tamaño de su grupo: las tasas de parque y el vehículo son costos fijos, así que cuatro personas compartiendo pagan notablemente menos cada una que dos.',
    'safari_faq_q2' => '¿Cuál es la mejor época para venir?',
    'safari_faq_a2' => 'De junio a octubre es la clásica temporada seca con la observación de fauna más fácil. Enero y febrero traen la temporada de nacimientos en Ndutu. De noviembre a mayo es más verde, tranquilo y económico, con algo de lluvia por las tardes.',
    'safari_faq_q3' => '¿Veremos los Big Five?',
    'safari_faq_a3' => 'León, elefante, búfalo y leopardo se ven regularmente en un safari de cuatro días del circuito norte. El rinoceronte negro es el difícil: el Cráter del Ngorongoro es la mejor oportunidad en Tanzania, pero ningún operador puede garantizar el avistamiento de un animal salvaje.',
    'safari_faq_q4' => '¿Cuántos días necesitamos?',
    'safari_faq_a4' => 'Tres días es el mínimo práctico para llegar al Serengeti sin pasar todo el viaje conduciendo. Cuatro a cinco días es el punto óptimo. Cualquier duración más corta es mejor invertida en Tarangire, Manyara y el Cráter del Ngorongoro, que están mucho más cerca de Arusha.',

    'safari_cta_title' => 'Planifique su viaje con nosotros',
    'safari_cta_intro' => 'Envíenos sus fechas, tamaño del grupo y presupuesto. Respondemos con un itinerario escrito y un desglose completo de precios, sin compromiso.',
    'safari_cta_whatsapp' => 'Escríbanos por WhatsApp',
    'safari_cta_contact_form' => 'Formulario de contacto',

