    'parks_meta_title' => 'Parques Nacionales de Tanzania: los 9 parques comparados (2026) | Serengeti Budget Safari',
    'parks_meta_description' => 'Compare los parques nacionales de Tanzania lado a lado: Serengeti, Ngorongoro, Tarangire, Manyara, Arusha, Kilimanjaro, Nyerere, Ruaha y Mikumi. Tasas 2026, fauna y días necesarios.',

    'parks_hero_badge' => 'Guías de parques',
    'parks_hero_title' => 'Los parques nacionales de Tanzania',
    'parks_hero_sub' => 'Nueve parques comparados lado a lado: fauna, tasas 2026, días necesarios y cuál conviene a su viaje. Luego lea la guía completa de los que le interesen.',

    'parks_northern_badge' => 'Parques del norte',
    'parks_northern_title' => 'El circuito norte',
    'parks_northern_intro' => 'Cinco parques a un día de viaje de Arusha, y el destino de la abrumadora mayoría de los safaris tanzanos.',

    'parks_southern_badge' => 'Parques del sur',
    'parks_southern_title' => 'El circuito sur',
    'parks_southern_intro' => 'Se alcanzan desde Dar es Salaam en lugar de Arusha. Más grandes, más vacíos, más económicos de entrar y más caros de alcanzar. Adonde va en un segundo viaje.',

    'parks_full_guide' => 'Guía completa',

    'parks_serengeti_name' => 'Serengeti',
    'parks_serengeti_desc' => '14.763 km² de llanuras, la Gran Migración, y la mayor densidad de grandes depredadores de África. Necesita tres días mínimo.',
    'parks_ngorongoro_name' => 'Ngorongoro',
    'parks_ngorongoro_desc' => 'La mayor caldera intacta de la Tierra con 25.000 animales dentro, y la única oportunidad realista de rinoceronte negro en Tanzania.',
    'parks_tarangire_name' => 'Tarangire',
    'parks_tarangire_desc' => 'Baobabs y 2.500–3.000 elefantes, a dos horas de Arusha, y el más tranquilo de los cuatro parques principales.',
    'parks_manyara_name' => 'Lago Manyara',
    'parks_manyara_desc' => 'Bosque de aguas subterráneas, flamencos, enormes tropas de babuinos, y el único safari nocturno y pasarela de dosel del circuito.',
    'parks_arusha_name' => 'Parque Nacional de Arusha',
    'parks_arusha_desc' => 'A cuarenta minutos de la ciudad, y el único lugar del circuito donde se puede caminar, hacer canoa y escalar. Sin leones.',
    'parks_kilimanjaro_name' => 'Kilimanjaro',
    'parks_kilimanjaro_desc' => 'La montaña más alta de África a 5.895 m, escalada en cinco a nueve días en siete rutas oficiales.',
    'parks_nyerere_name' => 'Nyerere (Selous)',
    'parks_nyerere_desc' => 'El parque nacional más grande de África, donde puede hacer un safari en bote, un safari a pie y un game drive en el mismo día.',
    'parks_ruaha_name' => 'Ruaha',
    'parks_ruaha_desc' => 'El parque más grande de Tanzania, con alrededor del 10% de los leones del mundo y 12.000 elefantes, con casi ningún otro vehículo.',
    'parks_mikumi_name' => 'Mikumi',
    'parks_mikumi_desc' => 'El único gran parque accesible desde una ciudad por carretera en una mañana. Llanuras abiertas, leones residentes, el safari real más económico de Tanzania.',

