    'parks_why_migration' => 'El único lugar donde ocurre. Elija la región según el mes.',
    'parks_want_bigfive' => 'Los Big Five en un día',
    'parks_why_bigfive' => 'El único parque donde el rinoceronte es realmente probable.',
    'parks_want_elephants' => 'Elefantes',
    'parks_why_elephants' => 'Manadas de cincuenta o más en la temporada seca.',
    'parks_want_walking' => 'Caminar, no conducir',
    'parks_why_walking' => 'Los tres permiten verdaderos safaris a pie.',
    'parks_want_oneday' => 'Solo un día',
    'parks_why_oneday' => 'Ambos accesibles y gratificantes en un día desde Arusha.',
    'parks_want_budget' => 'Sin vuelo, presupuesto bajo',
    'parks_why_budget' => 'Cuatro horas de Dar por carretera, la tasa de entrada más económica.',

    'parks_see_safaris' => 'Ver nuestros itinerarios de safari',

    'parks_faq_badge' => 'Preguntas frecuentes',
    'parks_faq_title' => 'Parques nacionales tanzanos: preguntas frecuentes',
    'parks_faq_q1' => '¿Cuál es el mejor parque nacional de Tanzania?',
    'parks_faq_a1' => 'Depende de lo que quiera. El Serengeti para la migración y depredadores, Ngorongoro para densidad y rinoceronte, Tarangire para elefantes, Ruaha para leones y soledad, Nyerere para safaris en bote. La mayoría de los buenos itinerarios combinan dos o tres en lugar de elegir uno.',
    'parks_faq_q2' => '¿Cuánto cuestan las tasas de parque tanzanas en 2026?',
    'parks_faq_a2' => 'Serengeti, Ngorongoro y Kilimanjaro están a 82,60 $ por adulto y día; Tarangire, lago Manyara, PN de Arusha y Nyerere están a 59,00 $; Ruaha y Mikumi están a 35,40 $. Todos incluyen 18% de IVA. Ngorongoro añade 295 $ por vehículo para descender al cráter.',
    'parks_faq_q3' => '¿Cuál es la diferencia entre los circuitos norte y sur?',
    'parks_faq_a3' => 'El circuito norte parte de Arusha e incluye el Serengeti, Ngorongoro, Tarangire, Manyara, PN de Arusha y Kilimanjaro. El circuito sur parte de Dar es Salaam y cubre Nyerere, Ruaha y Mikumi: más grandes, más vacíos, más económicos de entrar y más caros de alcanzar.',
    'parks_faq_q4' => '¿Qué parques puedo visitar en un día desde Arusha?',
    'parks_faq_a4' => 'El Parque Nacional de Arusha a 40 minutos, Tarangire y el lago Manyara a dos horas, y Ngorongoro a tres-cuatro horas. El Serengeti está a 7–8 horas y no es realista como excursión de un día.',
    'parks_faq_q5' => '¿Cuál es el parque más económico?',
    'parks_faq_a5' => 'Ruaha y Mikumi a 35,40 $ por adulto. Pero la entrada es solo parte del costo: Mikumi no necesita vuelo y es genuinamente el safari más económico de Tanzania, mientras que Ruaha requiere un vuelo de dos horas desde Dar.',
    'parks_faq_q6' => '¿Qué parque es mejor para los Big Five?',
    'parks_faq_a6' => 'Ngorongoro, porque es el único donde el rinoceronte negro es realistamente alcanzable. El Serengeti le da cuatro de los cinco fácilmente pero esencialmente ningún rinoceronte. Combinar los dos es la solución estándar.',
    'parks_faq_q7' => '¿Cuál es la mejor época para visitar los parques tanzanos?',
    'parks_faq_a7' => 'De junio a octubre es la temporada seca y la más fácil en todas partes. Enero y febrero convienen a la temporada de nacimientos del Serengeti. De marzo a mayo es húmedo: los parques del norte permanecen abiertos, pero la mayoría de los campamentos en Ruaha y Nyerere cierran completamente.',
    'parks_faq_q8' => '¿Cuántos días necesito para un safari tanzano?',
    'parks_faq_a8' => 'Dos días cubren bien Tarangire y Ngorongoro. Cuatro a cinco añaden el Serengeti adecuadamente. Seis a ocho le permiten seguir la migración o hacer el circuito sur.',
    'parks_faq_q9' => '¿Puedo pagar las tasas de parque en efectivo?',
    'parks_faq_a9' => 'No. Las entradas de TANAPA y NCAA no aceptan efectivo. Las tasas se pagan con tarjeta o tarjetas de parque precargadas. Cuando viaja con nosotros, esto se gestiona por usted y se incluye en el precio cotizado.',
    'parks_faq_q10' => '¿Necesito visitar todos los parques?',
    'parks_faq_a10' => 'No, y en un viaje corto no debería intentarlo. Dos parques bien hechos superan a cuatro apresurados. Un error común es meter el Serengeti en un viaje de cuatro días y pasar la mayor parte de él en el vehículo.',

    'parks_cta_title' => '¿No está seguro de qué parques elegir?',
    'parks_cta_intro' => 'Indíquenos cuántos días tiene y qué es lo que más quiere ver. Le diremos honestamente qué parques valen la pena para sus fechas, incluso cuando la respuesta sea "sáltese ese".',
    'parks_cta_whatsapp' => 'Escríbanos por WhatsApp',
    'parks_cta_contact_form' => 'Formulario de contacto',

    // ---------- Serengeti National Park page ----------
    'serengeti_meta_title' => 'Parque Nacional del Serengeti: la guía completa (2026) | Serengeti Budget Safari',
    'serengeti_meta_description' => 'Todo sobre el Parque Nacional del Serengeti: la Gran Migración mes a mes, las cinco regiones, la fauna, tasas de parque 2026, dónde alojarse y cuándo ir.',

    'serengeti_hero_badge' => 'Guía del parque',
    'serengeti_hero_title' => 'Parque Nacional del Serengeti',
    'serengeti_hero_sub' => 'La guía completa del parque más famoso de Tanzania: la Gran Migración mes a mes, dónde alojarse, cuánto cuesta y cuándo venir.',
    'serengeti_hero_cta_quote' => 'Solicitar presupuesto',

    'serengeti_intro_badge' => 'Introducción',
    'serengeti_intro_title' => '¿Qué es el Serengeti?',
    'serengeti_intro_p1' => 'El Parque Nacional del Serengeti cubre 14.763 km² del norte de Tanzania, aproximadamente el tamaño de Irlanda del Norte, y es el parque nacional más antiguo del país, declarado en 1951. Su nombre proviene de la palabra masái siringet, "el lugar donde la tierra se extiende para siempre".',
    'serengeti_intro_p2' => 'Es famoso por una cosa por encima de todo: la Gran Migración, el movimiento continuo de alrededor de 1,3 millones de ñus, 250.000 cebras y varios cientos de miles de gacelas siguiendo las lluvias en una ruta aproximadamente circular entre las llanuras del sur y el Masái Mara de Kenia. Este es el mayor movimiento terrestre de animales que queda en la tierra, y ocurre continuamente. No hay mes en que se detenga.',
    'serengeti_intro_p3' => 'El Serengeti también alberga una de las poblaciones de leones más densas de África (aproximadamente 3.000 animales) y más de 500 especies de aves registradas. Junto con el Área de Conservación del Ngorongoro forma un solo ecosistema de unos 30.000 km², y es Patrimonio de la Humanidad de la UNESCO desde 1981.',

    'serengeti_fact_area' => 'Superficie',
    'serengeti_fact_established' => 'Fundado en',
    'serengeti_fact_status' => 'Estado',
    'serengeti_fact_lions' => 'Leones',
    'serengeti_fact_wildebeest' => 'Ñus',
    'serengeti_fact_stay' => 'Estancia sugerida',
    'serengeti_fact_nights' => 'noches',
    'serengeti_fact_from_arusha' => 'Desde Arusha',
    'serengeti_fact_by_air' => 'En avión',

    'serengeti_regions_badge' => 'Dónde ir',
    'serengeti_regions_title' => 'Las cinco regiones del Serengeti',
    'serengeti_regions_intro' => 'El parque es más grande que algunos países, y dónde se aloje determina lo que verá. Estas son las principales zonas, y cuándo está cada una en su mejor momento.',
    'serengeti_region_seronera_name' => 'Seronera (Serengeti central)',
    'serengeti_region_seronera_desc' => 'El corazón del parque y la opción más segura para una primera visita. El valle del río retiene agua todo el año, así que la fauna residente nunca se va: leones, leopardos, elefantes, búfalos y guepardos están aquí cada mes. Ideal todo el año, perfecto para primeras visitas de 2–3 noches.',
    'serengeti_region_ndutu_name' => 'Ndutu y las llanuras del sur',
    'serengeti_region_ndutu_desc' => 'De diciembre a marzo, los troupeaux de la migración se concentran aquí para parir, y la densidad de depredadores que los siguen es extraordinaria. Es el mejor momento y lugar en Tanzania para observar una cacería. Fuera de esos meses, las llanuras se vacían casi por completo.',
    'serengeti_region_western_name' => 'Corredor occidental y el río Grumeti',
    'serengeti_region_western_desc' => 'Un largo brazo del parque que se extiende hacia el oeste hacia el Lago Victoria. Los troupeaux pasan por aquí de mayo a julio aproximadamente, y los cruces del Grumeti ocurren aquí, más pequeños que el Mara, pero con algunos de los cocodrilos más grandes de África esperando en las pozas.',
    'serengeti_region_kogatende_name' => 'Kogatende y el Serengeti del Norte',
    'serengeti_region_kogatende_desc' => 'Colinas onduladas y monte espeso a lo largo del río Mara, en la frontera con Kenia. De julio a octubre es aquí donde ocurren los cruces del río. Fuera de la temporada de cruces, es una de las partes más tranquilas y hermosas del parque.',

    'serengeti_migration_badge' => 'Gran Migración',
    'serengeti_migration_title' => 'La Gran Migración, mes a mes',
    'serengeti_migration_intro' => 'La migración no es un evento con una fecha. Es un circuito continuo impulsado por las lluvias, y las manadas están en algún lugar del ecosistema cada mes del año.',
    'serengeti_table_months' => 'Meses',
    'serengeti_table_where' => 'Dónde están las manadas',
    'serengeti_table_what_happens' => 'Qué sucede',
    'serengeti_mig_ndutu' => 'Ndutu y llanuras del sur',
    'serengeti_mig_calving' => 'Temporada de nacimientos. Alrededor de 400.000 crías nacidas, con la actividad de depredadores en su punto más alto del año.',
    'serengeti_mig_moving_nw' => 'Moviéndose hacia el noroeste',
    'serengeti_mig_rains' => 'Grandes lluvias. Las columnas se forman y se mueven a través del Serengeti central hacia el Corredor Occidental.',
    'serengeti_mig_western' => 'Corredor occidental',
    'serengeti_mig_grumeti' => 'Cruces del río Grumeti. Más pequeños que el Mara pero con enormes cocodrilos y una fracción de los vehículos.',
    'serengeti_mig_northern' => 'Serengeti del Norte y Masái Mara',
    'serengeti_mig_mara' => 'Cruces del río Mara: la imagen clásica. Agosto y septiembre son los meses pico.',
    'serengeti_mig_returning' => 'Regresando al sur',
    'serengeti_mig_south' => 'Las lluvias cortas atraen a las manadas de regreso a través del Serengeti oriental hacia las zonas de nacimiento.',
    'serengeti_migration_note' => 'La lluvia desplaza este patrón dos o tres semanas en cualquier dirección. Ningún operador puede prometer un cruce en una fecha fija.',

    'serengeti_wildlife_badge' => 'Fauna',
    'serengeti_wildlife_title' => 'Fauna: lo que realmente verá',
    'serengeti_wildlife_intro' => 'En un safari de tres días en el Serengeti central, basado en los registros de avistamiento de nuestros guías.',
    'serengeti_animal_lion' => 'León, la mayor densidad de África',
    'serengeti_animal_leopard' => 'Leopardo, valle de Seronera',
    'serengeti_animal_elephant' => 'Elefante',
    'serengeti_animal_buffalo' => 'Búfalo',
    'serengeti_animal_cheetah' => 'Guepardo, llanuras del sur',
    'serengeti_animal_zebra' => 'Cebra',
    'serengeti_animal_giraffe' => 'Jirafa',
    'serengeti_animal_hyena' => 'Hiena manchada',
    'serengeti_animal_rhino' => 'Rinoceronte negro, muy raro, solo Moru Kopjes',
    'serengeti_wildlife_p1' => 'León, leopardo, elefante y búfalo son todos realistas en un safari de tres días al Serengeti. El rinoceronte negro no: una pequeña población protegida sobrevive alrededor de los Moru Kopjes, pero los avistamientos son raros y generalmente distantes. Si ver rinocerontes le importa, añada el Cráter del Ngorongoro a su itinerario.',
    'serengeti_wildlife_p2' => 'La población de leones del Serengeti de alrededor de 3.000 es la mayor de África, organizada en manadas que mantienen territorio durante generaciones. Los guepardos favorecen las llanuras abiertas del sur donde pueden correr; los leopardos favorecen las acacias ribereñas. Las hienas manchadas son mucho más numerosas de lo que la mayoría de los visitantes espera y son cazadoras consumadas por derecho propio.',

    'serengeti_when_badge' => 'Mejor época',
    'serengeti_when_title' => 'Cuándo visitar',
    'serengeti_when_intro' => 'No hay temporada cerrada. Lo que cambia es lo que ve, cuántos otros vehículos hay en el avistamiento, y lo que paga.',
    'serengeti_when_p1' => 'Primer safari, quiere que sea fácil: junio a octubre. Vegetación escasa, animales concentrados en el agua, clima fiable. Quiere el mayor drama faunístico: finales de enero a febrero en Ndutu.',
    'serengeti_when_p2' => 'Quiere buena relación calidad-precio y espacio: marzo, abril, mayo o noviembre. Tendrá lluvia, y también tendrá el parque casi para usted solo a una fracción del precio.',

    'serengeti_stay_badge' => 'Alojamiento',
    'serengeti_stay_title' => 'Dónde alojarse',
    'serengeti_stay_intro' => 'El alojamiento es la variable más grande en lo que cuesta un safari al Serengeti. Las distancias son tan grandes que dónde duerme determina cuánto de su día se pasa conduciendo en lugar de observando.',
    'serengeti_stay_budget_title' => 'Económico',
    'serengeti_stay_budget_price' => 'desde 35,40 $/noche de tasa de parque + camping',
    'serengeti_stay_budget_desc' => 'Camping público: su propia tienda, baños compartidos de pozo y duchas frías, el cocinero prepara las comidas en el sitio. Dentro del parque, para los aventureros.',
    'serengeti_stay_mid_title' => 'Gama media',
    'serengeti_stay_mid_price' => '150–400 $/noche',
    'serengeti_stay_mid_desc' => 'Lodge o campamento con tienda dentro del parque: edificio permanente o lona con camas de verdad y baños privados. Se despierta dentro del ecosistema.',
    'serengeti_stay_luxury_title' => 'Lujo',
    'serengeti_stay_luxury_price' => '300–700 $+/noche',
    'serengeti_stay_luxury_desc' => 'Campamentos móviles que se reubican para seguir la migración, o campamentos con tienda premium. Pequeños, remotos, pocos vehículos cerca.',
    'serengeti_stay_note' => 'Dormir dentro del parque cuesta más: una tasa de concesión de 59,00 $ por adulto y noche además de la tarifa de la habitación. Pero ya está en medio de la acción al amanecer y al anochecer, cuando los depredadores están más activos.',

    'serengeti_fees_badge' => 'Costos',
    'serengeti_fees_title' => 'Tasas de parque (2026)',
    'serengeti_fees_intro' => 'Las tasas son fijadas por TANAPA, la Autoridad de Parques Nacionales de Tanzania, y son idénticas para cada operador.',
    'serengeti_table_category' => 'Categoría',
    'serengeti_table_adult' => 'Adulto (16+)',
    'serengeti_table_child' => 'Niño (5–15)',
    'serengeti_fee_entry' => 'Entrada, por 24 horas',
    'serengeti_fee_concession' => 'Concesión, dormir dentro del parque (por noche)',
    'serengeti_fee_campsite' => 'Camping público (por noche)',
    'serengeti_fees_note' => 'Todas las cifras incluyen 18% de IVA. Los niños menores de 5 años entran gratis. Las tasas son revisadas por el gobierno y pueden cambiar sin previo aviso. Su presupuesto escrito siempre indica el monto exacto para sus fechas.',

    'serengeti_gallery_badge' => 'Galería',
    'serengeti_gallery_title' => 'El Serengeti en imágenes',
    'serengeti_gallery_caption_1' => 'Manada de leones con una presa',
    'serengeti_gallery_caption_2' => 'Leopardo descansando en un árbol',
    'serengeti_gallery_caption_3' => 'Manada de cebras en las llanuras',
    'serengeti_gallery_caption_4' => 'Guepardos a la sombra',
    'serengeti_gallery_caption_5' => 'Leones acechando cebras',
    'serengeti_gallery_caption_6' => 'Leopardo, vista amplia',

    'serengeti_back_to_parks' => 'Comparar todos los parques',

    'serengeti_faq_badge' => 'Preguntas frecuentes',
    'serengeti_faq_title' => 'Parque Nacional del Serengeti: preguntas frecuentes',
    'serengeti_faq_q1' => '¿Cuánto cuesta entrar al Serengeti?',
    'serengeti_faq_a1' => 'La tasa de entrada 2026 para no residentes es de 82,60 $ por adulto y 23,60 $ por niño de 5 a 15 años, por 24 horas, incluyendo 18% de IVA. Los niños menores de 5 años entran gratis. Si duerme dentro del parque también hay una tasa de concesión de 59,00 $ por adulto y noche, o 35,40 $ para un camping público.',
    'serengeti_faq_q2' => '¿Cuántos días necesito en el Serengeti?',
    'serengeti_faq_a2' => 'Tres días es el mínimo realista, y cuatro a cinco es el punto óptimo. Con menos de tres días, el largo viaje desde Arusha consume la mayor parte de su viaje. Vería más fauna visitando en cambio Tarangire, el Lago Manyara y el Cráter del Ngorongoro.',
    'serengeti_faq_q3' => '¿Cuál es la mejor época para visitar el Serengeti?',
    'serengeti_faq_a3' => 'Junio a octubre para la observación de fauna más fácil y los cruces del río Mara. Finales de enero y febrero para la temporada de nacimientos en Ndutu, que es posiblemente el mejor espectáculo faunístico. Marzo a mayo es húmedo, vacío y el más económico.',
    'serengeti_faq_q4' => '¿Veré definitivamente un cruce de río?',
    'serengeti_faq_a4' => 'No, y sea escéptico con cualquiera que prometa uno. Los cruces son impredecibles: las manadas pueden esperar en la orilla todo un día y luego alejarse. Tres noches en Kogatende entre julio y octubre le dan una buena oportunidad, no una garantía.',
    'serengeti_faq_q5' => '¿Puedo ver los Big Five en el Serengeti?',
    'serengeti_faq_a5' => 'Cuatro de ellos de forma fiable: león, leopardo, elefante y búfalo. El rinoceronte negro sobrevive solo en pequeños números alrededor de los Moru Kopjes y rara vez se ve. Para el rinoceronte, añada el Cráter del Ngorongoro a su itinerario.',
    'serengeti_faq_q6' => '¿Cómo llego de Arusha al Serengeti?',
    'serengeti_faq_a6' => 'Por carretera son unos 325 km y 7–8 horas hasta Seronera, generalmente fraccionadas con una parada en Ngorongoro o Karatu. En avión ligero son alrededor de 1 hora 15 minutos. Muchos itinerarios van en coche en un sentido y vuelan en el otro.',
    'serengeti_faq_q7' => '¿Puedo hacer un safari al Serengeti con presupuesto ajustado?',
    'serengeti_faq_a7' => 'Sí, los safaris en camping comienzan desde alrededor de 200 € por persona y día. Obtiene el mismo guía, el mismo vehículo y los mismos animales; ahorra en dónde duerme. Viajar en un grupo de cuatro en lugar de dos también reduce sustancialmente el costo por persona.',
    'serengeti_faq_q8' => '¿Es el Serengeti mejor que el Masái Mara?',
    'serengeti_faq_a8' => 'Son el mismo ecosistema dividido por una frontera. El Serengeti es aproximadamente quince veces más grande, tiene hábitats más variados y mucho más espacio entre vehículos; el Mara es más compacto, así que los avistamientos llegan más rápido pero con más aglomeración.',

    'serengeti_cta_title' => '¿Listo para planificar su safari al Serengeti?',
    'serengeti_cta_intro' => 'Envíenos sus fechas, tamaño del grupo y presupuesto. Respondemos con un itinerario escrito y un desglose completo de precios, sin compromiso.',
    'serengeti_cta_whatsapp' => 'Escríbanos por WhatsApp',
    'serengeti_cta_safaris' => 'Ver itinerarios de safari',

    'ngorongoro_meta_title' => 'Cráter del Ngorongoro: la guía completa (2026) | Serengeti Budget Safari',
    'ngorongoro_meta_description' => 'Todo sobre el Cráter del Ngorongoro: probabilidades de rinoceronte negro, la tasa de descenso 2026 de 295 $, cuándo ir, dónde alojarse y los masái que viven allí.',

    'ngorongoro_hero_badge' => 'Guía del parque',
    'ngorongoro_hero_title' => 'Cráter del Ngorongoro',
    'ngorongoro_hero_sub' => 'La mayor caldera intacta de la Tierra, 25.000 animales dentro de un tazón de 260 km², y la mejor oportunidad de rinoceronte negro en Tanzania, todo en un solo día.',
    'ngorongoro_hero_cta_quote' => 'Solicitar presupuesto',

    'ngorongoro_intro_badge' => 'Introducción',
    'ngorongoro_intro_title' => '¿Qué es el Cráter del Ngorongoro?',
    'ngorongoro_intro_p1' => 'El Cráter del Ngorongoro es la mayor caldera volcánica intacta de la Tierra: un tazón de 19 km de diámetro, 610 m de profundidad y 260 km² de superficie, con paredes que se elevan casi verticalmente desde el fondo. Alrededor de 25.000 grandes animales viven dentro permanentemente, dándole la mayor densidad de gran fauna en cualquier lugar de África.',
    'ngorongoro_intro_p2' => 'El cráter se encuentra dentro del mucho más grande Área de Conservación del Ngorongoro, 8.292 km² de tierras altas, bosque y llanuras que también contiene la Garganta de Olduvai, los cráteres de Empakaai y Olmoti, y las llanuras de Ndutu donde la Gran Migración pare. Es Patrimonio de la Humanidad de la UNESCO e inusual en África por ser un área de uso múltiple: alrededor de 100.000 masái viven aquí con su ganado junto a la fauna.',
    'ngorongoro_intro_p3' => 'Para la mayoría de los visitantes un hecho lo resuelve: este es el lugar más fiable de Tanzania para ver rinoceronte negro, y por lo tanto el lugar donde completar los Big Five en un solo día es genuinamente posible.',

    'ngorongoro_fact_crater_area' => 'Fondo del cráter',
    'ngorongoro_fact_nca_area' => 'Área de conservación',
    'ngorongoro_fact_status' => 'Estado',
    'ngorongoro_fact_rhino' => 'Rinoceronte negro',
    'ngorongoro_fact_animals' => 'Animales en el cráter',
    'ngorongoro_fact_stay' => 'Estancia sugerida',
    'ngorongoro_fact_day' => 'día',
    'ngorongoro_fact_from_arusha' => 'Desde Arusha',
    'ngorongoro_fact_descent_limit' => 'Límite de descenso al cráter',

    'ngorongoro_areas_badge' => 'Entender la zona',
    'ngorongoro_areas_title' => 'El cráter frente al Área de Conservación más amplia',
    'ngorongoro_areas_intro' => 'La gente a menudo dice "Ngorongoro" para referirse a dos cosas diferentes. Aquí está la distinción, y por qué importa para su itinerario.',
    'ngorongoro_area_floor_name' => 'El fondo del cráter',
    'ngorongoro_area_floor_desc' => 'La caldera de 260 km² en sí: un tazón autónomo donde la mayoría de los animales viven todo el año porque las paredes los mantienen dentro. Esto es lo que casi todos quieren decir cuando dicen "Cráter del Ngorongoro", y es donde pasa su día de game drive.',
    'ngorongoro_area_wider_name' => 'El Área de Conservación',
    'ngorongoro_area_wider_desc' => 'La región completa de 8.292 km² que rodea el cráter: tierras altas, bosque, las llanuras de Ndutu y dos cráteres más, Empakaai y Olmoti. Es un área de uso múltiple catalogada por la UNESCO donde aproximadamente 100.000 masái viven junto a la fauna, a diferencia de un parque nacional donde las personas están excluidas.',
    'ngorongoro_area_olduvai_name' => 'Garganta de Olduvai',
    'ngorongoro_area_olduvai_desc' => 'A media hora del cráter, en el camino hacia el Serengeti, la Garganta de Olduvai corta 90 m a través de dos millones de años de sedimentos volcánicos. Louis y Mary Leakey trabajaron aquí desde la década de 1930 y encontraron restos de homínidos que remodelaron lo que se sabía sobre los orígenes humanos, incluido Paranthropus boisei en 1959. Hay un pequeño museo, y encaja fácilmente en el trayecto entre el Ngorongoro y el Serengeti.',

    'ngorongoro_maasai_badge' => 'Población',
    'ngorongoro_maasai_title' => 'Los masái que viven aquí',
    'ngorongoro_maasai_intro' => 'El Ngorongoro no es un parque nacional, y la distinción es deliberada.',
    'ngorongoro_maasai_p1' => 'Cuando el Serengeti fue declarado en 1959, los masái que vivían allí fueron desplazados; el Ngorongoro fue creado como un área de conservación de uso múltiple donde personas, ganado y fauna comparten la tierra. Alrededor de 100.000 masái viven en el Área de Conservación hoy con aproximadamente un millón de cabezas de ganado, pastando el fondo del cráter de día y regresando al borde por la noche.',
    'ngorongoro_maasai_p2' => 'Visitar un boma masái es posible y se organiza a través de la autoridad de conservación. La calidad varía. Algunas visitas están muy escenificadas. Trabajamos con comunidades con las que tenemos relaciones de larga data, donde la tasa llega a la aldea y puede realmente hacer preguntas.',

    'ngorongoro_wildlife_badge' => 'Fauna',
    'ngorongoro_wildlife_title' => 'Fauna: lo que realmente verá',
    'ngorongoro_wildlife_intro' => 'Probabilidades de avistamiento para un solo día completo en el fondo del cráter. Inusualmente altas, porque los animales no pueden dispersarse.',
    'ngorongoro_animal_lion' => 'León, alrededor del 95% de probabilidad',
    'ngorongoro_animal_rhino' => 'Rinoceronte negro, alrededor del 60% de probabilidad',
    'ngorongoro_animal_buffalo' => 'Búfalo, casi seguro',
    'ngorongoro_animal_zebra' => 'Cebra, casi seguro',
    'ngorongoro_animal_elephant' => 'Elefante, machos del Bosque Lerai',
    'ngorongoro_animal_hippo' => 'Hipopótamo, Pantano Gorigor',
    'ngorongoro_animal_hyena' => 'Hiena manchada',
    'ngorongoro_animal_flamingo' => 'Flamenco, Lago Magadi',
    'ngorongoro_animal_leopard' => 'Leopardo, raro, solo bosque del borde',
    'ngorongoro_wildlife_p1' => 'León, búfalo, elefante y rinoceronte negro son todos realistas en un solo día de cráter: una oportunidad genuina de los Big Five en 24 horas, lo cual es inusual en cualquier lugar de África. Solo el leopardo es un verdadero golpe de suerte: viven en el bosque del borde y rara vez se ven desde el fondo. No hay jirafas en absoluto: los caminos de descenso son demasiado empinados para ellas.',
    'ngorongoro_wildlife_p2' => 'Los leones del cráter están entre los más estudiados del mundo e ilustran el costo del aislamiento: la población está efectivamente cerrada, la diversidad genética es baja, y un brote de enfermedad en 1962 los redujo a un puñado de animales. Los números hoy rondan los 60, y están muy habituados a los vehículos. Alrededor de 30 rinocerontes negros viven en el cráter bajo protección de rangers las 24 horas, generalmente vistos a distancia a través de la hierba abierta, así que traiga prismáticos.',

    'ngorongoro_when_badge' => 'Mejor época',
    'ngorongoro_when_title' => 'Cuándo visitar',
    'ngorongoro_when_intro' => 'El cráter funciona todos los meses. Los animales no migran, así que a diferencia del Serengeti no hay temporada equivocada para la observación de fauna.',
    'ngorongoro_when_p1' => 'Junio a octubre es el más seco, el más frío al amanecer y el más concurrido: espere otros vehículos en cada avistamiento. Marzo a mayo trae las grandes lluvias: caminos de descenso resbaladizos y niebla que puede quedarse en el borde hasta media mañana, pero también el cráter más verde y las tarifas más económicas.',
    'ngorongoro_when_p2' => 'Más importante que el mes es estar en el fondo a las 06:30. Los depredadores están activos en las primeras dos horas, la luz es suave, y va por delante de los vehículos que descienden a las nueve. Esta sola decisión cambia la calidad del día más que la temporada.',

    'ngorongoro_stay_badge' => 'Alojamiento',
    'ngorongoro_stay_title' => 'Dónde alojarse',
    'ngorongoro_stay_intro' => 'Tres grandes opciones, y la decisión es principalmente sobre qué tan temprano puede estar en la puerta de descenso.',
    'ngorongoro_stay_budget_title' => 'Económico',
    'ngorongoro_stay_budget_price' => 'desde 35,40 $/noche de tasa de camping',
    'ngorongoro_stay_budget_desc' => 'Camping público Simba, en el propio borde: su propia tienda, instalaciones compartidas básicas, y búfalos o cebras a veces deambulando por el campamento de noche. Frío a 2.400 m: un saco de dormir adecuado no es opcional.',
    'ngorongoro_stay_mid_title' => 'Karatu',
    'ngorongoro_stay_mid_price' => '60–200 $/noche',
    'ngorongoro_stay_mid_desc' => 'Una ciudad real a 30–45 minutos de la entrada: mucho mejor relación calidad-precio, más cálida, más opciones de restaurantes. La contrapartida es un comienzo temprano, saliendo alrededor de las 05:30 para ser el primero en el camino de descenso.',
    'ngorongoro_stay_luxury_title' => 'Lodge en el borde del cráter',
    'ngorongoro_stay_luxury_price' => '250–800 $+/noche',
    'ngorongoro_stay_luxury_desc' => 'La vista directa hacia el cráter desde su habitación, y a diez minutos del camino de descenso para poder ser el primero en el fondo. Caro, frío de noche, y a menudo reservado meses de antelación.',
    'ngorongoro_stay_note' => 'Si visita por un solo día y el costo no es el factor decisivo, quédese en el borde. Ser el primero en el fondo vale mucho. Si tiene varios días en la zona, Karatu es la base sensata y el dinero ahorrado puede pagar una noche extra en el Serengeti.',

    'ngorongoro_fees_badge' => 'Costos',
    'ngorongoro_fees_title' => 'Tasas de parque (2026)',
    'ngorongoro_fees_intro' => 'El Ngorongoro es administrado por la NCAA, no la TANAPA, y tiene un cargo que sorprende a la gente: una tasa separada simplemente por conducir hacia el cráter, cobrada por vehículo en lugar de por persona.',
    'ngorongoro_table_category' => 'Categoría',
    'ngorongoro_table_adult' => 'Adulto (16+)',
    'ngorongoro_table_child' => 'Niño (5–15)',
    'ngorongoro_fee_entry' => 'Entrada al Área de Conservación, por 24 horas',
    'ngorongoro_fee_descent' => 'Tasa de servicio del cráter (descenso, por vehículo)',
    'ngorongoro_fee_descent_value' => '295,00 $ por vehículo',
    'ngorongoro_fee_concession' => 'Concesión, dormir dentro del ACN (por noche)',
    'ngorongoro_fee_campsite' => 'Camping público (por noche)',
    'ngorongoro_fees_note' => 'Todas las cifras incluyen 18% de IVA. Los niños menores de 5 años entran gratis. La tasa de descenso al cráter es por vehículo, no por persona, así que el costo por cabeza cae drásticamente con el tamaño del grupo: aproximadamente 148 $ cada uno para dos personas, menos de 50 $ cada uno para seis. Se aplica cada vez que desciende, así que un segundo día de cráter significa pagarla dos veces. Las tasas pueden cambiar sin previo aviso; su presupuesto escrito siempre indica el monto exacto para sus fechas.',

    'ngorongoro_gallery_badge' => 'Galería',
    'ngorongoro_gallery_title' => 'El Ngorongoro en imágenes',
    'ngorongoro_gallery_caption_1' => 'El cráter desde el borde',
    'ngorongoro_gallery_caption_2' => 'Rinoceronte en la pradera',
    'ngorongoro_gallery_caption_3' => 'Elefante bajo una acacia',
    'ngorongoro_gallery_caption_4' => 'León macho en el fondo del cráter',
    'ngorongoro_gallery_caption_5' => 'Hiena manchada en las llanuras',
    'ngorongoro_gallery_caption_6' => 'Familia de elefantes al atardecer',

    'ngorongoro_back_to_parks' => 'Comparar todos los parques',

    'ngorongoro_faq_badge' => 'Preguntas frecuentes',
    'ngorongoro_faq_title' => 'Cráter del Ngorongoro: preguntas frecuentes',
    'ngorongoro_faq_q1' => '¿Cuánto cuesta visitar el Cráter del Ngorongoro?',
    'ngorongoro_faq_a1' => 'En 2026, 82,60 $ por adulto por 24 horas para entrar al Área de Conservación, más una tasa de servicio del cráter de 295,00 $ por vehículo para el descenso. Los niños de 5 a 15 años pagan 23,60 $; los menores de cinco años son gratis. Todas las cifras incluyen 18% de IVA.',
    'ngorongoro_faq_q2' => '¿Por qué es tan alta la tasa de descenso al cráter?',
    'ngorongoro_faq_a2' => 'Se cobra por vehículo en lugar de por persona y financia la conservación y el programa de protección del rinoceronte. Como es por vehículo, el costo por cabeza cae drásticamente con el tamaño del grupo: alrededor de 148 $ cada uno para dos personas, menos de 50 $ cada uno para seis.',
    'ngorongoro_faq_q3' => '¿Veré rinoceronte negro en el cráter?',
    'ngorongoro_faq_a3' => 'Alrededor de 30 viven en el cráter y las probabilidades en un día completo son aproximadamente del 60%, pero generalmente a distancia a través de la hierba abierta. Traiga prismáticos. La mañana temprano ofrece la mejor oportunidad, antes de que se retiren hacia los márgenes del pantano.',
    'ngorongoro_faq_q4' => '¿Puedo ver los Big Five en un día?',
    'ngorongoro_faq_a4' => 'En el Ngorongoro esto es genuinamente posible, lo cual es inusual. León, búfalo y elefante son casi seguros, el rinoceronte es probable, y solo el leopardo es un verdadero golpe de suerte: viven en el bosque del borde y rara vez se ven desde el fondo.',
    'ngorongoro_faq_q5' => '¿Cuánto tiempo puedo quedarme en el cráter?',
    'ngorongoro_faq_a5' => 'Seis horas desde el momento en que desciende. El límite se aplica en la puerta de salida y existe para controlar el número de vehículos en un fondo pequeño.',
    'ngorongoro_faq_q6' => '¿A qué distancia está el Ngorongoro de Arusha, y puedo hacerlo como excursión de un día?',
    'ngorongoro_faq_a6' => 'Unos 180 km, tres a cuatro horas por carretera. Sí, una excursión de un día es posible, saliendo alrededor de las 05:30 y regresando después del anochecer, y sigue siendo uno de nuestros safaris de un día más solicitados, ya que se encuentra directamente en la ruta hacia el Serengeti.',
    'ngorongoro_faq_q7' => '¿Cuál es la diferencia entre el cráter y el Área de Conservación?',
    'ngorongoro_faq_a7' => 'El cráter es el fondo de la caldera de 260 km². El Área de Conservación es la región de 8.292 km² que lo rodea, que también incluye la Garganta de Olduvai, los cráteres de Empakaai y Olmoti, las llanuras de Ndutu y alrededor de 100.000 residentes masái.',
    'ngorongoro_faq_q8' => '¿Debo alojarme en el borde o en Karatu?',
    'ngorongoro_faq_a8' => 'Los lodges del borde cuestan 250–800 $ y le permiten ser el primero en el fondo. Karatu cuesta 60–200 $ y añade un trayecto de 30–45 minutos antes del amanecer. Para un solo día de cráter, el borde vale la pena; para estancias más largas Karatu ofrece mejor relación calidad-precio.',

    'ngorongoro_cta_title' => '¿Listo para planificar su safari al Ngorongoro?',
    'ngorongoro_cta_intro' => 'Envíenos sus fechas, tamaño del grupo y presupuesto. Respondemos con un itinerario escrito y un desglose completo de precios, sin compromiso.',
    'ngorongoro_cta_whatsapp' => 'Escríbanos por WhatsApp',
    'ngorongoro_cta_safaris' => 'Ver itinerarios de safari',

    'tarangire_meta_title' => 'Parque Nacional de Tarangire: la guía completa (2026) | Serengeti Budget Safari',
    'tarangire_meta_description' => 'Todo sobre el Parque Nacional de Tarangire: elefantes, baobabs antiguos, 550 especies de aves, tasas de parque 2026, dónde alojarse y cuándo ir.',

    'tarangire_hero_badge' => 'Guía del parque',
    'tarangire_hero_title' => 'Parque Nacional de Tarangire',
    'tarangire_hero_sub' => 'Baobabs antiguos, las mayores manadas de elefantes del norte de Tanzania y más especies de aves que cualquier otro parque del país. A dos horas de Arusha, y mucho más tranquilo que sus vecinos.',
    'tarangire_hero_cta_quote' => 'Solicitar presupuesto',

    'tarangire_intro_badge' => 'Introducción',
    'tarangire_intro_title' => '¿Qué es Tarangire?',
    'tarangire_intro_p1' => 'El Parque Nacional de Tarangire cubre 2.850 km² de bosque seco de acacias y país de baobabs a dos horas al sur de Arusha. Es el sexto parque más grande de Tanzania y, por razones difíciles de justificar, el más sistemáticamente pasado por alto en el circuito norte.',
    'tarangire_intro_p2' => 'Lleva el nombre del río Tarangire, que fluye a lo largo del parque y es la única agua permanente en kilómetros a la redonda. En la temporada seca, ese solo hecho transforma el lugar: animales de un ecosistema mucho más grande convergen en el río, y la concentración de fauna entre junio y octubre rivaliza con cualquier cosa en el Serengeti.',
    'tarangire_intro_p3' => 'Tarangire es más conocido por dos cosas: elefantes, con una población residente de 2.500 a 3.000 y manadas de cincuenta o más siendo comunes aquí, y baobabs, los enormes árboles de tronco hinchado que dan al paisaje un carácter que no se encuentra en ningún otro lugar del circuito. También alberga más de 550 especies de aves registradas, el mayor conteo de cualquier parque tanzano.',

    'tarangire_fact_area' => 'Superficie',
    'tarangire_fact_established' => 'Fundado en',
    'tarangire_fact_elephants' => 'Elefantes',
    'tarangire_fact_baobabs' => 'Baobabs',
    'tarangire_fact_baobabs_value' => 'Miles',
    'tarangire_fact_birds' => 'Especies de aves',
    'tarangire_fact_stay' => 'Estancia sugerida',
    'tarangire_fact_days' => 'días',
    'tarangire_fact_from_arusha' => 'Desde Arusha',
    'tarangire_fact_river' => 'Río Tarangire',
    'tarangire_fact_river_value' => 'Agua permanente',

    'tarangire_zones_badge' => 'Dónde ir',
    'tarangire_zones_title' => 'Las zonas de Tarangire',
    'tarangire_zones_intro' => 'El parque es más pequeño que el Serengeti, pero dónde vaya aún cambia lo que ve. Estas son las principales zonas, y por qué es conocida cada una.',
    'tarangire_zone_river_name' => 'El circuito del río Tarangire',
    'tarangire_zone_river_desc' => 'El corazón del parque y la primera visita clásica. El río retiene agua todo el año, y en la temporada seca atrae elefantes, búfalos, cebras y leones para beber y cavar en busca de agua en el lecho arenoso. La mayoría de los lodges y la red principal de game drives se encuentran a lo largo de este tramo.',
    'tarangire_zone_silale_name' => 'Pantano de Silale',
    'tarangire_zone_silale_desc' => 'Un gran pantano estacional en el centro del parque que retiene agua hasta la temporada seca. Atrae elefantes, búfalos y números excepcionales de aves y rapaces, y vale la pena el trayecto adicional desde el circuito principal del río.',
    'tarangire_zone_south_name' => 'Las extensiones del sur',
    'tarangire_zone_south_desc' => 'Más seco, más salvaje y raramente visitado por excursionistas de un día. Aquí es donde viven los antílopes de país seco (órix de orejas flecadas, kudú menor y gerenuk), y donde los visitantes de dos días son recompensados con la observación de fauna más tranquila del parque.',
    'tarangire_zone_north_name' => 'La zona de la entrada norte',
    'tarangire_zone_north_desc' => 'Alrededor de la entrada de Kwa Kuchinja, la parte del parque más cercana a Arusha. Colinas onduladas salpicadas de baobabs y pradera abierta hacen de este el tramo más fácil para una excursión de un día, con buena observación de fauna cerca de la propia entrada.',

    'tarangire_wildlife_badge' => 'Fauna',
    'tarangire_wildlife_title' => 'Fauna: lo que realmente verá',
    'tarangire_wildlife_intro' => 'Probabilidades de avistamiento para un día completo en temporada seca (junio–octubre), basadas en los registros de nuestros guías. En la temporada húmeda los animales se dispersan y cada cifra cae sustancialmente.',
    'tarangire_animal_elephant' => 'Elefante, enormes manadas, 99%',
    'tarangire_animal_zebra' => 'Cebra',
    'tarangire_animal_buffalo' => 'Búfalo',
    'tarangire_animal_giraffe' => 'Jirafa',
    'tarangire_animal_wildebeest' => 'Ñu',
    'tarangire_animal_lion' => 'León, a veces en árboles',
    'tarangire_animal_leopard' => 'Leopardo, alrededor del 25%',
    'tarangire_animal_hyena' => 'Hiena manchada',
    'tarangire_animal_oryx' => 'Órix de orejas flecadas, extensiones del sur',
    'tarangire_wildlife_p1' => 'Elefante, búfalo y león son todos realistas en un safari a Tarangire, y el elefante está cerca de la certeza en la temporada seca. El leopardo es posible pero poco común, alrededor del 25%, el guepardo es pura suerte, y no hay rinoceronte aquí en absoluto. Para los Big Five completos, combine Tarangire con el Cráter del Ngorongoro.',
    'tarangire_wildlife_p2' => 'Lo que hace que Tarangire valga la pena observar en lugar de simplemente contar es el comportamiento de los elefantes: en los meses secos puede ver a las matriarcas cavar pozos de un metro de profundidad en la arena del lecho del río, con cebras, impalas y babuinos esperando a distancia respetuosa para beber una vez que los elefantes se alejan. Las secas extensiones del sur de Tarangire también albergan tres antílopes difíciles de encontrar en el resto del circuito norte: el órix de orejas flecadas, el kudú menor y el gerenuk, que se para sobre sus patas traseras para ramonear.',

    'tarangire_when_badge' => 'Mejor época',
    'tarangire_when_title' => 'Cuándo visitar',
    'tarangire_when_intro' => 'Tarangire es el parque más fuertemente estacional del circuito norte. La diferencia entre agosto y abril no es una cuestión de grado. Es un parque diferente.',
    'tarangire_when_p1' => 'Julio a octubre es excepcional: el río es la única agua en kilómetros y todo llega a él, con las manadas de elefantes en su punto máximo. Junio es muy bueno y aún más tranquilo. Noviembre y diciembre traen las lluvias cortas. Los animales comienzan a dispersarse, pero es magnífico para las aves y los paisajes verdes fotogénicos.',
    'tarangire_when_p2' => 'Marzo a mayo, las grandes lluvias, es el período más débil para la fauna, con animales dispersos por una gran zona, pero es el mejor momento para la observación de aves y para tener el parque para usted solo. Si la gran fauna es su prioridad y solo puede visitar durante las grandes lluvias, considere pasar ese día en el Ngorongoro en su lugar, donde los animales del cráter no se dispersan.',

    'tarangire_stay_badge' => 'Alojamiento',
    'tarangire_stay_title' => 'Dónde alojarse',
    'tarangire_stay_intro' => 'Como Tarangire está a solo dos horas de Arusha, pernoctar es una elección más que una necesidad, pero cambia lo que ve. La mejor actividad de elefantes es al amanecer y al anochecer, y los visitantes de un día se pierden ambos.',
    'tarangire_stay_budget_title' => 'Económico',
    'tarangire_stay_budget_price' => 'desde 35,40 $/noche de tasa de parque + camping',
    'tarangire_stay_budget_desc' => 'Camping público dentro del parque: su propia tienda, baños básicos de pozo y agua fría, el cocinero prepara las comidas en el sitio. La forma más económica de dormir dentro de Tarangire.',
    'tarangire_stay_mid_title' => 'Gama media',
    'tarangire_stay_mid_price' => '150–400 $/noche',
    'tarangire_stay_mid_desc' => 'Lodge o campamento con tienda dentro del parque, varios situados en el escarpe con vista al río. Puede observar elefantes desde la terraza y ser el primero en las pistas por la mañana.',
    'tarangire_stay_luxury_title' => 'Fuera de la entrada',
    'tarangire_stay_luxury_price' => '60–150 $/noche',
    'tarangire_stay_luxury_desc' => 'Lodges justo fuera del límite del parque, a solo 15–30 minutos de la entrada. La opción más competitiva fuera del parque en todo el circuito, y cómo recomendamos recortar un presupuesto sin perder la experiencia.',
    'tarangire_stay_note' => 'Dormir dentro del parque cuesta más: una tasa de concesión de 47,20 $ por adulto y noche además de la tarifa de la habitación. Pero ya está en medio de la acción al amanecer y al anochecer, cuando la actividad de los elefantes alcanza su punto máximo.',

    'tarangire_fees_badge' => 'Costos',
    'tarangire_fees_title' => 'Tasas de parque (2026)',
    'tarangire_fees_intro' => 'Tarangire es un parque "select" bajo la tarifa de TANAPA, lo que lo hace sustancialmente más económico que el Serengeti o el Ngorongoro, una de las razones por las que ofrece tan buena relación calidad-precio.',
    'tarangire_table_category' => 'Categoría',
    'tarangire_table_adult' => 'Adulto (16+)',
    'tarangire_table_child' => 'Niño (5–15)',
    'tarangire_fee_entry' => 'Entrada, por 24 horas',
    'tarangire_fee_concession' => 'Concesión, dormir dentro del parque (por noche)',
    'tarangire_fee_campsite' => 'Camping público (por noche)',
    'tarangire_fees_note' => 'Todas las cifras incluyen 18% de IVA. Los niños menores de 5 años entran gratis. Las tasas son revisadas por el gobierno y pueden cambiar sin previo aviso. Su presupuesto escrito siempre indica el monto exacto para sus fechas.',

    'tarangire_gallery_badge' => 'Galería',
    'tarangire_gallery_title' => 'Tarangire en imágenes',
    'tarangire_gallery_caption_1' => 'Familia de elefantes al atardecer',
    'tarangire_gallery_caption_2' => 'Retrato de primer plano de un elefante',
    'tarangire_gallery_caption_3' => 'Amanecer en la sabana entre acacias',
    'tarangire_gallery_caption_4' => 'Elefante refugiándose bajo una acacia',
    'tarangire_gallery_caption_5' => 'Manada de cebras en las llanuras',
    'tarangire_gallery_caption_6' => 'León descansando en la hierba',

    'tarangire_back_to_parks' => 'Comparar todos los parques',

    'tarangire_faq_badge' => 'Preguntas frecuentes',
    'tarangire_faq_title' => 'Parque Nacional de Tarangire: preguntas frecuentes',
    'tarangire_faq_q1' => '¿Cuánto cuesta entrar a Tarangire?',
    'tarangire_faq_a1' => 'La tasa 2026 para no residentes es de 59,00 $ por adulto y 17,70 $ por niño de 5 a 15 años, por 24 horas, incluyendo 18% de IVA. Los niños menores de 5 años son gratis. Alojarse dentro del parque añade una tasa de concesión de 47,20 $ por adulto y noche, o 35,40 $ para un camping público.',
    'tarangire_faq_q2' => '¿Vale la pena visitar Tarangire?',
    'tarangire_faq_a2' => 'En la temporada seca, inequívocamente. Las concentraciones de elefantes a lo largo del río rivalizan con cualquier cosa en Tanzania, con una fracción de los vehículos y una tasa de entrada más baja que el Serengeti. Entre marzo y mayo la fauna se dispersa y es el más débil de los parques del norte.',
    'tarangire_faq_q3' => '¿Cuál es la mejor época para visitar Tarangire?',
    'tarangire_faq_a3' => 'Julio a octubre. El río Tarangire es la única agua permanente por un largo trecho en todas direcciones, así que en los meses secos todo el ecosistema converge en él. Junio es muy bueno y aún más tranquilo.',
    'tarangire_faq_q4' => '¿Cuántos elefantes hay en Tarangire?',
    'tarangire_faq_a4' => 'Entre 2.500 y 3.000 animales residentes. Manadas de cincuenta o más son rutinarias en la temporada seca, y varios cientos de elefantes en un solo día es normal.',
    'tarangire_faq_q5' => '¿Puedo visitar Tarangire como excursión de un día?',
    'tarangire_faq_a5' => 'Sí, y es uno de nuestros safaris de un día más populares. Salga de Arusha alrededor de las 06:00, pase el día en el parque, regrese por la noche. Pernoctar es mejor, porque la mejor actividad de elefantes es al amanecer y al anochecer.',
    'tarangire_faq_q6' => '¿Puedo ver los Big Five en Tarangire?',
    'tarangire_faq_a6' => 'Tres de ellos: elefante, búfalo y león. El leopardo es posible pero poco común, alrededor del 25%. No hay rinocerontes. Para los Big Five completos, combine Tarangire con el Cráter del Ngorongoro.',
    'tarangire_faq_q7' => '¿Cómo llego de Arusha a Tarangire?',
    'tarangire_faq_a7' => 'Unos 118 km, aproximadamente dos horas en buen asfalto con un corto tramo de grava hasta la entrada principal en Kwa Kuchinja. Es el más cercano de los principales parques del circuito norte, lo que lo convierte en una excursión práctica de un día completo o una primera noche fácil en un safari más largo.',
    'tarangire_faq_q8' => '¿Por qué hay tantos baobabs aquí?',
    'tarangire_faq_a8' => 'El suelo y las lluvias les convienen, y el parque los ha protegido durante más de cincuenta años. Algunos tienen más de mil años. Las profundas cicatrices verticales en los troncos son marcas de colmillos de elefantes despojando fibra por su humedad.',

    'tarangire_cta_title' => '¿Listo para planificar su safari a Tarangire?',
    'tarangire_cta_intro' => 'Envíenos sus fechas, tamaño del grupo y presupuesto. Respondemos con un itinerario escrito y un desglose completo de precios, sin compromiso.',
    'tarangire_cta_whatsapp' => 'Escríbanos por WhatsApp',
    'tarangire_cta_safaris' => 'Ver itinerarios de safari',

    'nyerere_meta_title' => 'Parque Nacional de Nyerere (Selous): la guía completa (2026) | Serengeti Budget Safari',
    'nyerere_meta_description' => 'Parque Nacional de Nyerere, antiguamente Selous: el parque más grande de África, safaris en bote por el río Rufiji, safaris a pie y licaón africano. Tasas 2026, cuándo ir y cómo llegar desde Dar.',

    'nyerere_hero_badge' => 'Guía del parque',
    'nyerere_hero_title' => 'Parque Nacional de Nyerere',
    'nyerere_hero_sub' => 'Antiguamente Selous: el parque nacional más grande de África, donde puede hacer un safari en bote, un safari a pie y un game drive en el mismo día.',
    'nyerere_hero_cta_quote' => 'Solicitar presupuesto',

    'nyerere_intro_badge' => 'Introducción',
    'nyerere_intro_title' => '¿Qué es el Parque Nacional de Nyerere?',
    'nyerere_intro_p1' => 'El Parque Nacional de Nyerere fue creado en 2019 a partir de la sección norte de la antigua Reserva de Caza Selous, y con más de 30.893 km² es el parque nacional más grande de África, más grande que Bélgica, y aproximadamente el doble del tamaño del Serengeti. Se encuentra en el sureste de Tanzania, accesible desde Dar es Salaam en lugar de Arusha, lo que lo convierte en la puerta de entrada natural al circuito de safari del sur.',
    'nyerere_intro_p2' => 'La mayoría de los viajeros todavía lo conocen como Selous. La porción sur restante conserva ese nombre como reserva de caza; la parte que visita como turista es ahora Nyerere, nombrada en honor al primer presidente de Tanzania.',
    'nyerere_intro_p3' => 'Lo que lo distingue es el agua. El río Rufiji lo atraviesa, extendiéndose en una red de lagos, canales y bancos de arena, y eso cambia lo que es un safari aquí: puede hacer un safari en bote, un safari a pie y un game drive en el mismo día, una combinación que simplemente no es posible en el Serengeti.',

    'nyerere_fact_area' => 'Superficie',
    'nyerere_fact_rank' => 'Clasificación',
    'nyerere_fact_rank_value' => 'El parque más grande de África',
    'nyerere_fact_established' => 'Fundado en',
    'nyerere_fact_status' => 'Estado',
    'nyerere_fact_boat' => 'Safaris en bote',
    'nyerere_fact_boat_value' => 'Sí, río Rufiji',
    'nyerere_fact_wilddog' => 'Licaón',
    'nyerere_fact_wilddog_value' => 'Bastión importante',
    'nyerere_fact_stay' => 'Estancia sugerida',
    'nyerere_fact_nights' => 'noches',
    'nyerere_fact_from_dar' => 'Desde Dar es Salaam',
    'nyerere_fact_minutes' => 'min en avión',

    'nyerere_regions_badge' => 'Dónde ir',
    'nyerere_regions_title' => 'Las zonas de Nyerere',
    'nyerere_regions_intro' => 'El parque es vasto, y casi todo el turismo se concentra en una pequeña sección norte alrededor del río y los lagos. Estas son las principales zonas, y lo que ofrece cada una.',
    'nyerere_region_rufiji_name' => 'El río Rufiji y sistema de lagos',
    'nyerere_region_rufiji_desc' => 'El río más grande de África Oriental por volumen se ralentiza, se extiende y se divide en una red de canales, lagos en herradura y bancos de arena a medida que cruza el parque. Cinco lagos principales (Tagalala, Manze, Nzerakera, Siwandu y Mzizimia) se encuentran aquí en la sección donde se basan la mayoría de los campamentos, cada uno con sus propios grupos de hipopótamos y aves residentes. Aquí es donde ocurren los safaris en bote, y es distinto a cualquier lugar del circuito norte.',
    'nyerere_region_stieglers_name' => 'Garganta de Stiegler y la zona turística norte',
    'nyerere_region_stieglers_desc' => 'La principal zona de visitantes, fácilmente accesible desde las pistas de aterrizaje cerca de los campamentos del Rufiji. La Garganta de Stiegler, de 100 m de profundidad y 100 m de ancho, atraviesa el norte del parque. Esta zona combina game drives, safaris a pie y excursiones en bote a poca distancia de cada lodge, por lo que casi todos los visitantes se alojan aquí.',
    'nyerere_region_south_name' => 'El desierto del sur',
    'nyerere_region_south_desc' => 'La gran mayoría de los 30.893 km² de Nyerere se encuentra al sur de la zona turística, y es genuinamente remoto: pocas carreteras, pocos campamentos, y raramente visitado incluso para los estándares tanzanos. No forma parte de un itinerario típico, pero subraya lo que hace a este parque diferente del circuito norte: espacio, y una ausencia casi total de otros vehículos.',

    'nyerere_activities_badge' => 'Lo que lo hace diferente',
    'nyerere_activities_title' => 'Safaris en bote, safaris a pie y más',
    'nyerere_activities_intro' => 'Esta es la razón por la que viene a Nyerere en lugar de añadir otro parque del norte.',
    'nyerere_table_activity' => 'Actividad',
    'nyerere_table_duration' => 'Duración',
    'nyerere_table_highlight' => 'Lo que le ofrece',
    'nyerere_act_boat_name' => 'Safari en bote por el Rufiji',
    'nyerere_act_boat_desc' => 'Navegar a la deriva por el río y sus lagos al nivel de los ojos con grupos de hipopótamos y cocodrilos en los bancos de arena, observando elefantes bajar a beber y águilas pescadoras trabajar los canales. El mejor safari en bote de Tanzania.',
    'nyerere_act_walking_name' => 'Safari a pie',
    'nyerere_act_walking_desc' => 'Con un ranger armado, generalmente al amanecer. Nyerere fue uno de los primeros lugares de Tanzania en ofrecer safaris a pie y sigue siendo uno de los mejores. Rastrea a pie y encuentra animales al nivel del suelo.',
    'nyerere_act_flycamp_name' => 'Fly-camping',
    'nyerere_act_flycamp_unit' => 'noche',
    'nyerere_act_flycamp_desc' => 'Una noche al aire libre bajo lona lejos del campamento principal, con un guía y un ranger. Simple, y a menudo la noche más memorable de todo el viaje.',
    'nyerere_act_drive_name' => 'Game drive',
    'nyerere_act_drive_desc' => 'Safari clásico en vehículo a través del bosque de miombo y pradera abierta, generalmente combinado con una excursión en bote o una caminata el mismo día.',
    'nyerere_activities_note' => 'Los safaris en bote, safaris a pie y fly-camping son facturados por separado por los campamentos. Indíquenos con antelación cuál quiere, ya que son la principal razón de venir.',

    'nyerere_wildlife_badge' => 'Fauna',
    'nyerere_wildlife_title' => 'Fauna: lo que realmente verá',
    'nyerere_wildlife_intro' => 'En una visita de tres días combinando game drives y safaris en bote en la temporada seca, basado en los registros de avistamiento de nuestros guías.',
    'nyerere_animal_hippo' => 'Hipopótamo, enormes grupos en el Rufiji',
    'nyerere_animal_crocodile' => 'Cocodrilo',
    'nyerere_animal_elephant' => 'Elefante',
    'nyerere_animal_lion' => 'León',
    'nyerere_animal_buffalo' => 'Búfalo',
    'nyerere_animal_wilddog' => 'Licaón africano, bastión mundial',
    'nyerere_animal_leopard' => 'Leopardo',
    'nyerere_animal_zebra' => 'Cebra',
    'nyerere_animal_rhino' => 'Rinoceronte negro, casi ninguno queda',
    'nyerere_wildlife_p1' => 'Hipopótamo y cocodrilo son casi certeza en el río, y elefante, león y búfalo son todos realistas en una estancia de tres días. Nyerere alberga una de las mayores poblaciones restantes de licaón africano en el continente, alrededor del 35% de probabilidad de avistamiento en una visita de tres días, lo cual es excepcional para una especie con menos de 7.000 individuos que quedan en estado salvaje.',
    'nyerere_wildlife_p2' => 'El rinoceronte negro está efectivamente ausente: un número minúsculo sobrevive en el ecosistema más amplio, pero para fines prácticos no debería planificar un viaje aquí esperando ver uno. Para el rinoceronte en Tanzania, el Cráter del Ngorongoro es la opción realista. A diferencia del Serengeti, Nyerere no tiene migración. En cambio, tiene grandes poblaciones residentes presentes todo el año.',

    'nyerere_when_badge' => 'Mejor época',
    'nyerere_when_title' => 'Cuándo visitar',
    'nyerere_when_intro' => 'Nyerere efectivamente cierra durante las grandes lluvias, una diferencia real con los parques del norte, que operan todo el año.',
    'nyerere_when_p1' => 'Junio a octubre es lo mejor: la temporada seca concentra la fauna a lo largo del Rufiji, los safaris en bote están en su mejor momento y las temperaturas son agradables. Noviembre y diciembre traen las lluvias cortas: paisajes verdes, buena observación de aves y menos visitantes, todavía muy practicable.',
    'nyerere_when_p2' => 'Enero y febrero son calurosos y húmedos pero todavía buenos para la fauna y excelentes para las aves. Marzo a mayo, las grandes lluvias, es cuando la mayoría de los campamentos cierran y las carreteras se inundan. No recomendamos viajar entonces.',

    'nyerere_stay_badge' => 'Alojamiento',
    'nyerere_stay_title' => 'Dónde alojarse',
    'nyerere_stay_intro' => 'Verifique cuidadosamente qué está incluido. En el extremo de lujo, safaris en bote, safaris a pie y tasas de parque a menudo están agrupados; en la gama media generalmente no lo están, y añadirlos cambia considerablemente el precio real. Detallamos todo por escrito.',
    'nyerere_stay_budget_title' => 'Económico',
    'nyerere_stay_budget_price' => 'desde 35,40 $/noche de tasa de parque + camping',
    'nyerere_stay_budget_desc' => 'Camping público o bandas simples cerca de la entrada de Mtemere, a menudo usados por viajes por carretera desde Dar. Instalaciones básicas; necesita su propio equipo o el nuestro.',
    'nyerere_stay_mid_title' => 'Gama media',
    'nyerere_stay_mid_price' => '200–400 $/noche',
    'nyerere_stay_mid_desc' => 'Cómodo campamento con tienda cerca de los lagos. Actividades como safaris en bote y caminatas generalmente se facturan por separado de la tarifa de la habitación.',
    'nyerere_stay_luxury_title' => 'Lujo',
    'nyerere_stay_luxury_price' => '450–1.000 $+/noche',
    'nyerere_stay_luxury_desc' => 'Pequeños campamentos en el Lago Manze o Siwandu, totalmente inclusivos con safaris en bote y a pie incorporados. Hipopótamos llamando fuera de la tienda por la noche.',
    'nyerere_stay_note' => 'Dónde basarse: la sección norte de lagos alrededor de Manze y Siwandu es donde ocurren los safaris en bote y la mayor parte de la observación de fauna. Los campamentos más al sur son más económicos pero pasa más del día conduciendo hacia el agua.',

    'nyerere_fees_badge' => 'Costos',
    'nyerere_fees_title' => 'Tasas de parque (2026)',
    'nyerere_fees_intro' => 'Las tasas son fijadas por TANAPA, la Autoridad de Parques Nacionales de Tanzania, y son idénticas para cada operador.',
    'nyerere_table_category' => 'Categoría',
    'nyerere_table_adult' => 'Adulto (16+)',
    'nyerere_table_child' => 'Niño (5–15)',
    'nyerere_fee_entry' => 'Entrada, por 24 horas',
    'nyerere_fee_concession' => 'Concesión, dormir dentro del parque (por noche)',
    'nyerere_fee_campsite' => 'Camping público (por noche)',
    'nyerere_fees_note' => 'Todas las cifras incluyen 18% de IVA. Los niños menores de 5 años entran gratis. Los safaris en bote, safaris a pie y fly-camping son facturados por separado por los campamentos. Las tasas son revisadas por el gobierno y pueden cambiar sin previo aviso. Su presupuesto escrito siempre indica el monto exacto para sus fechas.',

    'nyerere_gallery_badge' => 'Galería',
    'nyerere_gallery_title' => 'Nyerere en imágenes',
    'nyerere_gallery_caption_1' => 'Observando hipopótamos desde el bote',
    'nyerere_gallery_caption_2' => 'Rinoceronte pastando al anochecer',
    'nyerere_gallery_caption_3' => 'Familia de elefantes al atardecer',
    'nyerere_gallery_caption_4' => 'León descansando cerca del agua',
    'nyerere_gallery_caption_5' => 'Hiena manchada en la sabana',
    'nyerere_gallery_caption_6' => 'Elefante bajo una acacia',

    'nyerere_back_to_parks' => 'Comparar todos los parques',

    'nyerere_faq_badge' => 'Preguntas frecuentes',
    'nyerere_faq_title' => 'Parque Nacional de Nyerere: preguntas frecuentes',
    'nyerere_faq_q1' => '¿Es Nyerere lo mismo que Selous?',
    'nyerere_faq_a1' => 'El Parque Nacional de Nyerere fue creado en 2019 a partir de la sección norte de la Reserva de Caza Selous. La porción sur restante todavía se llama Selous. La zona que visitan los turistas es ahora Nyerere, aunque muchos operadores todavía usan el nombre antiguo.',
    'nyerere_faq_q2' => '¿Cuánto cuesta entrar a Nyerere?',
    'nyerere_faq_a2' => 'La tasa 2026 para no residentes es de 59,00 $ por adulto y 17,70 $ por niño de 5 a 15 años, por 24 horas, incluyendo 18% de IVA. Los safaris en bote, safaris a pie y fly-camping son facturados por separado por los campamentos.',
    'nyerere_faq_q3' => '¿Cómo llego a Nyerere?',
    'nyerere_faq_a3' => 'Unos 45 minutos en avión ligero desde Dar es Salaam, con vuelos programados diarios, o cinco a seis horas por carretera. Se llega a Nyerere desde Dar, no Arusha, lo que cambia la logística de un viaje comparado con los parques del norte.',
    'nyerere_faq_q4' => '¿Puedo hacer un safari en bote en Nyerere?',
    'nyerere_faq_a4' => 'Sí, y es la principal razón para venir. Dos o tres horas en el río Rufiji y sus lagos le ponen al nivel de grupos de hipopótamos y cocodrilos, con elefantes bajando a beber. Es el mejor safari en bote de Tanzania.',
    'nyerere_faq_q5' => '¿Puedo caminar en Nyerere?',
    'nyerere_faq_a5' => 'Sí, con un ranger armado, generalmente al amanecer durante dos a tres horas. Nyerere estuvo entre los primeros lugares de Tanzania en ofrecer safaris a pie y sigue siendo uno de los mejores para ello.',
    'nyerere_faq_q6' => '¿Veré licaón?',
    'nyerere_faq_a6' => 'Aproximadamente un 35% de probabilidad en una visita de tres días, sobresaliente para una especie con menos de 7.000 individuos que quedan en estado salvaje. Nyerere alberga una de las mayores poblaciones restantes de África.',
    'nyerere_faq_q7' => '¿Cuántos días necesito en Nyerere?',
    'nyerere_faq_a7' => 'Tres a cuatro días. Eso le da un safari en bote, un safari a pie y varios game drives sin apresurarse, que es todo el sentido de venir aquí en lugar de añadir otro parque del norte.',
    'nyerere_faq_q8' => '¿Hay rinocerontes en Nyerere?',
    'nyerere_faq_a8' => 'Un número muy pequeño de rinocerontes negros sobrevive en el ecosistema más amplio, pero debería asumir que no verá uno. Para el rinoceronte en Tanzania, el Cráter del Ngorongoro es la opción realista.',

    'nyerere_cta_title' => '¿Listo para planificar su safari a Nyerere?',
    'nyerere_cta_intro' => 'Envíenos sus fechas, tamaño del grupo y presupuesto. Respondemos con un itinerario escrito y un desglose completo de precios, sin compromiso.',
    'nyerere_cta_whatsapp' => 'Escríbanos por WhatsApp',
    'nyerere_cta_safaris' => 'Ver itinerarios de safari',

    // ===== Day Trips listing =====
    'daytrips_meta_title' => 'Excursiones de un día desde Arusha | Tarangire, Ngorongoro y más | Serengeti Budget Safari',
    'daytrips_meta_description' => 'Excursiones de un día desde Arusha: Tarangire, Cráter del Ngorongoro, Lago Manyara, Parque Nacional de Arusha, cascadas de Materuni, aguas termales de Chemka, una aldea masái y más.',
    'daytrips_hero_badge' => 'Excursiones',
    'daytrips_hero_title' => 'Excursiones de un día desde Arusha',
    'daytrips_hero_sub' => 'Excursiones de un día para los días previos a su safari, después de su ascensión al Kilimanjaro, o cuando tenga un día libre en la ciudad.',
    'daytrips_hero_quote' => 'Solicitar presupuesto',
    'daytrips_hero_whatsapp' => 'WhatsApp',
    'daytrips_grid_badge' => 'Elija su día',
    'daytrips_grid_title' => 'Excursiones y salidas de un día',
    'daytrips_grid_intro' => 'Saliendo de Arusha temprano y regresando la misma tarde o noche. Precios por persona, dos personas compartiendo, incluyendo tasas de parque (donde aplique), vehículo, guía y almuerzo.',
    'daytrips_1day' => 'Día completo',
    'daytrips_halfday' => 'Medio día',
    'daytrips_from_pp' => 'desde · p.p.',
    'daytrips_ask_price' => 'Preguntar precio',
    'daytrips_know_badge' => 'Bueno saber',
    'daytrips_know_title' => 'Planificando su excursión',
    'daytrips_pickup_title' => 'Recogida',
    'daytrips_pickup_desc' => 'Le recogemos en cualquier hotel de Arusha o Moshi. La salida suele ser entre las 06:00 y las 08:00 dependiendo del destino.',
    'daytrips_bring_title' => 'Qué traer',
    'daytrips_bring_desc' => 'Zapatos cerrados, una chaqueta ligera para la mañana temprano, protector solar, un sombrero y un traje de baño para Chemka o Materuni.',
    'daytrips_combine_title' => 'Combinar excursiones',
    'daytrips_combine_desc' => 'Materuni y Chemka encajan cómodamente en un solo día. También el Lago Duluti y un tour por la ciudad de Arusha. Pregunte y organizaremos el día según sus horarios de vuelo.',
    'daytrips_booking_title' => 'Reserva',
    'daytrips_booking_desc' => 'La mayoría de las excursiones se pueden organizar con 24 horas de antelación. Los safaris en parques se reservan mejor unos días antes en temporada alta.',
    'daytrips_final_title' => 'Planifique su excursión con nosotros',
    'daytrips_final_intro' => 'Envíenos sus fechas, tamaño del grupo y presupuesto. Respondemos con un itinerario escrito y un desglose completo de precios, sin compromiso.',
    'daytrips_final_whatsapp' => 'Escríbanos por WhatsApp',
    'daytrips_final_contact' => 'Formulario de contacto',

    'daytrip_tarangire_title' => 'Tarangire',
    'daytrip_tarangire_desc' => 'A dos horas de Arusha. Baobabs y las mayores manadas de elefantes del norte de Tanzania, especialmente de julio a octubre.',
    'daytrip_ngorongoro_title' => 'Cráter del Ngorongoro',
    'daytrip_ngorongoro_desc' => 'Un día largo, pero la concentración de fauna más densa de África, y la mejor oportunidad de rinoceronte negro en todo el país.',
    'daytrip_manyara_title' => 'Lago Manyara',
    'daytrip_manyara_desc' => 'Flamencos en el lago de soda, leones trepadores de árboles y bosque denso al pie del escarpe del Valle del Rift.',
    'daytrip_arushanp_title' => 'Parque Nacional de Arusha',
    'daytrip_arushanp_desc' => 'El más cercano a la ciudad, con jirafas, colobos y los lagos Momella. Los safaris a pie están permitidos aquí, lo cual es raro en Tanzania.',
    'daytrip_materuni_title' => 'Cascadas de Materuni y café',
    'daytrip_materuni_desc' => 'Una caminata por plantaciones de plátano y café en las laderas del Kilimanjaro hasta una cascada de 90 metros, seguida de tostar y moler café con una familia chagga.',
    'daytrip_chemka_title' => 'Aguas termales de Chemka',
    'daytrip_chemka_desc' => 'Una piscina natural turquesa en medio del monte seco, cálida todo el año y sombreada por raíces de higuera. El mejor baño de la tarde en la región.',
    'daytrip_maasai_title' => 'Aldea masái',
    'daytrip_maasai_desc' => 'Una visita a un boma en funcionamiento con nuestro guía masái Elius: las casas, el pastoreo, las danzas, y tiempo para hacer preguntas reales. No es un espectáculo escenificado.',
    'daytrip_duluti_title' => 'Lago Duluti',
    'daytrip_duluti_desc' => 'Un lago de cráter a veinte minutos de Arusha: piragüismo entre cormoranes y varanos, y una caminata alrededor del borde boscoso.',
    'daytrip_arushacity_title' => 'Tour por la ciudad de Arusha',
    'daytrip_arushacity_desc' => 'El mercado central, los comerciantes de tanzanita, el mercado de artesanía masái y la torre del reloj que se dice marca el punto medio entre El Cairo y Ciudad del Cabo.',
    'daytrip_kiliday_title' => 'Trek de un día al Kilimanjaro',
    'daytrip_kiliday_desc' => 'Hasta el refugio de Mandara a 2.700 m a través de la selva tropical y de vuelta el mismo día: la montaña sin la semana.',

