    // ===== Tarangire Day Trip (specific) =====
    'daytrip_tarangire_meta_title' => 'Safari de un día a Tarangire desde Arusha | Serengeti Budget Safari',
    'daytrip_tarangire_meta_description' => 'Un safari de un día completo desde Arusha al Parque Nacional de Tarangire: manadas de elefantes, baobabs antiguos y un game drive con recogida, almuerzo y tasas de parque incluidos.',
    'daytrip_tarangire_type' => 'Excursión',
    'daytrip_tarangire_budget' => 'Económico',
    'daytrip_tarangire_hero_title' => 'Safari de fauna de un día a Tarangire',
    'daytrip_tarangire_hero_route' => 'Arusha → Parque Nacional de Tarangire → Arusha',
    'daytrip_tarangire_start_val' => 'Arusha',
    'daytrip_tarangire_route_park' => 'Parque Nacional de Tarangire',
    'daytrip_tarangire_overview_title' => 'Un día de fauna en Tarangire',
    'daytrip_tarangire_overview_p1' => 'Pase un día completo explorando el Parque Nacional de Tarangire, famoso por sus elefantes, gigantes baobabs y diversa fauna. Salga de Arusha por la mañana, disfrute de un game drive de día completo y regrese a Arusha por la noche.',
    'daytrip_tarangire_love_1' => 'Game drive de día completo',
    'daytrip_tarangire_love_2' => 'Excelentes avistamientos de elefantes',
    'daytrip_tarangire_love_3' => 'Guía local profesional',
    'daytrip_tarangire_love_4' => 'Almuerzo incluido',
    'daytrip_tarangire_love_5' => 'Regreso a Arusha el mismo día',
    'daytrip_tarangire_exp_wildlife_val' => 'Leones, elefantes, jirafas, cebras y más',
    'daytrip_tarangire_exp_landscape_val' => 'Baobabs, sabana y paisajes espectaculares',
    'daytrip_tarangire_tl1_title' => 'Recogida en el hotel, Arusha',
    'daytrip_tarangire_tl1_desc' => 'Su chófer-guía le espera en su hotel justo después del amanecer, con el Land Cruiser cargado y listo. Para cuando la mayoría de la gente está pidiendo el desayuno, usted ya está en la carretera hacia el sur.',
    'daytrip_tarangire_tl2_title' => 'Entrada al país de los baobabs',
    'daytrip_tarangire_tl2_desc' => 'La entrada del parque marca el inicio de Tarangire, hogar de algunos de los baobabs más antiguos de Tanzania y las mayores manadas de elefantes fuera del ecosistema del Serengeti. El game drive matutino sigue el río Tarangire, donde la fauna se reúne incluso en los meses más secos.',
    'daytrip_tarangire_tl3_title' => 'Almuerzo picnic en el monte',
    'daytrip_tarangire_tl3_desc' => 'Un almuerzo para llevar en un lugar pintoresco elegido por su guía, a menudo con vista al valle del río y sus familias residentes de elefantes.',
    'daytrip_tarangire_tl4_title' => 'Game drive de la tarde',
    'daytrip_tarangire_tl4_desc' => 'La luz se suaviza y el monte cobra vida de nuevo después del calor de mediodía. Este es el mejor momento para la fotografía, y para avistar las jirafas, cebras y elefantes por los que Tarangire es conocido.',
    'daytrip_tarangire_tl5_title' => 'Última mirada, luego la entrada',
    'daytrip_tarangire_tl5_desc' => 'Un último trayecto a lo largo del río antes de salir por la entrada principal, los baobabs captando el sol tardío mientras comienza el viaje de regreso.',
    'daytrip_tarangire_tl6_title' => 'Regreso a Arusha',
    'daytrip_tarangire_tl6_desc' => 'Traslado a su hotel por la noche, con un día completo de fauna detrás de usted y, si continúa su safari, solo una noche de sueño antes de volver a ello.',
    'daytrip_tarangire_wl_elephant' => 'Elefantes',
    'daytrip_tarangire_wl_lion' => 'Leones',
    'daytrip_tarangire_wl_giraffe' => 'Jirafas',
    'daytrip_tarangire_wl_zebra' => 'Cebras',
    'daytrip_tarangire_wl_buffalo' => 'Búfalos',
    'daytrip_tarangire_wl_warthog' => 'Facóqueros',
    'daytrip_tarangire_faq_q1' => '¿Es este un safari privado?',
    'daytrip_tarangire_faq_a1' => 'Sí, por defecto es un vehículo privado para su grupo. También hay disponible una opción de grupo compartido a un precio por persona más bajo. Pregúntenos las fechas actuales.',
    'daytrip_tarangire_faq_q2' => '¿Puedo unirme como viajero solo?',
    'daytrip_tarangire_faq_a2' => 'Sí. Los viajeros solos pagan la tarifa de 1 persona para un viaje privado, o pueden pedirnos unirse a una salida de grupo existente para reducir el costo.',
    'daytrip_tarangire_faq_q3' => '¿A qué hora salimos de Arusha?',
    'daytrip_tarangire_faq_a3' => 'La recogida suele ser a las 06:30, para llegar a la entrada del parque cuando abre y aprovechar la mejor actividad faunística de la mañana.',
    'daytrip_tarangire_faq_q4' => '¿Está incluido el almuerzo?',
    'daytrip_tarangire_faq_a4' => 'Sí, un almuerzo picnic y agua potable están incluidos en el precio.',
    'daytrip_tarangire_faq_q5' => '¿Pueden venir niños?',
    'daytrip_tarangire_faq_a5' => 'Sí, Tarangire es un excelente primer safari para familias. El game drive es relajado y los avistamientos de elefantes están casi garantizados en la temporada seca.',
    'daytrip_final_title' => 'Su aventura en Tanzania comienza aquí',
    'daytrip_final_intro' => 'Un día. Fauna increíble. Recuerdos inolvidables.',
    'daytrip_final_whatsapp' => 'Preguntar por WhatsApp',

    // ===== About Us =====
    'about_meta_title' => 'Sobre nosotros | Serengeti Budget Safari: operador local de safaris en Tanzania',
    'about_meta_description' => 'Conozca al equipo local detrás de Serengeti Budget Safari, un operador con sede en Tanzania construido sobre el conocimiento local, precios honestos y servicio personal en el Serengeti, Ngorongoro y más allá.',

    'about_hero_title' => 'No solo planificamos safaris. Compartimos Tanzania.',
    'about_hero_sub' => 'Viajes auténticos. Conocimiento local. Experiencias inolvidables.',
    'about_hero_cta1' => 'Explorar nuestros safaris',
    'about_hero_cta2' => 'Hablar con nuestro equipo',

    'about_intro_badge' => 'Quiénes somos',
    'about_intro_title' => 'Su viaje comienza con gente que conoce Tanzania',
    'about_intro_p1' => 'Somos una empresa de safaris con sede en Tanzania dedicada a crear viajes memorables por los destinos más extraordinarios del país. Desde las llanuras infinitas del Serengeti hasta el dramático Cráter del Ngorongoro y las playas de Zanzíbar, combinamos conocimiento local, guías experimentados y una planificación cuidadosa para hacer especial cada viaje.',

    'about_story_badge' => 'Nuestra historia',
    'about_story_title' => 'Cómo empezó todo',
    'about_story_intro' => 'Una breve historia de nuestros inicios y de cómo llegamos hasta aquí.',
    'about_story_y1_title' => 'Nuestro viaje comienza',
    'about_story_y1_desc' => 'Fundada en Arusha con una idea simple: safaris construidos alrededor de precios honestos y conocimiento local real, sin los intermediarios que inflan el costo de un viaje.',
    'about_story_y2_title' => 'Más viajeros nos descubren',
    'about_story_y2_desc' => 'El boca a boca y los clientes que regresan nos ayudaron a crecer más allá de nuestras primeras rutas hacia el circuito norte más amplio.',
    'about_story_y3_title' => 'Experiencias de safari ampliadas',
    'about_story_y3_desc' => 'Añadimos trekking, extensiones a Zanzíbar y excursiones de un día, para que un primer visitante pudiera planificar todo un viaje a Tanzania con un solo equipo.',
    'about_story_y4_title' => 'Construyendo una mejor forma de explorar Tanzania',
    'about_story_y4_desc' => 'Hoy seguimos invirtiendo en cómo planificamos, tarificamos y comunicamos, para que cada viajero obtenga la misma experiencia honesta con la que comenzamos.',

    'about_why_badge' => 'Por qué viajar con nosotros',
    'about_why_title' => 'Por qué somos diferentes',
    'about_why_1_title' => 'Experiencia local',
    'about_why_1_desc' => 'Conocemos Tanzania más allá del mapa turístico: rutas reales, tiempos reales, consejos reales.',
    'about_why_2_title' => 'Viajes personalizados',
    'about_why_2_desc' => 'Su viaje puede adaptarse a sus intereses, tiempo y presupuesto, no encajarse en un paquete fijo.',
    'about_why_3_title' => 'Guías experimentados',
    'about_why_3_desc' => 'Viaje con profesionales locales de safari conocedores que saben dónde, y cuándo, buscar.',
    'about_why_4_title' => 'Tarificación transparente',
    'about_why_4_desc' => 'Precios claros sin confusos costos ocultos, desde su primer presupuesto hasta su factura final.',
    'about_why_5_title' => 'Soporte personal',
    'about_why_5_desc' => 'Desde su primer mensaje de WhatsApp hasta que llegue seguro a casa, está hablando con personas reales, no con un centro de llamadas.',
    'about_why_6_title' => 'Viaje responsable',
    'about_why_6_desc' => 'Aspiramos a respetar la fauna, las comunidades y los lugares que visitamos, no solo a pasar por ellos.',

