    'blogcost_meta_title' => '¿Cuánto cuesta un safari en Tanzania? (Desglose 2026) | Serengeti Budget Safari',
    'blogcost_meta_description' => 'Lo que realmente cuesta un safari tanzano en 2026, desglosado línea por línea: tasas de parque, alojamiento, vehículo y guía, más lo que nunca está incluido y cómo gastar menos sin arruinar el viaje.',
