    'blogcost_s1_title' => 'La respuesta corta',
    'blogcost_s1_p1' => 'Un safari tanzano cuesta aproximadamente <strong>200 a 600 € por persona y día</strong>, todo incluido. El rango es amplio porque tres cosas mueven el número más que cualquier otra: <strong>qué parques visita</strong>, <strong>dónde duerme</strong> y <strong>cuántas personas comparten el vehículo</strong>.',
