    'blogcost_t1_h3' => 'Lo que obtiene',
    'blogcost_t1_r1_a' => 'Económico / camping',
    'blogcost_t1_r1_c' => 'Camping o lodges sencillos fuera de los parques, vehículo compartido',
    'blogcost_t1_r2_a' => 'Gama media',
    'blogcost_t1_r2_c' => 'Lodges cómodos, vehículo privado',
