    'blogcost_s1_p2' => 'A continuación, desglosamos eso en las partidas reales para que pueda ver a dónde va el dinero, y dónde puede realmente ahorrar.',
    'blogcost_cta_label' => 'Safari relacionado',
    'blogcost_cta_title' => 'Safari Serengeti y Ngorongoro de 5 días',
    'blogcost_cta_price' => 'Desde 650 € por persona',
