    'blogcost_s2_title' => '1. Tasas de parque: el mayor costo fijo',
    'blogcost_s2_p1' => 'Las tasas de parque son fijadas por el gobierno y son <strong>idénticas para cada operador</strong>. Nadie puede descontarlas, y en un itinerario al Serengeti a menudo representan un tercio del precio total.',
    'blogcost_t2_h1' => 'Parque',
    'blogcost_t2_h2' => 'Adulto / 24h',
    'blogcost_t2_h3' => 'Concesión / noche',
    'blogcost_per_vehicle' => 'por vehículo',
    'blogcost_s2_example_title' => 'Un ejemplo práctico',
    'blogcost_s2_example_intro' => 'Dos personas, cuatro días, Tarangire + Serengeti (2 noches) + Ngorongoro, durmiendo fuera de los parques:',
    'blogcost_t3_h1' => 'Concepto',
    'blogcost_t3_h2' => 'Cálculo',
