    'blogcost_s2_p2' => 'Eso es antes de una sola noche de alojamiento, litro de combustible o día de salario de un guía.',
    'blogcost_s3_badge' => 'Alojamiento',
    'blogcost_s3_title' => '2. Alojamiento: la variable más grande',
    'blogcost_s3_p1' => 'Esta es la línea que decide si su safari es "económico" o "de lujo". La fauna es idéntica en ambos casos.',
    'blogcost_t4_h1' => 'Tipo',
    'blogcost_t4_h2' => 'Por persona / noche',
    'blogcost_t4_r1_a' => 'Camping público (dentro del parque)',
    'blogcost_plus_camping' => 'tasa de parque + costos de camping',
    'blogcost_t4_r2_a' => 'Lodge fuera del parque',
    'blogcost_t4_r3_a' => 'Lodge dentro del parque',
    'blogcost_plus_concession' => '+ tasa de concesión',
    'blogcost_t4_r4_a' => 'Campamento con tienda dentro del parque',
    'blogcost_t4_r5_a' => 'Campamento móvil de migración',
    'blogcost_t4_r6_a' => 'Ultra-lujo',
    'blogcost_s3_p2' => 'Note la tasa de concesión: dormir <em>dentro</em> de un parque añade 47–59 $ por adulto y noche además de la tarifa de la habitación. Le compra el amanecer y el atardecer dentro del ecosistema, que es cuando los depredadores están activos. Genuinamente vale la pena en un viaje corto, menos en uno largo.',
    'blogcost_s3_link' => 'Hable con nosotros sobre opciones de alojamiento',
    'blogcost_s4_badge' => 'Vehículo',
    'blogcost_s4_title' => '3. Vehículo y guía: por qué el tamaño del grupo importa tanto',
    'blogcost_s4_p1' => 'Un Land Cruiser con chófer-guía cuesta lo mismo ya sean dos o seis. El combustible, el vehículo, el salario del guía y la tasa de descenso al cráter son todos <strong>por vehículo</strong>, no por persona.',
    'blogcost_s4_p2' => 'Esta es la forma más efectiva de reducir el precio por persona, y la mayoría de los viajeros no se dan cuenta.',
    'blogcost_t5_h1' => 'Tamaño del grupo',
    'blogcost_t5_h2' => 'Parte del costo del vehículo',
    'blogcost_t5_h3' => 'Efecto en el precio por persona',
    'blogcost_people' => 'personas',
    'blogcost_each' => 'cada uno',
    'blogcost_t5_r1_c' => 'Referencia',
    'blogcost_t5_r2_c' => 'Notablemente más económico por cabeza',
    'blogcost_t5_r3_c' => 'Sustancialmente más económico por cabeza',
    'blogcost_s4_p3' => 'Si es dos personas con un presupuesto ajustado, unirse a una <strong>salida en grupo compartido</strong> logra el mismo ahorro. Renuncia a algo de flexibilidad en cuanto a horarios y paradas.',
    'blogcost_s5_badge' => 'Extras',
    'blogcost_s5_title' => '4. Lo que nunca está incluido',
    'blogcost_s5_i1_t' => 'Vuelos internacionales',
    'blogcost_s5_i1_d' => 'el mayor costo individual para la mayoría de los viajeros',
    'blogcost_s5_i2_t' => 'Visa tanzana',
    'blogcost_s5_i2_d' => '50 $ para la mayoría de las nacionalidades',
    'blogcost_s5_i3_t' => 'Seguro de viaje',
    'blogcost_s5_i3_d' => 'obligatorio en nuestros viajes, y debe cubrir evacuación',
    'blogcost_s5_i4_t' => 'Propinas',
    'blogcost_s5_i4_d' => 'aproximadamente 20–25 $ por día para el guía por parte del grupo, más el personal del campamento',
    'blogcost_s5_i5' => 'Bebidas que no sean agua, y gastos personales',
    'blogcost_s5_i6_t' => 'Extras opcionales',
    'blogcost_s5_i6_d' => 'vuelo en globo (~599 $), safaris nocturnos, visitas culturales',
    'blogcost_s5_p1' => 'Presupueste un extra de <strong>300–500 $ por persona</strong> para visa, propinas e imprevistos en un viaje de una semana, además del precio del safari.',
    'blogcost_s6_badge' => 'Ahorrar dinero',
    'blogcost_s6_title' => 'Cómo gastar menos sin arruinar el viaje',
    'blogcost_s6_sub1' => 'Cosas que ahorran dinero de verdad',
    'blogcost_s6_save1_t' => 'Viaje en temporada baja.',
    'blogcost_s6_save1_d' => 'Abril, mayo y noviembre son sustancialmente más económicos, y la fauna sigue ahí.',
    'blogcost_s6_save2_t' => 'Sea cuatro en lugar de dos.',
    'blogcost_s6_save2_d' => 'El costo del vehículo se divide.',
    'blogcost_s6_save3_t' => 'Duerma fuera de los parques.',
    'blogcost_s6_save3_d' => 'Ahorra la tasa de concesión y la tarifa de la habitación; le cuesta una hora de conducción cada mañana.',
    'blogcost_s6_save4_t' => 'Elija parques más económicos.',
    'blogcost_s6_save4_d' => 'Tarangire y Manyara están a 59,00 $ frente a los 82,60 $ del Serengeti, y están a dos horas de Arusha en lugar de ocho.',
    'blogcost_s6_save5_t' => 'Acampe.',
    'blogcost_s6_save5_d' => 'Mismo guía, mismo vehículo, mismos animales. Ahorra en la cama.',
    'blogcost_s6_save6_t' => 'Acorte el Serengeti, no el viaje.',
    'blogcost_s6_save6_d' => 'Dos noches en el Serengeti más dos noches en Tarangire cuesta mucho menos que cuatro noches en el Serengeti.',
    'blogcost_s6_sub2' => 'Falsas economías',
    'blogcost_s6_false1_t' => 'Recortar el viaje a dos días incluyendo el Serengeti.',
    'blogcost_s6_false1_d' => 'Paga las tasas de parque completas para pasar la mayor parte del tiempo conduciendo.',
    'blogcost_s6_false2_t' => 'Reservar el presupuesto más barato que encuentre.',
    'blogcost_s6_false2_d' => 'Las tasas de parque son fijas, así que un precio muy por debajo del mercado está siendo financiado por algo, generalmente el equipo, la comida o el vehículo.',
    'blogcost_s6_false3_t' => 'Omitir el seguro de viaje.',
    'blogcost_s6_false3_d' => 'La evacuación médica desde el Serengeti cuesta muchos miles de dólares.',
    'blogcost_s6_warn_t' => 'Una palabra sobre presupuestos sospechosamente baratos:',
    'blogcost_s6_warn_d' => 'las tasas de parque en esta página son públicas e idénticas para todos. Si un presupuesto para cuatro días al Serengeti está apenas por encima del total de tasas, pida al operador que lo detalle. Una empresa de confianza lo hará sin dudarlo.',
    'blogcost_s7_badge' => 'Ejemplos',
    'blogcost_s7_title' => 'Lo que cuestan itinerarios reales',
    'blogcost_s7_intro' => 'Precios indicativos por persona, dos personas compartiendo, incluyendo tasas de parque, vehículo, guía, alojamiento y comidas. Su presupuesto escrito detalla cada línea.',
    'blogcost_t6_h1' => 'Itinerario',
    'blogcost_days_tarangire_ngoro' => 'días: Tarangire y Ngorongoro',
    'blogcost_days_serengeti_ngoro' => 'días: Serengeti y Ngorongoro',
    'blogcost_days_bigfive' => 'días: circuito Big Five',
    'blogcost_days_migration' => 'días: safari de migración',
    'blogcost_days_zanzibar' => 'días: safari + Zanzíbar',
    'blogcost_s7_note' => 'Solo indicativo. Los precios varían según la temporada, el tamaño del grupo y la disponibilidad.',
    'blogcost_faq_badge' => 'Preguntas frecuentes',
    'blogcost_faq_title' => 'Costos del safari: preguntas frecuentes',
    'blogcost_faq_q1' => '¿Cuánto cuesta un safari tanzano por día?',
    'blogcost_faq_a1' => 'Aproximadamente 200–250 € por persona y día para camping económico, 250–350 € gama media, 400 $+ para en avión y 600 $+ para lujo. Las tasas de parque solas representan una gran parte de eso, y son idénticas para cada operador.',
    'blogcost_faq_q2' => '¿Qué está incluido en un precio de safari?',
    'blogcost_faq_a2' => 'Normalmente: vehículo 4x4 con chófer-guía, combustible, todas las tasas de entrada de parque en el itinerario, alojamiento y comidas como se describe, y agua potable. No incluido: vuelos internacionales, visa, seguro, bebidas, propinas y extras opcionales.',
    'blogcost_faq_q3' => '¿Cómo puedo hacer un safari más económico?',
    'blogcost_faq_a3' => 'Viaje en temporada baja, sea cuatro personas en lugar de dos para que el costo del vehículo se divida, duerma fuera de los parques, elija Tarangire y Manyara sobre el Serengeti, y considere el camping.',
    'blogcost_faq_q4' => '¿El tamaño del grupo realmente cambia el precio?',
    'blogcost_faq_a4' => 'Sustancialmente. El vehículo, el guía, el combustible y la tasa de descenso al cráter se cobran todos por vehículo, no por persona. Cuatro personas compartiendo pagan notablemente menos cada una que dos, y seis pagan aún menos.',
    'blogcost_faq_q5' => '¿Debería sospechar de presupuestos muy baratos?',
    'blogcost_faq_a5' => 'Sí. Las tasas de parque son públicas y fijas para todos, así que un precio apenas por encima del total de tasas está siendo financiado en otro lugar. Pida a cualquier operador que detalle su presupuesto.',
    'blogcost_faq_q6' => '¿Cuánto debo presupuestar para propinas?',
    'blogcost_faq_a6' => 'Alrededor de 20–25 $ por día para el chófer-guía, de parte del grupo en su conjunto, más 10–15 $ por día para el personal de campamento. En un viaje de una semana para dos personas, presupueste aproximadamente 200–300 $ en total.',
    'blogcost_faq_q7' => '¿Cuánto cuesta la visa tanzana?',
    'blogcost_faq_a7' => '50 $US para la mayoría de las nacionalidades, obtenida en línea en visa.immigration.go.tz antes de viajar, o a la llegada. Cuídese de sitios no oficiales que cobran tasas adicionales por lo mismo.',
    'blogcost_faq_q8' => '¿Puedo pagar en cuotas?',
    'blogcost_faq_a8' => 'Nuestros términos estándar son un depósito del 30% para confirmar y el saldo 30 días antes de la llegada. Si reserva con mucha antelación, generalmente podemos ser flexibles con el timing, solo pregunte.',
    'blogcost_related_badge' => 'Seguir leyendo',
    'blogcost_related_title' => 'Continuar explorando Tanzania',
    'blogcost_related_itineraries' => 'Nuestros itinerarios de safari',
    'blogcost_final_title' => '¿Quiere un número real para su viaje?',
    'blogcost_final_intro' => 'Envíenos sus fechas y tamaño del grupo y le enviaremos un presupuesto detallado: tasas de parque, camas, vehículo y guía listados por separado, para que vea exactamente a dónde va el dinero.',
    'blogcost_final_whatsapp' => 'Escríbanos por WhatsApp',
    'blogcost_final_contact' => 'Formulario de contacto',

    // ===== Blog article: The Great Migration Month by Month =====
    'blogmig_meta_title' => 'La Gran Migración mes a mes (Guía 2026) | Serengeti Budget Safari',
    'blogmig_meta_description' => 'Dónde están las manadas de la Gran Migración cada mes del año, cuándo ocurren la temporada de nacimientos y los cruces del río Mara, dónde alojarse para cada fase, y un relato honesto de lo que se puede y no se puede garantizar.',
    'blogmig_h1' => 'La Gran Migración, mes a mes',
    'blogmig_hero_sub' => 'Dónde están las manadas cada mes, cuándo ocurren los nacimientos y los cruces de río, y lo que ningún operador puede honestamente prometerle.',
    'blogmig_updated' => 'Actualizado 2026',
    'blogmig_quick_badge' => 'Respuestas rápidas',
    'blogmig_quick_title' => 'La migración en breve',
    'blogmig_quick_intro' => 'Las seis preguntas que más nos hacen.',
    'blogmig_qq1_q' => '¿Cuándo ocurre?',
    'blogmig_qq1_a' => 'Todo el año. Nunca se detiene, solo cambia la ubicación.',
    'blogmig_qq2_q' => '¿Temporada de nacimientos?',
    'blogmig_qq2_a' => 'Finales de enero a febrero, en Ndutu.',
    'blogmig_qq3_q' => '¿Cruces de río?',
    'blogmig_qq3_a' => 'Julio a octubre en el Mara, en el norte.',
    'blogmig_qq4_q' => '¿Dónde me alojo?',
    'blogmig_qq4_a' => 'Ndutu dic–mar, Kogatende jul–oct. Importa enormemente.',
    'blogmig_qq5_q' => '¿Cuántas noches?',
    'blogmig_qq5_a' => 'Tres mínimo en la zona de migración.',
    'blogmig_qq6_q' => '¿Cruce garantizado?',
    'blogmig_qq6_a' => 'No. Cualquiera que prometa uno está exagerando.',
    'blogmig_toc_title' => 'Contenido',
    'blogmig_toc_1' => 'Qué es realmente',
    'blogmig_toc_2' => 'Mes a mes',
    'blogmig_toc_3' => 'La temporada de nacimientos',
    'blogmig_toc_4' => 'Los cruces de río',
    'blogmig_toc_5' => 'Dónde alojarse por mes',
    'blogmig_toc_6' => 'Cómo planificarlo',
    'blogmig_toc_7' => 'Cinco mitos comunes',
    'blogmig_toc_8' => 'Preguntas frecuentes',
    'blogmig_s1_badge' => 'Lo básico',
    'blogmig_s1_title' => 'Qué es realmente la Gran Migración',
    'blogmig_s1_p1' => 'La Gran Migración es el movimiento continuo de aproximadamente <strong>1,3 millones de ñus</strong>, <strong>250.000 cebras</strong> y varios cientos de miles de gacelas de Thomson y de Grant alrededor del ecosistema Serengeti-Masái Mara. Es el mayor movimiento terrestre de animales que queda en la tierra.',
    'blogmig_s1_p2' => 'La cosa más útil de entender es esta: <strong>no es un evento con una fecha.</strong> Las manadas están en algún lugar del ecosistema cada mes del año, moviéndose en una ruta aproximadamente circular impulsada por las lluvias y el crecimiento de hierba nueva. No hay inicio ni fin. Lo que cambia mes a mes es <em>dónde</em> están, y por lo tanto dónde necesita estar usted.',
    'blogmig_s1_p3' => 'Una segunda cosa que vale la pena saber: los ñus no viajan como una sola manada enorme. Se mueven en largas columnas y grupos dispersos a lo largo de decenas de kilómetros, a veces convergiendo en las masas densas que aparecen en los documentales, a veces dispersos por la llanura abierta. Ambos son la migración.',
    'blogmig_fact_wildebeest' => 'Ñus',
    'blogmig_fact_zebra' => 'Cebras',
    'blogmig_fact_gazelle' => 'Gacelas',
    'blogmig_fact_distance' => 'Distancia anual',
    'blogmig_fact_calves' => 'Crías nacidas',
    'blogmig_fact_year' => 'año',
    'blogmig_fact_ecosystem' => 'Ecosistema',
    'blogmig_s2_badge' => 'El calendario',
    'blogmig_s2_title' => 'Mes a mes: dónde están las manadas',
    'blogmig_s2_intro' => 'El patrón de abajo se repite cada año, pero las lluvias lo desplazan dos o tres semanas en cualquier dirección. Trátelo como una fuerte probabilidad, nunca un horario.',
    'blogmig_t1_h1' => 'Mes',
    'blogmig_t1_h2' => 'Dónde están las manadas',
    'blogmig_t1_h3' => 'Qué está pasando',
    'blogmig_t1_h4' => 'Alojarse en',
    'blogmig_m1_name' => 'Enero', 'blogmig_m1_where' => 'Llanuras del sur y Ndutu', 'blogmig_m1_what' => 'Las manadas se asientan en las llanuras de hierba corta. Los nacimientos comienzan a finales del mes.', 'blogmig_m1_stay' => 'Ndutu',
    'blogmig_m2_name' => 'Febrero', 'blogmig_m2_where' => 'Ndutu y sur del Serengeti', 'blogmig_m2_what' => '<strong>Pico de nacimientos.</strong> Hasta 8.000 nacimientos al día en una ventana de tres semanas. Actividad de depredadores en su punto más alto del año.', 'blogmig_m2_stay' => 'Ndutu',
    'blogmig_m3_name' => 'Marzo', 'blogmig_m3_where' => 'Llanuras del sur, comenzando a moverse', 'blogmig_m3_what' => 'Las crías se fortalecen. Comienzan las grandes lluvias; las manadas comienzan a desplazarse hacia el noroeste.', 'blogmig_m3_stay' => 'Ndutu / Seronera',
    'blogmig_m4_name' => 'Abril', 'blogmig_m4_where' => 'Serengeti central y occidental', 'blogmig_m4_what' => 'Grandes lluvias. Las columnas se forman y se mueven. Verde, dramático, casi vacío de turistas.', 'blogmig_m4_stay' => 'Seronera / Moru',
    'blogmig_m5_name' => 'Mayo', 'blogmig_m5_where' => 'Corredor occidental', 'blogmig_m5_what' => 'Celo: los machos luchan por derechos de apareamiento. Largas columnas dirigiéndose hacia el oeste.', 'blogmig_m5_stay' => 'Corredor occidental',
    'blogmig_m6_name' => 'Junio', 'blogmig_m6_where' => 'Corredor occidental y río Grumeti', 'blogmig_m6_what' => '<strong>Cruces del Grumeti.</strong> Más pequeños que el Mara pero con enormes cocodrilos y muy pocos vehículos.', 'blogmig_m6_stay' => 'Corredor occidental / Grumeti',
    'blogmig_m7_name' => 'Julio', 'blogmig_m7_where' => 'Serengeti del Norte', 'blogmig_m7_what' => 'Las manadas llegan al río Mara. Primeros cruces, a menudo tentativos.', 'blogmig_m7_stay' => 'Kogatende',
    'blogmig_m8_name' => 'Agosto', 'blogmig_m8_where' => 'Serengeti del Norte y Masái Mara', 'blogmig_m8_what' => '<strong>Pico de cruces del Mara.</strong> Los más frecuentes y dramáticos del año.', 'blogmig_m8_stay' => 'Kogatende',
    'blogmig_m9_name' => 'Septiembre', 'blogmig_m9_where' => 'Serengeti del Norte y Mara', 'blogmig_m9_what' => 'Los cruces continúan en ambas direcciones mientras las manadas van y vienen a través del río.', 'blogmig_m9_stay' => 'Kogatende',
    'blogmig_m10_name' => 'Octubre', 'blogmig_m10_where' => 'Serengeti del Norte, desplazándose al sur', 'blogmig_m10_what' => 'Últimos cruces. Las manadas comienzan el viaje de regreso por el Serengeti oriental.', 'blogmig_m10_stay' => 'Kogatende / Lobo',
    'blogmig_m11_name' => 'Noviembre', 'blogmig_m11_where' => 'Serengeti oriental y central', 'blogmig_m11_what' => 'Las lluvias cortas atraen a las manadas hacia el sur. Largas columnas a través de Lobo y Seronera.', 'blogmig_m11_stay' => 'Lobo / Seronera',
    'blogmig_m12_name' => 'Diciembre', 'blogmig_m12_where' => 'Llanuras del sur', 'blogmig_m12_what' => 'Llegada a las llanuras de hierba corta. El circuito comienza de nuevo.', 'blogmig_m12_stay' => 'Ndutu / Seronera',
    'blogmig_s3_badge' => 'Nacimientos',
    'blogmig_s3_title' => 'La temporada de nacimientos: la parte que la mayoría se pierde',
    'blogmig_s3_p1' => 'Entre finales de enero y febrero, alrededor de <strong>400.000 crías de ñu</strong> nacen en las llanuras de hierba corta alrededor de <strong>Ndutu</strong>, con un pico de hasta <strong>8.000 nacimientos en un solo día</strong>. Aproximadamente el 80% de las hembras dan a luz dentro de la misma ventana de tres semanas.',
    'blogmig_s3_sub1' => 'Por qué todas dan a luz a la vez',
    'blogmig_s3_p2' => 'Es una estrategia de supervivencia llamada saturación de depredadores. Al inundar las llanuras con recién nacidos en un estallido concentrado, la manada garantiza que los depredadores no puedan llevárselos a todos. Los leones, hienas y guepardos simplemente se ven desbordados. Una cría nacida fuera de esa ventana tiene muchas más probabilidades de ser cazada.',
    'blogmig_s3_sub2' => 'Por qué Ndutu específicamente',
    'blogmig_s3_p3' => 'Las llanuras del sur se asientan sobre cenizas volcánicas sopladas desde las tierras altas del Ngorongoro, que crearon una capa dura cerca de la superficie. Los árboles no pueden enraizar a través de ella, así que las llanuras permanecen abiertas (buena visibilidad contra los depredadores), y la hierba corta que crece allí es inusualmente rica en calcio y fósforo. Es exactamente lo que una madre lactante necesita para construir hueso en una cría.',
    'blogmig_s3_sub3' => 'Lo que realmente se ve',
    'blogmig_s3_p4' => 'Recién nacidos de pie a los pocos minutos de nacer y corriendo en menos de una hora. Grupos de guardería de cientos de crías. E, inevitablemente, depredación: este es el mes en que leones, guepardos y hienas cazan con más éxito, y verá matanzas. Algunos viajeros encuentran eso difícil, así que vale la pena saberlo de antemano.',
    'blogmig_s3_note_t' => 'Una opinión honesta de nuestros guías:',
    'blogmig_s3_note_d' => 'la mayoría de la gente viene en agosto por los cruces de río. Si le pregunta a los guías qué temporada elegirían para ellos mismos, una clara mayoría dice febrero en Ndutu. La actividad faunística es más constante, más variada, y hay muchos menos vehículos.',
    'blogmig_s4_badge' => 'Cruces',
    'blogmig_s4_title' => 'Los cruces de río, y la verdad sobre ellos',
    'blogmig_s4_p1' => 'La imagen que todos tienen de la migración, miles de ñus lanzándose a un río mientras los cocodrilos esperan, es real, y ocurre en el <strong>río Mara</strong> en el norte del Serengeti entre julio y octubre, y en el <strong>río Grumeti</strong> en el oeste alrededor de junio.',
    'blogmig_s4_sub1' => 'Lo que realmente sucede',
    'blogmig_s4_p2' => 'Las manadas se reúnen en la orilla, a menudo por miles. Esperan. A veces veinte minutos, a veces seis horas, a veces todo el día. Luego un animal se lanza y el resto sigue en unos minutos frenéticos, o toda la manada da media vuelta y se aleja sin cruzar en absoluto.',
    'blogmig_s4_p3' => 'Nadie controla esto y nadie puede predecirlo. Se sabe de manadas que han cruzado, pastado en la otra orilla durante una hora, y cruzado directamente de vuelta.',
    'blogmig_s4_sub2' => 'Las probabilidades honestas',
    'blogmig_s4_p4' => 'Con <strong>tres noches en Kogatende entre finales de julio y septiembre</strong>, tiene una buena oportunidad de presenciar al menos un cruce. Con una noche, está apostando. Cualquier operador que garantice un cruce en una fecha específica está mal informado o le está vendiendo algo que no puede cumplir.',
    'blogmig_s4_note_t' => 'Lo que decimos a nuestros clientes:',
    'blogmig_s4_note_d' => 'reserve tres noches mínimo en el norte si un cruce es la razón de su viaje, vaya en agosto o principios de septiembre, y acepte que las mañanas que pasa esperando en una orilla sin que pase nada son parte de la experiencia.',
    'blogmig_s4_sub3' => 'Grumeti contra Mara',
    'blogmig_s4_mara' => 'Río Mara',
    'blogmig_s4_grumeti' => 'Río Grumeti',
    'blogmig_s4_row_months' => 'Meses',
    'blogmig_s4_mara_months' => 'Julio – Octubre',
    'blogmig_s4_grumeti_months' => 'Mayo – Julio',
    'blogmig_s4_row_scale' => 'Escala',
    'blogmig_s4_mara_scale' => 'Grande, dramático',
    'blogmig_s4_grumeti_scale' => 'Más pequeño, más disperso',
    'blogmig_s4_row_croc' => 'Cocodrilos',
    'blogmig_s4_mara_croc' => 'Muchos',
    'blogmig_s4_grumeti_croc' => 'Menos pero enormes',
    'blogmig_s4_row_vehicles' => 'Vehículos',
    'blogmig_s4_mara_vehicles' => 'Muchos en temporada alta',
    'blogmig_s4_grumeti_vehicles' => 'Muy pocos',
    'blogmig_s4_row_stay' => 'Dónde alojarse',
    'blogmig_s4_mara_stay' => 'Kogatende',
    'blogmig_s4_grumeti_stay' => 'Corredor occidental',
    'blogmig_s5_badge' => 'Alojamiento',
    'blogmig_s5_title' => 'Dónde alojarse para cada fase',
    'blogmig_s5_p1' => 'Aquí es donde fallan la mayoría de los viajes de migración. Reservar "un lodge en el Serengeti" no es suficiente: el parque tiene 14.763 km², y un lodge en el centro está a cinco horas de las manadas si están en el norte.',
    'blogmig_t2_h1' => 'Si viaja en…',
    'blogmig_t2_h2' => 'Alójese en…',
    'blogmig_t2_h3' => 'Por qué',
    'blogmig_t2_r1_a' => 'Diciembre – Marzo', 'blogmig_t2_r1_b' => 'Ndutu', 'blogmig_t2_r1_c' => 'Temporada de nacimientos en las llanuras del sur',
    'blogmig_t2_r2_a' => 'Abril – Mayo', 'blogmig_t2_r2_b' => 'Seronera / Moru', 'blogmig_t2_r2_c' => 'Manadas moviéndose por el centro y el oeste',
    'blogmig_t2_r3_a' => 'Mayo – Julio', 'blogmig_t2_r3_b' => 'Corredor occidental', 'blogmig_t2_r3_c' => 'Cruces del río Grumeti',
    'blogmig_t2_r4_a' => 'Julio – Octubre', 'blogmig_t2_r4_b' => 'Kogatende', 'blogmig_t2_r4_c' => 'Cruces del río Mara en el norte',
    'blogmig_t2_r5_a' => 'Noviembre', 'blogmig_t2_r5_b' => 'Lobo / Seronera', 'blogmig_t2_r5_c' => 'Viaje de regreso por el este',
    'blogmig_s5_sub1' => 'Campamentos móviles',
    'blogmig_s5_p2' => 'Varios operadores gestionan campamentos con tienda móviles que se reubican físicamente dos o tres veces al año para seguir a las manadas. Son la forma más fiable de mantenerse cerca de la migración, generalmente son pequeños y remotos, y cuestan aproximadamente 300–700 $ por persona y noche. Si la migración es el objetivo completo de su viaje, esto es lo que quiere.',
    'blogmig_s5_link' => 'Hable con nosotros sobre opciones de alojamiento',
    'blogmig_s6_badge' => 'Planificación',
    'blogmig_s6_title' => 'Cómo planificar un safari de migración',
    'blogmig_s6_step1_t' => 'Paso 1: decida qué fase quiere',
    'blogmig_s6_step1_d' => 'Nacimientos en Ndutu, o cruces de río en el norte. Estas son las dos experiencias principales y ocurren en extremos opuestos tanto del parque como del calendario. No puede hacer ambas en un viaje.',
    'blogmig_s6_step2_t' => 'Paso 2: reserve temprano',
    'blogmig_s6_step2_d' => 'Los campamentos en Kogatende para agosto y septiembre, y en Ndutu para febrero, se agotan <strong>de seis a doce meses antes</strong>. Esto no es una táctica de venta. Esas zonas tienen camas limitadas, y los buenos campamentos pequeños se van primero.',
    'blogmig_s6_step3_t' => 'Paso 3: déle suficientes noches',
    'blogmig_s6_step3_d' => 'Tres noches mínimo en la zona de migración. Dos es una apuesta, una es un boleto de lotería.',
    'blogmig_s6_step4_t' => 'Paso 4: considere volar',
    'blogmig_s6_step4_d' => 'Kogatende está a dos días de viaje desde Arusha. Un vuelo de 1 hora 15 minutos convierte cuatro días de conducción en cuatro días más de observación de fauna. Para un viaje al norte del Serengeti, volar es casi siempre la decisión correcta.',
    'blogmig_s6_step5_t' => 'Paso 5: incorpore el resto del ecosistema',
    'blogmig_s6_step5_d' => 'La migración no es lo único que vale la pena ver. Los depredadores residentes, el Cráter del Ngorongoro y los elefantes de Tarangire están todos ahí sin importar dónde estén las manadas, y un buen itinerario los usa para llenar los días alrededor de sus noches de migración.',
    'blogmig_t3_h1' => 'Duración del viaje',
    'blogmig_t3_h2' => 'Estructura sugerida',
    'blogmig_days' => 'días',
    'blogmig_t3_r1_b' => 'Vuelo a la zona de migración por 3 noches, Ngorongoro de vuelta',
    'blogmig_t3_r2_b' => 'Tarangire, Serengeti central 2 noches, zona de migración 3 noches, Ngorongoro',
    'blogmig_t3_r3_b' => 'Circuito norte completo con 4 noches en la zona de migración, luego Zanzíbar',
    'blogmig_s7_badge' => 'Mitos',
    'blogmig_s7_title' => 'Cinco cosas en las que la gente se equivoca',
    'blogmig_s7_myth1_t' => 'La migración ocurre en agosto',
    'blogmig_s7_myth1_d' => 'Los <em>cruces del río Mara</em> ocurren alrededor de agosto. La migración en sí es continua. Las manadas siempre están en algún lugar, y no hay mes en que no pase nada.',
    'blogmig_s7_myth2_t' => 'Necesito ir a Kenia para verla',
    'blogmig_s7_myth2_d' => 'Alrededor del 80% del circuito anual de la migración está dentro de Tanzania. Las manadas pasan aproximadamente dos a tres meses en el Masái Mara y el resto del año en el ecosistema del Serengeti.',
    'blogmig_s7_myth3_t' => 'Un cruce está garantizado si voy en el momento adecuado',
    'blogmig_s7_myth3_d' => 'No lo está. Estar en el lugar correcto en el mes correcto le da una buena oportunidad durante varios días. No le da a nadie una garantía en una sola mañana.',
    'blogmig_s7_myth4_t' => 'La migración es una manada gigante',
    'blogmig_s7_myth4_d' => 'Son columnas y grupos dispersos a lo largo de decenas de kilómetros, a veces convergiendo y a veces dispersos. La toma documental de una masa sólida es un momento, no el estado normal.',
    'blogmig_s7_myth5_t' => 'La temporada de lluvias es un mal momento',
    'blogmig_s7_myth5_d' => 'Abril y mayo son verdes, dramáticos, casi vacíos de otros vehículos y considerablemente más económicos, y las manadas se mueven por el centro y el oeste, lo cual es una observación perfectamente buena. Si su prioridad es el valor y la soledad en lugar de los cruces de río, los meses húmedos están subestimados.',
    'blogmig_faq_title' => 'La Gran Migración: preguntas frecuentes',
    'blogmig_faq_q1' => '¿Cuál es la mejor época para ver la Gran Migración?',
    'blogmig_faq_a1' => 'Depende de qué fase quiera. Finales de enero a febrero para la temporada de nacimientos en Ndutu; julio a octubre para los cruces del río Mara en el norte del Serengeti. Ambos son excepcionales, y ocurren en extremos opuestos del parque y del calendario.',
    'blogmig_faq_q2' => '¿Puedo ver la migración todo el año?',
    'blogmig_faq_a2' => 'Sí. Las manadas nunca abandonan el ecosistema. Se mueven en un circuito continuo. Lo que cambia es dónde están, así que la región donde se aloje debe coincidir con su mes.',
    'blogmig_faq_q3' => '¿Veré definitivamente un cruce de río?',
    'blogmig_faq_a3' => 'No, y sea escéptico con cualquiera que prometa uno. Las manadas pueden esperar en la orilla todo un día y luego alejarse. Tres noches en Kogatende entre finales de julio y septiembre le dan una buena oportunidad, no una garantía.',
    'blogmig_faq_q4' => '¿Debería ir a Tanzania o Kenia para la migración?',
    'blogmig_faq_a4' => 'Alrededor del 80% del circuito anual está en Tanzania. Las manadas pasan solo dos a tres meses en el Masái Mara. Tanzania también le ofrece la temporada de nacimientos, que Kenia no.',
    'blogmig_faq_q5' => '¿Dónde necesito alojarme para la temporada de nacimientos?',
    'blogmig_faq_a5' => 'Ndutu, en las llanuras de hierba corta del sur, entre diciembre y marzo. Note que Ndutu está técnicamente dentro del Área de Conservación del Ngorongoro en lugar del Serengeti, aunque ecológicamente es la misma llanura.',
    'blogmig_faq_q6' => '¿Cuántos días necesito para un safari de migración?',
    'blogmig_faq_a6' => 'Tres noches mínimo en la propia zona de migración, más días de viaje. Dos noches es una apuesta y una es un boleto de lotería. Cinco a siete días en total hace un viaje cómodo.',
    'blogmig_faq_q7' => '¿Cuántos ñus hay?',
    'blogmig_faq_a7' => 'Alrededor de 1,3 millones de ñus, más aproximadamente 250.000 cebras y varios cientos de miles de gacelas. Es el mayor movimiento terrestre de animales que queda en la tierra.',
    'blogmig_faq_q8' => '¿Qué es un campamento móvil?',
    'blogmig_faq_a8' => 'Un campamento con tienda que se reubica físicamente dos o tres veces al año para seguir a las manadas. Es la forma más fiable de mantenerse cerca de la migración, típicamente 300–700 $ por persona y noche, y generalmente pequeño y remoto.',
    'blogmig_final_title' => '¿Listo para planificar su safari de migración?',
    'blogmig_final_intro' => 'Díganos sus fechas y le diremos honestamente si es temporada de nacimientos, temporada de cruces, o algo intermedio, y construiremos el itinerario en consecuencia.',

    // Blog article: Kenya vs Tanzania safari
    'blogkenya_meta_title' => 'Safari Kenia contra Tanzania: una comparación honesta (2026)',
    'blogkenya_meta_description' => '¿Kenia o Tanzania para un safari? Una comparación honesta del Serengeti y el Masái Mara, meses de migración, tasas de parque, densidad de vehículos, reglas de conducción fuera de pista y qué país conviene a qué tipo de viaje.',
    'blogkenya_updated' => 'Actualizado 2026',
    'blogkenya_h1' => 'Safari Kenia contra Tanzania',
    'blogkenya_hero_sub' => 'El mismo ecosistema, dividido por una frontera: lo que cada país hace realmente mejor, escrito por un operador tanzano intentando ser justo al respecto.',
    'blogkenya_author' => 'Serengeti Budget Safari',
    'blogkenya_date' => '2026',
    'blogkenya_quick_badge' => 'Respuestas rápidas',
    'blogkenya_quick_title' => 'Kenia o Tanzania, en breve',
    'blogkenya_quick_intro' => 'Los titulares honestos.',
