    'blogkenya_qq1_a' => '9–10 meses en Tanzania, 2–3 en Kenia.',
    'blogkenya_qq2_q' => '¿Temporada de nacimientos?',
    'blogkenya_qq2_a' => 'Solo Tanzania, en Ndutu en ene–feb.',
    'blogkenya_qq3_q' => '¿Cuál es más económico?',
    'blogkenya_qq3_a' => 'Kenia, generalmente: tasas más bajas, distancias más cortas.',
    'blogkenya_qq4_q' => '¿Menos vehículos?',
