    'blogkenya_s1_badge' => 'En breve',
    'blogkenya_s1_title' => 'La respuesta corta',
    'blogkenya_s1_p1' => 'Comparten el mismo ecosistema y la misma migración, divididos por una frontera. En términos generales:',
    'blogkenya_s1_li1_t' => 'Tanzania',
    'blogkenya_s1_li1_d' => 'por la escala, variedad y la temporada de nacimientos. También tiene el Kilimanjaro, Zanzíbar y el Cráter del Ngorongoro.',
    'blogkenya_s1_li2_t' => 'Kenia',
    'blogkenya_s1_li2_d' => 'por la conveniencia y menor costo. Los avistamientos llegan más rápido en un área más pequeña, y generalmente es más económico.',
    'blogkenya_s1_p2' => 'Ninguno es objetivamente mejor. Lo que sigue es el detalle honesto, escrito, debemos decirlo claramente, por un operador tanzano. Hemos intentado ser justos.',
    'blogkenya_s2_badge' => 'Comparación',
    'blogkenya_s2_title' => 'Lado a lado',
    'blogkenya_t1_h1' => 'Factor',
    'blogkenya_t1_h2' => 'Tanzania',
    'blogkenya_t1_h3' => 'Kenia',
    'blogkenya_t1_r1_a' => 'Tamaño del parque insignia',
    'blogkenya_t1_r2_a' => 'Meses de migración',
    'blogkenya_t1_r2_b' => '~9–10 meses al año',
    'blogkenya_t1_r2_c' => '~2–3 meses (jul–oct)',
    'blogkenya_t1_r3_a' => 'Temporada de nacimientos',
    'blogkenya_t1_r4_a' => 'Cruces de río',
    'blogkenya_t1_r4_b' => 'Mara y Grumeti',
    'blogkenya_t1_r5_a' => 'Tasas de parque',
    'blogkenya_day' => 'día',
    'blogkenya_t1_r5_c' => 'Generalmente más bajas',
