    'blogkenya_t1_r9_a' => 'Rinoceronte negro',
    'blogkenya_t1_r9_b' => 'Ngorongoro (~60%)',
    'blogkenya_t1_r9_c' => 'Varias opciones fiables',
    'blogkenya_t1_r10_a' => 'Montaña más alta',
    'blogkenya_t1_r11_a' => 'Playa',
    'blogkenya_t1_r12_a' => 'Cómo moverse',
    'blogkenya_t1_r12_b' => 'Trayectos más largos',
    'blogkenya_t1_r12_c' => 'Trayectos más cortos',
    'blogkenya_s3_badge' => 'Migración',
    'blogkenya_s3_title' => 'La migración: ¿quién tiene más de ella?',
    'blogkenya_s3_p1' => 'Esta es la pregunta que la mayoría de la gente realmente se hace, y la respuesta es más clara de lo que sugiere el marketing de ambos lados.',
    'blogkenya_s3_p2' => 'Las manadas pasan aproximadamente <strong>nueve a diez meses del año en Tanzania</strong> y dos a tres meses en el Masái Mara de Kenia. Los famosos cruces del río Mara ocurren en la frontera, y pueden observarse desde cualquier lado entre julio y octubre.',
    'blogkenya_s3_p3' => '<strong>Lo que Tanzania tiene y Kenia no:</strong> la temporada de nacimientos. Alrededor de 400.000 ñus nacen en Ndutu a finales de enero y febrero, y eso no ocurre en ningún otro lugar.',
    'blogkenya_s3_p4' => '<strong>Lo que Kenia tiene y Tanzania no:</strong> la compacidad. El Mara tiene una décima parte del tamaño del Serengeti, así que cuando las manadas están allí, están concentradas y son fáciles de alcanzar.',
    'blogkenya_s4_badge' => 'Experiencia',
    'blogkenya_s4_title' => 'Cómo se siente realmente la experiencia',
    'blogkenya_s4_sub1' => 'Tanzania',
    'blogkenya_s4_p1' => 'Más grande, más vacío y más lento. Los trayectos entre parques son largos (Arusha al Serengeti son siete a ocho horas), y los paisajes cambian dramáticamente a medida que avanza. La conducción fuera de pista está prohibida, así que se mantiene en las pistas y los avistamientos se hacen a distancia respetuosa. En los parques menos visitados puede pasar una mañana sin ver otro vehículo.',
    'blogkenya_s4_sub2' => 'Kenia',
    'blogkenya_s4_p2' => 'Más compacto y a un ritmo más rápido. Los trayectos son más cortos, los avistamientos llegan más rápido, y en las reservas privadas que bordean el Mara, la conducción fuera de pista, los safaris nocturnos y las caminatas están todos permitidos, algo que los parques nacionales de Tanzania no permiten. La contrapartida es la densidad de vehículos: un buen avistamiento en el Mara en agosto puede atraer una multitud.',
    'blogkenya_s4_note_t' => 'El resumen honesto:',
    'blogkenya_s4_note_d' => 'si quiere la mayor variedad y la sensación de un espacio enorme, Tanzania. Si quiere la mayor fauna por día y por dólar en un viaje más corto, Kenia. Muchos viajeros experimentados terminan haciendo ambos.',
    'blogkenya_s5_badge' => 'Elegir',
    'blogkenya_s5_title' => '¿Cuál debería elegir?',
    'blogkenya_t2_h1' => 'Si usted…',
    'blogkenya_t2_h2' => 'Elija',
    'blogkenya_t2_r1_a' => 'Quiere la temporada de nacimientos',
    'blogkenya_t2_r2_a' => 'Quiere escalar el Kilimanjaro',
    'blogkenya_t2_r3_a' => 'Quiere una playa después',
    'blogkenya_t2_r4_a' => 'Quiere el Cráter del Ngorongoro',
    'blogkenya_t2_r5_a' => 'Tiene 10+ días',
    'blogkenya_t2_r6_a' => 'Tiene 5 días o menos',
    'blogkenya_t2_r7_a' => 'Tiene un presupuesto más ajustado',
    'blogkenya_t2_r8_a' => 'Quiere safaris nocturnos y fuera de pista',
    'blogkenya_conservancies' => 'reservas privadas',
    'blogkenya_t2_r9_a' => 'Quiere cruces de río en jul–oct',
    'blogkenya_either' => 'Cualquiera',
    'blogkenya_t2_r10_a' => 'Quiere menos otros vehículos',
    'blogkenya_southern_circuit' => '(circuito sur)',
    'blogkenya_s5_sub1' => '¿Puedo hacer ambos?',
    'blogkenya_s5_p1' => 'Sí. El Serengeti y el Masái Mara son adyacentes, y los itinerarios combinados son comunes, generalmente volando entre ellos, ya que el cruce fronterizo terrestre en Isebania es lento. Note que la <strong>Visa Turística de África Oriental no cubre Tanzania</strong>: necesita visas separadas para cada país. Presupueste de 10 a 14 días para hacer ambos correctamente.',
    'blogkenya_faq_badge' => 'Preguntas frecuentes',
    'blogkenya_faq_title' => 'Kenia contra Tanzania: preguntas frecuentes',
    'blogkenya_faq_q1' => '¿Es Tanzania o Kenia mejor para un safari?',
    'blogkenya_faq_a1' => 'Ninguno es objetivamente mejor. Tanzania ofrece mayor escala y variedad, la temporada de nacimientos, el Kilimanjaro, el Ngorongoro y Zanzíbar. Kenia es más compacto, generalmente más económico, y mejor para viajes cortos.',
    'blogkenya_faq_q2' => '¿Dónde está la Gran Migración: Tanzania o Kenia?',
    'blogkenya_faq_a2' => 'En ambos, pero las manadas pasan aproximadamente de nueve a diez meses del año en Tanzania y solo de dos a tres en el Masai Mara de Kenia. Los famosos cruces de ríos ocurren en la frontera entre julio y octubre.',
    'blogkenya_faq_q3' => '¿Qué es más barato, Kenia o Tanzania?',
    'blogkenya_faq_a3' => 'Kenia, generalmente. Las tarifas de los parques tanzanos son más altas ($82.60 por día en el Serengeti) y las distancias son mayores, lo que implica más combustible y más días. La compacidad de Kenia reduce el costo total del viaje.',
    'blogkenya_faq_q4' => '¿Es el Serengeti mejor que el Masai Mara?',
    'blogkenya_faq_a4' => 'Son el mismo ecosistema dividido por una frontera. El Serengeti es aproximadamente diez veces más grande, con hábitats más variados y menor densidad de vehículos; el Mara es compacto, por lo que los avistamientos llegan más rápido, pero con más aglomeración en temporada alta.',
    'blogkenya_faq_q5' => '¿Puedo ver la temporada de nacimientos en Kenia?',
    'blogkenya_faq_a5' => 'No. Los nacimientos ocurren en las llanuras de pasto corto del sur, en Ndutu, en Tanzania, a finales de enero y febrero. Es una de las razones más claras para elegir Tanzania.',
    'blogkenya_faq_q6' => '¿Puedo visitar ambos países en un solo viaje?',
    'blogkenya_faq_a6' => 'Sí, y los itinerarios combinados son comunes, generalmente volando entre el Serengeti y el Mara, ya que cruzar la frontera terrestre es lento. Reserve de 10 a 14 días y tenga en cuenta que necesita visados separados para cada país.',
    'blogkenya_faq_q7' => '¿El Visado de Turista de África Oriental cubre Tanzania?',
    'blogkenya_faq_a7' => 'No. Cubre solo Kenia, Uganda y Ruanda. Tanzania requiere su propio visado, actualmente $50 para la mayoría de las nacionalidades.',
    'blogkenya_faq_q8' => '¿Qué país es mejor para los Big Five?',
    'blogkenya_faq_a8' => 'Ambos ofrecen cuatro de los cinco con facilidad. Para el rinoceronte negro, Kenia tiene varias opciones fiables, incluyendo Ol Pejeta y el lago Nakuru, mientras que en Tanzania el cráter del Ngorongoro es prácticamente el único lugar realista.',
    'blogkenya_faq_q9' => '¿Dónde hay menos turistas?',
    'blogkenya_faq_a9' => 'Tanzania, particularmente el circuito sur: Ruaha, Nyerere y Mikumi reciben una fracción mínima de los visitantes del Serengeti o del Mara. Incluso Tarangire es tranquilo para los estándares de África Oriental.',
    'blogkenya_faq_q10' => '¿Puedo hacer safaris nocturnos y conducir fuera de pista?',
    'blogkenya_faq_a10' => 'En las reservas privadas de Kenia, sí. En los parques nacionales de Tanzania, conducir fuera de pista está prohibido y los safaris nocturnos no están permitidos, excepto en Lake Manyara, Tarangire y algunas concesiones privadas.',
    'blogkenya_faq_q11' => '¿Cuál es mejor para un primer safari?',
    'blogkenya_faq_a11' => 'Si tiene una semana o más y quiere variedad, Tanzania. Si tiene cuatro o cinco días, Kenia ofrece más fauna por día porque las distancias son mucho más cortas.',
    'blogkenya_faq_q12' => '¿Y el Kilimanjaro: está en Kenia o Tanzania?',
    'blogkenya_faq_a12' => 'En Tanzania, enteramente. La famosa vista del Kilimanjaro elevándose detrás de los elefantes suele fotografiarse desde Amboseli, en Kenia, pero la montaña en sí y todas las rutas de ascenso están en Tanzania.',
    'blogkenya_related_badge' => 'Sigue leyendo',
    'blogkenya_related_title' => 'Continúa explorando Tanzania',
    'blogkenya_final_title' => '¿Aún decidiendo?',
    'blogkenya_final_intro' => 'Cuéntenos sus fechas y cuánto tiempo tiene. Si Kenia realmente se adapta mejor a su viaje que Tanzania, se lo diremos. Preferimos ser útiles antes que ganar una reserva de la que se arrepienta.',
    'blogkenya_final_whatsapp' => 'Escríbanos por WhatsApp',
    'blogkenya_final_contact' => 'Formulario de contacto',

    // Blog article: Best time to visit Tanzania
    'blogbest_meta_title' => 'Mejor Época para Visitar Tanzania: Mes a Mes (2026) | Serengeti Budget Safari',
    'blogbest_meta_description' => 'Cuándo visitar Tanzania, mes a mes: temporada seca, las dos temporadas de lluvia, la temporada de nacimientos y los cruces del río Mara, temperaturas por altitud, y los mejores meses para el safari, el Kilimanjaro y Zanzíbar.',
    'blogbest_h1' => 'Mejor época para visitar Tanzania',
