    'blogbest_s1_title' => 'La respuesta corta',
    'blogbest_s1_p1' => '<strong>De junio a octubre</strong> es la temporada seca y la época más fácil para ver fauna en casi toda Tanzania. <strong>A finales de enero y febrero</strong> llega la temporada de nacimientos en el sur del Serengeti, que muchos guías consideran el mejor espectáculo. <strong>De marzo a mayo</strong> son las lluvias largas: verde, tranquilo y considerablemente más económico.',
    'blogbest_s1_p2' => 'No hay temporada cerrada. Lo que cambia es lo que se ve, con cuántos otros vehículos se comparte y lo que se paga.',
    'blogbest_t1_h1' => 'Temporada',
    'blogbest_t1_h2' => 'Meses',
