    'blogbest_t1_r4_c' => 'Variable',
    'blogbest_t1_r4_d' => 'Muy baja',
    'blogbest_t1_r4_e' => 'El más bajo',
    'blogbest_s2_badge' => 'Temporadas',
    'blogbest_s2_title' => 'Tanzania tiene dos temporadas de lluvia, no una',
    'blogbest_s2_p1' => 'Confundirlas es el error de planificación más común, y son realmente diferentes.',
    'blogbest_s2_sub1_title' => 'Las lluvias largas: de marzo a mayo',
    'blogbest_s2_sub1_p' => 'Lluvia real, a menudo durante varias horas al día, más intensa en abril. Algunas pistas se vuelven intransitables, el suelo de algodón negro en el Corredor Occidental se convierte en barro pegajoso, y varios campamentos de temporada cierran por completo, particularmente en Ruaha y Nyerere. También es la época más económica del año por un amplio margen, el paisaje es espectacular y se pueden tener los parques casi en exclusiva.',
    'blogbest_s2_sub2_title' => 'Las lluvias cortas: de noviembre a diciembre',
    'blogbest_s2_sub2_p' => 'Chubascos breves e intensos por la tarde, con el resto del día generalmente soleado. Nada cierra, nada se inunda, el país se vuelve verde y los precios siguen siendo moderados. Para muchos viajeros, este es el mejor compromiso del año, y está muy infravalorado.',
    'blogbest_s2_note_t' => 'Algo que vale la pena saber:',
    'blogbest_s2_note_d' => 'la lluvia en Tanzania rara vez arruina un día. Normalmente significa una hora intensa y luego aire despejado, luz dramática y un paisaje que se fotografía mucho mejor que el polvoriento agosto.',
    'blogbest_s3_badge' => 'El calendario',
