    'blogbest_m12_weather' => 'Lluvias cortas',
    'blogbest_m12_highlights' => 'Las manadas llegan a las llanuras del sur; concurrido desde mediados de mes',
    'blogbest_m12_verdict' => 'Bueno',
    'blogbest_s4_badge' => 'Elegir',
    'blogbest_s4_title' => 'Mejor época según lo que desee',
