    'blogbest_t3_h3' => 'Por qué',
    'blogbest_w1_want' => 'Avistamiento de fauna más fácil',
    'blogbest_w1_why' => 'Vegetación escasa, animales concentrados en el agua',
    'blogbest_w2_want' => 'Cruces del río Mara',
    'blogbest_w2_why' => 'Frecuencia máxima en el norte del Serengeti',
    'blogbest_w3_want' => 'Nacimientos y depredadores',
    'blogbest_w3_why' => '400.000 nacimientos; caza constante',
    'blogbest_w4_want' => 'Precios más bajos',
    'blogbest_w4_why' => 'Lluvias largas; los campamentos hacen grandes descuentos',
    'blogbest_w5_want' => 'Menos vehículos',
    'blogbest_w5_why' => 'Parques casi vacíos',
    'blogbest_w6_want' => 'Observación de aves',
    'blogbest_w6_why' => 'Migrantes presentes, residentes con plumaje reproductivo',
    'blogbest_w7_want' => 'Fotografía',
    'blogbest_w7_why' => 'Paisajes verdes, cielos dramáticos, aire limpio',
    'blogbest_w8_want' => 'Kilimanjaro',
    'blogbest_w8_why' => 'Más seco y estable en la montaña',
    'blogbest_w9_want' => 'Zanzíbar',
    'blogbest_w9_why' => 'Seco, mar en calma, buena visibilidad para bucear',
    'blogbest_w10_want' => 'Circuito sur',
    'blogbest_w10_why' => 'Ruaha y Nyerere cierran en gran parte de marzo a mayo',
    'blogbest_s5_badge' => 'Clima',
    'blogbest_s5_title' => 'Cómo es realmente el clima',
    'blogbest_s5_p1' => 'Tanzania está situada en el ecuador, pero la altitud importa mucho más que la latitud. Los parques del norte están entre 1.000 m y 2.400 m, por eso las mañanas son realmente frías.',
    'blogbest_t4_h1' => 'Lugar',
    'blogbest_t4_h2' => 'Altitud',
    'blogbest_t4_h3' => 'Día',
    'blogbest_t4_h4' => 'Amanecer',
    'blogbest_c1_place' => 'Borde del Ngorongoro',
    'blogbest_c2_place' => 'Serengeti',
    'blogbest_c3_place' => 'Arusha',
    'blogbest_c4_place' => 'Tarangire',
    'blogbest_c5_place' => 'Zanzíbar',
    'blogbest_c6_place' => 'Cumbre del Kilimanjaro',
    'blogbest_sea_level' => 'Nivel del mar',
    'blogbest_colder' => 'Más frío',
    'blogbest_s5_p2' => 'La cifra que sorprende a la gente es el borde del Ngorongoro al amanecer: alrededor de 5 °C, en un vehículo abierto, en movimiento. Todo visitante que solo preparó equipaje para "África" se arrepiente. Las capas de ropa no son opcionales.',
    'blogbest_faq_badge' => 'Preguntas frecuentes',
    'blogbest_faq_title' => 'Cuándo visitar Tanzania: preguntas frecuentes',
    'blogbest_faq_q1' => '¿Cuál es la mejor época para visitar Tanzania?',
    'blogbest_faq_a1' => 'De junio a octubre para el avistamiento de fauna más fácil en todas partes, y de finales de enero a febrero para la temporada de nacimientos en el Serengeti. De marzo a mayo son las lluvias largas: verde, tranquilo y con diferencia el más económico.',
    'blogbest_faq_q2' => '¿Cuál es la peor época para visitar Tanzania?',
    'blogbest_faq_a2' => 'Abril es el mes más lluvioso y el que más gente evita. Las pistas se vuelven difíciles, algunos campamentos del sur cierran por completo y las vistas suelen estar obstruidas. También es el mes más económico y los parques están casi vacíos, por lo que le conviene muy bien a algunos viajeros.',
    'blogbest_faq_q3' => '¿Puedo ir de safari en la temporada de lluvias?',
    'blogbest_faq_a3' => 'Sí. Los parques del norte funcionan todo el año y la lluvia suele llegar en ráfagas intensas en lugar de durante todo el día. Ruaha y Nyerere, en el sur, son diferentes. La mayoría de los campamentos allí cierran entre marzo y mayo.',
    'blogbest_faq_q4' => '¿Cuándo son los cruces del río Mara?',
    'blogbest_faq_a4' => 'De julio a octubre en el norte del Serengeti, siendo agosto y septiembre los meses de mayor frecuencia. Estar allí en el mes correcto le da una buena probabilidad a lo largo de varios días, nunca una garantía en una mañana concreta.',
    'blogbest_faq_q5' => '¿Cuándo es la temporada de nacimientos?',
    'blogbest_faq_a5' => 'A finales de enero y febrero, en las llanuras de pasto corto alrededor de Ndutu. Alrededor de 400.000 crías nacen en una ventana de tres semanas, y la actividad de los depredadores es la más alta del año.',
    'blogbest_faq_q6' => '¿Hace frío en Tanzania?',
    'blogbest_faq_a6' => 'En altitud, sí, y esto sorprende a la mayoría de los visitantes. El borde del Ngorongoro baja a unos 5 °C antes del amanecer, y el Serengeti a 13–15 °C. Durante el día hace calor, así que la respuesta son las capas de ropa en lugar de un abrigo grueso.',
    'blogbest_faq_q7' => '¿Cuándo es la época más económica para ir de safari?',
    'blogbest_faq_a7' => 'Abril y mayo, durante las lluvias largas, cuando los campamentos hacen grandes descuentos y los parques están casi vacíos. Noviembre es la siguiente opción más económica y considerablemente más seca: chubascos breves por la tarde en lugar de lluvia todo el día.',
    'blogbest_faq_q8' => '¿Cuándo es la mejor época para escalar el Kilimanjaro?',
    'blogbest_faq_a8' => 'De enero a principios de marzo y de junio a octubre. Enero y febrero tienen las noches de cumbre más cálidas; de junio a octubre es la época más seca y concurrida. Abril y mayo son las lluvias largas y es mejor evitarlas en la montaña.',
    'blogbest_faq_q9' => '¿Cuándo es la mejor época para Zanzíbar?',
    'blogbest_faq_a9' => 'De junio a octubre es seco y menos húmedo; de diciembre a febrero hace calor con mares en calma y excelente visibilidad para el buceo. De marzo a mayo son las lluvias largas, cuando algunos hoteles cierran.',
    'blogbest_faq_q10' => '¿Qué tan concurrido está agosto?',
    'blogbest_faq_a10' => 'Es el mes pico. Los campamentos del norte del Serengeti se agotan de seis a doce meses antes, los precios están en su punto más alto y compartirá los avistamientos. La fauna es magnífica. Simplemente no estará solo con ella.',
    'blogbest_faq_q11' => '¿Es noviembre un buen mes?',
    'blogbest_faq_a11' => 'Es uno de los más infravalorados. Las lluvias cortas traen breves chubascos por la tarde, el paisaje se vuelve verde, llegan aves migratorias para los observadores, los precios son moderados y los parques están tranquilos. Nada cierra.',
    'blogbest_faq_q12' => '¿Se detiene la migración en la temporada de lluvias?',
    'blogbest_faq_a12' => 'No. Las manadas están en el ecosistema todos los meses del año. Las lluvias son precisamente lo que las impulsa. En abril y mayo se están moviendo por el centro y el oeste del Serengeti.',
    'blogbest_faq_q13' => '¿Qué pasa con Navidad y Año Nuevo?',
    'blogbest_faq_a13' => 'Concurrido y caro. Muchos campamentos cobran un suplemento de temporada alta desde alrededor del 20 de diciembre hasta el 3 de enero y exigen estancias mínimas. El avistamiento de fauna es bueno, pero se paga por las fechas.',
    'blogbest_faq_q14' => '¿Puedo combinar safari y Zanzíbar en cualquier época del año?',
    'blogbest_faq_a14' => 'Las temporadas se alinean bien: de junio a octubre y de diciembre a febrero son buenas para ambos. De marzo a mayo estaría combinando un safari lluvioso con una costa lluviosa, por eso ese período es el más económico.',
    'blogbest_related_badge' => 'Sigue leyendo',
    'blogbest_related_title' => 'Continúa explorando Tanzania',
    'blogbest_related_kili' => 'Guía del Kilimanjaro',
    'blogbest_final_title' => 'Cuéntenos sus fechas',
    'blogbest_final_intro' => 'Envíenos las semanas en que puede viajar y le diremos honestamente qué verá entonces, dónde deberían estar las manadas, y si valdría la pena cambiar de fecha por quince días.',
    'blogbest_final_whatsapp' => 'Escríbanos por WhatsApp',
    'blogbest_final_contact' => 'Formulario de contacto',

    // ===== Blog article: Tipping on Safari and Kilimanjaro =====
    'blogtip_meta_title' => 'Propinas en Safari y Kilimanjaro: ¿Cuánto? (2026) | Serengeti Budget Safari',
    'blogtip_meta_description' => 'Cuánto dar de propina en Tanzania: cifras orientativas para guías de safari, personal de campamento y cocineros, además de las cifras mucho mayores de propinas del equipo del Kilimanjaro, con ejemplos prácticos y consejos sobre efectivo.',
    'blogtip_h1' => 'Propinas en safari y Kilimanjaro',
    'blogtip_hero_sub' => 'Qué es habitual, cuánto suma en total, y por qué la cifra del Kilimanjaro sorprende a la gente, explicado antes de reservar y no en la montaña.',
    'blogtip_updated' => 'Actualizado 2026',
    'blogtip_author' => 'Equipo de Serengeti Budget Safari',
    'blogtip_date' => 'Agosto de 2026',
    'blogtip_quick_badge' => 'Respuestas rápidas',
    'blogtip_quick_title' => 'Propinas en resumen',
    'blogtip_quick_intro' => 'Cifras orientativas, del grupo en conjunto.',
    'blogtip_qq1_q' => '¿Guía de safari?',
    'blogtip_qq1_a' => '$20–25 por día, del grupo.',
    'blogtip_qq2_q' => '¿Personal del campamento?',
    'blogtip_qq2_a' => '$10–15 por día en la caja común.',
    'blogtip_qq3_q' => '¿Total del Kilimanjaro?',
    'blogtip_qq3_a' => '$400–500 por escalador en una ruta de 7 días.',
    'blogtip_qq4_q' => '¿Efectivo o tarjeta?',
    'blogtip_qq4_a' => 'Solo efectivo. No hay cajeros automáticos en los parques.',
    'blogtip_qq5_q' => '¿Cuándo?',
    'blogtip_qq5_a' => 'Al final, no a diario.',
    'blogtip_qq6_q' => '¿Estado de los billetes?',
    'blogtip_qq6_a' => 'Los billetes de EE. UU. deben ser posteriores a 2009.',
    'blogtip_see_faq' => 'Ver todas las preguntas frecuentes',
    'blogtip_toc_title' => 'Contenido – Propinas en safari y Kilimanjaro',
    'blogtip_toc_1' => 'Por qué importa',
    'blogtip_toc_2' => 'Propinas en safari',
    'blogtip_toc_3' => 'Propinas en el Kilimanjaro',
    'blogtip_toc_4' => 'Puntos prácticos',
    'blogtip_toc_5' => 'Preguntas frecuentes',
    'blogtip_s1_badge' => 'Contexto',
    'blogtip_s1_title' => 'Por qué las propinas importan aquí',
    'blogtip_s1_p1' => 'Dar propina en Tanzania es habitual y forma una parte significativa de lo que ganan los guías, cocineros, porteadores y personal de campamento. Es verdaderamente discrecional (nadie se lo exigirá), pero se espera, y quienes la reciben cuentan con ella en su presupuesto.',
    'blogtip_s1_p2' => 'Las cifras a continuación son las orientaciones que damos a nuestros propios clientes. No son reglas, y debe ajustarlas según el servicio, el tamaño del grupo y su propio presupuesto sin sentirse mal por ello.',
    'blogtip_s2_badge' => 'Safari',
    'blogtip_s2_title' => 'Orientaciones de propinas en safari',
    'blogtip_t1_h1' => 'Quién',
    'blogtip_t1_h2' => 'Cantidad',
    'blogtip_t1_h3' => 'Base',
    'blogtip_t1_r1_a' => 'Guía-conductor',
    'blogtip_t1_r1_c' => 'Del grupo en conjunto, no por persona',
    'blogtip_t1_r2_a' => 'Personal de campamento / lodge',
    'blogtip_t1_r2_c' => 'En la caja común de propinas, del grupo',
    'blogtip_t1_r3_a' => 'Cocinero (safaris de acampada)',
    'blogtip_t1_r3_c' => 'Del grupo',
    'blogtip_t1_r4_a' => 'Conductor de traslado al aeropuerto',
    'blogtip_t1_r4_c' => 'Por traslado',
    'blogtip_t1_r5_a' => 'Restaurante',
    'blogtip_t1_r5_c' => 'Si el servicio no está incluido',
    'blogtip_per_day' => 'por día',
    'blogtip_s2_example_title' => 'Un ejemplo práctico',
    'blogtip_s2_example_intro' => 'Dos personas, safari de cuatro días, un guía-conductor, alojamiento en lodge:',
    'blogtip_s2_ex_li1' => 'Guía: $22 × 4 días = <strong>$88</strong>',
    'blogtip_s2_ex_li2' => 'Personal del lodge: $12 × 4 días = <strong>$48</strong>',
    'blogtip_s2_ex_li3' => '<strong>Total para el grupo: alrededor de $136</strong>, o $68 cada uno',
    'blogtip_s3_badge' => 'Kilimanjaro',
    'blogtip_s3_title' => 'Propinas en el Kilimanjaro',
    'blogtip_s3_p1' => 'Una ascensión implica un equipo mucho mayor, normalmente de tres a cuatro personas por escalador, y las propinas son una parte sustancial y esperada de sus ingresos. Las cifras son <strong>por día, del grupo completo</strong>.',
    'blogtip_t2_h1' => 'Función',
    'blogtip_t2_h2' => 'Por día, del grupo',
    'blogtip_t2_r1_a' => 'Guía principal',
    'blogtip_t2_r2_a' => 'Guía asistente',
    'blogtip_t2_r3_a' => 'Cocinero',
    'blogtip_t2_r4_a' => 'Porteador (cada uno)',
    'blogtip_s3_sub_title' => 'Cuánto suma esto en total',
    'blogtip_s3_p2' => 'Dos escaladores en una ruta Machame de siete días, con un equipo de aproximadamente once personas (un guía principal, un asistente, un cocinero y ocho porteadores) deberían presupuestar en torno a <strong>$800–1.000 en propinas totales</strong>, o $400–500 cada uno.',
    'blogtip_s3_p3' => 'Es una suma considerable y sorprende a la gente, por eso se lo decimos antes de reservar y no en la montaña. Inclúyalo en su presupuesto desde el principio.',
    'blogtip_s3_note_t' => 'Cómo funciona en la práctica:',
    'blogtip_s3_note_d' => 'las propinas se reúnen entre el grupo y se entregan en una ceremonia la última mañana, normalmente con el equipo cantando la canción del Kilimanjaro. Traiga el efectivo con usted. No hay cajeros automáticos en la montaña.',
    'blogtip_s4_badge' => 'Práctico',
    'blogtip_s4_title' => 'Puntos prácticos',
    'blogtip_s4_i1_t' => 'Traiga efectivo.',
    'blogtip_s4_i1_d' => 'Los dólares estadounidenses son lo habitual; los chelines tanzanos también sirven. No hay cajeros automáticos dentro de los parques ni en la montaña.',
    'blogtip_s4_i2_t' => 'Los billetes deben ser posteriores a 2009.',
    'blogtip_s4_i2_d' => 'Los billetes estadounidenses más antiguos se rechazan en toda Tanzania, incluso para propinas.',
    'blogtip_s4_i3_t' => 'Traiga billetes pequeños.',
    'blogtip_s4_i3_d' => 'Los billetes de $1, $5 y $10 facilitan repartir las propinas.',
    'blogtip_s4_i4_t' => 'Dé la propina al final,',
    'blogtip_s4_i4_d' => 'no a diario, excepto para traslados puntuales.',
    'blogtip_s4_i5_t' => 'Entregue las propinas en persona',
    'blogtip_s4_i5_d' => 'cuando pueda, o use la caja común para el personal de campamento de modo que cocina y limpieza queden incluidos.',
    'blogtip_s4_i6_t' => 'Ajuste según el servicio.',
    'blogtip_s4_i6_d' => 'Estas son orientaciones. Un guiado excepcional merece más; un servicio deficiente merece menos, y debe explicar por qué.',
    'blogtip_faq_badge' => 'Preguntas frecuentes',
    'blogtip_faq_title' => 'Propinas: preguntas frecuentes',
    'blogtip_faq_q1' => '¿Cuánto debo dar de propina a un guía de safari?',
    'blogtip_faq_a1' => 'Alrededor de $20–25 por día del grupo en conjunto, no por persona. Para un safari de cuatro días son aproximadamente $80–100 en total, sea cual sea el número de personas en el vehículo.',
    'blogtip_faq_q2' => '¿Es obligatorio dar propina en Tanzania?',
    'blogtip_faq_a2' => 'No, es discrecional. Pero es habitual y forma una parte significativa de lo que ganan los guías, cocineros y personal de campamento, y quienes la reciben cuentan con ella en su presupuesto.',
    'blogtip_faq_q3' => '¿Cuánto debo dar de propina en una ascensión al Kilimanjaro?',
    'blogtip_faq_a3' => 'Presupueste aproximadamente $800–1.000 en total para dos escaladores en una ruta de siete días con un equipo de unas once personas, alrededor de $400–500 cada uno. Por día, del grupo: $20–25 guía principal, $15–18 asistente, $12–15 cocinero, $8–10 por porteador.',
    'blogtip_faq_q4' => '¿Por qué son tan altas las propinas del Kilimanjaro?',
    'blogtip_faq_a4' => 'Porque el equipo es numeroso, normalmente de tres a cuatro personas por escalador, cargando su equipo, comida y agua en altitud. Las propinas son una parte sustancial y esperada de sus ingresos, por eso le decimos la cifra antes de reservar.',
    'blogtip_faq_q5' => '¿En qué moneda debo dar la propina?',
    'blogtip_faq_a5' => 'Los dólares estadounidenses son lo habitual y los chelines tanzanos también sirven. Los billetes deben ser posteriores a 2009. Los billetes estadounidenses más antiguos se rechazan en todo el país. Traiga denominaciones de $1, $5 y $10.',
    'blogtip_faq_q6' => '¿Cuándo debo dar la propina?',
    'blogtip_faq_a6' => 'Al final del safari o la ascensión en lugar de a diario, excepto para traslados puntuales al aeropuerto. En el Kilimanjaro suele haber una ceremonia de propinas en la última mañana.',
    'blogtip_faq_q7' => '¿Debo dar propina por persona o por grupo?',
    'blogtip_faq_a7' => 'Por grupo. Las cifras orientativas asumen que todo el vehículo o grupo de escalada contribuye en conjunto, por eso un grupo de cuatro no paga cuatro veces lo que paga una pareja.',
    'blogtip_faq_q8' => '¿Doy propina al personal del campamento por separado?',
    'blogtip_faq_a8' => 'Sí, normalmente en una caja común de propinas para que la cocina, la limpieza y el personal de servicio queden todos incluidos, personas a las que quizá nunca conozca pero que hicieron gran parte del trabajo.',
    'blogtip_faq_q9' => '¿Puedo dar propina con tarjeta?',
    'blogtip_faq_a9' => 'No. Traiga efectivo. No hay cajeros automáticos dentro de los parques nacionales ni en el Kilimanjaro, y los datáfonos de los lodges dependen de una conectividad que a menudo no está disponible.',
    'blogtip_faq_q10' => '¿Y si el servicio fue deficiente?',
    'blogtip_faq_a10' => 'Dé menos propina y díganos por qué. Las orientaciones de propinas no son obligaciones, y una opinión sincera nos resulta genuinamente más útil que una propina dada por incomodidad.',
    'blogtip_faq_q11' => '¿Debo dar propina a los porteadores individualmente?',
    'blogtip_faq_a11' => 'En el Kilimanjaro las propinas normalmente se juntan y las distribuye el guía principal en la ceremonia, lo que garantiza un reparto justo. Si quiere dar algo extra a un porteador en concreto, hágalo directa y privadamente.',
    'blogtip_faq_q12' => '¿Debo dar propina si el cargo por servicio ya está incluido?',
    'blogtip_faq_a12' => 'En restaurantes donde aparece un cargo por servicio en la cuenta, no se espera una propina adicional. Las propinas de safari y escalada son independientes y no están incluidas en el precio de su viaje.',
    'blogtip_related_badge' => 'Sigue leyendo',
    'blogtip_related_title' => 'Continúa explorando Tanzania',
    'blogtip_related_contact' => 'Haznos una pregunta',
    'blogtip_final_title' => '¿Presupuestando su viaje?',
    'blogtip_final_intro' => 'Pídanos un presupuesto detallado y le incluiremos una estimación realista de propinas para su itinerario y tamaño de grupo específicos, para que no haya sorpresas.',
    'blogtip_final_whatsapp' => 'Escríbanos por WhatsApp',
    'blogtip_final_contact' => 'Formulario de contacto',

