    'blogvisa_s1_badge' => 'Las opciones',
    'blogvisa_s1_title' => 'Dos formas de obtener un visado',
    'blogvisa_s1_p1' => 'La mayoría de los visitantes necesita un visado para Tanzania. El visado turístico estándar cuesta <strong>US$50</strong> para la mayoría de las nacionalidades, es válido por <strong>90 días</strong>, y puede obtenerse en línea con antelación o a la llegada.',
    'blogvisa_s1_sub1' => 'e-Visa en línea, recomendado',
    'blogvisa_s1_p2' => 'Solicite en <strong>visa.immigration.go.tz</strong>, suba sus documentos y pague con tarjeta. Una decisión suele tardar <strong>hasta 10 días hábiles</strong>, aunque puede ser más en periodos de alta demanda. Comience al menos <strong>tres semanas</strong> antes de viajar. Recibirá un PDF para imprimir y presentar a la llegada.',
    'blogvisa_s1_sub2' => 'Visado a la llegada',
    'blogvisa_s1_p3' => 'Disponible en los aeropuertos de Kilimanjaro (JRO), Dar es Salaam y Zanzíbar. Funciona, pero implica hacer cola tras un vuelo largo, a menudo una hora o más en momentos de mucha afluencia, y pagar en efectivo en dólares estadounidenses. Si tiene tiempo para solicitarlo en línea, hágalo.',
    'blogvisa_s1_warn_t' => 'Cuidado con los sitios no oficiales.',
    'blogvisa_s1_warn_d' => 'Buscar un visado tanzano devuelve muchos sitios que parecen oficiales y cobran entre €50 y 100 en "tarifas de servicio" por algo que puede hacer usted mismo en veinte minutos. El único sitio oficial es <strong>visa.immigration.go.tz</strong> y el visado cuesta $50.',

    'blogvisa_s2_badge' => 'Requisitos',
    'blogvisa_s2_title' => 'Qué necesita',
    'blogvisa_s2_i1_t' => 'Pasaporte',
    'blogvisa_s2_i1_d' => 'válido al menos seis meses desde su fecha de entrada, con dos páginas en blanco',
    'blogvisa_s2_i2' => 'Una <strong>foto de pasaporte digital</strong>',
    'blogvisa_s2_i3' => 'Su <strong>billete de vuelta o de continuación</strong>',
    'blogvisa_s2_i4' => 'La dirección de su <strong>alojamiento de la primera noche</strong>, que proporcionamos con la confirmación de su reserva',
    'blogvisa_s2_i5' => 'Una tarjeta de crédito o débito para el pago en línea',
    'blogvisa_s2_sub1' => 'Nacionalidades que pagan más',
    'blogvisa_s2_p1' => 'A los <strong>ciudadanos de EE. UU.</strong> se les expide un visado de entradas múltiples que cuesta <strong>$100</strong> en lugar del estándar de $50 de entrada única. Un pequeño número de nacionalidades requiere visados de referencia con un tiempo de tramitación más largo. Si tiene un pasaporte de fuera de Europa, América del Norte o la Commonwealth, verifique con bastante antelación.',

    'blogvisa_s3_badge' => 'Zanzíbar',
    'blogvisa_s3_title' => 'Zanzíbar: mismo visado, seguro adicional',
    'blogvisa_s3_p1' => 'Zanzíbar es parte de Tanzania, por lo que <strong>no necesita un segundo visado</strong>. Sin embargo, hay un requisito adicional que sorprende a la gente.',
    'blogvisa_s3_p2' => 'Desde 2024, todos los visitantes extranjeros a Zanzíbar deben tener un <strong>seguro de viaje obligatorio emitido por un proveedor aprobado por Zanzíbar</strong>, con un costo de alrededor de <strong>US$44</strong> y comprado en línea antes de la llegada. Su póliza de viaje europea o estadounidense existente, por completa que sea, <strong>no satisface este requisito</strong>. Es un producto separado, emitido localmente.',
    'blogvisa_s3_p3' => 'Esto se comprueba en el aeropuerto de Zanzíbar y en la terminal de ferris. Cómprelo con antelación; podemos gestionarlo con su reserva.',

    'blogvisa_s4_badge' => 'Entrada sanitaria',
    'blogvisa_s4_title' => 'Certificado de fiebre amarilla',
    'blogvisa_s4_p1' => 'Se requiere un certificado de fiebre amarilla <strong>solo</strong> si llega desde, o ha transitado durante más de 12 horas por, un país con riesgo de fiebre amarilla.',
    'blogvisa_s4_p2' => 'Los viajeros que vuelan directamente desde Europa, América del Norte o Asia <strong>no lo necesitan</strong>. Los viajeros que conectan por Nairobi, Adís Abeba u otros centros africanos <strong>puede que sí</strong>, según la duración de la escala. Aquí es donde la gente se ve sorprendida.',
    'blogvisa_s4_p3' => 'El certificado se comprueba a la llegada, y sin uno donde se requiera será vacunado en el aeropuerto a su propio costo. Verifique su ruta específica antes de volar.',

    'blogvisa_faq_badge' => 'Preguntas frecuentes',
    'blogvisa_faq_title' => 'Visado de Tanzania: preguntas frecuentes',
    'blogvisa_faq_q1' => '¿Necesito un visado para Tanzania?',
    'blogvisa_faq_a1' => 'La mayoría de las nacionalidades sí. El visado turístico estándar cuesta US$50, es válido por 90 días, y puede obtenerse en línea con antelación o a la llegada en los principales aeropuertos.',
    'blogvisa_faq_q2' => '¿Cuánto cuesta un visado tanzano?',
    'blogvisa_faq_a2' => 'US$50 para la mayoría de las nacionalidades. Los ciudadanos de EE. UU. pagan $100 por un visado de entradas múltiples. Cuidado con los sitios web no oficiales que cobran entre €50 y 100 en tarifas de servicio adicionales por lo mismo.',
    'blogvisa_faq_q3' => '¿Cuánto tarda la e-visa?',
    'blogvisa_faq_a3' => 'Normalmente hasta 10 días hábiles, a veces más en periodos de alta demanda. Solicite al menos tres semanas antes de viajar para estar seguro.',
    'blogvisa_faq_q4' => '¿Cuál es el sitio web oficial del visado?',
    'blogvisa_faq_a4' => 'visa.immigration.go.tz es el único portal oficial. Muchos sitios de aspecto convincente cobran tarifas considerables por un servicio que puede completar usted mismo en unos veinte minutos.',
    'blogvisa_faq_q5' => '¿Puedo obtener un visado a la llegada?',
    'blogvisa_faq_a5' => 'Sí, en los aeropuertos de Kilimanjaro, Dar es Salaam y Zanzíbar, pagando en efectivo en dólares estadounidenses. Funciona, pero espere hacer cola, a veces más de una hora tras un vuelo largo. Solicitarlo en línea es la opción más tranquila.',
    'blogvisa_faq_q6' => '¿Necesito un visado separado para Zanzíbar?',
    'blogvisa_faq_a6' => 'No. Zanzíbar es parte de Tanzania y el mismo visado lo cubre. Pero desde 2024 sí necesita un seguro de viaje obligatorio de un proveedor aprobado por Zanzíbar, con un costo de alrededor de US$44, comprado antes de la llegada.',
    'blogvisa_faq_q7' => '¿Mi seguro de viaje normal cubre el requisito de Zanzíbar?',
    'blogvisa_faq_a7' => 'No. El seguro obligatorio de Zanzíbar es un producto separado, emitido localmente. Su póliza europea o estadounidense, por completa que sea, no satisface el requisito y se comprueba a la llegada.',
    'blogvisa_faq_q8' => '¿Cuánto tiempo debe ser válido mi pasaporte?',
    'blogvisa_faq_a8' => 'Al menos seis meses después de su fecha de entrada, con dos páginas en blanco. Esto se comprueba y se exige.',
    'blogvisa_faq_q9' => '¿Necesito un certificado de fiebre amarilla?',
    'blogvisa_faq_a9' => 'Solo si llega desde, o ha transitado más de 12 horas por, un país de riesgo de fiebre amarilla. Los vuelos directos desde Europa no lo requieren, pero una escala larga en Nairobi o Adís Abeba puede que sí.',
    'blogvisa_faq_q10' => '¿Cuánto tiempo puedo quedarme?',
    'blogvisa_faq_a10' => 'El visado turístico estándar es válido por 90 días. Las prórrogas son posibles a través de las oficinas de inmigración en Tanzania, pero son burocráticas, así que planifique bien sus fechas.',
    'blogvisa_faq_q11' => '¿Puedo trabajar o hacer voluntariado con un visado turístico?',
    'blogvisa_faq_a11' => 'No. El voluntariado requiere un permiso diferente incluso sin remuneración, y las normas se aplican. Si planea hacer trabajo voluntario, gestione el permiso correcto con bastante antelación.',
    'blogvisa_faq_q12' => '¿Qué pasa si mi visado es rechazado o se retrasa?',
    'blogvisa_faq_a12' => 'Los retrasos son más comunes que los rechazos. Si se acerca su fecha de viaje y no ha llegado una decisión, el visado a la llegada sigue disponible en los principales aeropuertos como alternativa. Traiga efectivo en dólares estadounidenses.',
    'blogvisa_faq_q13' => '¿Necesitan visado los niños?',
    'blogvisa_faq_a13' => 'Sí, todo viajero necesita su propio visado sin importar la edad, y cada niño necesita su propio pasaporte. A los niños que viajan con un solo progenitor se les puede pedir una carta de consentimiento del otro.',
    'blogvisa_faq_q14' => '¿Es válido el Visado de Turista de África Oriental para Tanzania?',
    'blogvisa_faq_a14' => 'No. El Visado de Turista de África Oriental cubre Kenia, Uganda y Ruanda pero no Tanzania. Si combina Tanzania con Kenia, necesita visados separados para cada uno.',

    'blogvisa_related_badge' => 'Sigue leyendo',
    'blogvisa_related_title' => 'Continúa explorando Tanzania',
    'blogvisa_related_contact' => 'Haznos una pregunta',

    'blogvisa_final_title' => '¿Necesita ayuda con el papeleo?',
    'blogvisa_final_intro' => 'Le proporcionamos la dirección de alojamiento que su solicitud de visado necesita, y podemos gestionar el seguro obligatorio de Zanzíbar con su reserva. Solo pregunte.',
    'blogvisa_final_whatsapp' => 'Escríbanos por WhatsApp',
    'blogvisa_final_contact' => 'Formulario de contacto',

    // Blog article: Where to stay on safari
    'blogstay_meta_title' => 'Dónde Alojarse en Safari en Tanzania: ¿Lodge, Campamento o Acampada? | Serengeti Budget Safari',
    'blogstay_meta_description' => 'El alojamiento de safari en Tanzania explicado: campings, lodges, campamentos de tiendas y campamentos móviles comparados con precios reales, además de si dormir dentro o fuera de los parques nacionales.',
    'blogstay_h1' => 'Dónde alojarse en safari',
    'blogstay_hero_sub' => 'Camping, lodge, campamento de tiendas o campamento móvil: qué cuesta realmente cada uno, cómo es cada uno en realidad, y si dormir dentro del parque o fuera de él.',
    'blogstay_updated' => 'Actualizado 2026',
    'blogstay_author' => 'Equipo de Serengeti Budget Safari',
    'blogstay_date' => 'Agosto de 2026',

    'blogstay_quick_badge' => 'Respuestas rápidas',
    'blogstay_quick_title' => 'El alojamiento en resumen',
    'blogstay_quick_intro' => 'Las decisiones que realmente importan.',
    'blogstay_qq1_q' => '¿Dentro o fuera?',
    'blogstay_qq1_a' => 'Dentro si tiene 2–3 noches. Combine en viajes más largos.',
    'blogstay_qq2_q' => '¿Qué es una tarifa de concesión?',
    'blogstay_qq2_a' => '$47–59 por adulto por noche para dormir dentro de un parque.',
    'blogstay_qq3_q' => '¿La opción más económica?',
    'blogstay_qq3_a' => 'Acampada: $35,40 de tarifa de parque más costos de camping.',
    'blogstay_qq4_q' => '¿Experiencia clásica?',
    'blogstay_qq4_a' => 'Un campamento de tiendas permanente. Lona, y cada sonido.',
    'blogstay_qq5_q' => '¿Siguiendo la migración?',
    'blogstay_qq5_a' => 'Un campamento móvil, se traslada con las manadas.',
    'blogstay_qq6_q' => '¿Con cuánta antelación reservar?',
    'blogstay_qq6_a' => '6–12 meses para Kogatende o Ndutu en temporada alta.',

    'blogstay_toc_title' => 'Contenido – Dónde alojarse en safari',
    'blogstay_toc_1' => 'Los cinco tipos',
    'blogstay_toc_2' => '¿Dentro o fuera?',
    'blogstay_toc_3' => 'Cómo es cada uno en realidad',
    'blogstay_toc_4' => 'Cómo elegir',
    'blogstay_toc_5' => 'Preguntas frecuentes',

    'blogstay_s1_badge' => 'Las opciones',
    'blogstay_s1_title' => 'Los cinco tipos de alojamiento de safari',
    'blogstay_s1_p1' => 'Dónde duerme es la variable individual más importante en lo que cuesta un safari, y, en un viaje corto, en cuánta fauna ve realmente. Los animales son los mismos independientemente de lo que elija; lo que cambia es la comodidad, y qué tan lejos está de la acción al amanecer.',
    'blogstay_t1_h1' => 'Tipo',
    'blogstay_t1_h2' => 'Por persona / noche',
    'blogstay_t1_h3' => 'Qué es',
    'blogstay_t1_h4' => 'Mejor para',
    'blogstay_t1_r1_a' => 'Camping público',
    'blogstay_t1_r1_b' => '$35,40 tarifa de parque<br>+ costos de camping',
    'blogstay_t1_r1_c' => 'Su propia tienda dentro del parque, baños compartidos de pozo, duchas frías, cocinero que prepara comidas en el lugar.',
    'blogstay_t1_r1_d' => 'Viajeros con presupuesto ajustado, grupos, los aventureros',
    'blogstay_t1_r2_a' => 'Lodge fuera del parque',
    'blogstay_t1_r2_c' => 'Habitaciones sólidas, agua caliente, restaurante, generalmente piscina. En Karatu o en el límite de un parque.',
    'blogstay_t1_r2_d' => 'Mantener los costos bajos',
    'blogstay_t1_r3_a' => 'Lodge dentro del parque',
    'blogstay_t1_r3_c' => 'Edificio permanente, electricidad, restaurante, a menudo una piscina con vista a un abrevadero.',
    'blogstay_t1_r3_d' => 'Comodidad más conveniencia',
    'blogstay_t1_r4_a' => 'Campamento de tiendas',
    'blogstay_t1_r4_c' => 'Lona permanente con camas de verdad y baños privados. Se oye todo por la noche.',
    'blogstay_t1_r4_d' => 'La experiencia clásica de safari',
    'blogstay_t1_r5_a' => 'Campamento móvil',
    'blogstay_t1_r5_c' => 'Se traslada dos o tres veces al año para seguir la migración. Pequeño, remoto, pocos otros vehículos cerca.',
    'blogstay_t1_r5_d' => 'Viajes centrados en la migración',

    'blogstay_s2_badge' => 'La decisión clave',
    'blogstay_s2_title' => '¿Dentro o fuera del parque?',
    'blogstay_s2_p1' => 'Esta es la decisión que confunde a la mayoría de los planificadores primerizos, e importa más que la categoría del lodge.',
    'blogstay_s2_sub1' => 'Dormir dentro',
    'blogstay_s2_p2' => 'Paga una <strong>tarifa de concesión</strong> además de la tarifa de la habitación: $59,00 por adulto por noche en el Serengeti y el Ngorongoro, $47,20 en Tarangire, Manyara, Arusha NP y Nyerere. A cambio, ya está en medio del ecosistema cuando la luz es mejor, al amanecer y al atardecer, que es precisamente cuando los depredadores están activos.',
    'blogstay_s2_sub2' => 'Dormir fuera',
    'blogstay_s2_p3' => 'Ahorra la tarifa de concesión y normalmente gran parte de la tarifa de la habitación. El costo es el tiempo: la puerta más cercana puede estar a 30 o 90 minutos, lo que implica salir antes del amanecer y regresar después del anochecer, y perder las dos mejores horas de cada día conduciendo.',
    'blogstay_t2_h1' => 'Dentro del parque',
    'blogstay_t2_h2' => 'Fuera del parque',
    'blogstay_t2_r1_a' => 'Costo',
    'blogstay_t2_r1_b' => 'Más alto: habitación + $47–59/noche de concesión',
    'blogstay_t2_r1_c' => 'Más bajo',
    'blogstay_t2_r2_a' => 'Safari matutino',
    'blogstay_t2_r2_b' => 'Comienza inmediatamente',
    'blogstay_t2_r2_c' => '30–90 min de trayecto antes',
    'blogstay_t2_r3_a' => 'Luz vespertina',
    'blogstay_t2_r3_b' => 'Aprovechamiento total',
    'blogstay_t2_r3_c' => 'Debe salir pronto para llegar a la puerta',
    'blogstay_t2_r4_a' => 'Sonidos por la noche',
    'blogstay_t2_r4_b' => 'Hiena, león, hipopótamo',
    'blogstay_t2_r4_c' => 'Generalmente tranquilo',
    'blogstay_t2_r5_a' => 'Instalaciones',
    'blogstay_t2_r5_b' => 'Varía; a menudo más sencillas',
    'blogstay_t2_r5_c' => 'A menudo mejor relación calidad-precio',
    'blogstay_tip_t' => 'Lo que solemos recomendar:',
    'blogstay_tip_d' => 'en un viaje de tres noches o menos, quédese dentro del parque aunque implique una habitación más sencilla. Las horas extra al amanecer valen más que la comodidad extra. En una semana o más, combine: un par de noches dentro en el momento clave, noches más baratas fuera para el resto.',

    'blogstay_s3_badge' => 'La realidad',
    'blogstay_s3_title' => 'Cómo es realmente cada tipo',
    'blogstay_s3_sub1' => 'Camping',
    'blogstay_s3_p1' => 'Una tienda de campaña para dos personas en un camping público, un bloque de aseo compartido con agua fría, y un cocinero que prepara comida genuinamente buena en una fogata. Oirá hienas por la noche, y ocasionalmente leones. Los búfalos atraviesan algunos campings. Se le da una linterna y se le indica que no salga de la tienda después del anochecer, y esa instrucción no es decorativa.',
    'blogstay_s3_p2' => 'Es básico, no es para todos, y las personas que lo eligen suelen describirlo como la mejor parte del viaje.',
    'blogstay_s3_sub2' => 'Campamento de tiendas',
    'blogstay_s3_p3' => 'La palabra "tienda" es engañosa. Son estructuras de lona permanentes sobre plataformas, con camas de verdad, baños privados y agua caliente traída al amanecer. Lo que las hace especiales es la lona: se oye todo, y por la noche un askari lo acompaña hasta su tienda porque los animales se mueven por el campamento.',
    'blogstay_s3_sub3' => 'Lodge',
    'blogstay_s3_p4' => 'Un hotel dentro de un parque nacional. Paredes sólidas, electricidad, un restaurante, generalmente una piscina. Cómodo y fiable, y considerablemente menos evocador que la lona. Los mejores están construidos en escarpes o sobre abrevaderos y la vista hace el trabajo.',
    'blogstay_s3_sub4' => 'Campamento móvil',
    'blogstay_s3_p5' => 'Pequeño, generalmente de seis a doce tiendas, trasladado estacionalmente para seguir a las manadas. Energía solar, duchas de cubo, sin piscina, sin Wi-Fi. Remoto y tranquilo, y si la migración es la razón por la que vino, esto lo pone lo más cerca posible de ella.',

    'blogstay_s4_badge' => 'Elegir',
    'blogstay_s4_title' => 'Cómo elegir para su viaje',
    'blogstay_t3_h1' => 'Si usted…',
    'blogstay_t3_h2' => 'Elija',
    'blogstay_t3_h3' => 'Por qué',
    'blogstay_t3_r1_a' => 'Tiene solo 2–3 noches',
    'blogstay_t3_r1_b' => 'Dentro del parque',
    'blogstay_t3_r1_c' => 'El amanecer y el atardecer valen más que la comodidad',
    'blogstay_t3_r2_a' => 'Tiene una semana o más',
    'blogstay_t3_r2_b' => 'Combine dentro y fuera',
    'blogstay_t3_r2_c' => 'Ahorre en las noches normales, gaste en las clave',
    'blogstay_t3_r3_a' => 'Tiene un presupuesto ajustado',
    'blogstay_t3_r3_b' => 'Camping o lodges fuera',
    'blogstay_t3_r3_c' => 'Mismo guía, mismos animales, costo mucho menor',
    'blogstay_t3_r4_a' => 'Está siguiendo la migración',
    'blogstay_t3_r4_b' => 'Campamento móvil',
    'blogstay_t3_r4_c' => 'Se mueve con las manadas',
    'blogstay_t3_r5_a' => 'Viaja con niños',
    'blogstay_t3_r5_b' => 'Lodge con piscina',
    'blogstay_t3_r5_c' => 'Un lugar para gastar energía en las horas de calor',
    'blogstay_t3_r6_a' => 'Quiere la experiencia clásica',
    'blogstay_t3_r6_b' => 'Campamento de tiendas',
    'blogstay_t3_r6_c' => 'Lona, sonidos por la noche, un askari acompañándolo de vuelta',
    'blogstay_t3_r7_a' => 'Está de luna de miel',
    'blogstay_t3_r7_b' => 'Campamento pequeño de tiendas',
    'blogstay_t3_r7_c' => 'Privado, tranquilo, y mucho mejor que un lodge grande',

    'blogstay_s4_sub1' => 'Preguntas que vale la pena hacer antes de reservar',
    'blogstay_ask1' => '¿Está incluida la tarifa de concesión en el precio cotizado, o se añade aparte?',
    'blogstay_ask2' => '¿A qué distancia está de la puerta, y cuánto dura el trayecto hasta la zona principal de fauna?',
    'blogstay_ask3' => '¿Hay electricidad toda la noche, o solo horas de generador?',
    'blogstay_ask4' => '¿Están incluidas las bebidas, y cuáles?',
    'blogstay_ask5' => '¿Hay una edad mínima para los niños?',
    'blogstay_ask6' => '¿Hay Wi-Fi disponible, y dónde?',

    'blogstay_faq_badge' => 'Preguntas frecuentes',
    'blogstay_faq_title' => 'Alojamiento de safari: preguntas frecuentes',
    'blogstay_faq_q1' => '¿Debo alojarme dentro o fuera del parque nacional?',
    'blogstay_faq_a1' => 'En un viaje de tres noches o menos, dentro. Ya está en el ecosistema al amanecer y al atardecer cuando los depredadores están activos. En un viaje más largo, combine: noches más baratas fuera, noches clave dentro. Dormir dentro añade una tarifa de concesión de $47–59 por adulto por noche.',
    'blogstay_faq_q2' => '¿Qué es una tarifa de concesión?',
    'blogstay_faq_a2' => 'Un cargo por persona y por noche que cobra la autoridad del parque cuando duerme en un lodge o campamento dentro de un parque nacional. Es de $59,00 por adulto en el Serengeti y el Ngorongoro y $47,20 en Tarangire, Manyara, Arusha NP y Nyerere, además de la tarifa de la habitación.',
    'blogstay_faq_q3' => '¿Es seguro acampar en safari?',
    'blogstay_faq_a3' => 'Sí, en campings públicos designados, con las precauciones normales: quédese en la tienda después del anochecer, mantenga la comida sellada y lejos de la tienda, y siga las instrucciones de su guía. Los animales sí atraviesan los campings, precisamente por eso existen esas normas.',
    'blogstay_faq_q4' => '¿Cuál es la diferencia entre un lodge y un campamento de tiendas?',
    'blogstay_faq_a4' => 'Un lodge es un edificio permanente con paredes sólidas y electricidad. Un campamento de tiendas es lona permanente sobre una plataforma con camas de verdad y baños privados. La lona es lo importante. Se oye todo por la noche, lo que la mayoría de la gente considera el recuerdo que perdura.',
    'blogstay_faq_q5' => '¿Qué es un campamento móvil?',
    'blogstay_faq_a5' => 'Un campamento pequeño, generalmente de seis a doce tiendas, que se traslada físicamente dos o tres veces al año para seguir la migración. Energía solar, duchas de cubo, sin piscina. Si la migración es la razón de su viaje, esto lo pone lo más cerca posible de ella.',
    'blogstay_faq_q6' => '¿Cuánto cuesta el alojamiento de safari por noche?',
    'blogstay_faq_a6' => 'Los campings públicos cuestan $35,40 en tarifas de parque más costos de camping; los lodges fuera de los parques $60–150; los lodges dentro $150–400; los campamentos de tiendas $200–600; los campamentos móviles $300–700. El ultra lujo va desde $700 en adelante.',
    'blogstay_faq_q7' => '¿Necesito reservar alojamiento con antelación?',
    'blogstay_faq_a7' => 'Sí, particularmente para junio a octubre y para Ndutu en febrero. Los campamentos en el norte del Serengeti y Ndutu se agotan de seis a doce meses antes porque el número de camas en esas zonas es limitado.',
    'blogstay_faq_q8' => '¿Hay electricidad y Wi-Fi?',
    'blogstay_faq_a8' => 'Los lodges normalmente tienen ambos. Los campamentos de tiendas a menudo usan generadores durante horas fijas y proporcionan iluminación solar el resto del tiempo. Los campamentos móviles suelen tener energía solar y nada de Wi-Fi. Pregunte antes de reservar si le importa.',
    'blogstay_faq_q9' => '¿Están incluidas las comidas?',
    'blogstay_faq_a9' => 'Casi siempre en safari: la pensión completa es estándar, y se proporcionan almuerzos para llevar en los safaris de día completo. Las bebidas que no sean agua y té generalmente se cobran aparte, excepto en la gama de lujo, donde suelen estar incluidas.',
    'blogstay_faq_q10' => '¿Puedo alojarme en un lodge con niños?',
    'blogstay_faq_a10' => 'La mayoría de los lodges aceptan niños de cualquier edad. Algunos campamentos de tiendas establecen un mínimo de seis o doce años, debido a los desplazamientos a pie entre tiendas por la noche. Díganos las edades al consultar y filtraremos en consecuencia.',
    'blogstay_faq_q11' => '¿Qué ocurre por la noche en un campamento de tiendas?',
    'blogstay_faq_a11' => 'Un askari, un guardia nocturno, lo acompaña entre la zona del comedor y su tienda, porque los animales se mueven por el campamento después del anochecer. Oirá hipopótamo, hiena y a menudo león. La tienda se cierra con cremallera y es totalmente segura.',
    'blogstay_faq_q12' => '¿Vale la pena pagar por una piscina?',
    'blogstay_faq_a12' => 'Con niños, realmente sí. Las horas de calor entre safaris son largas y una piscina las resuelve. Sin niños importa mucho menos, y el dinero suele estar mejor invertido en la ubicación.',
    'blogstay_faq_q13' => '¿Cuál es la mejor opción de relación calidad-precio?',
    'blogstay_faq_a13' => 'Un lodge justo fuera del límite de un parque, a $60–150 por persona. Evita la tarifa de concesión y obtiene mejores instalaciones por el dinero, a costa de 30 a 90 minutos de trayecto cada mañana y tarde.',

    'blogstay_related_badge' => 'Sigue leyendo',
    'blogstay_related_title' => 'Continúa explorando Tanzania',
    'blogstay_final_title' => '¿No está seguro de cuál elegir?',
    'blogstay_final_intro' => 'Díganos su presupuesto y cuántas noches tiene. Le sugeriremos una combinación de noches dentro y fuera que le dé la mayor cantidad de fauna por su dinero.',
    'blogstay_final_whatsapp' => 'Escríbanos por WhatsApp',
    'blogstay_final_contact' => 'Formulario de contacto',

    // Blog: The Big Five in Tanzania
    'blogbig5_meta_title' => 'Los Big Five en Tanzania: Dónde y Cuándo Verlos | Serengeti Budget Safari',
    'blogbig5_meta_description' => 'Dónde ver león, leopardo, elefante, búfalo y rinoceronte negro en Tanzania, con probabilidades honestas de avistamiento para cada uno, los itinerarios que dan la mejor oportunidad, y por qué el rinoceronte es el difícil.',
    'blogbig5_h1' => 'Los Big Five en Tanzania',
    'blogbig5_hero_sub' => 'Dónde vive cada uno, cuáles son sus probabilidades realistas, y cómo planificar un itinerario que le dé una oportunidad genuina de ver los cinco.',
    'blogbig5_updated' => 'Actualizado 2026',
    'blogbig5_quick_badge' => 'Respuestas rápidas',
    'blogbig5_quick_title' => 'Los Big Five en resumen',
    'blogbig5_quick_intro' => 'Probabilidades honestas, antes del detalle.',
    'blogbig5_qq1_q' => '¿Cuáles son fáciles?',
    'blogbig5_qq1_a' => 'León, elefante y búfalo: casi seguros.',
    'blogbig5_qq2_q' => '¿Leopardo?',
    'blogbig5_qq2_a' => '55–60% en el valle de Seronera durante tres días.',
    'blogbig5_qq3_q' => '¿Rinoceronte negro?',
    'blogbig5_qq3_a' => '~60% en un día completo en el cráter del Ngorongoro. En ningún otro lugar.',
    'blogbig5_qq4_q' => '¿Cuántos días?',
    'blogbig5_qq4_a' => 'De cuatro a cinco para una oportunidad realista de ver los cinco.',
    'blogbig5_qq5_q' => '¿Qué debo traer?',
    'blogbig5_qq5_a' => 'Los binoculares importan más que un teleobjetivo para el rinoceronte.',
    'blogbig5_qq6_q' => '¿Garantizado?',
    'blogbig5_qq6_a' => 'Nunca. Cualquiera que prometa los cinco está exagerando.',
    'blogbig5_toc_title' => 'Contenido – Los Big Five en Tanzania',
    'blogbig5_toc_1' => 'Qué son',
    'blogbig5_toc_2' => 'Dónde ver cada uno',
    'blogbig5_toc_3' => 'Mejores itinerarios',
    'blogbig5_toc_4' => 'Más allá de los Big Five',
    'blogbig5_toc_5' => 'Preguntas frecuentes',
    'blogbig5_s1_badge' => 'Lo básico',
    'blogbig5_s1_title' => 'Qué son los Big Five, y por qué',
    'blogbig5_s1_p1' => 'León, leopardo, elefante, búfalo y rinoceronte negro. El término no tiene nada que ver con el tamaño. El hipopótamo y la jirafa son ambos más grandes que un leopardo. Proviene de la caza mayor de la era colonial, y se refería a los <strong>cinco animales considerados más peligrosos de cazar a pie</strong>.',
    'blogbig5_s1_p2' => 'El nombre ha sobrevivido a su origen y ahora es la lista de referencia estándar de un safari, lo cual es ligeramente absurdo pero genuinamente útil: entre los cinco cubren la mayoría de los hábitats y comportamientos que vale la pena viajar para ver.',
    'blogbig5_s1_p3' => 'La postura honesta sobre completar el conjunto: cuatro de los cinco son sencillos en un safari bien planificado del circuito norte. El <strong>rinoceronte negro es la dificultad</strong>, y todo lo que sigue trata realmente de cómo resolver ese único caso.',
    'blogbig5_fact_lion_label' => 'León',
    'blogbig5_fact_lion_value' => 'Fácil, Serengeti, Ngorongoro',
    'blogbig5_fact_elephant_label' => 'Elefante',
    'blogbig5_fact_elephant_value' => 'Fácil, Tarangire, Ruaha',
    'blogbig5_fact_buffalo_label' => 'Búfalo',
    'blogbig5_fact_buffalo_value' => 'Fácil, en todas partes',
    'blogbig5_fact_leopard_label' => 'Leopardo',
    'blogbig5_fact_leopard_value' => 'Moderado, Serengeti',
    'blogbig5_fact_rhino_label' => 'Rinoceronte negro',
    'blogbig5_fact_rhino_value' => 'Difícil, solo Ngorongoro',
    'blogbig5_fact_days_label' => 'Días para los cinco',
    'blogbig5_fact_days_value' => '4–5 de forma realista',
    'blogbig5_s2_badge' => 'Los cinco',
    'blogbig5_s2_title' => 'Dónde ver a cada uno',
    'blogbig5_s2_lion_h' => 'León',
    'blogbig5_s2_lion_p' => 'El más fácil. El <strong>Serengeti</strong> alberga alrededor de 3.000 y tiene una de las densidades más altas de África; el <strong>cráter del Ngorongoro</strong> tiene aproximadamente 60 en 260 km², por lo que son casi inevitables. <strong>Ruaha</strong>, en el sur, tiene manadas de veinte o más que cazan búfalos e incluso elefantes jóvenes.',
    'blogbig5_s2_lion_odds' => 'Mejores probabilidades: 90–95% en un safari de tres días por el circuito norte.',
    'blogbig5_s2_elephant_h' => 'Elefante',
    'blogbig5_s2_elephant_p' => '<strong>Tarangire</strong> en la temporada seca es lo mejor del circuito norte: de 2.500 a 3.000 animales residentes, con manadas de cincuenta o más a lo largo del río. <strong>Ruaha</strong> tiene alrededor de 12.000, la mayor población de África Oriental.',
    'blogbig5_s2_elephant_odds' => 'Mejores probabilidades: más del 95% en Tarangire de julio a octubre.',
    'blogbig5_s2_buffalo_h' => 'Búfalo',
    'blogbig5_s2_buffalo_p' => 'Común en todas partes, generalmente en grandes manadas. El cráter del Ngorongoro y el Serengeti albergan ambos miles. Los viejos toros solitarios, conocidos como dagga boys, son los que hay que tratar con respeto.',
    'blogbig5_s2_buffalo_odds' => 'Mejores probabilidades: más del 90% en cualquier lugar.',
    'blogbig5_s2_leopard_h' => 'Leopardo',
    'blogbig5_s2_leopard_p' => 'El esquivo, pero lejos de ser imposible. El <strong>valle de Seronera</strong>, en el centro del Serengeti, es el mejor lugar de Tanzania: los leopardos descansan en las acacias junto al río durante las horas de calor. <strong>Ndutu</strong> también es excelente.',
    'blogbig5_s2_leopard_odds' => 'Mejores probabilidades: 55–60% en tres días en el centro del Serengeti.',
    'blogbig5_s2_rhino_h' => 'Rinoceronte negro',
    'blogbig5_s2_rhino_p1' => 'El difícil. La población de Tanzania es pequeña y dispersa, y hay un solo lugar donde tiene una oportunidad genuina: el <strong>cráter del Ngorongoro</strong>, donde viven unos 30 bajo protección armada las 24 horas. Un puñado sobrevive cerca de los Moru Kopjes en el Serengeti, pero los avistamientos allí son raros.',
    'blogbig5_s2_rhino_p2' => 'Espere verlos a distancia sobre pasto abierto en lugar de cerca del vehículo. Unos buenos binoculares importan más aquí que un teleobjetivo, y la mañana temprano es cuando es más probable que estén al descubierto.',
    'blogbig5_s2_rhino_odds' => 'Mejores probabilidades: alrededor del 60% en un día completo en el cráter.',
    'blogbig5_s3_badge' => 'Planificación',
    'blogbig5_s3_title' => 'Itinerarios que le dan la mejor oportunidad',
    'blogbig5_t1_h1' => 'Viaje',
    'blogbig5_t1_h2' => 'Parques',
    'blogbig5_t1_h3' => 'Resultado realista',
    'blogbig5_t1_r1_a' => '2 días',
    'blogbig5_t1_r1_b' => 'Tarangire + Ngorongoro',
    'blogbig5_t1_r1_c' => 'León, elefante, búfalo casi seguros; rinoceronte probable; leopardo improbable. <strong>3–4 de 5.</strong>',
    'blogbig5_t1_r2_a' => '4 días',
    'blogbig5_t1_r2_b' => 'Tarangire, Serengeti, Ngorongoro',
    'blogbig5_t1_r2_c' => 'Las cuatro especies fáciles, más una oportunidad real de leopardo y rinoceronte. <strong>4–5 de 5.</strong>',
    'blogbig5_t1_r3_a' => '6 días',
    'blogbig5_t1_r3_b' => 'Circuito norte completo',
    'blogbig5_t1_r3_c' => 'Tiempo para trabajar el valle de Seronera en busca del leopardo y un día completo en el cráter para el rinoceronte. <strong>La mejor oportunidad de ver los cinco.</strong>',
    'blogbig5_s3_warn_t' => 'Nadie puede garantizar los Big Five.',
    'blogbig5_s3_warn_d' => 'Son animales salvajes en zonas enormes. Lo que un buen operador puede hacer es ponerlo en los lugares correctos a las horas correctas del día y ser honesto sobre las probabilidades, que es lo que son las cifras anteriores.',
    'blogbig5_s4_badge' => 'Más allá de los cinco',
    'blogbig5_s4_title' => 'Los animales que valen más que la lista',
    'blogbig5_s4_intro' => 'Pregúntele a un guía qué preferiría mostrarle, y los Big Five rara vez encabezan la lista.',
    'blogbig5_s4_i1_t' => 'Guepardo',
    'blogbig5_s4_i1_d' => 'el animal terrestre más rápido, cazando en las llanuras abiertas del sur. Una cacería de guepardo es un mejor espectáculo que la mayoría de los avistamientos de leones.',
    'blogbig5_s4_i2_t' => 'Licaón africano',
    'blogbig5_s4_i2_d' => 'quedan menos de 7.000 en todo el mundo. Nyerere y Ruaha son dos de los últimos bastiones, y una manada cazando es extraordinario.',
    'blogbig5_s4_i3_t' => 'La Gran Migración',
    'blogbig5_s4_i3_d' => '1,3 millones de ñus. Ningún animal individual compite con eso.',
    'blogbig5_s4_i4_t' => 'Jirafa',
    'blogbig5_s4_i4_d' => 'el animal nacional de Tanzania, y de alguna manera siempre más impresionante en persona de lo esperado.',
    'blogbig5_s4_i5_t' => 'Hipopótamo',
    'blogbig5_s4_i5_d' => 'estadísticamente el animal grande más peligroso de África, y mucho más entretenido de lo que sugiere la lista de los Big Five.',
    'blogbig5_s4_i6_t' => 'Serval, caracal, tejón de la miel, cerdo hormiguero: los avistamientos por los que los guías se emocionan genuinamente.',
    'blogbig5_s4_outro' => 'Nuestro consejo: use los Big Five para dar forma al itinerario, y luego olvide la lista una vez que esté allí. Las mejores mañanas de safari casi nunca son las que se pasan marcando casillas.',
    'blogbig5_tag_lion' => 'León',
    'blogbig5_tag_leopard' => 'Leopardo',
    'blogbig5_tag_elephant' => 'Elefante',
    'blogbig5_tag_buffalo' => 'Búfalo',
    'blogbig5_tag_rhino' => 'Rinoceronte negro',
    'blogbig5_tag_cheetah' => 'Guepardo',
    'blogbig5_tag_wilddog' => 'Licaón',
    'blogbig5_tag_giraffe' => 'Jirafa',
    'blogbig5_tag_hippo' => 'Hipopótamo',
    'blogbig5_faq_title' => 'Los Big Five: preguntas frecuentes',
    'blogbig5_faq_q1' => '¿Qué son los Big Five?',
    'blogbig5_faq_a1' => 'León, leopardo, elefante, búfalo y rinoceronte negro. El término proviene de la caza mayor colonial y se refería a los cinco animales considerados más peligrosos de cazar a pie, no a los más grandes.',
    'blogbig5_faq_q2' => '¿Puedo ver los Big Five en Tanzania?',
    'blogbig5_faq_a2' => 'Sí, y un safari de cuatro a cinco días por el circuito norte da una oportunidad realista de ver los cinco. León, elefante y búfalo son casi seguros, el leopardo tiene alrededor de un 55–60% en el Serengeti, y el rinoceronte alrededor del 60% en un día completo en el cráter del Ngorongoro.',
    'blogbig5_faq_q3' => '¿Cuál es el mejor lugar para ver rinoceronte negro?',
    'blogbig5_faq_a3' => 'El cráter del Ngorongoro, donde viven unos 30 bajo protección armada las 24 horas. Es la única opción realista en Tanzania. Espere avistamientos a distancia sobre pasto abierto. Traiga binoculares.',
    'blogbig5_faq_q4' => '¿Cuál es el mejor lugar para ver leopardo?',
    'blogbig5_faq_a4' => 'El valle de Seronera, en el centro del Serengeti. Los leopardos descansan en las acacias junto al río durante las horas de calor, lo que los hace localizables si se sabe dónde buscar. Ndutu también es excelente.',
    'blogbig5_faq_q5' => '¿Qué parque tiene más elefantes?',
    'blogbig5_faq_a5' => 'Ruaha con alrededor de 12.000, la mayor población de África Oriental. En el circuito norte, Tarangire es el mejor: de 2.500 a 3.000 animales residentes y manadas de cincuenta o más en temporada seca.',
    'blogbig5_faq_q6' => '¿Cuántos días necesito para ver los Big Five?',
    'blogbig5_faq_a6' => 'De cuatro a cinco de forma realista. Dos días cubren tres o cuatro de ellos. Seis días dan la mejor oportunidad, porque hay tiempo para trabajar el valle de Seronera en busca del leopardo y un día completo en el cráter para el rinoceronte.',
    'blogbig5_faq_q7' => '¿Puedo ver los Big Five solo en el Serengeti?',
    'blogbig5_faq_a7' => 'Cuatro de ellos, fácilmente. El rinoceronte negro es la excepción: un puñado sobrevive cerca de los Moru Kopjes pero los avistamientos son raros. Para completar el conjunto, añada el cráter del Ngorongoro.',
    'blogbig5_faq_q8' => '¿Están garantizados los Big Five?',
    'blogbig5_faq_a8' => 'No, y desconfíe de quien diga lo contrario. Son animales salvajes en zonas de miles de kilómetros cuadrados. Un buen operador mejora sus probabilidades estando en el lugar correcto en el momento correcto, y es honesto sobre cuáles son esas probabilidades.',
    'blogbig5_faq_q9' => '¿Por qué es tan raro el rinoceronte negro?',
    'blogbig5_faq_a9' => 'La caza furtiva. La población de rinoceronte negro de Tanzania cayó de miles en la década de 1970 a unas pocas decenas en la de 1990. Los números se están recuperando lentamente bajo protección intensiva, pero siguen en peligro crítico.',
    'blogbig5_faq_q10' => '¿Cuál es la diferencia entre el rinoceronte negro y el blanco?',
    'blogbig5_faq_a10' => 'Principalmente la forma de la boca. El rinoceronte negro tiene un labio ganchudo para ramonear arbustos; el blanco tiene un labio ancho y plano para pastar. Tanzania tiene rinoceronte negro; el blanco se encuentra principalmente en el sur de África.',
    'blogbig5_faq_q11' => '¿Qué es mejor que los Big Five?',
    'blogbig5_faq_a11' => 'Pregúntele a un guía y la mayoría dirá una cacería de guepardo, una manada de licaones, o la migración misma. Los Big Five son un marco de planificación útil y una mala descripción de lo que hace memorable a un safari.',
    'blogbig5_faq_q12' => '¿Dónde puedo ver guepardo?',
    'blogbig5_faq_a12' => 'Las llanuras abiertas del sur del Serengeti, particularmente alrededor de Ndutu durante la temporada de nacimientos. Los guepardos necesitan terreno abierto para correr y evitan las zonas con alta densidad de leones, ya que los leones los matan.',
    'blogbig5_faq_q13' => '¿Son realmente peligrosos los búfalos?',
    'blogbig5_faq_a13' => 'Sí. Los viejos toros solitarios, dagga boys, son responsables de más ataques a personas que la mayoría de los otros animales africanos. Desde un vehículo está totalmente seguro; a pie, son la razón por la que los safaris a pie llevan un ranger armado.',
    'blogbig5_faq_q14' => '¿Necesito un teleobjetivo para los Big Five?',
    'blogbig5_faq_a14' => 'Un objetivo de 300 mm o más largo ayuda considerablemente, particularmente para el rinoceronte y el leopardo. Pero los binoculares importan más de lo que la mayoría espera. Muchos avistamientos, especialmente de rinoceronte en el cráter, están demasiado lejos para cualquier objetivo realista.',
    'blogbig5_related_title' => 'Continúa explorando Tanzania',
    'blogbig5_related_ngorongoro' => 'Ngorongoro, para el rinoceronte',
    'blogbig5_final_title' => 'Planifique un itinerario Big Five',
    'blogbig5_final_intro' => 'Díganos cuántos días tiene y construiremos la ruta que le dé la mejor oportunidad genuina, y le diremos con claridad si su horario hace improbable ver los cinco.',

    // ===== Blog article: What to Pack for a Safari =====
    'blogpack_meta_title' => 'Qué Empacar para un Safari en Tanzania (Lista 2026) | Serengeti Budget Safari',
    'blogpack_meta_description' => 'Una lista práctica de equipaje de safari: ropa, botiquín médico, equipo fotográfico, documentos y dinero, además de qué dejar en casa, incluyendo artículos que son realmente ilegales en Tanzania.',
    'blogpack_h1' => 'Qué empacar para un safari',
    'blogpack_hero_sub' => 'Capas, colores neutros y 15 kg en una bolsa blanda, además de los artículos que los viajeros más olvidan, y los que son realmente ilegales en Tanzania.',
    'blogpack_updated' => 'Actualizado 2026',
    'blogpack_author' => 'Equipo de Serengeti Budget Safari',
    'blogpack_date' => 'Agosto de 2026',
    'blogpack_quick_badge' => 'Respuestas rápidas',
    'blogpack_quick_title' => 'El equipaje en resumen',
    'blogpack_quick_intro' => 'Lo esencial, antes de la lista completa.',
    'blogpack_qq1_q' => '¿La única regla?',
    'blogpack_qq1_a' => 'Capas. 14 °C al amanecer, 28 °C al mediodía.',
    'blogpack_qq2_q' => '¿Límite de equipaje?',
    'blogpack_qq2_a' => 'Bolsa blanda de 15 kg en vuelos internos. Se aplica estrictamente.',
    'blogpack_qq3_q' => '¿Qué colores?',
    'blogpack_qq3_a' => 'Caqui y verde oliva. Evite el azul y el negro: moscas tsetsé.',
    'blogpack_qq4_q' => '¿Artículo más olvidado?',
    'blogpack_qq4_a' => 'Binoculares. Más útiles que un teleobjetivo.',
    'blogpack_qq5_q' => '¿Qué está prohibido?',
    'blogpack_qq5_a' => 'Ropa de camuflaje y bolsas de plástico de un solo uso.',
    'blogpack_qq6_q' => '¿Cuánta ropa?',
    'blogpack_qq6_a' => 'Para cuatro días. Hay servicio de lavandería en casi todas partes.',
    'blogpack_see_faq' => 'Ver todas las preguntas frecuentes',
    'blogpack_toc_title' => 'Contenido – Qué empacar para un safari',
    'blogpack_toc_1' => 'La única regla',
    'blogpack_toc_2' => 'Ropa',
    'blogpack_toc_3' => 'Botiquín médico',
    'blogpack_toc_4' => 'Equipo fotográfico',
    'blogpack_toc_5' => 'Documentos y dinero',
    'blogpack_toc_6' => 'Qué dejar en casa',
    'blogpack_toc_7' => 'Preguntas frecuentes',
    'blogpack_s1_badge' => 'El principio',
    'blogpack_s1_title' => 'La única regla que importa',
    'blogpack_s1_p1' => '<strong>Vístase en capas.</strong> Un día de safari comienza a unos 14 °C (5 °C en el borde del Ngorongoro) y alcanza los 28 °C al mediodía, y experimentará ambos desde un vehículo abierto. Un solo abrigo de invierno es la respuesta equivocada; una capa base, un forro polar y una capa exterior cortavientos es la correcta.',
    'blogpack_s1_p2' => 'La segunda regla, si tiene vuelos internos: <strong>15 kg en una bolsa blanda</strong>. Las avionetas en Tanzania aplican esto estrictamente, y las maletas rígidas se rechazan porque no caben en la bodega. La mayoría de los lodges ofrecen lavandería en el mismo día, así que empacar para cuatro días en lugar de diez es casi siempre la decisión correcta.',
    'blogpack_s2_badge' => 'Ropa',
    'blogpack_s2_title' => 'Ropa',
    'blogpack_s2_i1_t' => 'Forro polar o chaqueta aislante',
    'blogpack_s2_i1_d' => 'esencial, y el artículo que más se olvida',
    'blogpack_s2_i2_t' => 'Capa exterior cortavientos',
    'blogpack_s2_i2_d' => 'la sensación térmica en un vehículo abierto al amanecer es considerable',
    'blogpack_s2_i3_t' => 'Camisas de manga larga',
    'blogpack_s2_i3_d' => 'protección contra el sol y los mosquitos',
    'blogpack_s2_i4' => 'Camisetas de tejido transpirable',
    'blogpack_s2_i5' => 'Pantalones largos ligeros, más útiles que los shorts',
    'blogpack_s2_i6' => 'Sombrero de ala ancha y gafas de sol',
    'blogpack_s2_i7_t' => 'Zapatos cerrados cómodos',
    'blogpack_s2_i7_d' => 'botas solo si va a hacer trekking',
    'blogpack_s2_i8_t' => 'Un buff o bufanda',
    'blogpack_s2_i8_d' => 'el polvo de la temporada seca es implacable',
    'blogpack_s2_i9' => 'Ropa de baño, muchos lodges tienen piscina',
    'blogpack_s2_i10' => 'Algo informal-elegante para la cena en los mejores lodges',
    'blogpack_s2_sub1' => 'Los colores importan más de lo que cree',
    'blogpack_s2_p1' => 'Use <strong>caqui, verde oliva, beige y marrón</strong>. Hay tres cosas específicas que evitar:',
    'blogpack_s2_n1_t' => 'Azul y negro',
    'blogpack_s2_n1_d' => 'atraen a las moscas tsetsé, presentes en Tarangire y el bosque de miombo de los parques del sur. Su picadura es dolorosa.',
    'blogpack_s2_n2_t' => 'Blanco',
    'blogpack_s2_n2_d' => 'deja de ser blanco después de medio día en una pista polvorienta.',
    'blogpack_s2_n3_t' => 'El camuflaje es ilegal para civiles en Tanzania.',
    'blogpack_s2_n3_d' => 'Está reservado para el ejército, y usarlo puede causar problemas genuinos.',
    'blogpack_s3_badge' => 'Salud',
    'blogpack_s3_title' => 'Botiquín médico y artículos de aseo',
    'blogpack_s3_i1_t' => 'Pastillas antipalúdicas',
    'blogpack_s3_i1_d' => 'recetadas por su médico',
    'blogpack_s3_i2_t' => 'Repelente de insectos con DEET',
    'blogpack_s3_i2_d' => 'la concentración más fuerte que tolere',
    'blogpack_s3_i3_t' => 'Protector solar de alto factor',
    'blogpack_s3_i3_d' => 'y bálsamo labial con SPF; la radiación UV en altitud es intensa',
    'blogpack_s3_i4' => 'Analgésicos, antidiarreicos y sales de rehidratación',
    'blogpack_s3_i5' => 'Tiritas, antiséptico, tratamiento de ampollas',
    'blogpack_s3_i6' => 'Cualquier medicamento con receta <strong>en su equipaje de mano</strong>, con una copia de la receta',
    'blogpack_s3_i7' => 'Gel desinfectante y toallitas húmedas, genuinamente útiles en trayectos largos',
    'blogpack_s3_i8' => 'Pastillas para el mareo si es propenso; las pistas son irregulares',
    'blogpack_s3_link' => 'Guía completa de vacunas y salud',
    'blogpack_s4_badge' => 'Fotografía',
    'blogpack_s4_title' => 'Fotografía y óptica',
    'blogpack_tag_binoculars' => 'Binoculares',
    'blogpack_tag_lens' => 'Objetivo de 300 mm o más',
    'blogpack_tag_wide' => 'Objetivo gran angular',
    'blogpack_tag_battery' => 'Baterías de repuesto',
    'blogpack_tag_memory' => 'Tarjetas de memoria',
    'blogpack_tag_dustbag' => 'Bolsa antipolvo',
    'blogpack_tag_beanbag' => 'Bolsa de arena',
    'blogpack_s4_p1' => 'Los <strong>binoculares</strong> son el artículo individual que menos se empaca. Muchos avistamientos, particularmente el rinoceronte en el cráter, están simplemente demasiado lejos para una cámara. Traiga <strong>un objetivo de 300 mm o más</strong> si le interesa en serio la fotografía de fauna, pero <strong>también uno gran angular</strong>: baobabs, el cráter, las llanuras al amanecer. Solo se arrepentirá de traer únicamente un teleobjetivo. Los campamentos a menudo usan generadores solo durante horas limitadas, así que traiga baterías de repuesto y más tarjetas de memoria de las que cree necesitar. Una bolsa antipolvo importa: el polvo de la temporada seca se mete en todo, y cambiar objetivos en un vehículo en movimiento es cómo se arruinan los sensores. Una bolsa de arena o sustituto es útil para estabilizar objetivos largos en la escotilla del techo.',
    'blogpack_s5_badge' => 'Documentos',
    'blogpack_s5_title' => 'Documentos y dinero',
    'blogpack_s5_i1_t' => 'Pasaporte',
    'blogpack_s5_i1_d' => 'válido al menos seis meses después de la entrada, con dos páginas en blanco',
    'blogpack_s5_i2_t' => 'Confirmación de visado impresa',
    'blogpack_s5_i2_d' => 'y póliza de seguro de viaje',
    'blogpack_s5_i3_t' => 'Certificado de fiebre amarilla',
    'blogpack_s5_i3_d' => 'si llega desde o transita por un país de riesgo',
    'blogpack_s5_i4' => '<strong>Dólares estadounidenses en efectivo</strong> para propinas y extras, y esto importa: <strong>los billetes deben ser posteriores a 2009</strong>. Los billetes más antiguos se rechazan en toda Tanzania.',
    'blogpack_s5_i5' => 'Denominaciones pequeñas para propinas ($1, $5, $10)',
    'blogpack_s5_i6' => 'Una tarjeta de crédito como respaldo, aunque la conectividad no es fiable',
    'blogpack_s5_i7_t' => 'Adaptador de enchufe tipo G',
    'blogpack_s5_i7_d' => 'el estándar británico de tres clavijas',
    'blogpack_s5_i8' => 'Copias digitales de todo, guardadas en algún lugar accesible sin conexión',
    'blogpack_s6_badge' => 'No traer',
    'blogpack_s6_title' => 'Qué dejar en casa',
    'blogpack_s6_i1_t' => 'Maletas rígidas',
    'blogpack_s6_i1_d' => 'si tiene vuelos internos, serán rechazadas',
    'blogpack_s6_i2_t' => 'Ropa de camuflaje',
    'blogpack_s6_i2_d' => 'ilegal para civiles',
    'blogpack_s6_i3_t' => 'Bolsas de plástico de un solo uso',
    'blogpack_s6_i3_d' => 'prohibidas en toda Tanzania desde 2019, y confiscadas en el aeropuerto',
    'blogpack_s6_i4_t' => 'Drones',
    'blogpack_s6_i4_d' => 'requieren permiso escrito de TANAPA, que rara vez se concede',
    'blogpack_s6_i5_t' => 'Un secador de pelo',
    'blogpack_s6_i5_d' => 'la mayoría de los lodges los tienen, y agotan la limitada energía del generador',
    'blogpack_s6_i6_t' => 'Ropa para diez días',
    'blogpack_s6_i6_d' => 'hay lavandería disponible en casi todas partes y normalmente en el mismo día',
    'blogpack_s6_i7_t' => 'Joyas de valor',
    'blogpack_s6_i7_d' => 'no hay dónde lucirlas ni un lugar seguro donde dejarlas',
    'blogpack_tip_t' => 'El consejo individual más útil:',
    'blogpack_tip_d' => 'empaque para cuatro días, no diez, y use la lavandería. Casi todos los viajeros que recibimos dicen después que trajeron aproximadamente el doble de lo que necesitaban.',
    'blogpack_faq_badge' => 'Preguntas frecuentes',
    'blogpack_faq_title' => 'Equipaje de safari: preguntas frecuentes',
    'blogpack_faq_q1' => '¿Qué debo ponerme en un safari?',
    'blogpack_faq_a1' => 'Capas en colores neutros: caqui, verde oliva, beige, marrón. Las mañanas rondan los 14 °C y las tardes cerca de 28 °C, y experimentará ambos desde un vehículo abierto. Evite el azul y el negro, que atraen a las moscas tsetsé.',
    'blogpack_faq_q2' => '¿Por qué debo evitar la ropa azul y negra?',
    'blogpack_faq_a2' => 'Las moscas tsetsé se sienten atraídas por esos colores, y están presentes en Tarangire y el bosque de miombo de los parques del sur. La picadura es dolorosa, aunque no hay riesgo de enfermedad del sueño en las principales zonas turísticas.',
    'blogpack_faq_q3' => '¿Puedo usar ropa de camuflaje?',
    'blogpack_faq_a3' => 'No. El camuflaje está reservado para el ejército en Tanzania y es ilegal para civiles. Usarlo puede causar problemas genuinos en los controles, así que déjelo en casa.',
    'blogpack_faq_q4' => '¿Cuál es el límite de equipaje en los vuelos internos?',
    'blogpack_faq_a4' => '15 kg en una bolsa blanda, estrictamente aplicado en avionetas. Las maletas rígidas se rechazan porque no caben en la bodega. Si tiene una bolsa más grande, la mayoría de los hoteles de Arusha se la guardarán mientras vuela.',
    'blogpack_faq_q5' => '¿Necesito botas de senderismo para un safari?',
    'blogpack_faq_a5' => 'No. Zapatos cerrados cómodos son suficientes para un safari en vehículo, ya que pasa la mayor parte del tiempo en un vehículo. Las botas adecuadas solo se necesitan para el Kilimanjaro, el monte Meru o safaris a pie serios.',
    'blogpack_faq_q6' => '¿Qué tanto frío hace realmente?',
    'blogpack_faq_a6' => 'El borde del Ngorongoro baja a unos 5 °C antes del amanecer y el Serengeti a 13–15 °C. En un vehículo abierto moviéndose a 30 km/h se siente considerablemente más frío. Un forro polar y una capa cortavientos no son opcionales.',
    'blogpack_faq_q7' => '¿Debo traer binoculares?',
    'blogpack_faq_a7' => 'Sí, y son el artículo que más se olvida. Muchos avistamientos, sobre todo el rinoceronte en el cráter del Ngorongoro, están demasiado lejos para un objetivo de cámara pero son perfectos con binoculares.',
    'blogpack_faq_q8' => '¿Qué equipo de cámara necesito?',
    'blogpack_faq_a8' => 'Un objetivo de 300 mm o más para fauna, más uno gran angular para paisajes. Traiga baterías de repuesto, ya que los campamentos a menudo usan generadores solo en horas fijas, y una bolsa antipolvo, ya que el polvo de la temporada seca destruye los sensores.',
    'blogpack_faq_q9' => '¿Puedo lavar ropa durante el safari?',
    'blogpack_faq_a9' => 'Sí, en casi todos los lodges y campamentos, normalmente en el mismo día. Por eso empacar para cuatro días en lugar de diez es casi siempre la decisión correcta, particularmente con un límite de vuelo de 15 kg.',
    'blogpack_faq_q10' => '¿Qué dinero debo traer?',
    'blogpack_faq_a10' => 'Dólares estadounidenses en efectivo para propinas y extras, en billetes posteriores a 2009. Los billetes más antiguos se rechazan en toda Tanzania. Traiga denominaciones pequeñas para propinas. Las tarjetas funcionan en los lodges pero la conectividad no es fiable.',
    'blogpack_faq_q11' => '¿Están realmente prohibidas las bolsas de plástico?',
    'blogpack_faq_a11' => 'Sí, desde 2019, y se aplica en el aeropuerto, donde se confiscan a la llegada. Traiga bolsas de tela o malla en su lugar. Las bolsas ziplock para artículos de aseo generalmente se toleran, pero lo más seguro es evitarlas todas.',
    'blogpack_faq_q12' => '¿Necesito un adaptador de enchufe?',
    'blogpack_faq_a12' => 'Sí, tipo G, el estándar británico de tres clavijas. El voltaje es de 230V. Traiga un adaptador multi-toma si tiene varios dispositivos, porque los campamentos a menudo tienen solo uno o dos enchufes por tienda.',
    'blogpack_faq_q13' => '¿Puedo traer un dron?',
    'blogpack_faq_a13' => 'Solo con permiso escrito de TANAPA, que rara vez se concede para turismo. Volar sin él arriesga la confiscación y una multa. Asuma que la respuesta es no a menos que tenga la documentación en mano.',
    'blogpack_related_badge' => 'Sigue leyendo',
    'blogpack_related_title' => 'Continúa explorando Tanzania',
    'blogpack_related_trekking' => 'El equipaje para el Kilimanjaro es diferente',
    'blogpack_final_title' => '¿Preguntas sobre qué traer?',
    'blogpack_final_intro' => 'Envíenos su itinerario y le diremos exactamente qué necesita para esos parques específicos y esa temporada, incluyendo si el límite de vuelo de 15 kg se aplica a usted.',
    'blogpack_final_whatsapp' => 'Escríbanos por WhatsApp',
    'blogpack_final_contact' => 'Formulario de contacto',

    // ===== Blog article: Vaccinations and Health =====
    'blogvax_meta_title' => 'Guía de Vacunas y Salud para Tanzania (2026) | Serengeti Budget Safari',
    'blogvax_meta_description' => 'Lo que realmente necesita antes de viajar a Tanzania: vacunas, malaria, agua, altitud y la cláusula de seguro que la mayoría pasa por alto. Información, no consejo médico.',
    'blogvax_updated' => 'Actualizado 2026',
    'blogvax_h1' => 'Vacunas y salud',
    'blogvax_hero_sub' => 'Lo que realmente necesita antes de viajar a Tanzania: vacunas, malaria, agua, altitud y la cláusula de seguro que la mayoría pasa por alto.',
    'blogvax_author' => 'Equipo de Serengeti Budget Safari',
    'blogvax_date' => 'Agosto de 2026',
    'blogvax_quick_badge' => 'Respuestas rápidas',
    'blogvax_quick_title' => 'La salud en resumen',
    'blogvax_quick_intro' => 'Lo esencial, pero visite una clínica de viajes de seis a ocho semanas antes.',
    'blogvax_qq1_q' => '¿Vacuna obligatoria?',
    'blogvax_qq1_a' => 'Solo la fiebre amarilla, y solo desde países de riesgo.',
    'blogvax_qq2_q' => '¿Malaria?',
    'blogvax_qq2_a' => 'Sí, en todas partes, incluido Zanzíbar. Tome profilaxis.',
    'blogvax_qq3_q' => '¿Agua del grifo?',
    'blogvax_qq3_a' => 'No. Solo embotellada o filtrada.',
    'blogvax_qq4_q' => '¿Seguro?',
    'blogvax_qq4_a' => 'Obligatorio, y debe cubrir la evacuación.',
    'blogvax_qq5_q' => '¿Escalar el Kilimanjaro?',
    'blogvax_qq5_a' => 'La póliza debe cubrir trekking hasta 6.000 m.',
    'blogvax_qq6_q' => '¿Cuándo ver a un médico?',
    'blogvax_qq6_a' => 'De seis a ocho semanas antes de viajar.',
    'blogvax_see_faq' => 'Ver todas las preguntas frecuentes',
    'blogvax_toc_title' => 'Contenido – Vacunas y salud',
    'blogvax_toc_1' => 'Lea esto primero',
    'blogvax_toc_2' => 'Vacunas',
    'blogvax_toc_3' => 'Malaria',
    'blogvax_toc_4' => 'Comida y agua',
    'blogvax_toc_5' => 'Altitud',
    'blogvax_toc_6' => 'Seguro de viaje',
    'blogvax_toc_7' => 'Otros aspectos de salud',
    'blogvax_toc_8' => 'Preguntas frecuentes',
    'blogvax_s0_badge' => 'Importante',
    'blogvax_s0_title' => 'Antes que nada',
    'blogvax_s0_warn_t' => 'Esta página es información, no consejo médico.',
    'blogvax_s0_warn_d' => 'Hable con su médico o una clínica de salud del viajero <strong>de seis a ocho semanas antes de viajar</strong>. Los requisitos dependen de su historial médico, su itinerario exacto y su ruta, y solo un médico puede aconsejarle adecuadamente.',
    'blogvax_s0_p1' => 'Dicho esto, esto es lo que la mayoría de los viajeros a Tanzania necesitan considerar.',
    'blogvax_s1_badge' => 'Vacunas',
    'blogvax_s1_title' => 'Vacunas',
    'blogvax_s1_sub1' => 'Requerida en un caso específico',
    'blogvax_s1_p1' => 'La <strong>fiebre amarilla</strong> es la única vacuna que es un requisito legal de entrada, y solo si llega desde, o ha transitado más de 12 horas por, un país con riesgo de fiebre amarilla. Los vuelos directos desde Europa no la requieren; una escala larga en Nairobi o Adís Abeba puede que sí.',
    'blogvax_s1_sub2' => 'Recomendada',
    'blogvax_t1_h1' => 'Vacuna',
    'blogvax_t1_h2' => 'Por qué',
    'blogvax_t1_h3' => 'Quién',
    'blogvax_t1_r1_a' => 'Hepatitis A',
    'blogvax_t1_r1_b' => 'Transmisión por alimentos y agua',
    'blogvax_t1_r1_c' => 'Todos los viajeros',
    'blogvax_t1_r2_a' => 'Fiebre tifoidea',
    'blogvax_t1_r2_b' => 'Transmisión por alimentos y agua',
    'blogvax_t1_r2_c' => 'La mayoría de los viajeros',
    'blogvax_t1_r3_a' => 'Tétanos, difteria, polio',
    'blogvax_t1_r3_b' => 'Refuerzos rutinarios',
    'blogvax_t1_r3_c' => 'Verifique que estén al día',
    'blogvax_t1_r4_a' => 'Hepatitis B',
    'blogvax_t1_r4_b' => 'Sangre y fluidos corporales',
    'blogvax_t1_r4_c' => 'Estancias más largas',
    'blogvax_t1_r5_a' => 'Rabia',
    'blogvax_t1_r5_b' => 'Mordeduras de animales',
    'blogvax_t1_r5_c' => 'Estancias rurales largas, o trabajo con animales',
    'blogvax_t1_r6_a' => 'Meningitis ACWY',
    'blogvax_t1_r6_b' => 'Riesgo estacional en partes de África',
    'blogvax_t1_r6_c' => 'Consulte a su médico',
    'blogvax_s2_badge' => 'Malaria',
    'blogvax_s2_title' => 'Malaria: la que más importa',
    'blogvax_s2_p1' => 'La malaria está presente en toda Tanzania, <strong>incluido Zanzíbar</strong>. El riesgo es menor en altitud (Arusha, Ngorongoro y las tierras altas del Serengeti) y mayor en la costa y en los parques del sur de baja altitud como Nyerere y Mikumi.',
    'blogvax_s2_sub1' => 'Profilaxis',
    'blogvax_s2_p2' => 'Su médico le recetará una de las opciones estándar (atovacuona/proguanil, doxiciclina o mefloquina), cada una con diferentes pautas de dosificación y efectos secundarios. Tómela exactamente como se indica, incluidas las dosis <em>después</em> de regresar, que es la parte que la gente olvida.',
    'blogvax_s2_sub2' => 'La prevención de picaduras importa igualmente',
    'blogvax_s2_p3' => 'Ninguna profilaxis es 100% efectiva, así que las medidas físicas no son opcionales:',
    'blogvax_s2_b1_t' => 'Repelente con DEET',
    'blogvax_s2_b1_d' => 'en la piel expuesta, reaplicado al atardecer',
    'blogvax_s2_b2_t' => 'Mangas largas y pantalones',
    'blogvax_s2_b2_d' => 'después del atardecer, ya que el mosquito de la malaria pica entre el anochecer y el amanecer',
    'blogvax_s2_b3_t' => 'Duerma bajo el mosquitero',
    'blogvax_s2_b3_d' => 'proporcionado; revíselo por si tiene agujeros',
    'blogvax_s2_b4_t' => 'Aire acondicionado o un ventilador',
    'blogvax_s2_b4_d' => 'durante la noche donde esté disponible',
    'blogvax_s2_warn_t' => 'Después de llegar a casa:',
    'blogvax_s2_warn_d' => 'si desarrolla fiebre dentro de los doce meses posteriores a su regreso, y particularmente dentro de los primeros tres meses, vea a un médico de inmediato y dígale que ha estado en una zona de malaria. La malaria es completamente tratable cuando se detecta a tiempo y peligrosa cuando no.',
    'blogvax_s3_badge' => 'Comida y agua',
    'blogvax_s3_title' => 'Comida y agua',
    'blogvax_s3_i1_t' => 'Beba solo agua embotellada o filtrada.',
    'blogvax_s3_i1_d' => 'Se proporciona en nuestros vehículos durante todos los safaris.',
    'blogvax_s3_i2' => 'Evite el hielo donde no esté seguro del origen del agua.',
    'blogvax_s3_i3' => 'Pele la fruta usted mismo.',
    'blogvax_s3_i4' => 'La comida de lodges y campamentos se prepara con un alto estándar y es segura.',
    'blogvax_s3_i5' => 'Para la comida callejera, aplique la prueba habitual: recién cocinada, servida caliente, y concurrida por locales.',
    'blogvax_s3_i6' => 'Cepíllese los dientes con agua embotellada si su estómago es sensible.',
    'blogvax_s3_p1' => 'La diarrea del viajero es la queja más común, y suele ser leve. Traiga sales de rehidratación y un antidiarreico, y vea a un médico si dura más de un par de días o implica fiebre o sangre.',
    'blogvax_s4_badge' => 'Altitud',
    'blogvax_s4_title' => 'Altitud',
    'blogvax_s4_p1' => 'La mayoría de los viajeros de safari no tendrán problemas de altitud, pero vale la pena conocer dos lugares.',
    'blogvax_s4_p2' => 'El borde del Ngorongoro está a 2.200–2.400 m. Un dolor de cabeza leve la primera noche es común. Beba más agua de la que cree necesitar y normalmente se pasa.',
    'blogvax_s4_p3' => 'El Kilimanjaro es un asunto completamente diferente. A 5.895 m hay aproximadamente la mitad del oxígeno disponible al nivel del mar, y el mal de altura es la principal razón por la que fallan las ascensiones. Los síntomas, la prevención y las señales de advertencia se explican en detalle en nuestra',
    'blogvax_s4_link' => 'guía del Kilimanjaro',
    'blogvax_s5_badge' => 'Seguro',
    'blogvax_s5_title' => 'Seguro de viaje',
    'blogvax_s5_p1' => 'El seguro de viaje es <strong>obligatorio</strong> en nuestros viajes, y esto no es una formalidad. Dentro de los parques, el hospital más cercano puede estar a horas por carretera, y los casos graves se trasladan por aire a Arusha, Dar es Salaam o Nairobi. La evacuación médica cuesta muchos miles de dólares.',
    'blogvax_s5_p2' => 'Su póliza debe cubrir:',
    'blogvax_s5_i1_t' => 'Gastos médicos',
    'blogvax_s5_i1_d' => 'y tratamiento hospitalario',
    'blogvax_s5_i2' => 'Evacuación de emergencia y repatriación',
    'blogvax_s5_i3_t' => 'Trekking hasta 6.000 m',
    'blogvax_s5_i3_d' => 'si va a escalar el Kilimanjaro o el Meru, muchas pólizas estándar excluyen la actividad en altitud, y esta es la brecha más común',
    'blogvax_s5_i4' => 'Cancelación de viaje, que también recomendamos',
    'blogvax_s5_p3' => 'Para Zanzíbar, recuerde el <strong>seguro local obligatorio separado (~$44)</strong> introducido en 2024, que su póliza normal no reemplaza.',
    'blogvax_s6_badge' => 'Práctico',
    'blogvax_s6_title' => 'Otros aspectos prácticos de salud',
    'blogvax_s6_i1_t' => 'Sol.',
    'blogvax_s6_i1_d' => 'La radiación UV a 1.500–2.400 m cerca del ecuador es intensa incluso cuando el aire está fresco. Protector solar de alto factor, sombrero y gafas de sol, todos los días.',
    'blogvax_s6_i2_t' => 'Moscas tsetsé.',
    'blogvax_s6_i2_d' => 'Presentes en Tarangire y el miombo del sur. La picadura duele; la enfermedad del sueño no es un riesgo práctico en las zonas turísticas. Evite la ropa azul y negra.',
    'blogvax_s6_i3_t' => 'Polvo.',
    'blogvax_s6_i3_d' => 'El polvo de la temporada seca irrita los ojos y las vías respiratorias. Traiga un buff, y gotas para los ojos si usa lentes de contacto.',
    'blogvax_s6_i4_t' => 'Esquistosomiasis (bilharzia).',
    'blogvax_s6_i4_d' => 'Presente en algunas aguas dulces. No nade en lagos o ríos a menos que su guía confirme que es seguro.',
    'blogvax_s6_i5_t' => 'Medicamentos con receta.',
    'blogvax_s6_i5_d' => 'Llévelos en el equipaje de mano en su envase original con una copia de la receta.',
    'blogvax_s6_i6_t' => 'Farmacias.',
    'blogvax_s6_i6_d' => 'Arusha y Moshi tienen farmacias bien surtidas. Dentro de los parques no hay ninguna, así que traiga lo que necesite.',
    'blogvax_faq_badge' => 'Preguntas frecuentes',
    'blogvax_faq_title' => 'Salud y vacunas: preguntas frecuentes',
    'blogvax_faq_q1' => '¿Qué vacunas necesito para Tanzania?',
    'blogvax_faq_a1' => 'La fiebre amarilla es un requisito legal solo si llega desde o transita por un país de riesgo. Se recomiendan la hepatitis A y la fiebre tifoidea para la mayoría de los viajeros, junto con los refuerzos rutinarios de tétanos, difteria y polio. Visite una clínica de viajes de seis a ocho semanas antes.',
    'blogvax_faq_q2' => '¿Necesito la vacuna contra la fiebre amarilla?',
    'blogvax_faq_a2' => 'Solo si llega desde, o ha transitado más de 12 horas por, un país de riesgo de fiebre amarilla. Los viajeros que vuelan directamente desde Europa no la necesitan, pero una escala larga en Nairobi o Adís Abeba puede activar el requisito.',
    'blogvax_faq_q3' => '¿Hay malaria en Tanzania?',
    'blogvax_faq_a3' => 'Sí, en todo el país, incluido Zanzíbar. El riesgo es menor en altitud en Arusha y las tierras altas del Ngorongoro, y mayor en la costa y en los parques del sur de baja altitud. La profilaxis más la prevención de picaduras es el enfoque estándar.',
    'blogvax_faq_q4' => '¿Qué antipalúdico debo tomar?',
    'blogvax_faq_a4' => 'Esa es una decisión de su médico. Las opciones comunes son atovacuona/proguanil, doxiciclina y mefloquina, cada una con diferente dosificación y efectos secundarios. Tome el curso completo, incluidas las dosis después de regresar a casa.',
    'blogvax_faq_q5' => '¿Hay malaria en Zanzíbar?',
    'blogvax_faq_a5' => 'Sí. Zanzíbar es una zona de malaria y estar en la costa significa que el riesgo es mayor que en las tierras altas del norte, no menor. Tome las mismas precauciones allí que en el safari.',
    'blogvax_faq_q6' => '¿Puedo beber el agua del grifo?',
    'blogvax_faq_a6' => 'No. Beba solo agua embotellada o filtrada, evite el hielo donde no esté seguro del origen, y pele su propia fruta. El agua potable se proporciona en nuestros vehículos durante todos los safaris.',
    'blogvax_faq_q7' => '¿Necesito seguro de viaje?',
    'blogvax_faq_a7' => 'Sí, es obligatorio en nuestros viajes. Debe cubrir gastos médicos y evacuación de emergencia, porque el hospital más cercano a un parque puede estar a horas de distancia y los casos graves se trasladan por aire a un costo considerable.',
    'blogvax_faq_q8' => '¿Mi seguro necesita cubrir la altitud?',
    'blogvax_faq_a8' => 'Si va a escalar el Kilimanjaro o el monte Meru, sí, debe cubrir explícitamente el trekking hasta 6.000 m. Muchas pólizas de viaje estándar excluyen la actividad en alta altitud, y esta es la brecha más común que vemos.',
    'blogvax_faq_q9' => '¿Qué pasa si me enfermo en el safari?',
    'blogvax_faq_a9' => 'Avise a su guía de inmediato. Los guías llevan botiquines de primeros auxilios y conocen las instalaciones más cercanas. Arusha y Moshi tienen buenas clínicas privadas; desde parques remotos, los casos graves se evacúan por aire, para eso está su seguro.',
    'blogvax_faq_q10' => '¿Hay mal de altura en el safari?',
    'blogvax_faq_a10' => 'Raramente. El borde del Ngorongoro a 2.200–2.400 m puede causar un dolor de cabeza leve la primera noche, que normalmente se resuelve bebiendo más agua. El Kilimanjaro es un asunto completamente diferente y se explica en nuestra guía del Kilimanjaro.',
    'blogvax_faq_q11' => '¿Son peligrosas las moscas tsetsé?',
    'blogvax_faq_a11' => 'La picadura es dolorosa pero la enfermedad del sueño no es un riesgo práctico en las principales zonas turísticas. Están presentes en Tarangire y el bosque de miombo del sur, y se sienten atraídas por la ropa azul oscuro y negra.',
    'blogvax_faq_q12' => '¿Puedo nadar en lagos y ríos?',
    'blogvax_faq_a12' => 'Solo si su guía confirma que es seguro. La bilharzia está presente en algunas aguas dulces, y los hipopótamos y cocodrilos están presentes en gran parte de ellas. Las piscinas de los lodges están bien, y las aguas termales de Maji Moto en Nyerere son seguras para nadar.',
    'blogvax_faq_q13' => '¿Qué pasa si desarrollo fiebre después de regresar a casa?',
    'blogvax_faq_a13' => 'Vea a un médico de inmediato y dígale que ha estado en una zona de malaria. La malaria puede aparecer hasta doce meses después de la exposición, más comúnmente dentro de los tres meses. Es completamente tratable cuando se detecta a tiempo.',
    'blogvax_related_badge' => 'Sigue leyendo',
    'blogvax_related_title' => 'Continúa explorando Tanzania',
    'blogvax_related_contact' => 'Haznos una pregunta',
    'blogvax_final_title' => '¿Preguntas sobre su viaje?',
    'blogvax_final_intro' => 'No podemos dar consejo médico, pero podemos decirle exactamente qué zonas y altitudes cubre su itinerario, información útil para llevar a su clínica de viajes.',
    'blogvax_final_whatsapp' => 'Escríbanos por WhatsApp',
    'blogvax_final_contact' => 'Formulario de contacto',

    // ===== Blog article: Serengeti vs Ngorongoro =====
    'blogsvn_meta_title' => 'Serengeti vs Ngorongoro: ¿Cuál Debería Elegir? | Serengeti Budget Safari',
    'blogsvn_meta_description' => 'Serengeti o el cráter del Ngorongoro: una comparación honesta de tamaño, costo, densidad de fauna y lo que realmente ofrece cada uno, de un operador que gestiona ambos.',
    'blogsvn_updated' => 'Actualizado 2026',
    'blogsvn_h1' => 'Serengeti vs Ngorongoro',
    'blogsvn_hero_sub' => 'Dos de los parques más conocidos de Tanzania, uno junto al otro y completamente diferentes en carácter. ¿Cuál se adapta a su viaje?',
    'blogsvn_quick_badge' => 'Respuestas rápidas',
    'blogsvn_quick_title' => 'Serengeti o Ngorongoro, en resumen',
    'blogsvn_quick_intro' => 'Las diferencias principales antes del detalle.',
    'blogsvn_qq1_q' => '¿Cuál es más grande?',
    'blogsvn_qq1_a' => 'El Serengeti, con diferencia: 14.763 km² frente a los 260 km² del cráter.',
    'blogsvn_qq2_q' => '¿Cuál tiene rinoceronte?',
    'blogsvn_qq2_a' => 'Ngorongoro. El Serengeti casi no tiene.',
    'blogsvn_qq3_q' => '¿Cuál tiene la migración?',
    'blogsvn_qq3_a' => 'El Serengeti, la mayor parte del año. El Ngorongoro solo la ve brevemente.',
    'blogsvn_qq4_q' => '¿Cuál lleva menos tiempo?',
    'blogsvn_qq4_a' => 'Ngorongoro, un día completo cubre el cráter.',
    'blogsvn_qq5_q' => '¿Cuál cuesta más?',
    'blogsvn_qq5_a' => 'Ngorongoro, una vez que se añade la tarifa de descenso al cráter de $295.',
    'blogsvn_qq6_q' => '¿Puedo hacer ambos?',
    'blogsvn_qq6_a' => 'Sí, y la mayoría de los itinerarios lo hacen. Están uno junto al otro.',
    'blogsvn_see_faq' => 'Ver todas las preguntas frecuentes',
    'blogsvn_toc_title' => 'Contenido – Serengeti vs Ngorongoro',
    'blogsvn_toc_1' => 'La respuesta corta',
    'blogsvn_toc_2' => 'Lado a lado',
    'blogsvn_toc_3' => 'Lo que el Serengeti hace mejor',
    'blogsvn_toc_4' => 'Lo que el Ngorongoro hace mejor',
    'blogsvn_toc_5' => 'Haciendo ambos',
    'blogsvn_toc_6' => 'Preguntas frecuentes',
    'blogsvn_s1_badge' => 'En resumen',
    'blogsvn_s1_title' => 'La respuesta corta',
    'blogsvn_s1_p1' => 'En realidad no son competidores. La mayoría de los itinerarios visitan <strong>ambos</strong>, porque están uno junto al otro y cumplen funciones diferentes. El Serengeti es vasto, variado, y hogar de la Gran Migración durante la mayor parte del año. El cráter del Ngorongoro es pequeño, autocontenido, y ofrece la concentración de fauna más densa de África en un solo día, incluido el rinoceronte negro que en gran medida le falta al Serengeti.',
    'blogsvn_s1_p2' => 'Si solo puede elegir uno: elija el Serengeti por la escala y la migración, elija Ngorongoro si su tiempo es muy limitado y quiere el máximo de fauna por hora.',
    'blogsvn_cta_label' => 'Ver Ambos en Un Viaje',
    'blogsvn_s2_badge' => 'Comparación',
    'blogsvn_s2_title' => 'Lado a lado',
    'blogsvn_t1_h1' => 'Factor',
    'blogsvn_t1_r1_a' => 'Tamaño',
    'blogsvn_crater_floor' => 'suelo del cráter',
    'blogsvn_t1_r2_a' => 'Establecido',
    'blogsvn_t1_r3_a' => 'Estatus',
    'blogsvn_t1_r3_b' => 'Patrimonio de la Humanidad de la UNESCO',
    'blogsvn_t1_r3_c' => 'Patrimonio de la Humanidad de la UNESCO',
    'blogsvn_t1_r4_a' => 'Tarifa de entrada (2026)',
    'blogsvn_per_vehicle' => 'por vehículo para descender',
    'blogsvn_t1_r5_a' => 'Mejor para',
    'blogsvn_t1_r5_b' => 'Escala, variedad, la migración',
    'blogsvn_t1_r5_c' => 'Densidad, rinoceronte, un solo día inolvidable',
    'blogsvn_t1_r6_a' => 'Leones',
    'blogsvn_t1_r6_c' => '~60 (en 260 km²)',
    'blogsvn_t1_r7_a' => 'Rinoceronte negro',
    'blogsvn_t1_r8_a' => 'Duración típica de la visita',
    'blogsvn_t1_r8_b' => '2–4 noches',
    'blogsvn_t1_r8_c' => '1 día completo',
    'blogsvn_s2_note' => 'Cifras de nuestros propios guías de parque. Vea las páginas completas del Serengeti y el Ngorongoro para más detalle.',
    'blogsvn_s3_badge' => 'Serengeti',
    'blogsvn_s3_title' => 'Lo que el Serengeti hace mejor',
    'blogsvn_s3_p1' => 'El Serengeti es el parque insignia de Tanzania por una razón: es enorme, ecológicamente variado, y tiene una de las densidades de leones más altas de África. También es el hogar durante todo el año de la Gran Migración. Las manadas están en algún lugar dentro del ecosistema todos los meses, moviéndose en un circuito continuo impulsado por las lluvias.',
    'blogsvn_s3_i1' => 'Llanuras interminables y hábitats variados, desde pastizales abiertos hasta bosques ribereños',
    'blogsvn_s3_i2' => 'La Gran Migración, en alguna forma, casi todos los meses del año',
    'blogsvn_s3_i3' => 'Algunos de los mejores avistamientos de leopardo en Tanzania, especialmente el valle de Seronera',
    'blogsvn_s3_p2' => 'Lo que no tiene: números significativos de rinoceronte negro, y una sensación genuinamente privada en temporada alta cerca de las zonas centrales populares.',
    'blogsvn_s3_link' => 'Guía completa del parque Serengeti',
    'blogsvn_s4_badge' => 'Ngorongoro',
    'blogsvn_s4_title' => 'Lo que el Ngorongoro hace mejor',
    'blogsvn_s4_p1' => 'El cráter del Ngorongoro es una caldera volcánica colapsada, 260 km² de pastizal rodeados por un borde de 600 metros. Nada emigra de allí, así que la densidad de fauna es extraordinaria. Aproximadamente 25.000 animales grandes viven dentro de él todo el año, visibles desde un solo día de safari.',
    'blogsvn_s4_i1' => 'El lugar más fiable de Tanzania para ver rinoceronte negro, con unos 30 viviendo bajo protección',
    'blogsvn_s4_i2' => 'Densidad de fauna inigualable para el tiempo invertido, un día, no varios',
    'blogsvn_s4_i3' => 'Paisaje espectacular desde el borde, mirando hacia el suelo del cráter',
    'blogsvn_s4_warn_t' => 'La trampa:',
    'blogsvn_s4_warn_d' => 'una tarifa separada de $295 por vehículo solo para descender al cráter, cobrada cada vez que baja, además de la entrada estándar al parque. Baja considerablemente por persona a medida que crece su grupo.',
    'blogsvn_s4_p2' => 'Lo que no tiene: la escala del Serengeti, ni la migración durante la mayor parte del año. El Ngorongoro es técnicamente parte del mismo ecosistema (las zonas de parto de Ndutu están dentro del Área de Conservación), pero el suelo del cráter en sí ve a las manadas solo brevemente.',
    'blogsvn_s4_link' => 'Guía completa del parque Ngorongoro',
    'blogsvn_s5_badge' => 'Juntos',
    'blogsvn_s5_title' => 'Por qué la mayoría hace ambos',
    'blogsvn_s5_p1' => 'Los dos parques son adyacentes, conectados por un trayecto corto, por lo que la gran mayoría de los itinerarios del circuito norte los combinan en lugar de elegir uno. Una forma típica: dos o tres noches en el Serengeti por el espacio y la variedad, luego una noche en o cerca del borde del cráter para un descenso temprano a la mañana siguiente. El cráter se hace mejor con la primera luz, antes de que lleguen los excursionistas de un día desde Karatu.',
    'blogsvn_s5_p2' => 'Nuestro propio <strong>Safari de 5 Días Serengeti y Ngorongoro</strong> está construido exactamente en torno a esta combinación.',
    'blogsvn_faq_badge' => 'Preguntas frecuentes',
    'blogsvn_faq_title' => 'Serengeti vs Ngorongoro: preguntas frecuentes',
    'blogsvn_faq_q1' => '¿Es el Ngorongoro parte del Serengeti?',
    'blogsvn_faq_a1' => 'No, son áreas protegidas separadas administradas de forma diferente (el Serengeti por TANAPA, el Ngorongoro por la NCAA), aunque están ecológicamente conectadas y son adyacentes entre sí.',
    'blogsvn_faq_q2' => '¿Cuál es mejor para los Big Five?',
    'blogsvn_faq_a2' => 'Juntos, no por separado. El Serengeti le da león, leopardo, elefante y búfalo con facilidad; el Ngorongoro es esencialmente el único lugar fiable en Tanzania para el rinoceronte negro. Visitar ambos es cómo la mayoría de los viajeros completan el conjunto.',
    'blogsvn_faq_q3' => '¿Cuántos días necesito para el Ngorongoro?',
    'blogsvn_faq_a3' => 'Un día completo cubre el suelo del cráter a fondo. Es lo bastante pequeño para que un solo safari, hecho temprano, vea la mayor parte de lo que hay que ver.',
    'blogsvn_faq_q4' => '¿Cuántos días necesito para el Serengeti?',
    'blogsvn_faq_a4' => 'De dos a cuatro noches como mínimo para apreciar su escala. En qué región se aloje debería coincidir con el mes, ya que la migración se mueve por diferentes partes del parque a lo largo del año.',
    'blogsvn_faq_q5' => '¿Por qué el Ngorongoro es mucho más caro por día?',
    'blogsvn_faq_a5' => 'La tarifa de descenso al cráter de $295, cobrada por vehículo cada vez que baja. Repartida entre un grupo se vuelve razonable, aproximadamente $50 cada uno para seis personas, pero para dos personas es un costo real además de la entrada estándar al parque.',
    'blogsvn_faq_q6' => '¿Puedo omitir uno y hacer solo el otro?',
    'blogsvn_faq_a6' => 'Sí. Si su tiempo es muy limitado, el Ngorongoro solo ofrece una densa observación de fauna en un solo día. Si tiene una semana o más, el Serengeti solo le da escala y variedad. La mayoría de los viajeros con 4 o más días hacen ambos.',
    'blogsvn_related_parks' => 'Todos los parques comparados',
    'blogsvn_final_title' => '¿Aún decidiendo entre los dos?',
    'blogsvn_final_intro' => 'Díganos cuántos días tiene y qué es lo que más le importa. Le diremos honestamente si hacer uno, el otro, o ambos.',

