    // ===== Privacy Policy =====
    'privacy_meta_title' => 'Política de Privacidad | Serengeti Budget Safari',
    'privacy_meta_description' => 'Cómo Serengeti Budget Safari recopila, usa y protege sus datos personales, y los derechos que tiene bajo el RGPD.',
    'privacy_h1' => 'Política de Privacidad',
    'privacy_intro' => 'Este aviso explica qué datos personales recopila <strong>Serengeti Budget Safari</strong> cuando visita este sitio web o nos pide un presupuesto, por qué los tratamos, y qué derechos tiene. Tratamos los datos personales conforme al Reglamento (UE) 2016/679 (RGPD).',
    'privacy_h2_1' => '1. Quiénes somos',
    'privacy_h2_2' => '2. Qué recopilamos',
    'privacy_h3_1' => 'Información que usted nos proporciona',
    'privacy_you_i1' => 'su nombre;',
    'privacy_you_i2' => 'dirección de correo electrónico y número de teléfono;',
    'privacy_you_i3' => 'país de residencia;',
    'privacy_you_i4' => 'fechas de viaje, número de viajeros y las preferencias de su consulta;',
    'privacy_you_i5' => 'cualquier otra cosa que decida contarnos (necesidades dietéticas, necesidades de accesibilidad, ocasiones especiales).',
    'privacy_h3_2' => 'Información recopilada automáticamente',
    'privacy_auto_i1' => 'dirección IP, tipo de navegador y dispositivo;',
    'privacy_auto_i2' => 'páginas visitadas y la fecha y hora de su visita;',
    'privacy_auto_i3' => 'el sitio desde el que llegó.',
    'privacy_h2_3' => '3. Por qué lo tratamos',
    'privacy_why_i1' => '<strong>Para responder a su consulta</strong> y preparar un presupuesto. Base jurídica: medidas tomadas a petición suya antes de celebrar un contrato (art. 6.1.b RGPD).',
    'privacy_why_i2' => '<strong>Para organizar y realizar el viaje</strong> que ha reservado. Base jurídica: ejecución de un contrato (art. 6.1.b RGPD).',
    'privacy_why_i3' => '<strong>Para cumplir obligaciones fiscales y contables</strong>. Base jurídica: obligación legal (art. 6.1.c RGPD).',
    'privacy_why_i4' => '<strong>Para mejorar este sitio web</strong> usando estadísticas agregadas. Base jurídica: interés legítimo (art. 6.1.f RGPD).',
    'privacy_why_note' => 'No enviamos mensajes de marketing sin su consentimiento explícito, y nunca vendemos sus datos.',
    'privacy_h2_4' => '4. Con quién los compartimos',
    'privacy_share_intro' => 'Compartimos sus datos solo con quienes los necesitan para realizar su viaje:',
    'privacy_share_i1' => 'lodges, campamentos de tiendas y hoteles donde se aloja;',
    'privacy_share_i2' => 'aerolíneas que operan vuelos internos, y empresas de traslado;',
    'privacy_share_i3' => 'autoridades de parques nacionales, cuando los permisos de entrada requieren datos del visitante;',
    'privacy_share_i4' => 'proveedores técnicos de este sitio web (alojamiento, correo electrónico);',
    'privacy_share_i5' => 'autoridades públicas, cuando la ley lo requiera.',
    'privacy_share_note' => 'Como operamos desde Tanzania, sus datos también se tratan fuera del Espacio Económico Europeo. Esta transferencia se realiza conforme al art. 49.1.b RGPD, ya que es necesaria para ejecutar el contrato de viaje que ha solicitado.',
    'privacy_h2_5' => '5. Cuánto tiempo los conservamos',
    'privacy_keep_i1' => '<strong>Consultas que no derivaron en una reserva:</strong> 24 meses desde el último contacto.',
    'privacy_keep_i2' => '<strong>Viajes confirmados:</strong> 10 años, por motivos contables y fiscales.',
    'privacy_keep_i3' => '<strong>Estadísticas del sitio web:</strong> hasta 26 meses en forma agregada.',
    'privacy_h2_6' => '6. Cookies',
    'privacy_cookies_p1' => 'Este sitio usa solo el almacenamiento técnico necesario para hacer funcionar las páginas y recordar el idioma que eligió. También cargamos fuentes e iconos de servicios externos (Google Fonts, Font Awesome vía CDN), que pueden registrar su dirección IP. Puede bloquear o eliminar las cookies en la configuración de su navegador; algunas funciones pueden entonces funcionar con menos fluidez. Vea nuestra',
    'privacy_cookies_link' => 'política de cookies',
    'privacy_h2_7' => '7. Sus derechos',
    'privacy_rights_intro' => 'En virtud de los artículos 15 a 22 del RGPD, tiene derecho a:',
    'privacy_rights_i1' => 'acceder a sus datos y recibir una copia;',
    'privacy_rights_i2' => 'que se corrijan o eliminen;',
    'privacy_rights_i3' => 'restringir el tratamiento u oponerse a él;',
    'privacy_rights_i4' => 'recibir sus datos en un formato portátil;',
    'privacy_rights_i5' => 'retirar el consentimiento en cualquier momento;',
    'privacy_rights_i6' => 'presentar una reclamación ante su autoridad nacional de protección de datos.',
    'privacy_rights_note' => 'Para ejercer cualquiera de estos derechos, escriba a <a href="mailto:serengetibudgetsafari@gmail.com">serengetibudgetsafari@gmail.com</a>. Respondemos dentro de 30 días.',
    'privacy_h2_8' => '8. Seguridad',
    'privacy_security_p1' => 'Aplicamos medidas técnicas y organizativas razonables para proteger sus datos frente al acceso no autorizado, la pérdida o la divulgación. Ninguna transmisión por internet es completamente segura: por favor, nunca nos envíe números de tarjeta completos por correo electrónico o WhatsApp.',
    'privacy_h2_9' => '9. Menores',
    'privacy_children_p1' => 'Este sitio web no está dirigido a menores de 16 años. Los datos de menores que viajan con nosotros son proporcionados por sus padres o tutores legales.',
    'privacy_h2_10' => '10. Cambios',
    'privacy_changes_p1' => 'Podemos actualizar este aviso; la fecha en la parte superior de la página siempre muestra la versión actual.',

    // ===== Terms & Conditions =====
    'terms_meta_title' => 'Términos y Condiciones | Serengeti Budget Safari',
    'terms_meta_description' => 'Condiciones de reserva de Serengeti Budget Safari: depósitos, pagos, cargos por cancelación, requisitos de seguro, responsabilidad y reclamaciones.',
    'terms_h1' => 'Términos y Condiciones',
    'terms_intro' => 'Estas condiciones rigen las reservas de safaris, ascensiones, excursiones de un día y estancias en Zanzíbar organizadas por <strong>Serengeti Budget Safari</strong>, con sede en Arusha, Tanzania. Al confirmar una reserva, confirma que las ha leído y aceptado.',
    'terms_note_title' => 'Importante:',
    'terms_note_body' => 'los importes, porcentajes y plazos que figuran a continuación son nuestras condiciones estándar. Las condiciones vinculantes para su viaje son las establecidas en el presupuesto escrito que le enviamos. Cuando ambos difieran, prevalece el presupuesto.',
    'terms_h2_1' => '1. Reserva y confirmación',
    'terms_booking_i1' => 'Solicitar un presupuesto es gratuito y no le supone ninguna obligación.',
    'terms_booking_i2' => 'Una reserva se confirma una vez que recibe nuestra confirmación escrita y se ha recibido el depósito.',
    'terms_booking_i3' => 'El espacio en lodges y campamentos no se reserva hasta la confirmación. En temporada alta, la disponibilidad puede cambiar en cuestión de horas.',
    'terms_booking_i4' => 'Por favor, facilítenos los nombres exactamente como aparecen en su pasaporte; las correcciones posteriores pueden generar cargos por parte de lodges y aerolíneas.',
    'terms_h2_2' => '2. Precios',
    'terms_prices_i1' => 'Los precios se indican en euros (EUR) o dólares estadounidenses (USD) según lo indicado en su presupuesto, por persona salvo que se indique lo contrario.',
    'terms_prices_i2' => 'Salvo que su presupuesto indique lo contrario, el precio cubre: un vehículo 4x4 con guía-conductor, combustible, tarifas de entrada a los parques de su itinerario, alojamiento y comidas según lo descrito, y agua potable durante los safaris.',
    'terms_prices_i3' => 'El precio excluye: vuelos internacionales, visado, seguro de viaje, bebidas, propinas, gastos personales, excursiones opcionales, y vuelos internos salvo que se indiquen expresamente.',
    'terms_prices_i4' => 'Las tarifas de entrada a los parques las establecen las autoridades tanzanas (TANAPA, NCAA). Si aumentan después de confirmarse su reserva, la diferencia debe pagarla el viajero.',
    'terms_h2_3' => '3. Pago',
    'terms_pay_deposit_t' => 'Depósito:',
    'terms_pay_deposit_d' => '30% del total al confirmar.',
    'terms_pay_balance_t' => 'Saldo:',
    'terms_pay_balance_d' => 'vence 30 días antes de la salida. Para reservas hechas dentro de los 30 días previos a la salida, el importe total se paga al confirmar.',
    'terms_pay_i3' => 'Los cargos bancarios y de transferencia corren a cargo del viajero.',
    'terms_pay_i4' => 'Si el saldo no se paga en la fecha de vencimiento, podemos tratar la reserva como cancelada y aplicar los cargos de la cláusula 4.',
    'terms_h2_4' => '4. Cancelación por su parte',
    'terms_cancel_intro' => 'Las cancelaciones deben hacerse por escrito. Se aplican los siguientes cargos, calculados sobre el precio total del viaje:',
    'terms_cancel_th1' => 'Aviso antes de la salida',
    'terms_cancel_th2' => 'Cargo',
    'terms_cancel_r1_a' => 'Más de 60 días',
    'terms_cancel_r1_b' => 'Depósito retenido (30%)',
    'terms_cancel_r2_a' => 'De 60 a 30 días',
    'terms_cancel_r2_b' => '50% del total',
    'terms_cancel_r3_a' => 'De 29 a 15 días',
    'terms_cancel_r3_b' => '75% del total',
    'terms_cancel_r4_a' => 'Menos de 15 días, o no presentarse',
    'terms_cancel_r4_b' => '100% del total',
    'terms_cancel_note' => 'Algunos lodges, campamentos móviles y vuelos internos imponen sus propias condiciones más estrictas; cuando sea así, se lo indicamos en el presupuesto.',
    'terms_h2_5' => '5. Cambios',
    'terms_changes_i1' => 'Los cambios solicitados con más de 30 días de antelación a la salida son gratuitos, salvo cualquier diferencia en el costo de los servicios y las tarifas de los proveedores.',
    'terms_changes_i2' => 'Los cambios solicitados dentro de los 30 días previos a la salida se tratan como una cancelación y una nueva reserva.',
    'terms_changes_i3' => 'Podemos modificar un itinerario por razones de seguridad, clima, condiciones de las carreteras, cierres de parques o disponibilidad de alojamiento, ofreciendo servicios de un estándar equivalente.',
    'terms_h2_6' => '6. Seguro de viaje',
    'terms_insurance_p1' => '<strong>El seguro de viaje es obligatorio</strong> en todos nuestros viajes. Debe cubrir gastos médicos, evacuación de emergencia y repatriación. Para el Kilimanjaro y el monte Meru, su póliza debe cubrir explícitamente el trekking en alta altitud hasta 6.000 m. También recomendamos cobertura de cancelación. No somos responsables de los costos derivados de un seguro inadecuado.',
    'terms_h2_7' => '7. Documentos, salud y seguridad',
    'terms_docs_i1' => 'Su pasaporte debe ser válido por al menos seis meses desde la fecha de entrada y tener dos páginas en blanco.',
    'terms_docs_i2' => 'Obtener un visado tanzano es responsabilidad del viajero.',
    'terms_docs_i3' => 'Se requiere un certificado de fiebre amarilla si llega desde, o ha transitado por, un país de riesgo.',
    'terms_docs_i4' => 'Por favor, infórmenos en el momento de la reserva sobre cualquier afección médica, alergia o medicación relevante para el viaje.',
    'terms_docs_i5' => 'En los safaris debe seguir las instrucciones de su guía: no salga del vehículo sin permiso y no se acerque a los animales.',
    'terms_h2_8' => '8. Responsabilidad',
    'terms_liability_i1' => 'Organizamos su viaje con diligencia profesional y somos responsables de la correcta prestación de los servicios que ofrecemos directamente.',
    'terms_liability_i2' => 'No somos responsables de retrasos, cancelaciones o pérdidas causados por eventos fuera de nuestro control razonable: clima, desastres naturales, epidemias, disturbios civiles, huelgas, decisiones de las autoridades o fallos de la infraestructura pública.',
    'terms_liability_i3' => 'No somos responsables de los servicios que reserve de forma independiente con terceros.',
    'terms_liability_i4' => 'Los avistamientos de fauna ocurren en la naturaleza y no pueden garantizarse.',
    'terms_liability_i5' => 'El equipaje y las pertenencias personales siguen siendo responsabilidad del viajero.',
    'terms_h2_9' => '9. Conducta',
    'terms_conduct_p1' => 'Nos reservamos el derecho de retirar de un viaje, sin reembolso, a cualquier persona que ponga en peligro su propia seguridad o la de otros, dañe el medio ambiente o la fauna, o se comporte con grave falta de respeto hacia las comunidades locales o nuestro personal.',
    'terms_h2_10' => '10. Reclamaciones',
    'terms_complaints_p1' => 'Si algo sale mal durante su viaje, avise a su guía o a nuestra oficina de inmediato. La mayoría de los problemas pueden resolverse en el momento. Las reclamaciones por escrito deben llegar a <a href="mailto:serengetibudgetsafari@gmail.com">serengetibudgetsafari@gmail.com</a> dentro de los 30 días posteriores a la finalización de su viaje.',
    'terms_h2_11' => '11. Ley aplicable',
    'terms_law_p1' => 'Este contrato se rige por la legislación de la República Unida de Tanzania. Antes de emprender acciones legales, ambas partes acuerdan intentar una solución amistosa.',
    'terms_contact_title' => '¿Preguntas antes de reservar?',
    'terms_contact_body' => 'Escriba a <a href="mailto:serengetibudgetsafari@gmail.com">serengetibudgetsafari@gmail.com</a> o escríbanos por <a href="https://wa.me/255697612865" rel="noopener">WhatsApp +255 697 612 865</a>. Respondemos todos los días entre las 07:00 y las 21:00, hora de Tanzania.',

