    'cookies_meta_title' => 'Política de Cookies | Serengeti Budget Safari',
    'cookies_meta_description' => 'Qué cookies y servicios de terceros usa este sitio web, y cómo controlarlos en su navegador.',
    'cookies_h1' => 'Política de Cookies',
    'cookies_intro' => 'Las cookies son pequeños archivos de texto que un sitio web guarda en su dispositivo. Esta página explica qué usamos y cómo puede controlarlo.',
    'cookies_h2_1' => '1. Almacenamiento técnico',
    'cookies_technical_intro' => 'Necesario para que el sitio funcione; no se requiere consentimiento:',
    'cookies_th_name' => 'Nombre',
    'cookies_th_purpose' => 'Propósito',
    'cookies_th_duration' => 'Duración',
    'cookies_row_lang_purpose' => 'Recuerda el idioma que eligió para no preguntárselo en cada visita',
    'cookies_row_lang_duration' => 'Hasta que lo borre',
    'cookies_technical_note' => 'Este valor se guarda en el <em>almacenamiento local</em> de su navegador. Permanece en su dispositivo y nunca se envía a nuestros servidores.',
    'cookies_h2_2' => '2. Servicios de terceros',
    'cookies_third_party_intro' => 'Para mostrar las páginas cargamos recursos de proveedores externos, que pueden registrar su dirección IP y detalles del navegador:',
    'cookies_gfonts_purpose' => 'tipografías',
    'cookies_fa_purpose' => 'iconos',
    'cookies_google_notice' => 'Aviso de privacidad de Google',
    'cookies_cloudflare_notice' => 'Aviso de privacidad de Cloudflare',
    'cookies_h2_3' => '3. Contenido incrustado',
    'cookies_embed_p1' => 'Algunas páginas pueden incrustar vídeos o mapas alojados en otros sitios (por ejemplo, YouTube o Google Maps). Cuando lo hacen, ese proveedor puede establecer sus propias cookies una vez que empiece la reproducción o interactúe con el mapa.',
    'cookies_h2_4' => '4. Lo que no usamos',
    'cookies_notuse_p1' => 'No usamos cookies de publicidad o perfilado, y no vendemos datos de navegación a anunciantes.',
    'cookies_h2_5' => '5. Gestionar las cookies',
    'cookies_manage_intro' => 'Puede bloquear o eliminar las cookies en la configuración de su navegador:',
    'cookies_manage_chrome' => 'Configuración → Privacidad y seguridad → Cookies',
    'cookies_manage_safari' => 'Preferencias → Privacidad',
    'cookies_manage_firefox' => 'Configuración → Privacidad y seguridad',
    'cookies_manage_edge' => 'Configuración → Cookies y permisos del sitio',
    'cookies_manage_note' => 'Si desactiva el almacenamiento técnico, el sitio sigue funcionando, pero deberá elegir su idioma en cada visita.',
    'cookies_h2_6' => '6. Contacto',
    'cookies_contact_p1' => 'Cualquier pregunta, escriba a <a href="mailto:serengetibudgetsafari@gmail.com">serengetibudgetsafari@gmail.com</a>.',

