    'bsg_meta_title' => 'La Guía Definitiva de Safari Económico en Tanzania: Parques, Precios y Paquetes de Confianza',
    'bsg_meta_description' => 'La guía más completa de safari económico en Tanzania. Tarifas de parques reales, precios de alojamiento, secretos locales, itinerarios de muestra y paquetes de confianza de un operador local de Arusha.',

    'bsg_badge' => 'La Guía Completa 2026',
    'bsg_h1' => 'La Guía Definitiva y Detallada de Safari Económico en Tanzania',
    'bsg_price_highlight' => 'Desde €200',
    'bsg_price_highlight_small' => 'por persona / día',
    'bsg_hero_intro' => 'Todo lo que necesita antes de reservar: tarifas de parques reales, precios de alojamiento honestos, secretos locales, y, una vez que sepa por qué está pagando, nuestros paquetes de confianza, sin cargos ocultos.',
    'bsg_hero_cta_packages' => 'Ver Paquetes de Confianza',
