    'bsg_toc_book' => 'Reservar Ahora',

    'bsg_intro_title' => '¿Por Qué Tanzania para Su Safari Económico?',
    'bsg_intro_p1' => 'Tanzania no es solo otro destino de safari. Es <strong>el</strong> destino de safari. Con más de 20 parques nacionales, la mayor concentración de fauna del planeta, y la legendaria Gran Migración, Tanzania ofrece una experiencia de safari inigualable en cualquier otro lugar del mundo.',
    'bsg_intro_p2' => 'Pero aquí está la verdad que la mayoría de las agencias de viajes no le dirán: <strong>Tanzania se puede hacer con un presupuesto ajustado.</strong> No un presupuesto de "mochilero", sino un safari cómodo, auténtico e inolvidable que no arruinará sus finanzas. El secreto está en entender el sistema: tarifas de parques, niveles de alojamiento, precios estacionales, dinámicas de grupo y conocimiento local.',
    'bsg_intro_p3' => 'Esta guía proviene de nuestro propio equipo de guías con base en Arusha. Es la guía que desearíamos que todo viajero leyera antes de solicitar un presupuesto, porque una vez que entienda a dónde va el dinero, sabrá exactamente cómo es un precio justo.',
    'bsg_intro_box' => '<strong>Lo que hace diferente a esta guía:</strong> Cada cifra aquí proviene de experiencia real: nuestros propios vehículos, nuestras propias rutas, nuestros propios precios negociados en cada camping y lodge. Esto no es teoría, es el conocimiento práctico de un operador local que vive y trabaja en Tanzania.',
    'bsg_quick_title' => 'Respuesta Rápida: ¿Cuánto Cuesta un Safari Económico en Tanzania?',
    'bsg_quick_p1' => 'Un safari económico en Tanzania normalmente cuesta <strong>€150–€300 por persona por día</strong>. El rango depende de varios factores:',
    'bsg_quick_li1' => '<strong>Tamaño del grupo:</strong> más personas implica un costo por persona menor: un grupo de 6 puede pagar tan poco como €150 por persona por día.',
    'bsg_quick_li2' => '<strong>Temporada:</strong> la temporada verde (marzo–mayo) ofrece las tarifas más bajas; la temporada seca (junio–octubre) es más cara.',
    'bsg_quick_li3' => '<strong>Tipo de alojamiento:</strong> el camping es la opción más económica; los campamentos de tiendas y los lodges aumentan el costo.',
    'bsg_quick_li4' => '<strong>Parques visitados:</strong> el Serengeti y el Ngorongoro tienen tarifas más altas que Tarangire o el Lago Manyara.',
    'bsg_quick_li5' => '<strong>Tipo de vehículo:</strong> compartir en grupo es más barato que un vehículo privado.',
    'bsg_quick_p2' => 'Para un <strong>safari de 3 días</strong>, presupueste aproximadamente <strong>€550–€750</strong>. Para un <strong>safari de 5 días</strong>, espere <strong>€1.000–€1.500</strong>. Para un <strong>safari de 7 días</strong>, presupueste <strong>€1.300–€2.000</strong>.',
    'bsg_quick_pro' => '<strong>Consejo profesional:</strong> el factor individual más importante para mantener bajos los costos es el <strong>tamaño del grupo</strong>. Viaje con 4–6 personas y ahorrará un 20–40% en comparación con un safari privado. El segundo factor más importante es la <strong>temporada</strong>: la temporada verde ofrece la mejor relación calidad-precio.',
    'bsg_quick_see_breakdown' => 'Ver el desglose completo de costos',

    'bsg_read_more' => 'Leer más',
    'bsg_read_less' => 'Leer menos',
    'bsg_toc_jump' => 'Ir a la sección',

    'bsg_packages_title' => 'Paquetes de Safari de Confianza: Reserve con Confianza',
    'bsg_packages_p1' => 'Entendemos que reservar un safari es una gran decisión. Por eso cada paquete a continuación está construido con total transparencia, sin cargos ocultos, y un compromiso con la calidad. Cada paquete incluye:',
    'bsg_packages_inc1' => 'Guía-conductor profesional, con dominio del inglés',
    'bsg_packages_inc2' => 'Vehículo de safari 4×4 moderno con techo abatible',
    'bsg_packages_inc3' => 'Tarifas de entrada a los parques y tasas de conservación',
    'bsg_packages_inc4' => 'Alojamiento según lo especificado: camping, campamento de tiendas o lodge',
    'bsg_packages_inc5' => 'Pensión completa y agua potable',
    'bsg_packages_inc6' => 'Soporte 24/7 y cancelación gratuita hasta 14 días antes de la salida',
    'bsg_packages_custom' => '¿Necesita un safari personalizado? <a href="%s">Contáctenos para un itinerario a medida</a>. Diseñaremos el safari adecuado para su grupo, presupuesto e intereses.',

    'bsg_pkg1_days' => '1 Día',
    'bsg_pkg1_name' => 'Safari Exprés Tarangire',
    'bsg_pkg1_route' => 'Parque Nacional Tarangire',
    'bsg_pkg1_price' => '€200',
    'bsg_pkg1_f1' => 'Safari de día completo, elefantes y baobabs',
    'bsg_pkg1_f2' => 'Almuerzo de picnic dentro del parque',
    'bsg_pkg1_f3' => 'Tarifas de parque incluidas',
    'bsg_pkg1_f4' => 'Cancelación gratuita hasta 14 días',
