    'bsg_cost_title' => 'Desglose Detallado de Costos: A Dónde Va Cada Euro',
    'bsg_cost_p1' => 'Uno de los mayores temores que tienen los viajeros son los costos ocultos. Creemos en la transparencia total. Aquí está exactamente a dónde va el dinero de su safari.',
    'bsg_cost_th1' => 'Componente',
    'bsg_cost_th2' => 'Qué cubre',
    'bsg_cost_th3' => '% típico del total',
    'bsg_cost_row1_label' => 'Tarifas de parque y tasas de conservación',
    'bsg_cost_row1_desc' => 'Entrada a parques nacionales, tarifas del cráter, rangers antifurtivos, conservación del hábitat',
    'bsg_cost_row1_pct' => '30–40%',
    'bsg_cost_row2_label' => 'Transporte y alquiler de vehículo',
    'bsg_cost_row2_desc' => 'Vehículo de safari 4×4, combustible, salario del guía-conductor, mantenimiento, seguro',
    'bsg_cost_row2_pct' => '25–35%',
    'bsg_cost_row3_label' => 'Alojamiento',
    'bsg_cost_row3_desc' => 'Tarifas de camping, campamento de tiendas, o lodge, varía según el tipo',
    'bsg_cost_row3_pct' => '15–20%',
    'bsg_cost_row4_label' => 'Comidas',
    'bsg_cost_row4_desc' => 'Pensión completa: desayuno, almuerzo (a menudo picnic en el monte), cena',
    'bsg_cost_row4_pct' => '10–15%',
    'bsg_cost_row5_label' => 'Guía y personal',
    'bsg_cost_row5_desc' => 'La experiencia de su guía, habilidades de rastreo, formación en seguridad',
    'bsg_cost_row5_pct' => '8–12%',
    'bsg_cost_insider' => '<strong>Secreto de iniciado:</strong> las tarifas de parque representan el 30–40% del costo total. Por eso elegir los parques correctos importa. Un safari de 5 días con Serengeti y Ngorongoro tendrá unos €300–€400 solo en tarifas de parque; un safari de 5 días con Tarangire, Manyara y Arusha NP tendrá unos €150–€200.',

    'bsg_parks_title' => 'Análisis Detallado de los Parques: Tarifas y Mejor Época',
    'bsg_parks_p1' => 'Cada parque tiene su propia tarifa de entrada, carácter y temporada ideal. Aquí hay un desglose honesto de los parques a los que hacemos safaris más a menudo.',
    'bsg_park1_name' => 'Serengeti',
    'bsg_park1_tier' => 'alto',
    'bsg_park1_fee' => 'Entrada: $82/día',
    'bsg_park1_desc' => 'El parque más famoso del mundo. Llanuras interminables, la Gran Migración, y la mayor densidad de depredadores de la Tierra.',
    'bsg_park1_best' => 'Mejor época: dic–jul para la migración, ago–oct para los cruces de río. Recomendado: 2–4 noches.',
    'bsg_park2_name' => 'Cráter del Ngorongoro',
    'bsg_park2_tier' => 'medio',
    'bsg_park2_fee' => 'Entrada: $71/día + $295 cráter',
    'bsg_park2_desc' => 'Un anfiteatro natural con la mayor densidad de fauna de África: los cinco Big Five presentes, incluido el rinoceronte negro.',
    'bsg_park2_best' => 'Mejor época: todo el año. Recomendado: 1–2 noches.',
    'bsg_park3_name' => 'Tarangire',
    'bsg_park3_tier' => 'bajo',
    'bsg_park3_fee' => 'Entrada: $53/día',
    'bsg_park3_desc' => 'Hogar de las mayores manadas de elefantes de Tanzania y de icónicos baobabs, con menos multitudes que el Serengeti.',
    'bsg_park3_best' => 'Mejor época: jun–oct (temporada seca). Recomendado: 1–2 noches.',
    'bsg_park4_name' => 'Lago Manyara',
    'bsg_park4_tier' => 'bajo',
    'bsg_park4_fee' => 'Entrada: $53/día',
    'bsg_park4_desc' => 'Famoso por sus leones trepadores de árboles, flamencos en el lago de soda, y un exuberante bosque de aguas subterráneas.',
    'bsg_park4_best' => 'Mejor época: todo el año. Recomendado: 1 noche.',
    'bsg_park5_name' => 'Parque Nacional Arusha',
    'bsg_park5_tier' => 'bajo',
    'bsg_park5_fee' => 'Entrada: $53/día',
    'bsg_park5_desc' => 'Safaris a pie, vistas del monte Meru y monos colobo: una excelente opción de medio día o día completo.',
    'bsg_park5_best' => 'Mejor época: todo el año. Recomendado: 1 día.',
    'bsg_park6_name' => 'Mikumi',
    'bsg_park6_tier' => 'bajo',
    'bsg_park6_fee' => 'Entrada: $35/día',
    'bsg_park6_desc' => '"Pequeño Serengeti": fauna de sabana clásica, fácil acceso desde Dar es Salaam. Ideal para safaris cortos y económicos.',
    'bsg_park6_best' => 'Mejor época: todo el año. Recomendado: 1–2 noches.',
    'bsg_park7_name' => 'Nyerere (Selous)',
    'bsg_park7_tier' => 'medio',
    'bsg_park7_fee' => 'Entrada: $53/día',
    'bsg_park7_desc' => 'La mayor área protegida de África. Safaris en barco por el río Rufiji, safaris a pie, licaones, elefantes e hipopótamos.',
    'bsg_park7_best' => 'Mejor época: jun–oct (seca). Recomendado: 2–3 noches.',
    'bsg_park8_name' => 'Ruaha',
    'bsg_park8_tier' => 'medio',
    'bsg_park8_fee' => 'Entrada: $35/día',
    'bsg_park8_desc' => 'Remoto, salvaje e impresionante: enormes manadas de elefantes, licaones y hermosos paisajes de baobabs.',
    'bsg_park8_best' => 'Mejor época: jun–oct (seca). Recomendado: 2–4 noches.',
    'bsg_parks_legend' => '$ = más económico (entrada bajo $40) · $$ = moderado ($40–$60) · $$$ = costo más alto (más de $60)',
    'bsg_parks_strategy' => '<strong>Estrategia económica:</strong> si tiene un presupuesto ajustado, concéntrese en parques con tarifas de entrada más bajas: Mikumi ($35), Ruaha ($35), Tarangire ($53) y el Lago Manyara ($53). El Serengeti y el Ngorongoro cuestan más pero ofrecen una fauna inigualable. La mayoría de los viajeros combinan 2 días en Tarangire, 2 en el Serengeti, 1 en el Ngorongoro y 1 en Manyara.',

    'bsg_acc_title' => 'Alojamiento Económico: Precios Reales de 2026',
    'bsg_acc_p1' => 'Su elección de alojamiento tiene el mayor impacto en su presupuesto de safari. Aquí hay opciones honestas cerca de los parques principales, con precios actuales.',
    'bsg_acc1_name' => 'Campings Públicos (dentro de los parques)',
    'bsg_acc1_price' => '$25–$30 <small>por persona / noche</small>',
    'bsg_acc1_loc' => 'Serengeti, Ngorongoro, Tarangire',
    'bsg_acc1_desc' => 'Instalaciones básicas, sonidos de fauna increíbles. Los campings de Seronera, Simba y Kikoti son los más populares. Reserve con antelación.',
    'bsg_acc2_name' => 'Campamentos de Tiendas Económicos',
    'bsg_acc2_price' => '$80–$120 <small>por persona / noche</small>',
    'bsg_acc2_loc' => 'Varios parques',
    'bsg_acc2_desc' => 'Tiendas de safari con acceso a pie, camas de verdad y baños privados: un excelente punto medio entre el camping y los lodges.',
    'bsg_acc3_name' => 'Lodges Económicos de Karatu',
    'bsg_acc3_price' => '$50–$80 <small>por habitación / noche</small>',
    'bsg_acc3_loc' => 'Karatu (cerca del Ngorongoro)',
    'bsg_acc3_desc' => 'Lodges asequibles justo fuera del Ngorongoro, mucho más baratos que el borde del cráter, con un acceso similar.',
    'bsg_acc4_name' => 'Casas de Huéspedes de Arusha y Moshi',
    'bsg_acc4_price' => '$35–$60 <small>por habitación / noche</small>',
    'bsg_acc4_loc' => 'Arusha / Moshi',
    'bsg_acc4_desc' => 'Habitaciones básicas pero limpias con desayuno: una buena base antes y después de su safari.',
    'bsg_acc_tip' => '<strong>Consejo de alojamiento:</strong> los campings públicos dentro de los parques nacionales se llenan rápidamente en temporada alta (junio–octubre). Reserve con 2–3 meses de antelación. Para lodges económicos, revise lugares justo fuera de los parques: a menudo 30–50% más baratos que dentro.',

    'bsg_tips_title' => 'Secretos Locales: De Nuestros Propios Guías',
    'bsg_tips_p1' => 'Consejos de iniciados de nuestro equipo de guías tanzanos, cosas que no encontrará en una guía de viajes. Estos le ahorrarán dinero y mejorarán su experiencia.',
    'bsg_tip1' => '<strong>El secreto de la "hora dorada"</strong> — los safaris son mejores al amanecer (6:00–8:30) y a última hora de la tarde (16:00–18:30). Muchos viajeros con presupuesto ajustado se saltan el safari matutino temprano — no sea uno de ellos.',
    'bsg_tip2' => '<strong>Ahorre en la tarifa del cráter</strong> — la tarifa de descenso al Ngorongoro ($295 por vehículo) es cara, pero pasar la noche en el borde para un safari de día completo aporta mucho más valor que uno de medio día.',
    'bsg_tip3' => '<strong>Coma como un local</strong> — un plato de ugali con pescado o carne en un puesto local de "mama lishe" cuesta $3–$5: seguro, delicioso y una fracción de los precios de restaurantes turísticos.',
    'bsg_tip4' => '<strong>La elección del vehículo importa</strong> — para safaris económicos, insista en un 4×4 con techo abatible. Los minibuses son más baratos pero ofrecen mala visibilidad y tienen dificultades en las carreteras irregulares del parque.',
    'bsg_tip5' => '<strong>El punto óptimo de temporada media</strong> — noviembre y diciembre (lluvias cortas) suelen ser breves chubascos por la tarde, no lluvia constante — y ofrecen tarifas más bajas con la misma fauna increíble.',
    'bsg_tip6' => '<strong>Aloje fuera del parque</strong> — pueblos como Mto wa Mbu (cerca de Manyara) o Karatu (cerca del Ngorongoro) son un 50–70% más baratos que los lodges dentro del parque, mientras sigue haciendo safaris de día completo.',
    'bsg_tip7' => '<strong>La estrategia del "madrugador"</strong> — salga del campamento a las 5:30 para ser el primero en el parque, ver a los depredadores cazando, y adelantarse a las multitudes que empiezan a llegar hacia las 9:00.',
    'bsg_tip8' => '<strong>La temporada baja está infravalorada</strong> — abril y mayo traen breves ráfagas de lluvia, paisajes increíblemente verdes, una avifauna espectacular, y los parques casi en exclusiva.',
    'bsg_tip9' => '<strong>Dé buena propina, dé propina con criterio</strong> — el estándar es $10–$20 por día para su guía y $5–$10 por día para el personal del campamento, en efectivo.',
    'bsg_tip10' => '<strong>Empaque ligero</strong> — los vehículos de safari tienen espacio limitado. Una bolsa de lona blanda es mejor que una maleta rígida.',

    'bsg_best_time_title' => 'Mejor Época para Ir: Guía Estacional',
    'bsg_best_time_p1' => 'Tanzania es un destino para todo el año, pero la experiencia de la fauna cambia con las estaciones.',
    'bsg_month_jan' => 'Comienzan los nacimientos · Cálido y seco',
    'bsg_month_feb' => 'Pico de nacimientos · Observación excelente',
    'bsg_month_mar' => 'Terminan los nacimientos · Paisajes exuberantes',
    'bsg_month_apr' => 'Lluvias largas · Tarifas más bajas',
    'bsg_month_may' => 'Las lluvias disminuyen · Excelente relación calidad-precio',
    'bsg_month_jun' => 'Temporada seca · Cruces del Grumeti',
    'bsg_month_jul' => 'Cruces del Mara · Temporada alta',
    'bsg_month_aug' => 'Cruces del Mara · Mes más concurrido',
    'bsg_month_sep' => 'Manadas en el norte · Aún concurrido',
    'bsg_month_oct' => 'Las manadas se mueven al sur · Buena relación calidad-precio',
    'bsg_month_nov' => 'Lluvias cortas · Excelente relación calidad-precio',
    'bsg_month_dec' => 'Temporada verde · Gran fotografía',
    'bsg_best_time_box' => '<strong>Mejores ventanas económicas:</strong> noviembre–diciembre (lluvias cortas) y marzo–mayo (lluvias largas) ofrecen tarifas más bajas, menos multitudes y paisajes exuberantes: ideal para quienes buscan valor.',

    'bsg_itin_title' => 'Itinerarios de Muestra',
    'bsg_itin_p1' => 'Un vistazo día a día de lo que realmente incluyen nuestros paquetes económicos más populares.',
    'bsg_itin1_name' => 'Safari Clásico del Serengeti de 3 Días',
    'bsg_itin1_days' => '3 días / 2 noches',
    'bsg_itin1_route' => 'Arusha → Serengeti Central → Ngorongoro → Arusha',
    'bsg_itin1_detail' => '<strong>Día 1:</strong> Arusha → Serengeti, safari en ruta, noche en campamento de tiendas.<br><strong>Día 2:</strong> Safari de día completo en el Serengeti, noche en campamento de tiendas.<br><strong>Día 3:</strong> Descenso al Cráter del Ngorongoro, regreso a Arusha.',
    'bsg_itin1_price' => 'Desde €1.000 por persona',
    'bsg_itin2_name' => 'Circuito Norte Clásico de 5 Días',
    'bsg_itin2_days' => '5 días / 4 noches',
    'bsg_itin2_route' => 'Arusha → Tarangire → Serengeti → Ngorongoro → Arusha',
    'bsg_itin2_detail' => '<strong>Día 1:</strong> Arusha → Tarangire, safari por la tarde.<br><strong>Día 2:</strong> Tarangire → Serengeti, safari en ruta.<br><strong>Día 3:</strong> Safari de día completo en el Serengeti.<br><strong>Día 4:</strong> Serengeti → Ngorongoro, descenso al cráter.<br><strong>Día 5:</strong> Regreso a Arusha.',
    'bsg_itin2_price' => 'Desde €1.450 por persona',

    'bsg_faq_title' => 'Preguntas Frecuentes',
    'bsg_faq_q1' => '¿Cuánto cuesta un safari económico en Tanzania?',
    'bsg_faq_a1' => 'Normalmente €150–€300 por persona por día, dependiendo del tamaño del grupo, la temporada, el alojamiento y los parques visitados.',
    'bsg_faq_q2' => '¿Cuál es el mes más económico para un safari en Tanzania?',
    'bsg_faq_a2' => 'Abril y mayo (las lluvias largas) ofrecen las tarifas más bajas, con paisajes exuberantes y menos multitudes.',
    'bsg_faq_q3' => '¿Cuál es el parque nacional más económico de Tanzania?',
    'bsg_faq_a3' => 'Mikumi, el Parque Nacional Arusha y el Lago Manyara tienen las tarifas de entrada más bajas.',
    'bsg_faq_q4' => '¿Es seguro acampar en un safari en Tanzania?',
    'bsg_faq_a4' => 'Sí, los campings públicos dentro de los parques nacionales están patrullados y son ampliamente usados por viajeros con presupuesto ajustado. Los guías le informan sobre la seguridad del campamento al llegar.',
    'bsg_faq_q5' => '¿Puedo negociar los precios de safari en Tanzania?',
    'bsg_faq_a5' => 'Los precios de operadores locales licenciados suelen ser ya justos y transparentes. Desconfíe de presupuestos inusualmente baratos, ya que a menudo ocultan costos adicionales en la puerta.',
    'bsg_faq_q6' => '¿Necesito un vehículo privado para un safari económico?',
    'bsg_faq_a6' => 'No, los safaris compartidos en grupo con 4–6 viajeros reducen significativamente el costo por persona mientras siguen dando a todos un asiento junto a la ventana.',
    'bsg_faq_q7' => '¿Qué incluye un paquete de safari económico?',
    'bsg_faq_a7' => 'Normalmente un guía-conductor, vehículo 4×4, tarifas de parque, alojamiento según lo especificado, pensión completa y agua potable. Confirme siempre exactamente qué se incluye antes de reservar.',
    'bsg_faq_q8' => '¿Con cuánta antelación debo reservar?',
    'bsg_faq_a8' => 'Para temporada alta (junio–octubre), reserve con 3–6 meses de antelación. Para temporada media y baja, 4–6 semanas suele ser suficiente.',

    'bsg_book_title' => 'Reserve Su Safari Económico',
    'bsg_book_p1' => 'Rellene los datos a continuación y nuestro equipo responderá dentro de 24 horas con disponibilidad y un precio exacto.',
    'bsg_cta_title' => '¿Listo para Ver Tanzania a Su Manera?',
    'bsg_cta_p' => 'Obtenga un presupuesto gratuito y sin compromiso de un operador local de Arusha: precios honestos, sin intermediarios.',
    'bsg_cta_button' => 'Obtener Su Presupuesto Gratis',
    'bsg_share_label' => 'Comparta esta guía:',
    'bsg_print' => 'Imprimir Guía',
