    'lsg_meta_title' => 'La Guía Definitiva de Safari de Lujo en Tanzania: Lodges Exclusivos, Precios y Paquetes a Medida',
    'lsg_meta_description' => 'La guía definitiva de safari de lujo en Tanzania. Lodges exclusivos, guiado privado, análisis detallado de costos, consejos de iniciados y paquetes a medida de un operador local de Arusha.',

    'lsg_badge' => 'La Guía Completa de Lujo 2026',
