    'lsg_price_highlight_small' => 'por persona',
    'lsg_hero_intro' => 'Todo lo que necesita antes de reservar: qué significa el verdadero lujo en un safari, lodges exclusivos, guiado privado, desgloses de costos honestos, y, una vez que sepa por qué está pagando, nuestros paquetes a medida.',
