    'lsg_intro_title' => 'El Arte del Safari de Lujo',
    'lsg_intro_p1' => 'Un safari de lujo en Tanzania no es solo unas vacaciones. Es una experiencia que cambia la vida. Despertar con el dorado amanecer africano, el rugido lejano de un león en las llanuras, rastrear un leopardo con un guía que ha pasado décadas aprendiendo los secretos de la naturaleza salvaje.',
    'lsg_intro_p2' => 'Pero el lujo no se trata simplemente del precio. Se trata de <strong>exclusividad, personalización y atención meticulosa al detalle</strong>. Un vehículo privado y un guía dedicado que anticipa sus necesidades. Lodges que son maravillas arquitectónicas fusionadas con el paisaje mientras ofrecen todas las comodidades modernas.',
    'lsg_intro_p3' => 'Esta guía proviene de nuestro propio equipo de especialistas con base en Arusha que han creado safaris de lujo durante años. Cada lodge y experiencia enumerados aquí ha sido verificado personalmente. No solo vendemos lujo, lo seleccionamos.',
    'lsg_intro_box' => '<strong>Lo que nos distingue:</strong> no somos una plataforma de reservas. Somos un equipo local que ha estado creando safaris de lujo durante años. Cada lodge y cada experiencia se verifica personalmente, para que tenga acceso a conocimientos de iniciados que no encontrará en ningún otro lugar.',

    'lsg_quick_title' => 'Respuesta Rápida: ¿Cuánto Cuesta un Safari de Lujo en Tanzania?',
    'lsg_quick_p1' => 'Un safari de lujo en Tanzania normalmente cuesta <strong>€350–€1.200+ por persona por noche</strong>. Este amplio rango refleja la diversidad de ofertas de lujo, desde campamentos de tiendas boutique hasta villas privadas ultra exclusivas.',
    'lsg_quick_li1' => '<strong>Lujo premium:</strong> €350–€600/noche: excelentes campamentos de tiendas, vehículo privado, servicio superior.',
    'lsg_quick_li2' => '<strong>Ultra lujo:</strong> €600–€900/noche: lodges de talla mundial, guías de élite, a menudo vuelos chárter privados.',
    'lsg_quick_li3' => '<strong>Privado exclusivo:</strong> €900–€1.200+/noche: villas privadas, servicio de mayordomo, exclusividad total.',
    'lsg_quick_li4' => '<strong>Temporada:</strong> los meses de temporada media (noviembre–diciembre, febrero) ofrecen los mismos lodges a tarifas un 20–30% más bajas.',
    'lsg_quick_li5' => '<strong>Privado vs grupo:</strong> un vehículo y guía privados cuestan más pero definen lo que realmente significa "lujo".',
    'lsg_quick_p2' => 'Para un <strong>safari de lujo de 5 días</strong>, presupueste aproximadamente <strong>€1.800–€3.500 por persona</strong>. Para un <strong>safari de 7 días</strong>, espere <strong>€2.500–€5.000</strong>. Para un <strong>safari de 10 días con Zanzíbar</strong>, presupueste <strong>€3.800–€7.000+</strong>.',
    'lsg_quick_pro' => '<strong>Consejo profesional:</strong> el mejor valor en safaris de lujo proviene de viajar en las <strong>temporadas medias</strong> (noviembre–diciembre y febrero). Los mismos lodges exclusivos, los mismos guías expertos, a menudo tarifas un 20–30% más bajas, con menos multitudes y una experiencia más íntima.',

    'lsg_packages_title' => 'Paquetes de Safari de Lujo: Curados para Viajeros Exigentes',
    'lsg_packages_p1' => 'Cada paquete está elaborado por nuestros especialistas en safaris de lujo, desde la selección del lodge hasta el momento de los safaris. Cada paquete incluye:',
    'lsg_packages_inc1' => 'Vehículo de safari 4×4 privado con techo abatible',
    'lsg_packages_inc2' => 'Guía de élite certificado con años de experiencia en safaris de lujo',
    'lsg_packages_inc3' => 'Lodges de lujo seleccionados a mano, verificados personalmente por nuestro equipo',
    'lsg_packages_inc4' => 'Comidas gourmet en pensión completa y bebidas premium',
    'lsg_packages_inc5' => 'Todas las tarifas de parque y tasas de conservación',
    'lsg_packages_inc6' => 'Soporte dedicado 24/7, desde la reserva hasta la salida',
    'lsg_packages_custom' => '¿Necesita un itinerario totalmente personalizado? <a href="%s">Contacte a nuestros especialistas en safaris de lujo</a>. Diseñaremos el safari perfecto para su grupo, presupuesto y sueños.',

