    'lsg_cost_title' => 'Desglose Detallado de Costos: A Dónde Va Cada Euro',
    'lsg_cost_p1' => 'La transparencia es la base de la confianza. Aquí hay un desglose granular de exactamente a dónde va su inversión en el safari de lujo.',
    'lsg_cost_th1' => 'Componente',
    'lsg_cost_th2' => 'Qué cubre',
    'lsg_cost_th3' => '% típico del total',
    'lsg_cost_row1_label' => 'Alojamiento',
    'lsg_cost_row1_desc' => 'Lodges ultra lujosos, villas privadas, campamentos de tiendas: diseño, servicio, ubicación',
    'lsg_cost_row1_pct' => '40–50%',
    'lsg_cost_row2_label' => 'Transporte y vuelos chárter',
    'lsg_cost_row2_desc' => 'Vehículos 4×4 privados, vuelos chárter privados, traslados de lujo',
    'lsg_cost_row2_pct' => '20–30%',
    'lsg_cost_row3_label' => 'Servicios de guía experto',
    'lsg_cost_row3_desc' => 'Guías de élite certificados con años de experiencia en safaris de lujo',
    'lsg_cost_row3_pct' => '10–15%',
    'lsg_cost_row4_label' => 'Tarifas de parque y conservación',
    'lsg_cost_row4_desc' => 'Tarifas de entrada, descenso al cráter, tasas de conservación, antifurtivismo',
    'lsg_cost_row4_pct' => '10–15%',
    'lsg_cost_row5_label' => 'Experiencias exclusivas',
    'lsg_cost_row5_desc' => 'Globo aerostático, cena privada en el monte, spa, safaris a pie',
    'lsg_cost_row5_pct' => '5–10%',
    'lsg_cost_insider' => '<strong>La verdadera diferencia:</strong> un safari "premium" ofrece buena calidad pero probablemente compartirá vehículo y tendrá menos flexibilidad. Un <strong>safari de lujo</strong> significa exclusividad total: un vehículo privado, un guía dedicado que conoce sus preferencias, y experiencias adaptadas enteramente a usted.',

    'lsg_lodges_title' => 'Mejores Lodges de Lujo: Seleccionados a Mano por Excelencia',
    'lsg_lodges_p1' => 'Estos están entre los mejores lodges de lujo de Tanzania, verificados personalmente por nuestro equipo. Cada uno ofrece un entorno único, un servicio excepcional y una experiencia inolvidable.',
    'lsg_lodge1_name' => 'Singita Sasakwa Lodge',
    'lsg_lodge1_tier' => 'alto',
    'lsg_lodge1_fee' => '$1.800–$3.200/noche',
    'lsg_lodge1_desc' => 'Lodge de estilo eduardiano con vistas panorámicas del Serengeti, piscinas infinitas privadas y servicio de mayordomo.',
    'lsg_lodge1_best' => 'Ubicación: Serengeti (Reserva Grumeti). Mejor para: avistamientos excepcionales de grandes felinos.',
    'lsg_lodge2_name' => '&amp;Beyond Serengeti Under Canvas',
    'lsg_lodge2_tier' => 'alto',
    'lsg_lodge2_fee' => '$1.200–$1.900/noche',
    'lsg_lodge2_desc' => 'Un campamento de lujo móvil que sigue la migración, con elegancia de safari clásica y comodidades modernas.',
    'lsg_lodge2_best' => 'Ubicación: Serengeti (móvil). Mejor para: una observación de la migración inigualable.',
    'lsg_lodge3_name' => 'Four Seasons Safari Lodge',
    'lsg_lodge3_tier' => 'medio',
    'lsg_lodge3_fee' => '$950–$1.600/noche',
    'lsg_lodge3_desc' => 'Lujo de talla mundial con una piscina infinita sobre un abrevadero, un spa galardonado y un servicio apto para familias.',
    'lsg_lodge3_best' => 'Ubicación: Serengeti. Mejor para: familias y viajeros de lujo primerizos.',
    'lsg_lodge4_name' => 'Ngorongoro Crater Lodge',
    'lsg_lodge4_tier' => 'alto',
    'lsg_lodge4_fee' => '$1.400–$2.200/noche',
    'lsg_lodge4_desc' => 'Arquitectura impresionante encaramada en el borde del cráter, con suites opulentas y vistas inigualables del cráter.',
    'lsg_lodge4_best' => 'Ubicación: borde del Ngorongoro. Mejor para: el entorno más espectacular de África.',
    'lsg_lodge5_name' => 'Tarangire Treetops',
    'lsg_lodge5_tier' => 'medio',
    'lsg_lodge5_fee' => '$800–$1.400/noche',
    'lsg_lodge5_desc' => 'Suites elevadas en casas del árbol sobre Tarangire, con enormes manadas de elefantes y baobabs icónicos.',
    'lsg_lodge5_best' => 'Ubicación: Tarangire. Mejor para: una estancia única e inolvidable.',
    'lsg_lodge6_name' => 'Zuri Zanzibar',
    'lsg_lodge6_tier' => 'medio',
    'lsg_lodge6_fee' => '$600–$1.200/noche',
    'lsg_lodge6_desc' => 'Resort de lujo frente a la playa con piscinas infinitas, un spa de talla mundial y una gastronomía excepcional.',
    'lsg_lodge6_best' => 'Ubicación: Zanzíbar. Mejor para: el final de playa perfecto para la luna de miel.',

    'lsg_exp_title' => 'Experiencias Exclusivas: La Diferencia del Lujo',
    'lsg_exp_p1' => 'Lo que realmente distingue a un safari de lujo son las experiencias que el dinero normalmente no puede comprar, pero que nosotros podemos organizar.',
    'lsg_exp1' => '<strong>Safari en globo aerostático</strong> — flote silenciosamente sobre el Serengeti al amanecer con un desayuno con champán en el monte. Desde €500 por persona.',
    'lsg_exp2' => '<strong>Cena privada en el monte</strong> — una cena a la luz de las velas en plena naturaleza con un chef privado, buenos vinos y un camarero personal. Desde €300 por pareja.',
    'lsg_exp3' => '<strong>Safari en avioneta</strong> — evite los trayectos largos y vuele directamente a su lodge en un chárter privado, usando aeronaves modernas con buenos historiales de seguridad. Desde €500 por vuelo.',
    'lsg_exp4' => '<strong>Safari a pie con un guía de élite</strong> — rastree animales y aprenda sobre el monte a pie con un guía experto. Desde €200 por persona.',
    'lsg_exp5' => '<strong>Safari fotográfico privado</strong> — safaris dedicados con un guía formado en fotografía de fauna, posicionándose para la mejor luz. Desde €300 extra por día.',
    'lsg_exp6' => '<strong>Retiro de spa y bienestar</strong> — relájese después de los safaris con tratamientos inspirados en tradiciones africanas. Desde €100 por tratamiento.',
    'lsg_exp_box' => '<strong>Nuestra promesa:</strong> cada experiencia que ofrecemos se verifica personalmente. Trabajamos con los mejores operadores, guías y lugares para asegurar que sea impecable. Si no está a la altura de nuestro estándar, no lo recomendamos.',

    'lsg_best_time_title' => 'Mejor Época para un Safari de Lujo: Guía Estacional',
    'lsg_best_time_p1' => 'Para los viajeros de lujo, la mejor época suele ser la temporada media: los mismos lodges y guías exclusivos a una tarifa notablemente más baja.',
    'lsg_month_jan' => 'Nacimientos · Premium',
    'lsg_month_feb' => 'Pico de nacimientos · Mejor relación calidad-precio',
    'lsg_month_mar' => 'Temporada verde · Gran relación calidad-precio',
    'lsg_month_apr' => 'Lluvias largas · Tarifas más bajas',
    'lsg_month_may' => 'Las lluvias disminuyen · Buena relación calidad-precio',
    'lsg_month_jun' => 'Temporada seca · Premium',
    'lsg_month_jul' => 'Cruces del Mara · Máxima afluencia',
    'lsg_month_aug' => 'Mes más concurrido · Premium',
    'lsg_month_sep' => 'Manadas en el norte · Premium',
    'lsg_month_oct' => 'Buena relación calidad-precio · Multitudes disminuyendo',
    'lsg_month_nov' => 'Lluvias cortas · Mejor relación calidad-precio',
    'lsg_month_dec' => 'Temporada verde · Gran relación calidad-precio',
    'lsg_best_time_box' => '<strong>Mejor ventana de valor:</strong> noviembre–diciembre y febrero ofrecen los mismos lodges y guías exclusivos a tarifas un 20–30% más bajas, con menos multitudes y una experiencia más íntima.',

    'lsg_itin_title' => 'Itinerarios de Lujo de Muestra',
    'lsg_itin_p1' => 'Un vistazo día a día de lo que realmente incluyen nuestros paquetes de lujo más solicitados.',
    'lsg_itin1_name' => 'Safari de Lujo Clásico de 5 Días',
    'lsg_itin1_days' => '5 días / 4 noches',
    'lsg_itin1_route' => 'Tarangire + Ngorongoro + Serengeti',
    'lsg_itin1_detail' => '<strong>Día 1:</strong> Llegada a Arusha, chárter privado a Tarangire, safari por la tarde.<br><strong>Día 2:</strong> Tarangire → Ngorongoro, descenso al cráter de día completo con guía privado.<br><strong>Día 3:</strong> Ngorongoro → Serengeti, chárter privado, safari por la tarde.<br><strong>Día 4:</strong> Día completo en el Serengeti: safaris por la mañana y la tarde, globo aerostático opcional.<br><strong>Día 5:</strong> Safari matutino, chárter privado a Arusha, salida.',
    'lsg_itin1_price' => 'Desde €2.300 por persona',
    'lsg_itin2_name' => 'El Definitivo Serengeti y Cráter de 7 Días',
    'lsg_itin2_days' => '7 días / 6 noches',
    'lsg_itin2_route' => 'Serengeti + Ngorongoro + Manyara',
    'lsg_itin2_detail' => '<strong>Días 1–2:</strong> Serengeti: 2 noches en un lodge ultra lujoso, cobertura completa de la migración.<br><strong>Días 3–4:</strong> Serengeti: 2 noches en un campamento móvil siguiendo la migración.<br><strong>Día 5:</strong> Serengeti → Ngorongoro, chárter privado, noche en el borde del cráter.<br><strong>Día 6:</strong> Ngorongoro → Manyara, chárter privado.<br><strong>Día 7:</strong> Manyara → Arusha, salida.',
    'lsg_itin2_price' => 'Desde €6.900 por persona',

    'lsg_faq_title' => 'Preguntas Frecuentes',
    'lsg_faq_q1' => '¿Cuánto cuesta un safari de lujo en Tanzania?',
    'lsg_faq_a1' => 'Normalmente €350–€1.200+ por persona por noche, dependiendo de la categoría del lodge, si el vehículo y el guía son privados, y la temporada.',
    'lsg_faq_q2' => '¿Cuál es el lodge más exclusivo del Serengeti?',
    'lsg_faq_a2' => 'Singita Sasakwa, &Beyond Serengeti Under Canvas y Ngorongoro Crater Lodge están entre las propiedades más exclusivas con las que trabajamos.',
    'lsg_faq_q3' => '¿Qué incluye un safari de lujo?',
    'lsg_faq_a3' => 'Un vehículo 4×4 privado, un guía de élite, alojamiento de lujo, todas las comidas, bebidas premium, tarifas de parque, y a menudo vuelos chárter privados.',
    'lsg_faq_q4' => '¿Siempre se incluye un vehículo privado?',
    'lsg_faq_a4' => 'Sí, en todos los paquetes de esta página, el vehículo y el guía son privados para su grupo, no compartidos con otros viajeros.',
    'lsg_faq_q5' => '¿Cuál es la mejor época para un safari de lujo?',
    'lsg_faq_a5' => 'Noviembre–diciembre y febrero ofrecen los mismos lodges exclusivos a tarifas un 20–30% más bajas. Junio–septiembre es temporada alta para la observación de la migración pero la más concurrida y cara.',
    'lsg_faq_q6' => '¿Pueden los niños unirse a un safari de lujo?',
    'lsg_faq_a6' => 'Sí, varios de nuestros lodges asociados (Four Seasons, Zuri Zanzibar) ofrecen suites familiares y programas para niños.',
    'lsg_faq_q7' => '¿Los paquetes de lujo incluyen vuelos internos?',
    'lsg_faq_a7' => 'Los paquetes en avioneta incluyen vuelos chárter internos; los itinerarios terrestres pueden añadirlos como opción para ahorrar tiempo de conducción.',
    'lsg_faq_q8' => '¿Con cuánta antelación debo reservar un safari de lujo?',
    'lsg_faq_a8' => 'Los mejores lodges se reservan con 6–12 meses de antelación para la temporada alta (junio–septiembre). Para la temporada media, 3–4 meses suele ser suficiente.',

    'lsg_book_title' => 'Consulte Sobre Su Safari de Lujo',
    'lsg_book_p1' => 'Rellene los datos a continuación y nuestro especialista en safaris de lujo responderá dentro de 12 horas con un itinerario personalizado.',
    'lsg_cta_title' => '¿Listo para un Safari Creado en Torno a Usted?',
    'lsg_cta_p' => 'Obtenga una propuesta a medida y sin compromiso de un especialista local de Arusha: lodges exclusivos, precios honestos.',
    'lsg_cta_button' => 'Consultar Ahora',
    'lsg_share_label' => 'Comparta esta guía:',
    'lsg_print' => 'Imprimir Guía',

