    'mgg_meta_title' => 'La Guía de la Gran Migración: Mes a Mes, Cruces de Ríos, Precios y Paquetes',
    'mgg_meta_description' => 'La guía definitiva de la Gran Migración del Serengeti. Movimientos mes a mes, estrategia de cruces de ríos, temporada de nacimientos, alojamiento y paquetes de safari de migración de confianza.',

    'mgg_badge' => 'La Guía Completa de la Migración 2026',
    'mgg_h1' => 'La Gran Migración: La Guía Completa',
    'mgg_price_highlight' => 'Desde €200',
    'mgg_price_highlight_small' => 'por persona / día',
    'mgg_hero_intro' => 'Todo lo que necesita antes de reservar: dónde están las manadas cada mes, cómo funcionan realmente los cruces de ríos, precios de alojamiento honestos, y, una vez que sepa qué está persiguiendo, nuestros paquetes de migración de confianza.',
