    'mgg_intro_title' => 'El Mayor Espectáculo de Fauna en la Tierra',
    'mgg_intro_p1' => 'La Gran Migración no es solo un evento de fauna. Es el mayor espectáculo de fauna del planeta. Cada año, más de <strong>1,5 millones de ñus</strong>, junto con <strong>200.000 cebras</strong>, se mueven en una peregrinación continua y circular por el ecosistema Serengeti-Mara, cubriendo aproximadamente <strong>800 kilómetros</strong> al año.',
    'mgg_intro_p2' => 'Pero la Gran Migración no se trata solo de números. Se trata de drama, supervivencia y el poder puro de la naturaleza. Es el retumbar de los cascos por las llanuras, el espectáculo sobrecogedor de los cruces de ríos, y los momentos íntimos de nacimiento y depredación.',
    'mgg_intro_p3' => 'Esta guía proviene de nuestro propio equipo de guías con base en Arusha que sigue a las manadas todo el año. Sabemos dónde encontrarlas, cuándo encontrarlas, y cómo darle la mejor experiencia posible.',
    'mgg_intro_box' => '<strong>Por qué esta guía es diferente:</strong> no solo leemos sobre la Migración. Nuestros guías están en el Serengeti siguiendo a las manadas y prediciendo sus movimientos. Cada consejo aquí proviene de experiencia real, no de información genérica.',

    'mgg_route_title' => 'La Ruta de la Migración: Entendiendo el Ciclo',
    'mgg_route_p1' => 'La migración sigue una ruta circular por el ecosistema Serengeti-Mara, impulsada enteramente por las lluvias y la disponibilidad de pasto fresco. Entender esta ruta es esencial para planificar su safari.',
    'mgg_route_box' => '<strong>Sur del Serengeti (Ndutu)</strong> → enero–marzo (Nacimientos)<br><strong>Centro y oeste del Serengeti</strong> → abril–mayo (Dispersión)<br><strong>Corredor Occidental (Grumeti)</strong> → junio–julio (Cruces del Grumeti)<br><strong>Norte del Serengeti (río Mara)</strong> → julio–septiembre (Cruces del Mara)<br><strong>Centro del Serengeti</strong> → octubre–noviembre (Regreso al Sur)<br><strong>Sur del Serengeti (Ndutu)</strong> → diciembre (Pre-nacimientos)',
    'mgg_route_tip' => '<strong>Idea clave:</strong> la migración no es una sola manada moviéndose junta. Es una serie de manadas moviéndose en diferentes direcciones. Entender el patrón general le ayuda a planificar, pero los guías locales pueden decirle exactamente dónde están las manadas en un momento dado.',

    'mgg_months_title' => 'Mes a Mes: Dónde, Qué y Por Qué',
    'mgg_months_p1' => 'Un desglose detallado, mes a mes, de la Gran Migración. Para cada mes, exactamente dónde están las manadas y qué puede esperar ver.',
    'mgg_m_jan_loc' => 'Sur del Serengeti (Ndutu)',
    'mgg_m_jan_desc' => 'Las manadas llegan a las llanuras de pasto corto. Comienza la temporada de nacimientos, con depredadores activos cerca.',
    'mgg_m_feb_loc' => 'Sur del Serengeti (Ndutu)',
    'mgg_m_feb_desc' => 'Pico de la temporada de nacimientos: más de 8.000 crías nacen cada día. Uno de los momentos más dramáticos para presenciar el ciclo de la vida.',
    'mgg_m_mar_loc' => 'Centro y oeste del Serengeti',
    'mgg_m_mar_desc' => 'Las manadas comienzan a moverse hacia el oeste y el norte a medida que las llanuras del sur empiezan a secarse.',
    'mgg_m_apr_loc' => 'Corredor Occidental (Grumeti)',
    'mgg_m_apr_desc' => 'Llegan las lluvias largas y las manadas se reúnen en el Corredor Occidental, preparando el escenario para los primeros cruces.',
    'mgg_m_may_loc' => 'Corredor Occidental (río Grumeti)',
    'mgg_m_may_desc' => 'Las manadas se concentran alrededor del río Grumeti. Comienzan los primeros cruces dramáticos.',
    'mgg_m_jun_loc' => 'Oeste y norte del Serengeti',
    'mgg_m_jun_desc' => 'Las manadas avanzan hacia el norte, hacia el río Mara, mientras comienza la temporada seca.',
    'mgg_m_jul_loc' => 'Norte del Serengeti (río Mara)',
    'mgg_m_jul_desc' => 'Las manadas llegan al río Mara. Comienzan los icónicos cruces.',
    'mgg_m_aug_loc' => 'Norte del Serengeti (río Mara)',
    'mgg_m_aug_desc' => 'Pico de los cruces del río Mara: el momento más concurrido y espectacular para presenciar la migración.',
    'mgg_m_sep_loc' => 'Norte del Serengeti (río Mara)',
    'mgg_m_sep_desc' => 'Los cruces continúan con algo menos de afluencia. La observación de fauna sigue siendo excepcional.',
    'mgg_m_oct_loc' => 'Norte y centro del Serengeti',
    'mgg_m_oct_desc' => 'Las manadas comienzan su viaje hacia el sur. Buena relación calidad-precio con menos multitudes.',
    'mgg_m_nov_loc' => 'Centro y sur del Serengeti',
    'mgg_m_nov_desc' => 'Comienzan las lluvias cortas y las manadas regresan a las llanuras del sur, preparándose para la próxima temporada de nacimientos.',
    'mgg_m_dec_loc' => 'Sur del Serengeti (Ndutu)',
    'mgg_m_dec_desc' => 'Las manadas se asientan en las llanuras del sur, pastando en hierba rica en nutrientes mientras el ciclo comienza de nuevo.',

    'mgg_packages_title' => 'Paquetes de Migración de Confianza: Reserve con Confianza',
    'mgg_packages_p1' => 'Programados según la fase de migración que quiera ver, cada paquete a continuación está construido con total transparencia y sin cargos ocultos. Cada paquete incluye:',
    'mgg_packages_inc1' => 'Guía-conductor profesional, con dominio del inglés',
