    'mgg_packages_inc6' => 'Soporte 24/7 y cancelación gratuita hasta 14 días antes de la salida',
    'mgg_packages_custom' => '¿No está seguro de qué fase perseguir? <a href="%s">Contáctenos y cuéntenos sus fechas de viaje</a>. Le diremos exactamente qué verá.',

