    'mgg_crossings_title' => 'Cruces de Ríos: La Guía Experta Definitiva',
    'mgg_crossings_p1' => 'Los cruces de ríos son los momentos más icónicos y dramáticos de la Gran Migración. Dos ríos son el escenario: el río Grumeti en el Corredor Occidental y el río Mara en el norte.',
    'mgg_crossings_grumeti_title' => 'Cruces del Río Grumeti: El Drama del Oeste',
    'mgg_crossings_grumeti_p' => 'Los cruces del Grumeti son los primeros grandes obstáculos de agua que enfrentan las manadas. Menos famosos que el río Mara, pero igualmente dramáticos y con mucha menos afluencia, hogar de algunos de los cocodrilos más grandes de África.',
    'mgg_crossings_grumeti_tip' => '<strong>Mejor época:</strong> finales de mayo a principios de julio. <strong>Secreto de iniciado:</strong> los cruces del Grumeti suelen ser más caóticos que los del Mara. Los ñus son menos experimentados, lo que hace los cruces más salvajes.',
    'mgg_crossings_mara_title' => 'Cruces del Río Mara: El Espectáculo Mundialmente Famoso',
    'mgg_crossings_mara_p' => 'Los cruces del río Mara son el espectáculo de fauna más famoso de la Tierra. Cientos de miles de ñus y cebras se reúnen en las orillas del río antes de lanzarse a aguas infestadas de cocodrilos.',
    'mgg_crossings_mara_tip' => '<strong>Mejor época:</strong> mediados de julio a finales de agosto. <strong>Consejo de observación:</strong> los cruces son impredecibles. Puede que necesite esperar varias horas, muy probablemente por la mañana temprano o a última hora de la tarde.',
    'mgg_crossings_pro' => '<strong>Consejo profesional:</strong> para evitar las multitudes en el río Mara, considere los cruces del río Grumeti en junio: un drama similar, una fracción de los turistas, y precios más bajos.',

    'mgg_calving_title' => 'Temporada de Nacimientos: El Círculo de la Vida',
    'mgg_calving_p1' => 'Entre <strong>enero y marzo</strong>, el sur del Serengeti se convierte en el escenario de uno de los eventos más extraordinarios de la naturaleza: la temporada de nacimientos de los ñus. Más de <strong>500.000 crías</strong> nacen en cuestión de semanas, con hasta <strong>8.000 nacimientos por día</strong> en el pico.',
    'mgg_calving_p2' => 'Este es un momento de intensa actividad de depredadores: leones, guepardos, leopardos e hienas siguen de cerca a las manadas, aprovechando la abundancia de crías recién nacidas.',
    'mgg_calving_box' => '<strong>Datos rápidos de la temporada de nacimientos:</strong> más de 500.000 crías nacidas al año, más de 8.000 nacimientos por día en el pico, mejor observación en la zona de Ndutu, excelente para fotografía gracias al pasto corto y la suave luz matutina.',

    'mgg_acc_title' => 'Dónde Alojarse: Alojamiento de Migración',
    'mgg_acc_p1' => 'Elegir el alojamiento correcto para la fase de migración correcta importa. Aquí hay opciones honestas para todos los presupuestos.',
    'mgg_acc1_name' => 'Campings Públicos del Serengeti y Ndutu',
    'mgg_acc1_price' => '$25–$30 <small>por persona / noche</small>',
    'mgg_acc1_loc' => 'Seronera, Ndutu, Grumeti',
    'mgg_acc1_desc' => 'Instalaciones básicas, sonidos de fauna increíbles, dentro del parque. Reserve con antelación. Se llenan rápido en temporada alta.',
    'mgg_acc2_name' => 'Campamentos de Tiendas de Gama Media',
    'mgg_acc2_price' => '$150–$250 <small>por persona / noche</small>',
    'mgg_acc2_loc' => 'Centro y oeste del Serengeti',
    'mgg_acc2_desc' => 'Baños privados, comedor central, excelente acceso a la migración sin el precio del ultra lujo.',
    'mgg_acc3_name' => 'Campamentos Móviles que Siguen a las Manadas',
    'mgg_acc3_price' => '$120–$180 <small>por persona / noche</small>',
    'mgg_acc3_loc' => 'Se mueve con la migración',
    'mgg_acc3_desc' => 'Campamentos que se trasladan durante la temporada para mantenerse cerca de la acción: un acceso a la fauna inigualable.',
    'mgg_acc4_name' => 'Lodges de Lujo en el Borde del Cráter',
    'mgg_acc4_price' => '$750–$1.300 <small>por persona / noche</small>',
    'mgg_acc4_loc' => 'Borde del Cráter del Ngorongoro',
    'mgg_acc4_desc' => 'Vistas impresionantes y servicio excepcional, ideal para combinar un safari de migración con el cráter.',
    'mgg_acc_tip' => '<strong>Consejo de reserva:</strong> para los meses pico de migración (julio–septiembre), reserve con 6–12 meses de antelación. Los campamentos mejor ubicados se agotan primero, sin importar la categoría de presupuesto.',

    'mgg_best_time_title' => 'Mejor Época para Visitar: Una Guía Estacional',
    'mgg_best_time_p1' => 'La mejor época depende enteramente de lo que quiera ver. Cada temporada ofrece una experiencia única.',
    'mgg_month_jan' => 'Comienzan los nacimientos · Ndutu',
    'mgg_month_feb' => 'Pico de nacimientos · Acción de depredadores',
    'mgg_month_mar' => 'Terminan los nacimientos · Las manadas se dispersan',
    'mgg_month_apr' => 'Lluvias largas · Acumulación en el Grumeti',
    'mgg_month_may' => 'Comienzan los cruces del Grumeti',
    'mgg_month_jun' => 'Las manadas avanzan al norte · Cruces',
    'mgg_month_jul' => 'Comienzan los cruces del Mara',
    'mgg_month_aug' => 'Pico de los cruces del Mara',
    'mgg_month_sep' => 'Continúan los cruces',
    'mgg_month_oct' => 'Las manadas se mueven al sur · Buena relación calidad-precio',
    'mgg_month_nov' => 'Lluvias cortas · Las manadas regresan al sur',
    'mgg_month_dec' => 'Pre-nacimientos · Llanuras del sur',
    'mgg_best_time_box' => '<strong>Consejo del experto en migración:</strong> "No hay mala época para ver la Migración. Cada temporada ofrece algo único. ¿Quiere drama? Visite en agosto. ¿Quiere intimidad? Visite en febrero. ¿Quiere soledad? Visite en abril."',

    'mgg_itin_title' => 'Itinerarios de Migración de Muestra',
    'mgg_itin_p1' => 'Un vistazo día a día de lo que realmente incluyen nuestros paquetes de migración más solicitados.',
    'mgg_itin1_name' => 'Safari de la Temporada de Nacimientos de 5 Días',
    'mgg_itin1_days' => '5 días / 4 noches',
    'mgg_itin1_route' => 'Ndutu + Ngorongoro + Centro del Serengeti (ene–mar)',
    'mgg_itin1_detail' => '<strong>Día 1:</strong> Llegada a Arusha → traslado a Ndutu, safari por la tarde.<br><strong>Día 2:</strong> Día completo en Ndutu: observación de nacimientos y acción de depredadores.<br><strong>Día 3:</strong> Ndutu → Cráter del Ngorongoro, descenso de día completo.<br><strong>Día 4:</strong> Ngorongoro → Centro del Serengeti, safari en ruta.<br><strong>Día 5:</strong> Safari matutino, regreso a Arusha.',
    'mgg_itin1_price' => 'Desde €1.150 por persona',
    'mgg_itin2_name' => 'Safari de los Cruces del Río Mara de 8 Días',
    'mgg_itin2_days' => '8 días / 7 noches',
    'mgg_itin2_route' => 'Norte del Serengeti + Ngorongoro (jul–sep)',
    'mgg_itin2_detail' => '<strong>Día 1:</strong> Llegada a Arusha → traslado al Norte del Serengeti.<br><strong>Días 2–4:</strong> Días completos en el río Mara, esperando los cruces.<br><strong>Día 5:</strong> Norte → Centro del Serengeti, safari.<br><strong>Día 6:</strong> Día completo en el Centro del Serengeti.<br><strong>Día 7:</strong> Serengeti → Ngorongoro, descenso al cráter.<br><strong>Día 8:</strong> Ngorongoro → Arusha, salida.',
    'mgg_itin2_price' => 'Desde €2.450 por persona',

    'mgg_tips_title' => 'Consejos Locales: De Guías que Siguen a las Manadas',
    'mgg_tips_p1' => 'Consejos de iniciados de nuestros especialistas en migración, cosas que no encontrará en una guía de viajes.',
    'mgg_tip1' => '<strong>El juego de la espera</strong> — para los cruces de ríos, esté preparado para esperar. Las manadas pueden tardar horas en decidirse a cruzar. Traiga snacks, agua y paciencia — la recompensa vale la pena.',
    'mgg_tip2' => '<strong>Predicción de cruces</strong> — los guías experimentados pueden predecir los cruces observando a los ñus reunirse y caminar de un lado a otro en la orilla. La tensión es palpable antes de un cruce.',
    'mgg_tip3' => '<strong>La elección del campamento importa</strong> — para la temporada de nacimientos, alójese en Ndutu, para los cruces del Grumeti, alójese en el Corredor Occidental, para los cruces del Mara, alójese en el Norte del Serengeti. Elegir la base correcta ahorra horas de conducción diarias.',
    'mgg_tip4' => '<strong>Reserve pronto — de verdad pronto</strong> — para la temporada pico de migración (julio–septiembre), reserve el alojamiento con 6–12 meses de antelación. Los campamentos mejor ubicados se agotan con más de un año de antelación.',
    'mgg_tip5' => '<strong>Siga a los depredadores</strong> — la migración no se trata solo de los ñus. Leones, guepardos y leopardos siguen a las manadas, y seguirlos a menudo lleva a los momentos más dramáticos.',
    'mgg_tip6' => '<strong>Fotografía de la hora dorada</strong> — la mejor luz para los cruces es al amanecer y al atardecer. La luz cálida hace el drama aún más poderoso.',
    'mgg_tip7' => '<strong>Valor de la temporada media</strong> — octubre–diciembre y febrero ofrecen una excelente relación calidad-precio, con multitudes más pequeñas y precios más bajos mientras la observación de fauna sigue siendo excepcional.',
    'mgg_tip8' => '<strong>El seguro de viaje es esencial</strong> — la evacuación médica desde el Serengeti es cara pero necesaria. Asegúrese de que su póliza cubra actividades de safari.',

    'mgg_faq_title' => 'Preguntas Frecuentes',
    'mgg_faq_q1' => '¿Cuál es la mejor época para ver la Gran Migración?',
    'mgg_faq_a1' => 'Depende de lo que quiera ver: nacimientos en enero–febrero, cruces del Grumeti en junio–julio, cruces del Mara en julio–septiembre, y el regreso al sur en octubre–diciembre.',
    'mgg_faq_q2' => '¿Cuál es el mejor lugar para ver el cruce de los ñus?',
    'mgg_faq_a2' => 'Los cruces del río Mara en el norte del Serengeti (julio–septiembre) son los más famosos, mientras que los cruces del río Grumeti (junio–julio) también son espectaculares con muchas menos multitudes.',
    'mgg_faq_q3' => '¿Cuánto cuesta un safari de migración?',
    'mgg_faq_a3' => 'Desde €150–€300 por persona por día para camping económico, €300–€600 para gama media, y €800+ para lodges de lujo y campamentos móviles.',
    'mgg_faq_q4' => '¿Puedo ver la migración en la temporada verde?',
    'mgg_faq_a4' => 'Sí. La temporada verde (marzo–mayo) ofrece paisajes exuberantes, menos multitudes y precios más bajos, con las manadas dispersándose por el Corredor Occidental.',
    'mgg_faq_q5' => '¿Con cuánta antelación debo reservar un safari de migración?',
    'mgg_faq_a5' => 'Para la temporada pico (julio–septiembre), reserve con 6–12 meses de antelación. Para la temporada de nacimientos y los meses medios, 3–4 meses suele ser suficiente.',
    'mgg_faq_q6' => '¿Es predecible la migración?',
    'mgg_faq_a6' => 'La migración sigue las lluvias, pero el momento exacto puede variar unas semanas cada año. Los guías locales siguen las condiciones en tiempo real para predecir los movimientos.',
    'mgg_faq_q7' => '¿Pueden los niños unirse a un safari de migración?',
    'mgg_faq_a7' => 'Sí, la mayoría de los safaris de migración son aptos para familias, y varios lodges asociados ofrecen suites familiares y actividades para niños.',
    'mgg_faq_q8' => '¿Cuál es la diferencia entre los cruces del Grumeti y del Mara?',
    'mgg_faq_a8' => 'Los cruces del Grumeti (junio–julio) tienen menos afluencia y grandes cocodrilos. Los cruces del Mara (julio–septiembre) son más famosos, de mayor escala, y más concurridos.',

    'mgg_book_title' => 'Reserve Su Safari de Migración',
    'mgg_book_p1' => 'Díganos sus fechas de viaje y nuestro especialista en migración responderá dentro de 24 horas con exactamente lo que verá y un precio exacto.',
    'mgg_cta_title' => '¿Listo para Presenciar el Mayor Espectáculo de Fauna?',
    'mgg_cta_p' => 'Obtenga un presupuesto gratuito y sin compromiso de un operador local de Arusha que sigue a las manadas todo el año.',
    'mgg_cta_button' => 'Obtener Su Presupuesto Gratis',
    'mgg_share_label' => 'Comparta esta guía:',
    'mgg_print' => 'Imprimir Guía',

