    'dtg_meta_title' => 'La Guía Definitiva de Excursiones de un Día en Tanzania: Todos los Tours, Precios y Consejos Locales',
    'dtg_meta_description' => 'La guía más completa de excursiones de un día en Tanzania. Excursiones de safari, tours culturales, caminatas de un día al Kilimanjaro, precios, consejos locales y paquetes de confianza de un operador local de Arusha.',

    'dtg_badge' => 'La Guía Completa de Excursiones de un Día 2026',
    'dtg_h1' => 'La Guía Definitiva de Excursiones de un Día en Tanzania',
    'dtg_price_highlight' => 'Desde €50',
    'dtg_price_highlight_small' => 'por persona',
    'dtg_hero_intro' => 'Todo lo que necesita antes de reservar: cada opción de excursión de un día desde Arusha y Moshi, precios honestos, secretos locales, y, una vez que sepa qué se adapta a su día, nuestros paquetes de confianza.',
