    'dtg_intro_title' => 'El Recurso Definitivo de Excursiones de un Día',
    'dtg_intro_p1' => 'Tanzania es un país vasto con una increíble diversidad de experiencias, y no necesita una semana para disfrutarlas. Las excursiones de un día son la forma perfecta de explorar lo más destacado, ya sea que esté en Arusha, Moshi o simplemente de paso en un safari más largo.',
    'dtg_intro_p2' => '¿Qué hace diferente a esta guía? Cada excursión aquí ha sido probada personalmente por nuestro equipo de guías locales. Hemos incluido consejos de iniciados y asesoramiento práctico que no encontrará en ningún otro lugar, ya sea que viaje solo, en pareja o en familia.',
    'dtg_intro_box' => '<strong>¿Por qué confiar en nosotros?</strong> Nuestro equipo ha organizado excursiones de un día durante más de 15 años. Conocemos a los mejores guías, las mejores épocas para visitar y los lugares ocultos que la mayoría de los turistas se pierden. Esta guía se basa en experiencia real, no en información genérica.',

    'dtg_trips_title' => 'Todas las Excursiones de un Día: Por Categoría',
    'dtg_trips_p1' => 'A continuación encontrará las principales categorías de excursiones de un día, organizadas por tipo. Cada una tiene precios detallados y consejos locales más adelante en esta guía.',
    'dtg_trip1_name' => 'Excursiones de Safari de un Día',
    'dtg_trip1_desc' => 'Cráter del Ngorongoro, Tarangire, Lago Manyara y Parque Nacional Arusha: una observación de fauna increíble en solo unas horas desde Arusha o Moshi.',
    'dtg_trip2_name' => 'Excursiones Culturales de un Día',
    'dtg_trip2_desc' => 'Pueblos de Mto wa Mbu, comunidades masái, y tribus hadzabe y datoga cerca del lago Eyasi: inmersión cultural auténtica.',
    'dtg_trip3_name' => 'Caminatas de un Día al Kilimanjaro',
    'dtg_trip3_desc' => 'Caminatas de un día a Mandara Hut o la meseta de Shira: experimente las laderas bajas del Kilimanjaro sin comprometerse con la ascensión completa.',
    'dtg_trip4_name' => 'Lago Natron y Joyas Ocultas',
    'dtg_trip4_desc' => 'Flamencos, cascadas y paisajes dramáticos fuera del circuito de safari habitual.',

    'dtg_packages_title' => 'Excursiones de Confianza: Reserve con Confianza',
    'dtg_packages_p1' => 'Cada excursión de un día a continuación la realizan nuestros propios conductores y guías, con precios transparentes y sin cargos ocultos. Cada excursión incluye:',
