    'dtg_tips_title' => 'Consejos Locales: De Nuestros Propios Guías',
    'dtg_tips_p1' => 'Consejos de iniciados de nuestro equipo de guías tanzanos, cosas que le ahorrarán tiempo, dinero y decepciones.',
    'dtg_tip1' => '<strong>Salga temprano</strong> — para el Ngorongoro, salga de Arusha antes de las 5:30 para captar la mejor actividad matutina de depredadores. El cráter se llena después de las 10:00.',
    'dtg_tip2' => '<strong>La temporada seca concentra la fauna</strong> — Tarangire de junio a octubre ofrece manadas de elefantes increíbles alrededor del río a medida que el agua escasea en otros lugares.',
    'dtg_tip3' => '<strong>No se salte la caminata por el bosque</strong> — en el Lago Manyara, la caminata por el bosque de aguas subterráneas a menudo se pasa por alto pero es una excelente manera de ver monos azules y antílopes de matorral de cerca.',
    'dtg_tip4' => '<strong>Reserve las excursiones hadzabe por la mañana</strong> — los hadzabe cazan al amanecer, así que una visita matutina le da la experiencia más auténtica de su vida diaria.',
    'dtg_tip5' => '<strong>Combine excursiones sabiamente</strong> — el Lago Manyara y el pueblo de Mto wa Mbu se pueden combinar en un día sin sentirse apresurado, ahorrándole un día de su viaje.',
    'dtg_tip6' => '<strong>Empaque capas</strong> — las mañanas pueden ser frescas, especialmente cerca del Ngorongoro y el Kilimanjaro, pero el sol del mediodía es intenso. Vístase en capas que pueda quitarse.',
    'dtg_tip7' => '<strong>Confirme la hora de recogida la noche anterior</strong> — el tráfico en Arusha puede variar; una rápida confirmación por WhatsApp la noche anterior evita cualquier confusión.',
    'dtg_tip8' => '<strong>Traiga efectivo para propinas y recuerdos</strong> — las visitas a pueblos y excursiones culturales son un excelente lugar para comprar artesanías auténticas directamente de los artesanos, pero el pago con tarjeta rara vez está disponible.',

    'dtg_prices_title' => 'Guía de Precios de Excursiones de un Día',
    'dtg_prices_p1' => 'Los precios varían principalmente según la distancia desde Arusha y las tarifas de entrada a los parques. Aquí hay un desglose honesto.',
    'dtg_prices_th1' => 'Excursión de un Día',
    'dtg_prices_th2' => 'Distancia desde Arusha',
    'dtg_prices_th3' => 'Precio Típico',
    'dtg_prices_row1_label' => 'Parque Nacional Arusha',
    'dtg_prices_row1_dist' => '30 minutos',
    'dtg_prices_row1_price' => '€130',
    'dtg_prices_row2_label' => 'Excursión Cultural a Mto wa Mbu',
    'dtg_prices_row2_dist' => '2 horas',
    'dtg_prices_row2_price' => '€90',
    'dtg_prices_row3_label' => 'Lago Manyara',
    'dtg_prices_row3_dist' => '2 horas',
    'dtg_prices_row3_price' => '€160',
    'dtg_prices_row4_label' => 'Tarangire',
    'dtg_prices_row4_dist' => '2 horas',
    'dtg_prices_row4_price' => '€180',
    'dtg_prices_row5_label' => 'Hadzabe y Datoga (Lago Eyasi)',
    'dtg_prices_row5_dist' => '3 horas',
    'dtg_prices_row5_price' => '€140',
    'dtg_prices_row6_label' => 'Cráter del Ngorongoro',
    'dtg_prices_row6_dist' => '3 horas',
    'dtg_prices_row6_price' => '€250',
    'dtg_prices_insider' => '<strong>Consejo de iniciado:</strong> el tamaño del grupo también importa aquí: compartir vehículo con 3–4 viajeros más puede bajar el precio por persona un 20–30% en comparación con una excursión privada.',

    'dtg_best_time_title' => 'Mejor Época para las Excursiones de un Día',
    'dtg_best_time_p1' => 'La mayoría de las excursiones de un día funcionan bien todo el año, pero algunas cosas cambian con las estaciones.',
    'dtg_best_time_li1' => '<strong>Cráter del Ngorongoro:</strong> bueno todo el año, pero las salidas tempranas por la mañana importan más en la temporada seca (junio–octubre) cuando el cráter está más concurrido.',
    'dtg_best_time_li2' => '<strong>Tarangire:</strong> mejor de junio a octubre cuando la fauna se concentra alrededor del río durante la temporada seca.',
    'dtg_best_time_li3' => '<strong>Excursiones culturales (Hadzabe, Mto wa Mbu):</strong> buenas todo el año, aunque las carreteras al Lago Eyasi pueden ser más difíciles durante las lluvias largas de marzo a mayo.',
    'dtg_best_time_li4' => '<strong>Caminatas de un día al Kilimanjaro:</strong> vistas más claras de junio a octubre y de enero a marzo, evite las lluvias largas (marzo–mayo).',
    'dtg_best_time_box' => '<strong>Regla general:</strong> si solo tiene un día y quiere la mayor probabilidad de tomar grandes fotos de fauna, apunte a junio–octubre y salga antes de las 6:00.',

    'dtg_packing_title' => 'Qué Traer',
    'dtg_packing_p1' => 'Una excursión de un día necesita mucho menos que un safari de varios días, pero algunos elementos esenciales marcan una diferencia real.',
    'dtg_packing_li1' => 'Ropa de colores neutros (caqui, verde oliva, tostado), evite colores brillantes y blanco puro',
    'dtg_packing_li2' => 'Una chaqueta ligera o forro polar para las salidas tempranas por la mañana',
    'dtg_packing_li3' => 'Protector solar, gafas de sol y un sombrero de ala ancha',
    'dtg_packing_li4' => 'Binoculares, la mayoría de los vehículos de excursión tienen espacio para el equipo personal',
    'dtg_packing_li5' => 'Una cámara con objetivo de zoom, más baterías de repuesto',
    'dtg_packing_li6' => 'Efectivo (chelines tanzanos o USD) para propinas y recuerdos',
    'dtg_packing_li7' => 'Una botella de agua reutilizable, se proporciona agua potable pero traiga una botella para rellenar',

    'dtg_faq_title' => 'Preguntas Frecuentes',
    'dtg_faq_q1' => '¿Cuál es la mejor excursión de un día desde Arusha?',
    'dtg_faq_a1' => 'La excursión de un día al Cráter del Ngorongoro es la más popular para la fauna, pero Tarangire y la excursión cultural hadzabe son excelentes alternativas según sus intereses.',
    'dtg_faq_q2' => '¿Cuánto cuesta un safari de un día en Tanzania?',
    'dtg_faq_a2' => 'Los safaris de un día suelen costar entre €90 y €250 por persona, dependiendo del parque y el tamaño del grupo.',
    'dtg_faq_q3' => '¿Puedo visitar a los hadzabe en un día?',
    'dtg_faq_a3' => 'Sí, desde Arusha o Karatu, una excursión de un día a las tribus hadzabe y datoga cerca del Lago Eyasi es totalmente posible.',
    'dtg_faq_q4' => '¿A qué hora salen las excursiones de un día?',
    'dtg_faq_a4' => 'La mayoría sale entre las 5:30 y las 7:00 para las excursiones de fauna, y alrededor de las 8:00 para las excursiones culturales. Las salidas más tempranas generalmente significan una mejor observación de fauna.',
    'dtg_faq_q5' => '¿Está incluido el almuerzo?',
    'dtg_faq_a5' => 'Sí, todos los paquetes de excursión de un día incluyen un almuerzo de picnic y agua potable.',
    'dtg_faq_q6' => '¿Puedo combinar dos excursiones de un día en un solo día?',
    'dtg_faq_a6' => 'Algunas combinaciones funcionan bien (como el Lago Manyara con el pueblo de Mto wa Mbu), pero el Ngorongoro y Tarangire se hacen mejor cada uno como un día completo dedicado.',
    'dtg_faq_q7' => '¿Necesito reservar con antelación?',
    'dtg_faq_a7' => 'Un aviso de 2–3 días suele ser suficiente, aunque en temporada alta (junio–octubre) conviene reservar con una semana de antelación.',
    'dtg_faq_q8' => '¿Está incluida la recogida en el hotel?',
    'dtg_faq_a8' => 'Sí, todas las excursiones de un día incluyen recogida y regreso a su hotel en Arusha o Moshi.',

    'dtg_book_title' => 'Reserve Su Excursión de un Día',
    'dtg_book_p1' => 'Rellene los datos a continuación y nuestro equipo responderá dentro de 24 horas con disponibilidad y un precio exacto.',
    'dtg_cta_title' => '¿Listo para Aprovechar al Máximo Su Día?',
